(function () {
  "use strict";
  function wpal() {
    if (window.__APP_PRINTING)
      return {
        bg: "rgba(0,0,0,0)",
        axis: "#4b5563",
        grid: "rgba(55,65,81,.14)",
        txt: "#1f2430",
        dim: "#5b6472",
      };
    const light = document.documentElement.getAttribute("data-theme") === "light";
    return light
      ? {
          bg: "#f7f5ef",
          axis: "#9a9488",
          grid: "rgba(70,64,55,.18)",
          txt: "#4a463d",
          dim: "#8a8578",
        }
      : {
          bg: "#05070f",
          axis: "#3b4770",
          grid: "rgba(103,115,155,.18)",
          txt: "#eaeefb",
          dim: "#67739b",
        };
  }
  function wl2rgb(wl) {
    let r = 0,
      g = 0,
      b = 0;
    if (wl < 440) {
      r = -(wl - 440) / 60;
      b = 1;
    } else if (wl < 490) {
      g = (wl - 440) / 50;
      b = 1;
    } else if (wl < 510) {
      g = 1;
      b = -(wl - 510) / 20;
    } else if (wl < 580) {
      r = (wl - 510) / 70;
      g = 1;
    } else if (wl < 645) {
      r = 1;
      g = -(wl - 645) / 65;
    } else {
      r = 1;
    }
    let f = 1;
    if (wl < 420) f = 0.3 + (0.7 * (wl - 400)) / 20;
    else if (wl > 700) f = 0.3 + (0.7 * (700 - wl)) / 0.0001 || 0.3;
    f = Math.max(0.15, Math.min(1, f));
    return [
      Math.round(255 * Math.pow(r * f, 0.8)),
      Math.round(255 * Math.pow(g * f, 0.8)),
      Math.round(255 * Math.pow(b * f, 0.8)),
    ];
  }
  window.PackWidgetKit = Object.assign(window.PackWidgetKit || {}, { wpal, wl2rgb });
})();
