import { main } from "../../preferences/prefs.js";
import { _recordQuizAnswer, after, escHtml, runMmd, toFa } from "../../core.js";
// آزمون مروری گزینه‌ای از داده‌های پک (assessments). هر سؤال: { id, q, choices[], answer (اندیس صفر-مبنا), explain?, session? }
// پاسخ اول هر سؤال مثل پرسش درون‌متنی ثبت می‌شود (وزن کمتر، خطا به دفتر اشتباهات).
export function pageExam() {
  const tests = CourseRuntime.getPackAssessments() || [];
  if (!tests.length) {
    main.innerHTML = `<div class="page learn-page"><h2>آزمون مروری</h2><p class="learn-meta">آزمونی در این بسته نیست.</p></div>`;
    return;
  }
  const itemsOf = (a) =>
    (Array.isArray(a.items) ? a.items : Array.isArray(a.questions) ? a.questions : []).filter(
      (q) => q && Array.isArray(q.choices) && q.choices.length >= 2 && Number.isInteger(q.answer),
    );

  const showList = () => {
    main.innerHTML = `<div class="page learn-page"><h2>آزمون مروری</h2><div class="learn-list">${tests
      .map((a, i) => {
        const n = itemsOf(a).length;
        return `<article class="card learn-item">
          <h3>${escHtml(a.title || "آزمون " + toFa(i + 1))}</h3>
          <p style="color:var(--text-secondary)">${escHtml(a.desc || a.summary || "")}</p>
          <p class="learn-meta">${toFa(n)} سؤال</p>
          <div class="learn-actions"><button type="button" class="btn g" data-start="${i}" ${n ? "" : "disabled"}>شروع</button></div>
        </article>`;
      })
      .join("")}</div></div>`;
    main.querySelectorAll("[data-start]").forEach((b) => {
      b.onclick = () => runTest(Number(b.dataset.start));
    });
  };

  const runTest = (ti) => {
    const a = tests[ti];
    const items = itemsOf(a);
    const sid = a.session || "";
    const results = [];
    let idx = 0;

    const finish = () => {
      const correct = results.filter((r) => r.ok).length;
      main.innerHTML = `<div class="page learn-page">
        <h2>نتیجه: ${toFa(correct)} از ${toFa(items.length)}</h2>
        <p class="learn-meta">${toFa(Math.round((correct / items.length) * 100))}٪ درست</p>
        <div class="learn-actions"><button type="button" class="btn g" id="examBack">بازگشت به فهرست آزمون‌ها</button></div>
      </div>`;
      document.getElementById("examBack").onclick = showList;
    };

    const draw = () => {
      if (idx >= items.length) return finish();
      const q = items[idx];
      const last = idx + 1 >= items.length;
      main.innerHTML = `<div class="page learn-page">
        <p class="learn-meta">${toFa(idx + 1)} از ${toFa(items.length)}</p>
        <h2 class="exam-q">${escHtml(q.q || q.title || "")}</h2>
        <div class="exam-choices" role="radiogroup" aria-label="گزینه‌ها">${q.choices
          .map((c, k) => `<button type="button" class="btn exam-c" role="radio" aria-checked="false" data-k="${k}">${escHtml(c)}</button>`)
          .join("")}</div>
        <p class="exam-fb" aria-live="polite"></p>
        <div class="learn-actions"><button type="button" class="btn g" id="examNext" disabled>${last ? "پایان" : "سؤال بعدی"}</button></div>
      </div>`;
      let locked = false;
      const choices = Array.from(main.querySelectorAll(".exam-c"));
      choices.forEach((btn) => {
        btn.onclick = () => {
          if (locked) return;
          locked = true;
          const k = Number(btn.dataset.k);
          const ok = k === q.answer;
          choices.forEach((c, j) => {
            c.setAttribute("aria-checked", j === k ? "true" : "false");
            if (j === q.answer) c.classList.add("right");
          });
          if (!ok) btn.classList.add("wrong");
          const fb = main.querySelector(".exam-fb");
          fb.textContent = ok ? "پاسخ درست" : "پاسخ نادرست" + (q.explain ? " — " + q.explain : "");
          fb.dataset.ok = ok ? "1" : "0";
          results.push({ ok, q, qid: q.id || "i" + idx });
          recordAnswer(results[results.length - 1]);
          main.querySelector("#examNext").disabled = false;
        };
      });
      main.querySelector("#examNext").onclick = () => {
        idx += 1;
        draw();
      };
    };

    // هر پاسخ همان لحظه ثبت می‌شود (پاسخ اول، مثل پرسش درون‌متنی). بدون جلسهٔ مرتبط، شاهد تسلط ساخته نمی‌شود.
    const recordAnswer = (r) => {
      if (!sid || typeof _recordQuizAnswer !== "function") return;
      _recordQuizAnswer("quiz:" + sid + ":" + r.qid, r.ok, r.q.q || "");
    };
    idx = 0;
    draw();
  };

  showList();
}

export function _validateGraphData(rawNodes) {
  if (!Array.isArray(rawNodes) || !rawNodes.length) {
    return { ok: false, reason: "nodata", nodes: [], edges: [] };
  }
  const nodes = [];
  const idSet = new Set();
  rawNodes.forEach((n, i) => {
    if (!n || typeof n !== "object") return;
    const id = String(n.id || "n" + i);
    if (idSet.has(id)) return;
    idSet.add(id);
    nodes.push({
      id,
      label: String(n.label || n.t || n.title || id),
      type: String(n.type || "concept"),
    });
  });
  const edges = [];
  rawNodes.forEach((n) => {
    if (!n || typeof n !== "object") return;
    const from = String(n.id || "");
    const targets = Array.isArray(n.to) ? n.to : Array.isArray(n.edges) ? n.edges : [];
    targets.forEach((t) => {
      const to = String(t);
      if (idSet.has(from) && idSet.has(to) && from !== to) {
        edges.push({ from, to });
      }
    });
  });
  if (nodes.length < 5) {
    return { ok: false, reason: "fewnodes", nodes, edges, minNodes: 5, actualNodes: nodes.length };
  }
  if (edges.length < 4) {
    return { ok: false, reason: "fewedges", nodes, edges, minEdges: 4, actualEdges: edges.length };
  }
  return { ok: true, nodes, edges };
}

export function _buildMermaidSource(nodes, edges) {
  const lines = ["flowchart TB"];
  const index = new Map();
  nodes.forEach((n, i) => {
    const vid = "N" + i;
    index.set(n.id, vid);
    const lab = n.label
      .replace(/["\[\]{}()<>]/g, " ")
      .replace(/\s+/g, " ")
      .trim();
    lines.push(`  ${vid}["${lab}"]`);
  });
  edges.forEach((e) => {
    const a = index.get(e.from);
    const b = index.get(e.to);
    if (a && b) lines.push(`  ${a} --> ${b}`);
  });
  return lines.join("\n");
}

export function pageGraph() {
  const raw = CourseRuntime.getPackGraphNodes();
  const check = _validateGraphData(raw);

  if (!check.ok) {
    main.innerHTML = _renderGraphEmpty(check);
    return;
  }

  const mmd = _buildMermaidSource(check.nodes, check.edges);
  const typeCount = {};
  check.nodes.forEach((n) => {
    typeCount[n.type] = (typeCount[n.type] || 0) + 1;
  });
  const legend = Object.entries(typeCount)
    .map(([t, c]) => `<span class="ov-chip">${escHtml(t)}: ${toFa(c)}</span>`)
    .join("");

  main.innerHTML = `<div class="page learn-page">
    <div class="learn-head">
      <h2>گراف مفهومی</h2>
      <span class="learn-meta">${toFa(check.nodes.length)} گره · ${toFa(check.edges.length)} یال</span>
    </div>
    <div class="prog-panel">
      <div class="prog-panel-h">
        <h2>نقشهٔ روابط</h2>
        <span class="prog-panel-meta">ترکیب گره‌ها: ${legend}</span>
      </div>
      <p style="margin:0 0 12px;color:var(--text-secondary);line-height:1.85;font-size:calc(13px * var(--fs-scale, 1))">
        هر گره یک مفهوم، جلسه یا فرمول است و هر یال یک رابطهٔ مفهومی. جابه‌جایی در گراف با کشیدن گره‌ها ممکن است.
      </p>
      <div class="graph-canvas"><div class="mmd" data-graph-source></div></div>
    </div>
  </div>`;

  const mmdEl = main.querySelector("[data-graph-source]");
  if (mmdEl) mmdEl.textContent = mmd;
  if (typeof after === "function") after(main);
  else if (typeof runMmd === "function") runMmd(main);
}

export function _renderGraphEmpty(check) {
  const reason = check.reason;
  let title = "گراف مفهومی در دسترس نیست";
  let body = "";
  let hint = "";

  if (reason === "nodata") {
    body = "این درس دادهٔ گراف مفهومی (<code>GRAPH_NODES</code>) تعریف نکرده است.";
    hint =
      "تا زمانی که این داده از طرف درس‌نامه‌ساز فراهم نشود، نمایش گراف کیفیت لازم را نخواهد داشت.";
  } else if (reason === "fewnodes") {
    title = "دادهٔ گراف کافی نیست";
    body = `گراف این درس فقط <b>${toFa(check.actualNodes)}</b> گره دارد؛ آستانهٔ کیفیت <b>${toFa(check.minNodes)}</b> گره است.`;
    hint =
      "نمایش گراف کوچک، روابط مفهومی را به‌درستی نشان نمی‌دهد و بیش از آنکه کمک کند، گمراه‌کننده است.";
  } else if (reason === "fewedges") {
    title = "روابط گراف کافی نیست";
    body = `گراف این درس <b>${toFa(check.actualEdges)}</b> یال دارد؛ آستانهٔ کیفیت <b>${toFa(check.minEdges)}</b> یال است.`;
    hint = "گراف بدون روابط کافی، نقشهٔ مفهومی واقعی نیست.";
  } else {
    body = "دادهٔ گراف معتبر نیست.";
  }

  return `<div class="page learn-page">
    <div class="learn-head"><h2>گراف مفهومی</h2></div>
    <div class="card" style="padding:26px 24px;max-width:560px;margin:20px auto;text-align:center">
      <div style="font-size:calc(44px * var(--fs-scale, 1));line-height:1;color:var(--text-tertiary);margin-bottom:14px" aria-hidden="true">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4"
             style="width:44px;height:44px;margin:0 auto;display:block;opacity:.5">
          <circle cx="12" cy="5" r="2.5"/><circle cx="5" cy="19" r="2.5"/><circle cx="19" cy="19" r="2.5"/>
          <path d="m10.4 7.5-4.3 9"/><path d="m13.6 7.5 4.3 9"/><path d="M7.5 19h9"/>
        </svg>
      </div>
      <h2 style="margin:0 0 10px;font-size:1.15rem">${title}</h2>
      <p style="color:var(--text-secondary);margin:0 0 8px;line-height:1.9">${body}</p>
      ${hint ? `<p style="color:var(--text-tertiary);margin:0 0 18px;line-height:1.85;font-size:calc(12.5px * var(--fs-scale, 1))">${escHtml(hint)}</p>` : ""}
      <div style="display:flex;gap:8px;justify-content:center;flex-wrap:wrap">
        <button type="button" class="btn" onclick="go('home')">بازگشت به داشبورد</button>
      </div>
    </div>
  </div>`;
}

window.pageGraph = pageGraph;
