// رندررهای callout و define (Phase 5.4).
import { escHtml } from "../escape.js";
import { CALLOUT_TONES } from "../block-types.js";
import type { BlockMap, Renderer } from "../types.js";
import { textHTML } from "./shared.js";

export const renderCallout: Renderer<BlockMap["callout"]> = (b) => {
  const tone = (CALLOUT_TONES as readonly string[]).includes(b.tone || "") ? b.tone : "note";
  const title = b.title ? `<b>${escHtml(b.title)}</b>` : "";
  return `<aside class="rd-callout rd-${tone}">${title}<div>${textHTML(b)}</div></aside>`;
};

export const renderDefine: Renderer<BlockMap["define"]> = (b) => {
  const term = escHtml(b.term || "");
  // define قواعد متفاوتی دارد: html تهی هم معتبر است و به text نمی‌افتد (رفتار نسخهٔ قبلی).
  const body =
    b.html != null
      ? b.html
      : b.text != null
        ? escHtml(String(b.text))
        : b.definition != null
          ? escHtml(String(b.definition))
          : "";
  return `<div class="rd-define"><span class="rd-define-term">${term}</span><div class="rd-define-body">${body}</div></div>`;
};
