// طرح zod برای اعتبارسنجی شکل پک در زمان اجرا.
// این طرح ساختار را کنترل می‌کند (نوع و الزام فیلدها)؛ قواعد معنایی (ارجاع‌ها، یکتایی، کیفیت محتوا)
// همچنان در validate.ts است. فیلدهای ناشناخته مجازند (looseObject) تا قرارداد additive بماند.

import { z } from "zod";
import { EXPERIENCE_KINDS } from "./constants.js";

export const formulaSchema = z.looseObject({
  t: z.string().min(1),
  tex: z.string().min(1),
  cat: z.string().optional(),
  vars: z.array(z.array(z.unknown()).length(2)),
  review: z.boolean().optional(),
});

export const conceptSchema = z.looseObject({
  t: z.string().min(1),
  pts: z.array(z.unknown()),
  ex: z.unknown().optional(),
  review: z.boolean().optional(),
});

export const sessionSchema = z.looseObject({
  id: z.string().regex(/^s\d{2,}$/),
  num: z.number().int(),
  title: z.string(),
  experience: z.string().refine((v) => EXPERIENCE_KINDS.includes(v), {
    message: "experience ناشناخته است",
  }),
  review: z.enum(["auto", "off"]),
  concepts: z.array(conceptSchema),
  formulas: z.array(formulaSchema),
  widgets: z.array(z.string()),
});

export const courseSchema = z.looseObject({
  meta: z.looseObject({ id: z.string().min(1), title: z.string() }),
  sessions: z.array(sessionSchema),
});

export const packSchema = z.looseObject({
  id: z.string().min(1),
  course: courseSchema,
});

// فهرست خطاهای شکل به‌صورت «مسیر: پیام»؛ آرایهٔ خالی یعنی شکل معتبر است
export function checkPackShape(pack: unknown): string[] {
  const result = packSchema.safeParse(pack);
  if (result.success) return [];
  return result.error.issues.map((i) => i.path.join(".") + ": " + i.message);
}
