(function () {
  "use strict";
  const K = window.PackWidgetKit;
  const wpal = K.wpal;
  let P = wpal();
  globalThis.addEventListener("lector:theme", () => {
    P = wpal();
  });
  const W = {
    title: "عدسی نازک — همگرا و واگرا",
    desc: "پرتوهای اصلی عدسی و تشکیل تصویر؛ فرمول $\\frac{1}{s}+\\frac{1}{s'}=\\frac{1}{f}$ در عمل.",
    sess: ["s10", "s11"],
    mount(box) {
      box.innerHTML = `<div class="wgrid"><div class="wstage"><svg viewBox="0 0 680 400"></svg></div><div><div class="ctls"></div><div class="seg" style="margin-top:6px"></div><div class="winfo"></div></div></div>`;
      const sg = box.querySelector("svg"),
        ct = box.querySelector(".ctls"),
        seg = box.querySelector(".seg"),
        info = box.querySelector(".winfo");
      let type = "conv",
        fp = 140,
        s = 300;
      const LX = 340,
        Y = 205,
        HO = 72;
      ctl(ct, "فاصلهٔ جسم تا عدسی", 70, 300, 5, s, "واحد", (v) => {
        s = v;
        draw();
      });
      ctl(ct, "اندازهٔ فاصلهٔ کانونی", 60, 220, 5, fp, "واحد", (v) => {
        fp = v;
        draw();
      });
      seg.innerHTML = `<button data-t="conv" class="on">همگرا</button><button data-t="div">واگرا</button>`;
      seg.querySelectorAll("button").forEach(
        (b) =>
          (b.onclick = () => {
            type = b.dataset.t;
            seg.querySelectorAll("button").forEach((x) => x.classList.toggle("on", x === b));
            draw();
          }),
      );
      function line(x1, y1, x2, y2, st, w = 2, dash) {
        const l = svgEl("line", { x1, y1, x2, y2, stroke: st, "stroke-width": w }, sg);
        if (dash) l.setAttribute("stroke-dasharray", dash);
      }
      function txt(x, y, t, fill = wpal().txt, sz = 12) {
        const e = svgEl(
          "text",
          {
            x,
            y,
            fill,
            "font-size": sz,
            "text-anchor": "middle",
            "font-family": "Vazirmatn",
          },
          sg,
        );
        e.textContent = t;
      }
      function draw() {
        P = wpal();
        sg.innerHTML = "";
        const f = type === "conv" ? fp : -fp,
          xo = LX - s,
          tipY = Y - HO;
        line(20, Y, 660, Y, P.axis, 1.5);
        if (type === "conv") {
          svgEl(
            "path",
            {
              d: `M ${LX} ${Y - 150} Q ${LX + 30} ${Y} ${LX} ${Y + 150} Q ${LX - 30} ${Y} ${LX} ${Y - 150}`,
              fill: "rgba(96,165,250,.15)",
              stroke: "#60a5fa",
              "stroke-width": 2.5,
            },
            sg,
          );
        } else {
          svgEl(
            "path",
            {
              d: `M ${LX - 12} ${Y - 150} Q ${LX + 22} ${Y} ${LX - 12} ${Y + 150} L ${LX + 12} ${Y + 150} Q ${LX - 22} ${Y} ${LX + 12} ${Y - 150} Z`,
              fill: "rgba(96,165,250,.13)",
              stroke: "#60a5fa",
              "stroke-width": 2.2,
            },
            sg,
          );
        }
        const nearInf = type === "conv" && Math.abs(s - f) < 7;
        let si = null,
          m = null,
          xi = null,
          yim = null;
        if (!nearInf) {
          si = (s * f) / (s - f);
          m = -si / s;
          xi = LX + si;
          yim = Y - m * HO;
        }
        const real = si > 0;
        [
          [LX - f, "F", "#fbbf24"],
          [LX + f, "F'", "#fbbf24"],
          [LX, "V", "#94a3b8"],
        ].forEach((p) => {
          svgEl("circle", { cx: p[0], cy: Y, r: 4, fill: p[2] }, sg);
          txt(p[0], Y + 22, p[1], p[2], 13);
        });
        const Fx = LX - f;
        if (!nearInf) {
          line(xo, tipY, LX, tipY, "#fcd34d");
          if (real) {
            const k = (660 - LX) / (xi - LX);
            const ey = tipY + k * (yim - tipY);
            line(LX, tipY, 660, ey, "#38bdf8");
          } else {
            const dx = LX - xi,
              dy = tipY - yim,
              L = Math.hypot(dx, dy);
            line(LX, tipY, LX + (dx / L) * 300, tipY + (dy / L) * 300, "#38bdf8");
            line(LX, tipY, xi, yim, "#38bdf8", 1.6, "6 6");
          }
          const t2 = (LX - xo) / (Fx - xo),
            y2 = tipY + t2 * (Y - tipY);
          line(xo, tipY, LX, y2, "#fcd34d");
          if (type === "conv" && s < f) line(xo, tipY, Fx, Y, "#fcd34d", 1.4, "5 6");
          line(LX, y2, 660, y2, "#38bdf8");
          if (!real) line(LX, y2, xi, yim, "#38bdf8", 1.6, "6 6");
          const k3 = (Y - tipY) / (LX - xo);
          line(xo, tipY, LX, Y, "#fcd34d");
          if (real) line(LX, Y, xi, yim, "#38bdf8");
          else {
            line(LX, Y, 660, Y + (660 - LX) * k3, "#38bdf8");
            line(LX, Y, xi, yim, "#38bdf8", 1.6, "6 6");
          }
        } else {
          txt(340, 58, "جسم روی کانون است؛ پرتوهای خروجی موازی — تصویر در بی‌نهایت", "#fbbf24", 14);
        }
        line(xo, Y, xo, tipY, "#34d399", 3.5);
        svgEl("path", { d: `M ${xo} ${tipY} l -6 12 l 12 0 z`, fill: "#34d399" }, sg);
        txt(xo, Y + 24, "جسم", "#34d399");
        if (!nearInf) {
          const col = real ? "#f472b6" : "#c084fc";
          line(xi, Y, xi, yim, col, 3.5, real ? null : "7 7");
          const dir = yim < Y ? -1 : 1;
          svgEl("path", { d: `M ${xi} ${yim} l -6 ${-dir * 12} l 12 0 z`, fill: col }, sg);
          txt(xi, Y + 24, "تصویر", col);
        }
        const cm = (v) => (v / 4).toFixed(1);
        let props = nearInf
          ? `<span class="badge b-amb">تصویر در بی‌نهایت</span>`
          : (real
              ? `<span class="badge b-grn">حقیقی</span>`
              : `<span class="badge b-vio">مجازی</span>`) +
            (m < 0
              ? `<span class="badge b-ros">معکوس</span>`
              : `<span class="badge b-cyn">مستقیم</span>`) +
            (Math.abs(m) > 1.02
              ? `<span class="badge b-amb">بزرگ‌نمایی ×${Math.abs(m).toFixed(2)}</span>`
              : Math.abs(m) < 0.98
                ? `<span class="badge b-blu">کوچک‌نمایی ×${Math.abs(m).toFixed(2)}</span>`
                : `<span class="badge b-blu">هم‌اندازه</span>`);
        info.innerHTML = `<div class="row"><span>فاصلهٔ جسم $s$</span><b>${toFa(cm(s))} cm</b></div>
  <div class="row"><span>فاصلهٔ کانونی $f$</span><b>${toFa(cm(Math.abs(f)))} cm ${f > 0 ? "(همگرا)" : "(واگرا)"}</b></div>
  <div class="row"><span>فاصلهٔ تصویر $s'$</span><b>${nearInf ? "بی‌نهایت" : toFa(cm(Math.abs(si))) + " cm — " + (real ? "سمت خروج" : "سمت ورود")}</b></div>
  <div class="row"><span>بزرگ‌نمایی $m=-\\frac{s\'}{s}$</span><b>${nearInf ? "—" : toFa(m.toFixed(2))}</b></div><div class="props">${props}</div>`;
        if (window.renderMathInElement)
          renderMathInElement(info, {
            delimiters: [{ left: "$", right: "$", display: false }],
            throwOnError: false,
          });
      }
      draw();
    },
  };
  CourseRuntime.registerPackSource("optics", { widgets: { lens: W } });
})();
