import { ensureStore, escHtml } from "./core.js";
import { applyBrand, applyCourseLook, assertLicenseOrBanner } from "./brand.js";
import { applyPrefs, main, migrateOldPrefs, watchSystemTheme } from "./preferences/prefs.js";
import { route, updateProg } from "./ui/layout/router.js";
import { initPWA } from "./boot.js";
// راه‌اندازی اپ؛ توسط main.js پس از بارگذاری KaTeX فراخوانی می‌شود (نه هنگام import).
export async function bootstrap() {
  "use strict";

  try {

    const _packIds = CourseRuntime.listPacks().map((p) => p.id);
    if (!_packIds.length) throw new Error("[app] هیچ pack source ثبت نشده است");
    const pack = await Loader.load({ mode: "local", id: _packIds[0] });
    if (!pack || !pack.course) throw new Error("[app] PackData.course is missing");
    if (typeof ensureStore === "function") ensureStore();
    for (let _i = 1; _i < _packIds.length; _i++) {
      try {
        await Loader.load({ mode: "local", id: _packIds[_i], activate: false });
      } catch (_e) {
        if (window.console) console.warn("[app] pack load failed:", _packIds[_i], _e);
      }
    }

    if (typeof getValidationIssues === "function") {
      const issues = getValidationIssues();
      if (issues.length && window.console) {
        const e = issues.filter((i) => i.lvl === "error").length;
        console.groupCollapsed(
          "[contract v" + CONTRACT_VERSION + "] " + e + " خطا · " + (issues.length - e) + " هشدار",
        );
        issues.forEach((i) =>
          console[i.lvl === "error" ? "error" : "warn"](i.where + " — " + i.msg),
        );
        console.groupEnd();
      }
    }

    if (typeof applyCourseLook === "function") applyCourseLook();
    if (typeof migrateOldPrefs === "function") migrateOldPrefs();
    if (typeof applyPrefs === "function") applyPrefs();
    if (typeof watchSystemTheme === "function") watchSystemTheme();
    if (typeof applyBrand === "function") applyBrand();
    if (typeof assertLicenseOrBanner === "function") assertLicenseOrBanner();

    if (typeof Shell !== "undefined" && Shell.mount) Shell.mount();

    if (typeof updateProg === "function") updateProg();

    if (location.hash === "") location.hash = "#/home";
    else if (typeof route === "function") route();

    const hd = document.querySelector("header.top");
    if (hd) hd.classList.toggle("scrolled", window.scrollY > 8);

    if (typeof initPWA === "function") initPWA();
  } catch (error) {
    if (window.console) console.error("[app] bootstrap failed", error);
    const main = document.getElementById("main");
    if (main) {
      main.innerHTML = `<div class="page"><div class="card" style="padding:28px 24px;max-width:720px;margin:40px auto"><h2>خطا در بارگذاری درس</h2><p>${escHtml(error && error.message ? error.message : "خطای ناشناخته")}</p></div></div>`;
    }
  }
}
