import { escHtml } from "../escape.js";
import type { TextFields } from "../types.js";

// اولویت متن: html (اگر تهی نباشد) → text → definition. تهی بودن html به text می‌افتد.
export function textHTML(b: TextFields): string {
  if (b.html != null && b.html !== "") return b.html;
  if (b.text != null && b.text !== "") return escHtml(String(b.text));
  if (b.definition != null && b.definition !== "") return escHtml(String(b.definition));
  return "";
}
