import { escHtml, getSolvedSet, loadMistakes, markMistake, saveSolved, toast, updateSolvedProg } from "../../core.js";
import { _updateProbProgressBanner } from "../pages/problems.js";
import { updateProg } from "../layout/router.js";
// بلوک تمرین یک مسئله: پاسخ‌دهی، راهنمای مرحله‌ای، بازخورد تشخیصی و تاریخچهٔ تلاش‌ها.
// فقط برای مسئله‌هایی که answerSpec دارند فعال می‌شود؛ بقیه همان خودارزیابی قبلی را دارند.
//
// قرارداد UI ↔ موتور:
//  - بررسی و تشخیص: AnswerCheck (خالص)
//  - ثبت تلاش: LearningState.recordAttempt (IndexedDB، با سقوط به حافظه)
//  - حل‌شدن: خودکار با پاسخ درست؛ دفتر اشتباهات: خودکار با پاسخ نادرست (کاربر هر دو را می‌تواند دستی برگرداند)
(function initPractice(global) {
  "use strict";

  const HISTORY_SHOWN = 5;
  const RESULT_LABEL = {
    correct: "درست",
    incorrect: "نادرست",
    "unit-missing": "واحد ناقص",
    "unit-mismatch": "واحد نادرست",
    invalid: "ورودی نامعتبر",
    unchecked: "بدون بررسی",
  };

  function findProblem(pid) {
    const list = (global.CourseRuntime && CourseRuntime.getProblems()) || [];
    return list.find((p) => p && p.id === pid) || null;
  }

  function readInput(spec, root) {
    if (spec.type === "choice") {
      const sel = root.querySelector('input[name="pr-choice-' + root.dataset.pid + '"]:checked');
      return sel ? Number(sel.value) : null;
    }
    const el = root.querySelector(".pr-input");
    return el ? el.value : "";
  }

  function fmtTime(at) {
    try {
      return new Date(at).toLocaleString("fa-IR", { dateStyle: "short", timeStyle: "short" });
    } catch (_) {
      return "";
    }
  }

  function inputControls(p, pid) {
    const spec = p.answerSpec;
    if (spec.type === "choice") {
      return (spec.options || [])
        .map(
          (o, i) =>
            `<label class="pr-opt"><input type="radio" name="pr-choice-${escHtml(pid)}" value="${i}"><span class="lt">${["الف", "ب", "ج", "د", "ه", "و"][i] || i + 1}</span><span>${escHtml(o)}</span></label>`,
        )
        .join("");
    }
    if (spec.type === "numeric") {
      const unit = spec.unit ? `<span class="pr-unit" dir="ltr">${escHtml(spec.unit)}</span>` : "";
      return `<div class="pr-numeric"><input class="pr-input" dir="ltr" inputmode="decimal" autocomplete="off" aria-label="پاسخ عددی" placeholder="عدد${spec.unit ? " و واحد" : ""}">${unit}</div>`;
    }
    return `<input class="pr-input" type="text" autocomplete="off" aria-label="پاسخ متنی" placeholder="پاسخ خود را بنویسید">`;
  }

  function mountPractice(art) {
    if (!art || !art.id) return;
    const p = findProblem(art.id);
    if (!p || !p.answerSpec || typeof AnswerCheck === "undefined") return;
    if (AnswerCheck.validateSpec(p.answerSpec).length) return;

    const pid = p.id;
    const hints = Array.isArray(p.hints) ? p.hints : [];
    const root = document.createElement("section");
    root.className = "practice";
    root.dataset.pid = pid;
    root.innerHTML = `
      <div class="pr-head"><span class="pr-kick">تمرین</span></div>
      <form class="pr-form" novalidate>
        ${inputControls(p, pid)}
        <button type="submit" class="btn g pr-check">بررسی پاسخ</button>
      </form>
      <div class="pr-feedback" role="status" aria-live="polite"></div>
      <div class="pr-hints">
        ${hints.length ? `<button type="button" class="btn ghost btn-sm pr-hint-btn">راهنما (۰ از ${hints.length})</button><ol class="pr-hint-list"></ol>` : ""}
      </div>
      <div class="pr-history" aria-live="polite"></div>`;
    const slot = art.querySelector(".practice-slot");
    if (slot) slot.replaceWith(root);
    else {
      const meta = art.querySelector(".meta-box");
      if (meta) meta.after(root);
      else art.appendChild(root);
    }

    let hintsShown = 0;
    const hintBtn = root.querySelector(".pr-hint-btn");
    const hintList = root.querySelector(".pr-hint-list");
    if (hintBtn) {
      hintBtn.onclick = () => {
        if (hintsShown >= hints.length) return;
        const li = document.createElement("li");
        li.textContent = String(hints[hintsShown]);
        hintList.appendChild(li);
        hintsShown++;
        hintBtn.textContent =
          hintsShown >= hints.length
            ? "همهٔ راهنمایی‌ها نشان داده شد"
            : `راهنمای بعدی (${AnswerCheck.toAsciiDigits(hintsShown)} از ${AnswerCheck.toAsciiDigits(hints.length)})`;
        hintBtn.disabled = hintsShown >= hints.length;
      };
    }

    const fb = root.querySelector(".pr-feedback");
    const form = root.querySelector(".pr-form");
    form.addEventListener("submit", (e) => {
      e.preventDefault();
      const value = readInput(p.answerSpec, root);
      const result = AnswerCheck.checkAnswer(p.answerSpec, value);
      const msgs = AnswerCheck.diagnose(p.answerSpec, value, result);
      renderFeedback(fb, result, msgs);

      if (result.status === "correct") {
        const set = getSolvedSet();
        if (!set.has(pid)) {
          set.add(pid);
          saveSolved();
          if (typeof updateSolvedProg === "function") updateSolvedProg();
          if (typeof _updateProbProgressBanner === "function") _updateProbProgressBanner();
          art.dataset.state = "solved";
          const btn = art.querySelector(".prob-act.solve");
          if (btn) btn.setAttribute("aria-pressed", "true");
        }
      }
      if (result.status !== "correct" && result.status !== "invalid" && typeof markMistake === "function") {
        if (!loadMistakes()[pid]) markMistake(pid, { title: p.title || pid, section: "" });
      }
      if (result.status !== "invalid") {
        LearningState.recordAttempt({
          pid,
          packId: CourseRuntime.getActivePackId() || "",
          status: result.status,
          input: value == null ? "" : String(value),
          hintsUsed: hintsShown,
        })
          .then(() => {
            refreshHistory(root, pid);
            if (typeof updateProg === "function") updateProg();
          })
          .catch(() => toastSafe("ثبت تلاش ممکن نشد"));
      }
      if (typeof window._updateProbSidebar === "function") window._updateProbSidebar();
    });

    refreshHistory(root, pid);
  }

  function renderFeedback(fb, result, msgs) {
    const ok = result.status === "correct";
    const label = RESULT_LABEL[result.status] || result.status;
    fb.dataset.status = result.status;
    fb.innerHTML = `
      <div class="pr-verdict ${ok ? "is-ok" : "is-bad"}"><b>${escHtml(label)}</b></div>
      ${ok ? "" : msgs.length ? `<ul class="pr-diag">${msgs.map((m) => `<li>${escHtml(m)}</li>`).join("")}</ul>` : ""}
      ${ok ? `<p class="pr-note">پاسخ درست ثبت و مسئله حل‌شده علامت خورد.</p>` : ""}`;
  }

  async function refreshHistory(root, pid) {
    const box = root.querySelector(".pr-history");
    if (!box) return;
    let rows = [];
    try {
      rows = await LearningState.attemptsFor(pid);
    } catch (_) {
      rows = [];
    }
    if (!rows.length) {
      box.innerHTML = `<p class="pr-note">هنوز تلاشی ثبت نشده است.</p>`;
      return;
    }
    const correct = rows.filter((r) => r.status === "correct").length;
    const items = rows
      .slice(0, HISTORY_SHOWN)
      .map(
        (r) =>
          `<li><span class="pr-h-st st-${escHtml(r.status)}">${escHtml(RESULT_LABEL[r.status] || r.status)}</span><span dir="ltr" class="pr-h-in">${escHtml(r.input || "—")}</span><time>${escHtml(fmtTime(r.at))}</time></li>`,
      )
      .join("");
    box.innerHTML = `
      <details class="pr-hist-d">
        <summary>${escHtml(String(rows.length))} تلاش · ${escHtml(String(correct))} درست</summary>
        <ul class="pr-hist-list">${items}</ul>
      </details>`;
  }

  function toastSafe(msg) {
    if (typeof toast === "function") toast(msg);
  }

  global.mountPractice = mountPractice;
})(typeof window !== "undefined" ? window : globalThis);
