// مقادیر مشتق‌شده از پک: ارجاع مسائل، آمار عمق جلسه و مجموعهٔ قابلیت‌های فعال.
// همه توابع خالص‌اند و فقط به ورودی خود وابسته‌اند (به جز depthTarget که پک فعال را می‌خواند).

import { getCourse } from "../runtime/active.js";
import { FEATURE_DEFAULTS } from "./constants.js";
import type { Course, FeatureSet, Pack, Problem, Session } from "./types.js";

type Dict = Record<string, unknown>;

// مسائل با ارجاع فرمول، به‌صورت id مسئله → فهرست ارجاع‌ها
export function deriveProblemRefs(
  problems: Problem[] | null | undefined,
): Record<string, unknown[]> {
  const out: Record<string, unknown[]> = {};
  (problems || []).forEach((p) => {
    if (p && p.id && Array.isArray(p.refs) && p.refs.length) out[p.id] = p.refs;
  });
  return out;
}

export interface SessionDepth {
  concepts: number;
  formulas: number;
  tips: number;
  diagrams: number;
  summary: number;
  chars: number;
  examples: number;
}

export function sessionDepth(s: Partial<Session> | null | undefined): SessionDepth {
  const session = (s || {}) as Partial<Session>;
  const chars = JSON.stringify(session).length;
  return {
    concepts: (session.concepts || []).length,
    formulas: (session.formulas || []).length,
    tips: (session.tips || []).length,
    diagrams: (session.diagrams || []).length,
    summary: (session.summary || "").length,
    chars,
    examples: (session.concepts || []).filter((c) => c.ex).length,
  };
}

const DEFAULT_DEPTH_TARGET = Object.freeze({
  concepts: 8,
  formulas: 8,
  tips: 5,
  summary: 350,
  chars: 9000,
});

// هدف عمق جلسه؛ meta.depthTarget پک فعال آن را بازنویسی می‌کند
export function depthTarget(): Record<string, number> {
  const c = (getCourse() || {}) as Partial<Course>;
  return Object.assign({}, DEFAULT_DEPTH_TARGET, (c.meta && (c.meta as Dict).depthTarget) || {});
}

// قابلیت‌های فعال: تنظیم صریح meta.features (on/off) یا حضور محتوا (auto)
export function deriveFeatures(pack: Partial<Pack> | null | undefined): FeatureSet {
  const p = (pack || {}) as Partial<Pack>;
  const course = (p.course || {}) as Partial<Course>;
  const raw = ((course.meta && course.meta.features) || {}) as Dict;
  const sessions = (course.sessions || []) as Session[];
  const present: Record<keyof FeatureSet, boolean> = {
    labs: Object.keys(p.widgets || {}).length > 0,
    problems:
      (p.problems || []).length > 0 ||
      ((p.problemSections || []).length > 0 && Object.keys(p.problemHtml || {}).length > 0),
    glossary: Array.isArray(course.glossary) && course.glossary.length > 0,
    refs: sessions.some((s) => (s.formulas || []).length > 0),
    review: (p.reviewCards || []).length > 0 || sessions.some((s) => (s.concepts || []).length > 0),
    exam: (p.assessments || []).length > 0,
    graph: (p.graphNodes || []).length > 0,
  };
  const out = {} as FeatureSet;
  Object.keys(FEATURE_DEFAULTS).forEach((k) => {
    const key = k as keyof FeatureSet;
    const mode = raw[k] != null ? raw[k] : FEATURE_DEFAULTS[k];
    out[key] = mode === "on" ? true : mode === "off" ? false : !!present[key];
  });
  return out;
}
