// فرار HTML. همان پیاده‌سازی core.js (بدون وابستگی به DOM یا global) تا خروجی بایت‌به‌بایت یکی بماند.
export function escHtml(s: unknown): string {
  return String(s == null ? "" : s)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}
