/*
 * Guard — محدودکنندهٔ سطح دسترسی در مرورگر.
 * هشدار: این فقط جلوی کاربر عادی را می‌گیرد. هر کسی با حرفهٔ کافی می‌تواند آن را دور بزند.
 * حفاظت واقعی محتوا باید روی سرور باشد.
 *
 * قوانین:
 *  - کلیدهای توسعه‌دهنده: F12، Ctrl/⌘+Shift+I/J/C، Ctrl/⌘+U، Ctrl/⌘+S، Ctrl/⌘+Alt+I  (Ctrl+P برای چاپ آزاد است)
 *  - انتخاب متن فقط داخل بخش متن جلسات (.rd-sec) و فیلدهای ورودی مجاز است.
 *  - راست‌کلیک فقط روی لینک‌ها و آیتم‌های ناوبری برنامه غیرفعال می‌شود؛ بقیهٔ صفحه منوی مرورگر/برنامه را دارد.
 *  - اگر ابزار توسعه‌دهنده از روی اندازهٔ پنجره تشخیص داده شود، محتوا تار و پیام نمایش داده می‌شود.
 *  - برای مالک: localStorage["lector:guard"] = "off" (فقط روی همان مرورگر).
 *
 * تنظیمات کاربر: جلوه‌ها و کیفیت تأثیری روی گارد ندارند.
 */
(function initGuard(global) {
  "use strict";

  const doc = document;
  const root = doc.documentElement;

  let disabled = false;
  try {
    disabled = global.localStorage.getItem("lector:guard") === "off";
  } catch (_) {}
  if (disabled) return;

  const TEXT_ZONE = ".rd-sec, .allow-select, .glos-card";
  const FIELD = "input, textarea, select, [contenteditable='true']";
  const NAV_LINK = "a[href], [data-sid], .sr-i, [data-nav], [data-href]";
  const DEV_KEYS_SHIFT = ["i", "j", "c"];

  const inText = (el) => !!(el && el.closest && el.closest(TEXT_ZONE));
  const inField = (el) => !!(el && el.closest && el.closest(FIELD));

  // ── ۱. کلیدهای توسعه‌دهنده ──────────────────────────────────────
  const TOAST_MS = 2200;
  let toastEl = null;
  let toastTimer = 0;

  function ensureToast() {
    if (toastEl) return toastEl;
    toastEl = doc.createElement("div");
    toastEl.id = "guardToast";
    toastEl.setAttribute("role", "status");
    toastEl.setAttribute("aria-live", "polite");
    doc.body.appendChild(toastEl);
    return toastEl;
  }

  // نمایش کوتاه و جمع‌وجور؛ برچسب کلید به‌صورت متن امن (textContent) می‌نشیند
  function showBlocked(label) {
    const el = ensureToast();
    el.textContent = "";
    const kbd = doc.createElement("kbd");
    kbd.textContent = label;
    const txt = doc.createElement("span");
    txt.textContent = "در این برنامه غیرفعال است";
    el.append(kbd, txt);
    el.classList.add("on");
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => el.classList.remove("on"), TOAST_MS);
  }

  function comboLabel(e) {
    const mac = /Mac|iPhone|iPad/.test(navigator.platform || "");
    const parts = [];
    if (e.ctrlKey || e.metaKey) parts.push(mac && e.metaKey ? "⌘" : "Ctrl");
    if (e.altKey) parts.push("Alt");
    if (e.shiftKey) parts.push("Shift");
    parts.push(e.key && e.key.length === 1 ? e.key.toUpperCase() : e.key);
    return parts.join("+");
  }

  doc.addEventListener(
    "keydown",
    (e) => {
      const k = String(e.key || "").toLowerCase();
      const mod = e.ctrlKey || e.metaKey;
      const blocked =
        e.key === "F12" ||
        e.keyCode === 123 ||
        (mod && e.shiftKey && DEV_KEYS_SHIFT.includes(k)) ||
        (mod && e.altKey && k === "i") ||
        (mod && !e.shiftKey && (k === "u" || k === "s"));
      if (blocked) {
        e.preventDefault();
        e.stopPropagation();
        showBlocked(comboLabel(e));
      }
    },
    { capture: true },
  );

  // ── ۲. انتخاب متن فقط در بخش متن جلسات ──────────────────────────
  doc.addEventListener("selectstart", (e) => {
    const t = e.target;
    const el = t && t.nodeType === 1 ? t : t && t.parentElement;
    if (inField(el) || inText(el)) return;
    e.preventDefault();
  });

  doc.addEventListener("copy", (e) => {
    const sel = global.getSelection && global.getSelection();
    const anchor = sel && sel.anchorNode;
    const el = anchor && (anchor.nodeType === 1 ? anchor : anchor.parentElement);
    if (inField(doc.activeElement) || inText(el)) return;
    e.preventDefault();
  });

  // ── ۳. راست‌کلیک فقط روی لینک‌ها و ناوبری ───────────────────────
  doc.addEventListener(
    "contextmenu",
    (e) => {
      const t = e.target;
      if (t && t.closest && t.closest(NAV_LINK) && !inField(t)) {
        e.preventDefault();
      }
    },
    { capture: true },
  );

  // ── ۴. تشخیص ابزار توسعه‌دهنده (اندازهٔ پنجره) و تار کردن محتوا ─
  const isDesktop = global.matchMedia && matchMedia("(hover: hover) and (pointer: fine)").matches;
  let flagged = false;
  let overlay = null;

  function ensureStyle() {
    if (doc.getElementById("guardStyle")) return;
    const st = doc.createElement("style");
    st.id = "guardStyle";
    st.textContent =
      "#guardToast{position:fixed;bottom:calc(env(safe-area-inset-bottom,0px) + 18px);left:50%;transform:translate(-50%,10px);z-index:var(--z-toast,120);display:flex;align-items:center;gap:10px;padding:7px 14px 7px 10px;border-radius:999px;background:var(--surface-raised,#111);color:var(--text-primary,#eee);border:1px solid var(--border-subtle,#333);box-shadow:0 8px 24px rgba(0,0,0,.22);font-size:13px;line-height:1;white-space:nowrap;pointer-events:none;opacity:0;transition:opacity .22s ease,transform .22s ease;}" +
      "#guardToast.on{opacity:1;transform:translate(-50%,0);}" +
      "#guardToast kbd{font-family:var(--font-mono,monospace);font-size:12px;padding:4px 7px;border-radius:7px;background:color-mix(in srgb,var(--accent,#6d8bff) 16%,transparent);color:var(--accent,#6d8bff);border:1px solid color-mix(in srgb,var(--accent,#6d8bff) 35%,transparent);}" +
      "@media (prefers-reduced-motion: reduce){#guardToast{transition:none}}" +
      "html.guard-on #main,html.guard-on .shell{filter:blur(10px);transition:filter .3s ease;}" +
      "#guardOverlay{position:fixed;inset:0;z-index:var(--z-guard,150);display:none;align-items:center;justify-content:center;padding:24px;background:rgba(3,7,18,.55);}" +
      "html.guard-on #guardOverlay{display:flex;}" +
      "#guardOverlay .gd-box{max-width:420px;padding:22px 24px;border-radius:16px;background:var(--surface-raised,#111);color:var(--text-primary,#eee);border:1px solid var(--border-subtle,#333);text-align:center;line-height:1.9;font-size:14px;}";
    doc.head.appendChild(st);
  }
  ensureStyle();

  function ensureOverlay() {
    if (overlay) return overlay;
    ensureStyle();
    overlay = doc.createElement("div");
    overlay.id = "guardOverlay";
    overlay.setAttribute("role", "alert");
    overlay.innerHTML =
      '<div class="gd-box">محتوای این صفحه برای حفاظت از حق مؤلف محدود شده است.<br>با بستن ابزار توسعه‌دهنده، نمایش برمی‌گردد.</div>';
    doc.body.appendChild(overlay);
    return overlay;
  }

  function setGuard(on) {
    ensureOverlay();
    root.classList.toggle("guard-on", on);
  }

  function flagDevtools() {
    if (!flagged) {
      flagged = true;
      setGuard(true);
    }
    lastFlag = Date.now();
  }
  let lastFlag = 0;

  function sizeCheck() {
    if (!isDesktop) return;
    const dw = global.outerWidth - global.innerWidth;
    const dh = global.outerHeight - global.innerHeight;
    const open = dw > 180 || dh > 220;
    if (open) flagDevtools();
    else if (flagged && Date.now() - lastFlag > 800) {
      flagged = false;
      setGuard(false);
    }
  }

  if (isDesktop) {
    global.addEventListener("resize", sizeCheck, { passive: true });
    setInterval(sizeCheck, 1000);
  }

  global.Guard = Object.freeze({ flagged: () => flagged });
})(window);
