(function () {
  "use strict";
  const K = window.PackWidgetKit;
  const wpal = K.wpal;
  let P = wpal();
  globalThis.addEventListener("lector:theme", () => {
    P = wpal();
  });
  const W = {
    title: "شکست نور و بازتاب کلی داخلی",
    desc: "قانون اسنل $n_1\\sin\\theta_1=n_2\\sin\\theta_2$ را به‌صورت زنده آزمایش کنید.",
    sess: ["s06", "s08", "s10"],
    mount(box) {
      box.innerHTML = `<div class="wgrid"><div class="wstage"><svg viewBox="0 0 680 420"></svg></div><div><div class="ctls"></div><div class="winfo"></div></div></div>`;
      const sg = box.querySelector("svg"),
        ct = box.querySelector(".ctls"),
        info = box.querySelector(".winfo");
      let n1 = 1.0,
        n2 = 1.5,
        th = 40;
      ctl(ct, "ضریب شکست محیط ۱ — بالا", 1, 2.4, 0.01, 1, "", (v) => {
        n1 = v;
        draw();
      });
      ctl(ct, "ضریب شکست محیط ۲ — پایین", 1, 2.4, 0.01, 1.5, "", (v) => {
        n2 = v;
        draw();
      });
      ctl(ct, "زاویهٔ تابش θ₁", 0, 89, 1, 40, "°", (v) => {
        th = v;
        draw();
      });
      function line(x1, y1, x2, y2, st, w = 2.5, dash) {
        const l = svgEl("line", { x1, y1, x2, y2, stroke: st, "stroke-width": w }, sg);
        if (dash) l.setAttribute("stroke-dasharray", dash);
      }
      function txt(x, y, t, fill, sz = 12, anc = "middle") {
        const e = svgEl(
          "text",
          {
            x,
            y,
            fill,
            "font-size": sz,
            "text-anchor": anc,
            "font-family": "Vazirmatn",
          },
          sg,
        );
        e.textContent = t;
      }
      function draw() {
        P = wpal();
        sg.innerHTML = "";
        const CX = 340,
          CY = 210,
          L = 190;
        svgEl(
          "rect",
          {
            x: 20,
            y: 20,
            width: 640,
            height: CY - 20,
            fill: `rgba(56,189,248,${0.05 + n1 * 0.07})`,
          },
          sg,
        );
        svgEl(
          "rect",
          {
            x: 20,
            y: CY,
            width: 640,
            height: 190,
            fill: `rgba(96,165,250,${0.06 + n2 * 0.11})`,
          },
          sg,
        );
        line(20, CY, 660, CY, "#8fa3d9", 2);
        line(CX, 30, CX, 400, "#64748b", 1.4, "6 6");
        const a1 = (th * Math.PI) / 180,
          s2 = (n1 * Math.sin(a1)) / n2;
        line(CX - L * Math.sin(a1), CY - L * Math.cos(a1), CX, CY, "#fcd34d");
        const tir = s2 > 1;
        line(
          CX,
          CY,
          CX + L * Math.sin(a1),
          CY - L * Math.cos(a1),
          tir ? "#fcd34d" : "#8fa3d9",
          tir ? 2.5 : 1.6,
          tir ? null : "5 6",
        );
        if (!tir) {
          const a2 = Math.asin(s2);
          line(CX, CY, CX + L * Math.sin(a2), CY + L * Math.cos(a2), "#38bdf8");
          txt(CX + 14, CY + 70, "θ₂", "#38bdf8", 15, "start");
          txt(CX + 14, CY - 52, "θ₁", "#fcd34d", 15, "start");
        } else txt(CX + 14, CY - 52, "θ₁", "#fcd34d", 15, "start");
        txt(90, 48, "محیط ۱ — n₁=" + n1.toFixed(2), "#a5f3fc", 13, "start");
        txt(90, 392, "محیط ۲ — n₂=" + n2.toFixed(2), "#bfdbfe", 13, "start");
        if (tir) txt(340, 60, "بازتاب کلی داخلی — پرتو شکستی وجود ندارد", "#fb7185", 15);
        const thc = n1 > n2 ? (Math.asin(n2 / n1) * 180) / Math.PI : null;
        info.innerHTML = `<div class="row"><span>زاویهٔ تابش θ₁</span><b>${toFa(th)}°</b></div>
  <div class="row"><span>زاویهٔ شکست θ₂</span><b>${tir ? "— بازتاب کلی" : toFa(((Math.asin(s2) * 180) / Math.PI).toFixed(1)) + "°"}</b></div>
  <div class="row"><span>نسبت شکست</span><b>${tir ? "پرتو به محیط ۲ نمی‌رود" : "پرتو " + (n2 > n1 ? "به نرمال نزدیک" : "از نرمال دور") + " می‌شود"}</b></div>
  ${thc !== null ? `<div class="row"><span>زاویهٔ حد θ_c</span><b>${toFa(thc.toFixed(1))}°</b></div>` : ""}
  <div class="props">${tir ? '<span class="badge b-ros">بازتاب با ضریب ۱ — بدون اتلاف</span>' : '<span class="badge b-cyn">شکست مطابق قانون اسنل</span>'}${thc !== null ? '<span class="badge b-amb">شرط بازتاب کلی: θ₁ &gt; θ_c</span>' : ""}</div>`;
      }
      draw();
    },
  };
  CourseRuntime.registerPackSource("optics", { widgets: { refraction: W } });
})();
