// KaTeX و auto-render کلاسیک‌اند و window.katex / window.renderMathInElement می‌سازند.
// ترتیب مهم است (auto-render به katex نیاز دارد) و app قبل از آن بوت نمی‌شود.
const loadClassicScript = (src) =>
  new Promise((resolve, reject) => {
    const el = document.createElement("script");
    el.src = src;
    el.onload = () => resolve();
    el.onerror = () => reject(new Error("failed to load " + src));
    document.head.appendChild(el);
  });
await loadClassicScript(katexUrl);
await loadClassicScript(autoRenderUrl);
await bootstrap();
