(function () {
  "use strict";
  const K = window.PackWidgetKit;
  const wpal = K.wpal;
  let P = wpal();
  globalThis.addEventListener("lector:theme", () => {
    P = wpal();
  });
  const W = {
    title: "موج الکترومغناطیسی — میدان‌های E و B",
    desc: "دو میدان هم‌فاز، عمود بر هم و عمود بر راستای انتشار؛ $E_0=cB_0$.",
    sess: ["s13"],
    mount(box) {
      box.innerHTML = `<div class="wstage"><canvas width="700" height="330"></canvas></div><div style="display:flex;gap:14px;align-items:center;margin-top:12px;flex-wrap:wrap"><div class="ctls" style="flex:1;min-width:180px;margin:0"></div><div class="ctls" style="flex:1;min-width:180px;margin:0"></div><button class="btn" id="emPlay">${icon("pause")} توقف</button></div>`;
      const cv = box.querySelector("canvas"),
        x = setupHD(cv, 700, 330);
      let t = 0,
        lam = 170,
        sp = 1,
        play = true;
      ctl(box.querySelectorAll(".ctls")[0], "طول‌موج", 90, 280, 5, 170, "واحد", (v) => (lam = v));
      ctl(box.querySelectorAll(".ctls")[1], "سرعت نمایش", 0.2, 2.5, 0.1, 1, "", (v) => (sp = v));
      box.querySelector("#emPlay").onclick = (e) => {
        play = !play;
        e.target.innerHTML = play ? `${icon("pause")} توقف` : `${icon("play")} پخش`;
      };

      const A_E = 88,
        A_B = 60;
      const cy = 168,
        x0 = 44,
        x1 = 656;

      const angleZ = Math.PI / 6;
      const cosZ = Math.cos(angleZ);
      const sinZ = Math.sin(angleZ);

      let _visible = true;
      try {
        const _io = new IntersectionObserver(
          (entries) => entries.forEach((e) => { _visible = e.isIntersecting; }),
          { threshold: 0 },
        );
        _io.observe(cv);
      } catch (_) {}

      function frame() {
        if (!cv.isConnected) return;
        if (!_visible || document.hidden || window.__APP_PAUSED) {
          requestAnimationFrame(frame);
          return;
        }
        if (play) t += 0.05 * sp;
        x.fillStyle = P.bg;
        x.fillRect(0, 0, 700, 330);

        x.strokeStyle = P.axis;
        x.lineWidth = 1.5;
        x.beginPath();
        x.moveTo(x0 - 10, cy);
        x.lineTo(x1 + 18, cy);
        x.stroke();
        x.fillStyle = "#3b4770";
        x.beginPath();
        x.moveTo(x1 + 18, cy);
        x.lineTo(x1 + 6, cy - 6);
        x.lineTo(x1 + 6, cy + 6);
        x.fill();
        x.font = "bold 12px Vazirmatn";
        x.textAlign = "center";
        x.fillStyle = "#fbbf24";
        x.fillText("راستای انتشار (x)", x1 - 70, cy - 14);

        x.strokeStyle = "rgba(251, 113, 133, 0.3)";
        x.lineWidth = 1;
        x.setLineDash([5, 5]);
        x.beginPath();
        x.moveTo(x0, cy - A_E - 20);
        x.lineTo(x0, cy + A_E + 20);
        x.stroke();
        x.setLineDash([]);
        x.fillStyle = "#fb7185";
        x.fillText("محور E (y)", x0, cy - A_E - 25);

        const zLen = 100;
        const zx = x0 + zLen * cosZ;
        const zy = cy + zLen * sinZ;
        x.strokeStyle = "rgba(56, 189, 248, 0.3)";
        x.lineWidth = 1;
        x.setLineDash([5, 5]);
        x.beginPath();
        x.moveTo(x0, cy);
        x.lineTo(zx, zy);
        x.stroke();
        x.setLineDash([]);
        x.fillStyle = "#38bdf8";
        x.textAlign = "left";
        x.fillText("محور B (z)", zx + 5, zy + 5);

        const k = (2 * Math.PI) / lam;

        x.strokeStyle = "rgba(251,113,133,.25)";
        x.lineWidth = 1;
        for (let X = x0; X <= x1; X += 14) {
          const s = Math.sin(k * (X - x0) - t);
          x.beginPath();
          x.moveTo(X, cy);
          x.lineTo(X, cy - A_E * s);
          x.stroke();
        }
        x.strokeStyle = "#fb7185";
        x.lineWidth = 2.6;
        x.beginPath();
        for (let X = x0; X <= x1; X++) {
          const Y = cy - A_E * Math.sin(k * (X - x0) - t);
          X === x0 ? x.moveTo(X, Y) : x.lineTo(X, Y);
        }
        x.stroke();
        x.textAlign = "center";
        x.fillStyle = "#fb7185";
        x.fillText("میدان الکتریکی E", x0 + 70, cy - A_E - 12);

        x.strokeStyle = "#38bdf8";
        x.lineWidth = 2.4;
        x.beginPath();
        for (let X = x0; X <= x1; X++) {
          const phase = k * (X - x0) - t;
          const s = Math.sin(phase);
          const z_val = A_B * s;

          const screenX = X + z_val * cosZ;
          const screenY = cy + z_val * sinZ;

          X === x0 ? x.moveTo(screenX, screenY) : x.lineTo(screenX, screenY);
        }
        x.stroke();

        x.strokeStyle = "rgba(56,189,248,.15)";
        x.lineWidth = 1;
        for (let X = x0; X <= x1; X += 14) {
          const phase = k * (X - x0) - t;
          const s = Math.sin(phase);
          const z_val = A_B * s;
          const screenX = X + z_val * cosZ;
          const screenY = cy + z_val * sinZ;
          x.beginPath();
          x.moveTo(X, cy);
          x.lineTo(screenX, screenY);
          x.stroke();
        }

        x.fillStyle = "#38bdf8";
        x.textAlign = "center";
        x.fillText("میدان مغناطیسی B", x1 - 80, cy + 52);

        requestAnimationFrame(frame);
      }
      frame();
    },
  };
  CourseRuntime.registerPackSource("optics", { widgets: { emwave: W } });
})();
