// Presentation (قالب نمایش) به‌صورت توابع خالص: resolvePresentation / currentPresentation / applyPresentation.
// هیچ توابعی به DOM یا به global وابسته نیست؛ استثنا فقط در پوشش سازگاری global `Presentation`
// (برای کدهای JS موجود) که مقدار را از CourseRuntime می‌خواند و روی یک عنصر DOM اعمال می‌کند.

export type Reader = "classic" | "prism" | "atlas" | "notebook";
export type Structure = "linear" | "tree" | "graph";
export type Tokens = Readonly<Record<string, number>>;
export type ReaderId = Reader; // نام قدیمی

export interface ReaderDef {
  id: Reader;
  label: string;
  readerMax: string;
}

export type IssueLevel = "info" | "warn" | "error";

export interface PresentationIssue {
  level: IssueLevel;
  path: string;
  msg: string;
}

// مقدار حل‌شدهٔ presentation (بعد از normalizeMeta)
export interface PresentationValue {
  archetype: string;
  reader: Reader;
  readerMax: string;
  structure: Structure;
  defaults: Readonly<Record<string, string>>;
  tokens: Tokens;
}

// ورودی خام (meta یا presentation) که ممکن است ناقص یا نامعتبر باشد
export interface PresentationConfig {
  presentation?: unknown;
  archetype?: unknown;
  layout?: unknown;
  structure?: unknown;
  [key: string]: unknown;
}

// کوچک‌ترین سطحی از عنصر DOM که apply به آن نیاز دارد (برای تست بدون DOM)
export interface PresentationTarget {
  setAttribute(name: string, value: string): void;
  style: {
    setProperty(name: string, value: string): void;
    removeProperty(name: string): void;
  };
}

export const READERS: Readonly<Record<Reader, ReaderDef>> = Object.freeze({
  classic: Object.freeze({ id: "classic", label: "کلاسیک", readerMax: "46rem" }),
  prism: Object.freeze({ id: "prism", label: "منشور", readerMax: "56rem" }),
  atlas: Object.freeze({ id: "atlas", label: "اطلس", readerMax: "none" }),
  notebook: Object.freeze({ id: "notebook", label: "دفترچه", readerMax: "52rem" }),
});

export const STRUCTURES: Readonly<Record<Structure, boolean>> = Object.freeze({
  linear: true,
  tree: false,
  graph: false,
});

const DEFAULT = Object.freeze({
  archetype: "stem",
  reader: "classic" as Reader,
  structure: "linear" as Structure,
});

const TOKEN_LIMITS: Readonly<Record<string, readonly [number, number]>> = Object.freeze({
  readingLine: Object.freeze([1.4, 2.4] as const),
  sessionGap: Object.freeze([8, 40] as const),
});

const DEFAULT_OPTIONS: Readonly<Record<string, readonly string[]>> = Object.freeze({
  width: ["narrow", "wide"],
  density: ["comfortable", "compact"],
  fs: ["small", "medium", "large"],
  font: ["vazirmatn", "naskh", "system"],
  lh: ["normal", "relaxed", "loose"],
  justify: ["start", "justify"],
});

// فهرست آرکی‌تایپ‌های شناخته‌شده؛ اگر ArchetypeRegistry روی global باشد از آن می‌خواند
export function knownArchetypes(): string[] {
  try {
    const reg = (globalThis as { ArchetypeRegistry?: { list?: () => string[] } }).ArchetypeRegistry;
    if (reg && typeof reg.list === "function") return reg.list();
  } catch {
    // ignore: fall through to defaults
  }
  return ["stem", "narrative", "base"];
}

function clamp(n: number, [lo, hi]: readonly [number, number]): number {
  return Math.min(hi, Math.max(lo, n));
}

export function resolvePresentation(
  meta: PresentationConfig | null | undefined,
  known: readonly string[] = knownArchetypes(),
): { value: PresentationValue; issues: PresentationIssue[] } {
  const m: PresentationConfig = meta && typeof meta === "object" ? meta : {};
  const issues: PresentationIssue[] = [];
  const add = (level: IssueLevel, path: string, msg: string) => issues.push({ level, path, msg });

  const hasBlock = m.presentation && typeof m.presentation === "object";
  const legacy = !!(m.archetype || m.layout || m.structure);
  const src: PresentationConfig = hasBlock ? (m.presentation as PresentationConfig) : {};
  if (!hasBlock && legacy) {
    add(
      "warn",
      "meta.archetype/layout/structure",
      "فیلدهای جدا منسوخ‌اند — به meta.presentation منتقل شوند",
    );
  }
  const pick = (blockVal: unknown, legacyVal: unknown): unknown =>
    hasBlock ? blockVal : legacyVal !== undefined ? legacyVal : undefined;

  let archetype = (pick(src.archetype, m.archetype) || DEFAULT.archetype) as string;
  if (!known.includes(archetype)) {
    add(
      "warn",
      "presentation.archetype",
      "آرکی‌تایپ «" + archetype + "» شناخته نشد — به stem تنزل می‌کند",
    );
    archetype = DEFAULT.archetype;
  }

  let reader = (pick(src.reader, m.layout) || DEFAULT.reader) as string;
  if (!Object.prototype.hasOwnProperty.call(READERS, reader)) {
    add(
      "warn",
      "presentation.reader",
      "قالب مطالعه «" + reader + "» ناشناخته است — به classic تنزل می‌کند",
    );
    reader = DEFAULT.reader;
  }

  let structure = (pick(src.structure, m.structure) || DEFAULT.structure) as string;
  if (!Object.prototype.hasOwnProperty.call(STRUCTURES, structure)) {
    add(
      "warn",
      "presentation.structure",
      "ساختار «" + structure + "» ناشناخته است — به linear تنزل می‌کند",
    );
    structure = DEFAULT.structure;
  } else if (!STRUCTURES[structure as Structure]) {
    add(
      "warn",
      "presentation.structure",
      "ساختار «" + structure + "» هنوز در موتور پیاده‌سازی نشده — linear اعمال می‌شود",
    );
    structure = DEFAULT.structure;
  }

  const defaults: Record<string, string> = {};
  const rawDefaults: Record<string, unknown> =
    src.defaults && typeof src.defaults === "object"
      ? (src.defaults as Record<string, unknown>)
      : {};
  Object.keys(rawDefaults).forEach((key) => {
    const allowed = DEFAULT_OPTIONS[key];
    if (!allowed) {
      add("warn", "presentation.defaults." + key, "کلید پیش‌فرض ناشناخته است");
      return;
    }
    const value = rawDefaults[key];
    if (typeof value === "string" && allowed.includes(value)) defaults[key] = value;
    else add("warn", "presentation.defaults." + key, "مقدار «" + String(value) + "» مجاز نیست");
  });

  const tokens: Record<string, number> = {};
  const rawTokens: Record<string, unknown> =
    src.tokens && typeof src.tokens === "object" ? (src.tokens as Record<string, unknown>) : {};
  Object.keys(rawTokens).forEach((key) => {
    const lim = TOKEN_LIMITS[key];
    const v = +(rawTokens[key] as number);
    if (!lim) {
      add("warn", "presentation.tokens." + key, "توکن ناشناخته است");
      return;
    }
    if (!Number.isFinite(v)) {
      add("warn", "presentation.tokens." + key, "عدد نامعتبر");
      return;
    }
    const c = clamp(v, lim);
    if (c !== v)
      add(
        "info",
        "presentation.tokens." + key,
        "مقدار " + v + " خارج از بازهٔ مجاز بود و به " + c + " کلَمپ شد",
      );
    tokens[key] = c;
  });

  const reader_ = reader as Reader;
  const value: PresentationValue = Object.freeze({
    archetype,
    reader: reader_,
    readerMax: READERS[reader_].readerMax,
    structure: structure as Structure,
    defaults: Object.freeze(defaults),
    tokens: Object.freeze(tokens),
  });
  return { value, issues };
}

// meta را در جا با مقدار حل‌شده پر می‌کند (presentation + فیلدهای سازگاری) و مسائل را برمی‌گرداند
export function normalizePresentationMeta(meta: PresentationConfig): PresentationIssue[] {
  const r = resolvePresentation(meta);
  meta.presentation = r.value;
  meta.archetype = r.value.archetype;
  meta.layout = r.value.reader;
  meta.structure = r.value.structure;
  return r.issues;
}

// کش بر اساس هویت شیٔ meta: همان شیء دوباره حل نمی‌شود
const cache = new WeakMap<object, PresentationValue>();
let fallbackValue: PresentationValue | null = null;

export function currentPresentation(meta?: PresentationConfig | null): PresentationValue {
  if (meta && typeof meta === "object") {
    if (meta.presentation && (meta.presentation as PresentationValue).reader)
      return meta.presentation as PresentationValue;
    const hit = cache.get(meta);
    if (hit) return hit;
    const value = resolvePresentation(meta).value;
    cache.set(meta, value);
    return value;
  }
  if (!fallbackValue) fallbackValue = resolvePresentation(null).value;
  return fallbackValue;
}

// مقدار پیش‌فرض یک گزینهٔ خواننده (width، fs، …) از presentation.defaults
export function presentationDefault(
  value: PresentationValue,
  key: string,
  fallback: string,
): string {
  const d = value.defaults || {};
  return Object.prototype.hasOwnProperty.call(d, key) ? (d[key] as string) : fallback;
}

// متغیرهای CSS و data-attribute را روی هدف می‌نویسد؛ بدون DOM مستقیم
export function applyPresentation(target: PresentationTarget, value: PresentationValue): void {
  target.setAttribute("data-archetype", value.archetype);
  target.setAttribute("data-layout", value.reader);
  target.setAttribute("data-structure", value.structure);
  target.style.setProperty("--reader-max", value.readerMax);
  if (value.tokens.readingLine != null)
    target.style.setProperty("--archetype-reading-line", String(value.tokens.readingLine));
  else target.style.removeProperty("--archetype-reading-line");
  if (value.tokens.sessionGap != null)
    target.style.setProperty("--archetype-session-gap", value.tokens.sessionGap + "px");
  else target.style.removeProperty("--archetype-session-gap");
}

// ── پوشش سازگاری global ───────────────────────────────────────────────
// کدهای JS موجود از Presentation.* استفاده می‌کنند؛ این بخش فقط به همین‌ها واسطه می‌شود.

export interface PresentationApi {
  READERS: typeof READERS;
  STRUCTURES: typeof STRUCTURES;
  resolve(meta: PresentationConfig | null | undefined): {
    value: PresentationValue;
    issues: PresentationIssue[];
  };
  normalizeMeta(meta: PresentationConfig): PresentationIssue[];
  current(): PresentationValue;
  prefDefault(key: string, fallback: string): string;
  apply(root?: PresentationTarget | null): void;
}

declare global {
  interface Window {
    Presentation: PresentationApi;
  }
  var Presentation: PresentationApi;
}

function currentFromRuntime(): PresentationValue {
  let meta: PresentationConfig | null | undefined = null;
  try {
    const rt = (globalThis as { CourseRuntime?: { getCourse?: () => unknown } }).CourseRuntime;
    const C = rt && rt.getCourse ? (rt.getCourse() as { meta?: PresentationConfig }) : null;
    meta = C && C.meta;
  } catch {
    // CourseRuntime ممکن است هنوز نصب نشده باشد
  }
  return currentPresentation(meta);
}

(function installGlobal(g: typeof globalThis) {
  "use strict";
  const api: PresentationApi = Object.freeze({
    READERS,
    STRUCTURES,
    resolve: (meta: PresentationConfig | null | undefined) => resolvePresentation(meta),
    normalizeMeta: normalizePresentationMeta,
    current: currentFromRuntime,
    prefDefault: (key: string, fallback: string) =>
      presentationDefault(currentFromRuntime(), key, fallback),
    apply(root?: PresentationTarget | null) {
      const html =
        root ||
        ((g as { document?: { documentElement?: PresentationTarget } }).document
          ?.documentElement as PresentationTarget | undefined);
      if (!html) return;
      applyPresentation(html, currentFromRuntime());
    },
  });
  g.Presentation = api;
})(typeof window !== "undefined" ? window : globalThis);
