export function _readerBlock(s, b) {
  return BlockRenderers.render(b, { session: s, archetype: ArchetypeRegistry.getActive() });
}

export function _readerSection(s, sec, i) {
  const titleHTML = sec.title
    ? `<h2><span class="rd-sec-num">${toFa(i + 1)}</span>${escHtml(sec.title)}</h2>`
    : "";
  const blocks = sec.blocks.map((b) => _readerBlock(s, b)).join("");
  return `<section class="rd-sec" id="${escHtml(sec.id)}">${titleHTML}${blocks}</section>`;
}

export function _currentLayout() {
  return document.documentElement.getAttribute("data-layout") || "classic";
}

export function _layoutSection(s, sec, i, layout) {
  const titleHTML = sec.title
    ? `<h2><span class="rd-sec-num">${toFa(i + 1)}</span>${escHtml(sec.title)}</h2>`
    : "";
  const allBlocks = sec.blocks.map((b) => _readerBlock(s, b)).join("");

  if (layout === "classic") {
    const mainB = [];
    const sideB = [];
    sec.blocks.forEach((b) => {
      if (b.type === "callout") sideB.push(b);
      else mainB.push(b);
    });
    const mainHTML = mainB.map((b) => _readerBlock(s, b)).join("");
    const sideHTML = sideB.map((b) => _readerBlock(s, b)).join("");
    return `<section class="rd-sec rd-sec--classic" id="${escHtml(sec.id)}">
      <div class="rd-classic-grid">
        <div class="rd-classic-main">${titleHTML}${mainHTML}</div>
        ${sideHTML ? `<aside class="rd-classic-side">${sideHTML}</aside>` : ""}
      </div>
    </section>`;
  }

  if (layout === "prism") {
    return `<section class="rd-sec rd-sec--prism" id="${escHtml(sec.id)}">
      <div class="rd-prism-tab">${titleHTML}</div>
      <div class="rd-prism-body">${allBlocks}</div>
    </section>`;
  }

  if (layout === "atlas") {
    return `<section class="rd-sec rd-sec--atlas" id="${escHtml(sec.id)}">
      ${titleHTML}${allBlocks}
    </section>`;
  }

  if (layout === "notebook") {
    const rot = i % 3 === 0 ? "-0.5deg" : i % 3 === 1 ? "0.4deg" : "-0.2deg";
    return `<section class="rd-sec rd-sec--notebook" style="--rot:${rot}" id="${escHtml(sec.id)}">
      ${titleHTML}${allBlocks}
    </section>`;
  }

  return `<section class="rd-sec" id="${escHtml(sec.id)}">${titleHTML}${allBlocks}</section>`;
}

export function _detailSections(s) {
  return ((s.detail && s.detail.sections) || []).filter(
    (sec) => sec && Array.isArray(sec.blocks) && sec.blocks.length,
  );
}
// ── رندر تنبل بخش‌های درس ──────────────────────────────────────────
// هدف: با اسکرول سریع یا باز کردن درس، بیش از یک بخش در یک فریم ساخته نشود و هیچ‌وقت
// بخشی که کاربر به آن می‌رسد خالی نماند.
//  - بخش‌های بالای صفحه (LZ_EAGER) همان لحظه ساخته می‌شوند.
//  - بقیه جای‌نگه‌دار با ارتفاع برآوردی‌اند؛ IntersectionObserver با حاشیهٔ بزرگ آن‌ها را نزدیک viewport خبر می‌دهد.
//  - عنصری که واقعاً داخل viewport است همان لحظه پر می‌شود؛ بقیه در صف، یکی در هر فریم.
//  - هر کلیک روی TOC یا هر anchor، بخش مقصد را قبل از اسکرول پر می‌کند تا موقعیت جابه‌جا نشود.
//  - هر ناوبری یا تغییر حالت، با _lzReset همهٔ کارهای معلق را لغو می‌کند.
export const LZ_EAGER = 2;
export const LZ_MARGIN = "1600px 0px";
export let _lz = null;
export let _lzPending = null;

export function _lzReset() {
  if (!_lz) return;
  const st = _lz;
  _lz = null;
  st.active = false;
  try {
    if (st.io) st.io.disconnect();
  } catch (_) {}
  if (st.raf) cancelAnimationFrame(st.raf);
  if (st.onClick) document.removeEventListener("click", st.onClick, true);
}

export function _lzWire(el, s) {
  try {
    if (typeof katexifyText === "function") katexifyText(el);
    if (typeof runMmd === "function") runMmd(el);
    if (typeof mountWidgetsLazy === "function") mountWidgetsLazy(el);
    if (typeof _wireQuiz === "function") _wireQuiz(el);
    if (typeof _wireFlash === "function") _wireFlash(el);
    if (typeof _wireChecklist === "function") _wireChecklist(el);
    _renderDetailMath(s, el);
  } catch (_) {}
}

export function _lzFillNow(ph) {
  const st = _lz;
  if (!st || !st.active || !ph || !ph.isConnected || ph.dataset.lz == null) return false;
  const ent = st.store.get(ph.dataset.lz);
  if (!ent) return false;
  st.store.delete(ph.dataset.lz);
  const tpl = document.createElement("template");
  tpl.innerHTML = ent.build();
  const added = Array.from(tpl.content.children);
  ph.replaceWith(tpl.content);
  added.forEach((el) => _lzWire(el, st.s));
  if (typeof window._sessRemeasure === "function") window._sessRemeasure();
  return true;
}

export function _lzQueueFill() {
  const st = _lz;
  if (!st || !st.active || st.raf) return;
  st.raf = requestAnimationFrame(() => {
    st.raf = 0;
    if (!st.active || !st.root.isConnected) return;
    while (st.queue.length) {
      const ph = st.queue.shift();
      if (ph && ph.dataset.lz != null && _lzFillNow(ph)) break;
    }
    if (st.queue.length) _lzQueueFill();
  });
}

export function _lzEnsureId(id) {
  if (!_lz || !id) return;
  const el = document.getElementById(id);
  if (el && el.dataset && el.dataset.lz != null) _lzFillNow(el);
}

export function _lzActivate(root, s) {
  _lzReset();
  const store = _lzPending;
  _lzPending = null;
  if (!store || !store.size || !root) return;
  const st = { root, s, store, active: true, queue: [], raf: 0, io: null, onClick: null };
  _lz = st;

  st.onClick = (e) => {
    const a = e.target && e.target.closest ? e.target.closest("[data-target]") : null;
    if (a && a.dataset.target) _lzEnsureId(a.dataset.target);
  };
  document.addEventListener("click", st.onClick, true);

  const phs = Array.from(root.querySelectorAll("[data-lz]"));
  if (!("IntersectionObserver" in window)) {
    st.queue.push(...phs);
    _lzQueueFill();
    return;
  }
  const io = new IntersectionObserver(
    (entries) => {
      if (!st.active) return;
      let syncLeft = 2;
      entries.forEach((en) => {
        if (!en.isIntersecting) return;
        const ph = en.target;
        io.unobserve(ph);
        const r = en.boundingClientRect;
        const inView = r.bottom > 0 && r.top < window.innerHeight;
        if (inView && syncLeft > 0) {
          syncLeft -= 1;
          _lzFillNow(ph);
        } else {
          st.queue.push(ph);
        }
      });
      if (st.queue.length) _lzQueueFill();
    },
    { rootMargin: LZ_MARGIN },
  );
  st.io = io;
  phs.forEach((p) => io.observe(p));
}

export function _readerHTML(s) {
  const d = s.detail;
  const secs = _detailSections(s);
  let nBlocks = 0;
  secs.forEach((sec) => {
    nBlocks += (sec.blocks || []).length;
  });
  const _wcStrip = (s) =>
    String(s || "")
      .replace(/<[^>]*>/g, " ")
      .replace(/&[a-z#0-9]+;/gi, " ")
      .replace(/\s+/g, " ")
      .trim();
  const _wcCount = (s) => {
    const t = _wcStrip(s);
    return t ? t.split(" ").length : 0;
  };
  const words =
    _wcCount(d.intro) +
    _wcCount(d.outro) +
    secs.reduce(
      (acc, sec) =>
        acc +
        (sec.blocks || []).reduce((a, b) => {
          return a + _wcCount(b.html || b.text || "");
        }, 0),
      0,
    );
  const mins = Math.max(3, Math.round(words / 140) || Math.round(nBlocks * 0.6));
  const banner = `<div class="rd-meta-line" data-read-mins="${mins}" data-read-secs="${secs.length}">
<span>${toFa(secs.length)} بخش · حدود ${toFa(mins)} دقیقه</span>
</div>`;
  const intro = d.intro
    ? `<div class="rd-intro">${d.intro
        .split(/\n\n+/)
        .map((p) => `<p class="rd-p">${p}</p>`)
        .join("")}</div>`
    : "";
  const _baseLayout = _currentLayout();
  const layout =
    _baseLayout === "atlas" && (secs.length < 3 || words < 400) ? "classic" : _baseLayout;
  // بخش‌های اول همان لحظه ساخته می‌شوند؛ بقیه فقط جای‌نگه‌دار دارند و در _lzActivate پر می‌شوند.
  const lazyStore = new Map();
  let lazyKey = 0;
  const sections = secs
    .map((sec, i) => {
      const sep = i > 0 && layout === "classic" ? `<hr class="rd-hr">` : "";
      if (i < LZ_EAGER) return sep + _layoutSection(s, sec, i, layout);
      const key = String(lazyKey++);
      const est = Math.min(2400, Math.max(160, (sec.blocks || []).length * 120));
      lazyStore.set(key, { build: () => sep + _layoutSection(s, sec, i, layout) });
      const idAttr = sec.id ? ` id="${escHtml(sec.id)}"` : "";
      return `<section class="rd-lz" data-lz="${key}"${idAttr} style="min-height:${est}px" aria-busy="true"></section>`;
    })
    .join("");
  _lzPending = lazyStore.size ? lazyStore : null;
  const outro = d.outro
    ? `<div class="rd-outro">${d.outro
        .split(/\n\n+/)
        .map((p) => `<p class="rd-p">${p}</p>`)
        .join("")}</div>`
    : "";
  return `<div class="rd-reader rd-reader--${layout}">${banner}${intro}${sections}${outro}${_notesHTML(s)}</div>`;
}

// _katexIO حذف شد — مدیریت از طریق deferKatex در core.js

export function _katexRenderSmart(items) {
  if (!items.length) return;
  const vh = (window.innerHeight || 800) + 500;
  const measured = items.map((it) => {
    const r = it.el.getBoundingClientRect();
    return { ...it, inView: r.top < vh && r.bottom > -500 };
  });
  measured.forEach((it) => {
    if (it.inView) {
      try {
        katex.render(it.tex, it.el, {
          displayMode: it.display,
          throwOnError: false,
          strict: false,
        });
      } catch (_) {
        it.el.textContent = it.tex;
      }
      return;
    }
    deferKatexTex(it.el, it.tex, it.display);
  });
}

export function _renderDetailMath(s, root) {
  const scope = root || main;
  const items = [];
  scope.querySelectorAll(".rd-math").forEach((wrap) => {
    const el = wrap.querySelector(".rd-math-body");
    const tex = wrap.getAttribute("data-tex") || "";
    if (!tex) {
      if (wrap) wrap.remove();
      return;
    }
    items.push({ el, tex, display: true });
  });
  scope.querySelectorAll(".rd-formula").forEach((el) => {
    const ref = el.getAttribute("data-ref");
    const idx = s.formulas.findIndex((f) => f.t === ref);
    if (idx < 0) {
      el.remove();
      return;
    }
    const f = s.formulas[idx];
    const cat = getCat(f.cat);
    const varsHTML = (f.vars || []).length
      ? `<div class="rd-formula-vars">${f.vars.map((v) => `<span class="v"><span dir="ltr" style="font-family:monospace;color:var(--color-cyan)">$${v[0]}$</span><span>${v[1]}</span></span>`).join("")}</div>`
      : "";
    el.innerHTML =
      `<div class="rd-formula-head"><b>${escHtml(f.t)}</b><span class="badge ${cat.c}">${cat.l}</span></div>` +
      `<div class="rd-formula-tex" dir="ltr"></div>` +
      (f.use ? `<div class="rd-formula-use">${f.use}</div>` : "") +
      varsHTML;
    items.push({ el: el.querySelector(".rd-formula-tex"), tex: f.tex, display: true });
  });
  _katexRenderSmart(items);
}

export function _renderReviewFormulas(s) {
  const items = [];
  main.querySelectorAll(".rd-rf-tex[data-tex]").forEach((el) => {
    const tex = el.getAttribute("data-tex") || "";
    if (!tex) {
      el.remove();
      return;
    }
    el.removeAttribute("data-tex");
    items.push({ el, tex, display: true });
  });
  _katexRenderSmart(items);
}

