export function _sessionTemplate() {
  return Presentation.current().reader || "classic";
}

export function _sessionMode(session) {
  const stored = typeof getSessionMode === "function" ? getSessionMode() : "detail";
  const hasDetail = !!(
    session &&
    session.detail &&
    session.detail.sections &&
    session.detail.sections.length
  );
  if (stored === "detail" && !hasDetail) return "brief";
  return ["detail", "brief", "review"].includes(stored) ? stored : "brief";
}

// ── یادداشت‌های جلسه ──
export const _NOTE_MAX = 4000;
export let _notePending = null; // { id, text } تا قبل از ذخیره‌ی واقعی
export let _noteTimer = null;

export function _notesHTML(s) {
  const txt = getNote(s.id);
  return `<details class="sess-notes sess-notes-v2" id="sessNotes" data-sid="${escHtml(s.id)}"${txt ? " open" : ""}>
    <summary>
      <span class="sn-ttl">${icon("pencil")}<span>یادداشت‌های من</span></span>
      <span class="sn-state" id="sessNoteState" data-kind="${txt.trim() ? "saved" : "empty"}" aria-live="polite">${txt.trim() ? "ذخیره شد" : "خالی"}</span>
    </summary>
    <div class="sn-body">
      <textarea id="sessNoteTa" class="sn-ta" maxlength="${_NOTE_MAX}" rows="5"
        placeholder="نکته، سؤال یا تفسیر خودت را بنویس…" aria-label="یادداشت‌های این جلسه">${escHtml(txt)}</textarea>
      <div class="sn-foot">
        <span class="sn-hint">فقط روی همین مرورگر ذخیره می‌شود</span>
        <span class="sn-count" id="sessNoteCount">${toFa(txt.length)} / ${toFa(_NOTE_MAX)}</span>
      </div>
    </div>
  </details>`;
}

export function _noteSetState(kind) {
  const el = document.getElementById("sessNoteState");
  if (!el) return;
  const label = { saving: "در حال ذخیره…", saved: "ذخیره شد", empty: "خالی" }[kind] || "";
  el.textContent = label;
  el.dataset.kind = kind;
}

// نوشتن واقعی در حافظه (همیشه‌ی سریع؛ هم با تأخیر، هم فوری در blur/خروج/تغییر جلسه)
export function _noteFlush() {
  clearTimeout(_noteTimer);
  _noteTimer = null;
  if (!_notePending) return;
  const { id, text } = _notePending;
  _notePending = null;
  try {
    setNote(id, text);
    _noteSetState(text.trim() ? "saved" : "empty");
  } catch (_) {
    if (typeof toast === "function") toast("ذخیرهٔ یادداشت ناموفق بود (فضای کم)", "err");
  }
}

export function _noteOnInput(ta) {
  const det = ta.closest("#sessNotes");
  const sid = det && det.dataset.sid;
  if (!sid) return;
  const v = ta.value;
  const cnt = document.getElementById("sessNoteCount");
  if (cnt) cnt.textContent = `${toFa(v.length)} / ${toFa(_NOTE_MAX)}`;
  _notePending = { id: sid, text: v };
  _noteSetState("saving");
  clearTimeout(_noteTimer);
  _noteTimer = setTimeout(_noteFlush, 350);
}

document.addEventListener("input", (e) => {
  if (e.target && e.target.id === "sessNoteTa") _noteOnInput(e.target);
});
document.addEventListener("focusout", (e) => {
  if (e.target && e.target.id === "sessNoteTa") _noteFlush();
});
window.addEventListener("pagehide", _noteFlush);
document.addEventListener("visibilitychange", () => {
  if (document.hidden) _noteFlush();
});

