export function _vwTocHTML(s, packId) {
  const items = [];
  const _tocSecs = _detailSections(s);

  if (_tocSecs.length) {
    _tocSecs.forEach((sec, i) => {
      items.push({
        id: sec.id,
        num: i + 1,
        label: sec.title || "بخش " + (i + 1),
      });
    });
  } else if (Array.isArray(s.concepts) && s.concepts.length) {
    s.concepts.forEach((c, i) => {
      items.push({
        id: "c-" + s.id + "-" + i,
        num: i + 1,
        label: c.t,
      });
    });
  }

  if (!items.length) {
    return `<div class="sess-toc-empty">
      <p>در این حالت فهرست بخش‌ها موجود نیست.</p>
    </div>`;
  }

  const links = items
    .map(
      (it) => `
    <button type="button" class="vw-toc-sess" data-target="${escHtml(it.id)}">
      <span class="toc-sess-n">${toFa(it.num)}</span>
      <span class="toc-sess-body">
        <span class="toc-sess-tx">${escHtml(it.label)}</span>
      </span>
    </button>
  `,
    )
    .join("");

  return `<div class="toc-head">
    <span class="toc-head-kicker">در این جلسه</span>
    <p class="toc-head-count"><b>${toFa(items.length)}</b> بخش</p>
    <div class="toc-head-prog" aria-hidden="true"><i id="vwTocProgBar"></i></div>
  </div>
  <nav class="toc-list" id="sessTocList" aria-label="فهرست بخش‌ها">
    ${links}
  </nav>`;
}

export function _modeBanner(mode, s) {
  const hasDetail = !!(s.detail && s.detail.sections && s.detail.sections.length);
  if (mode === "detail") return "";
  if (mode === "brief")
    return `<div class="mode-banner">
    ${icon("list")}
    <div>نمای مختصر — <b>${toFa((s.concepts || []).length)} مفهوم، ${toFa((s.formulas || []).length)} فرمول، ${toFa((s.tips || []).length)} نکته</b>.
    ${hasDetail ? "برای متن کامل، «مفصل» را بزنید." : "این جلسه متن مفصل ندارد."}</div>
  </div>`;
  if (mode === "review")
    return `<div class="mode-banner">
    ${icon("bolt")}
    <div><b>حالت مرور</b> — فقط هسته‌ها: تعریف، فرمول، نکتهٔ کلیدی و خودسنجی. برای شب امتحان.</div>
  </div>`;
  return "";
}

export function _animateBanner(el) {
  if (!el || typeof Motion === "undefined") return;
  if (Motion.prefersReduced && Motion.prefersReduced()) return;

  el.style.opacity = "0";
  el.style.transform = "translateY(16px)";
  el.style.filter = "blur(6px)";
  void el.offsetWidth;

  try {
    const anim = el.animate(
      [
        { opacity: 0, transform: "translateY(16px)", filter: "blur(6px)" },
        { opacity: 1, transform: "none", filter: "blur(0px)" },
      ],
      {
        duration: 450,
        easing: "cubic-bezier(.22, 1, .36, 1)",
        fill: "both",
        delay: 40,
      },
    );

    anim.finished
      .then(() => {
        el.style.opacity = "";
        el.style.transform = "";
        el.style.filter = "";
      })
      .catch(() => {
        el.style.opacity = "";
        el.style.transform = "";
        el.style.filter = "";
      });
  } catch (_) {
    el.style.opacity = "";
    el.style.transform = "";
    el.style.filter = "";
  }
}

export function _swapSessionBody(s, newMode) {
  const doc = document.getElementById("doc");
  const body = document.getElementById("docBody");
  if (!doc || !body) return;

  let bodyHTML = "";
  if (newMode === "detail") bodyHTML = _readerHTML(s);
  else if (newMode === "brief") bodyHTML = _briefBodyHTML(s);
  else bodyHTML = _reviewBodyHTML(s);

  doc.classList.remove("mode-detail", "mode-brief", "mode-review");
  doc.classList.add("mode-" + newMode);

  const oldBanner = doc.querySelector(".mode-banner");
  const bannerHTML = _modeBanner(newMode, s);
  if (bannerHTML) {
    const tmp = document.createElement("div");
    tmp.innerHTML = bannerHTML;
    const newBanner = tmp.firstElementChild;
    if (oldBanner) oldBanner.replaceWith(newBanner);
    else doc.querySelector(".doc-head").after(newBanner);
    _animateBanner(newBanner);
  } else if (oldBanner) {
    oldBanner.remove();
  }

  _noteFlush();
  _lzReset();
  body.innerHTML = bodyHTML;
  main.querySelectorAll("[data-tool]").forEach((b) => {
    b.hidden = newMode !== "detail";
  });

  if (newMode === "detail") _renderDetailMath(s);
  else if (newMode === "review") _renderReviewFormulas(s);
  if (typeof after === "function") after(main);
  if (newMode === "brief") mountFormulas(main, s.formulas, s);
  if (newMode === "detail") _lzActivate(body, s);

  if (typeof stagger === "function") stagger(main);
}

export function pageSession(id, anchor) {
  _noteFlush();
  _lzReset();
  if (typeof window._sessCleanup === "function") {
    try {
      window._sessCleanup();
    } catch (_) {}
    window._sessCleanup = null;
  }
  const s = ((CourseRuntime.getCourse() || {}).sessions || []).find((x) => x.id === id);
  if (!s) {
    go("home");
    return;
  }
  setLastVisited(s.id);

  const _oldPrev = document.getElementById("prevS");
  const _oldNext = document.getElementById("nextS");
  const _oldPrevH = _oldPrev ? _oldPrev.offsetHeight : 0;
  const _oldNextH = _oldNext ? _oldNext.offsetHeight : 0;

  const packId = CourseRuntime.getActivePackId();
  const tpl = _sessionTemplate();
  const hasDetail = !!(s.detail && s.detail.sections && s.detail.sections.length);
  const mode = _sessionMode(s);

  let bodyHTML = "";
  if (mode === "detail") {
    bodyHTML = _readerHTML(s);
  } else if (mode === "brief") {
    bodyHTML = _briefBodyHTML(s);
  } else {
    bodyHTML = _reviewBodyHTML(s);
  }

  const kicker = `جلسهٔ ${toFa(s.num)}${s.topics && s.topics[0] ? " · " + escHtml(s.topics[0].slice(0, 40)) : ""}`;
  const metaBits = [];
  if (s.date) metaBits.push(`<span>${icon("cal")} ${escHtml(s.date)}</span>`);
  if (s.time && s.time !== "—") metaBits.push(`<span>${icon("clock")} ${escHtml(s.time)}</span>`);
  metaBits.push(
    `<span>${icon("book")} ${toFa((s.concepts || []).length)} مفهوم · ${toFa((s.formulas || []).length)} فرمول</span>`,
  );

  main.innerHTML = `
    <div class="huge-bg-num" aria-hidden="true">${toFa(s.num)}</div>
    <div class="viewer">
    <div class="viewer-main" id="viewerMain">
      ${_vwBarHTML(s, mode, hasDetail)}
      <article class="doc tpl-${tpl} mode-${mode}" id="doc">
        <header class="doc-head">
          <div class="doc-kicker">${kicker}</div>
          <h1 class="doc-title">${escHtml(s.title)}</h1>
          <div class="doc-meta">${metaBits.join("")}</div>
        </header>

        ${_modeBanner(mode, s)}

        <div class="doc-body" id="docBody" data-sess-id="${escHtml(s.id)}">${bodyHTML}</div>
      </article>
    </div>

    <aside class="viewer-toc" id="viewerToc">
      ${_vwTocHTML(s, packId)}
      <nav class="doc-foot doc-nav" aria-label="پیجر جلسه">
        ${(() => {
          const idx = ((CourseRuntime.getCourse() || {}).sessions || []).findIndex(
            (x) => x.id === s.id,
          );
          const prev = ((CourseRuntime.getCourse() || {}).sessions || [])[idx - 1];
          const next = ((CourseRuntime.getCourse() || {}).sessions || [])[idx + 1];
          return `
          <button class="doc-nav-btn prev" id="prevS" type="button" ${prev ? "" : "disabled"}>
            <span class="doc-nav-arr">${icon("chevRight")}</span>
            <span class="doc-nav-tx">
              <small>جلسهٔ قبل</small>
              <b>${prev ? escHtml(prev.title) : "—"}</b>
            </span>
          </button>
          <button class="doc-nav-read" id="readBtn" type="button" aria-pressed="${readSet.has(s.id)}">
            ${readSet.has(s.id) ? icon("check") : ""}
            <span>${readSet.has(s.id) ? "خوانده شد" : "علامت‌گذاری مطالعه"}</span>
          </button>
          <button class="doc-nav-btn next" id="nextS" type="button" ${next ? "" : "disabled"}>
            <span class="doc-nav-tx">
              <small>جلسهٔ بعد</small>
              <b>${next ? escHtml(next.title) : "—"}</b>
            </span>
            <span class="doc-nav-arr">${icon("chevLeft")}</span>
          </button>
          `;
        })()}
      </nav>
    </aside>
  </div>`;

  if (mode === "detail") {
    _renderDetailMath(s);
  } else if (mode === "review") {
    _renderReviewFormulas(s);
  }

  if (typeof after === "function") after(main);
  if (mode === "detail") _lzActivate(main.querySelector("#docBody") || main, s);

  if (mode === "brief" && s.formulas && s.formulas.length && typeof mountFormulas === "function") {
    mountFormulas(main, s.formulas, s);
  }

  const readBtn = document.getElementById("readBtn");
  if (readBtn) {
    readBtn.onclick = () => {
      if (readSet.has(s.id)) readSet.delete(s.id);
      else readSet.add(s.id);
      saveRead();
      refreshShellSidebar();
      if (typeof updateProg === "function") updateProg();
      const now = readSet.has(s.id);
      readBtn.classList.toggle("done", now);
      readBtn.innerHTML =
        (now ? icon("check") : "") + `<span>${now ? "خوانده شد" : "علامت‌گذاری مطالعه"}</span>`;
    };
  }
  const modeSwitch = document.getElementById("modeSwitch");
  if (modeSwitch) {
    modeSwitch.querySelectorAll(".vw-tab").forEach((b) => {
      b.onclick = () => {
        if (b.disabled || b.classList.contains("active")) return;
        const next = b.dataset.mode;
        setSessionMode(next);
        modeSwitch.querySelectorAll(".vw-tab").forEach((x) => {
          x.classList.toggle("active", x === b);
          x.setAttribute("aria-selected", x === b ? "true" : "false");
        });
        _swapSessionBody(s, next);
        const docEl = document.getElementById("doc");
        if (docEl) {
          const top = docEl.getBoundingClientRect().top + window.scrollY;
          if (window.scrollY > top + 40) {
            window.scrollTo({ top: Math.max(0, top - 88), behavior: "smooth" });
          }
        }
      };
    });
  }

  const mobMoreBtn = document.getElementById("vwMobMoreBtn");
  const mobMenu = document.getElementById("vwMobMenu");
  if (mobMoreBtn && mobMenu) {
    mobMoreBtn.onclick = (e) => {
      e.stopPropagation();
      const isOn = mobMenu.classList.toggle("on");
      mobMoreBtn.classList.toggle("active", isOn);
    };
    document.addEventListener("click", (e) => {
      if (
        !mobMenu.contains(e.target) &&
        e.target !== mobMoreBtn &&
        !mobMoreBtn.contains(e.target)
      ) {
        mobMenu.classList.remove("on");
        mobMoreBtn.classList.remove("active");
      }
    });
  }

  const zoomCtrl = document.getElementById("zoomCtrl");
  if (zoomCtrl) {
    const ZK = "lector:session:zoom";
    let zoom = 1;
    try {
      const v = parseFloat(sessionStorage.getItem(ZK));
      if (Number.isFinite(v) && v >= 0.8 && v <= 1.6) zoom = v;
    } catch (_) {}

    let _zoomFirstRun = true;
    const applyZoom = () => {
      const d = document.getElementById("doc");
      const lb = document.getElementById("zoomLabel");
      const lbMob = document.getElementById("zoomLabelMob");
      const prevZoom = _zoomFirstRun
        ? zoom
        : d
          ? parseFloat(d.style.getPropertyValue("--doc-zoom")) || zoom
          : zoom;

      if (d) d.style.setProperty("--doc-zoom", zoom.toFixed(2));
      if (lb) lb.textContent = toFa(Math.round(zoom * 100)) + "٪";
      if (lbMob) lbMob.textContent = toFa(Math.round(zoom * 100)) + "٪";
      try {
        sessionStorage.setItem(ZK, String(zoom));
      } catch (_) {}

      if (_zoomFirstRun) {
        _zoomFirstRun = false;
        return;
      }
      if (!d) return;
      if (Math.abs(prevZoom - zoom) < 0.001) return;
      if (window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches)
        return;
      const _dm = document.documentElement.dataset.motion;
      if (_dm === "off" || _dm === "reduced") return;

      try {
        d.animate(
          [{ transform: `scale(${(prevZoom / zoom).toFixed(4)})` }, { transform: "scale(1)" }],
          {
            duration: 340,
            easing: "cubic-bezier(.22, 1, .36, 1)",
            fill: "none",
          },
        );
      } catch (_) {}
    };
    applyZoom();

    document.querySelectorAll("[data-zoom]").forEach((b) => {
      b.onclick = () => {
        zoom = Math.max(0.8, Math.min(1.6, zoom + +b.dataset.zoom * 0.1));
        applyZoom();
      };
    });
  }

  const bm = document.getElementById("bmBtn");
  if (bm && typeof toggleBookmark === "function") {
    bm.onclick = () => {
      const on = toggleBookmark(s.id, { title: s.title, num: s.num });
      bm.setAttribute("aria-pressed", on ? "true" : "false");
      bm.innerHTML = on ? icon("starFilled") : icon("star");
      if (typeof Shell !== "undefined" && Shell.toast) {
        Shell.toast(on ? "نشانک افزوده شد" : "نشانک برداشته شد", "ok");
      }
    };
  }

  main.querySelectorAll(".vw-toc-sess").forEach((b) => {
    b.onclick = () => {
      const sid = b.dataset.sid;
      if (!sid || sid === s.id) return;
      setExplicitNav(true);
      goSession(packId, sid);
    };
  });

  const prev = document.getElementById("prevS");
  if (prev)
    prev.onclick = () => {
      const idx = (CourseRuntime.getCourse() || {}).sessions.findIndex((x) => x.id === s.id);
      const p = ((CourseRuntime.getCourse() || {}).sessions || [])[idx - 1];
      if (p) {
        setExplicitNav(true);
        goSession(packId, p.id);
      }
    };
  const next = document.getElementById("nextS");
  if (next)
    next.onclick = () => {
      const idx = (CourseRuntime.getCourse() || {}).sessions.findIndex((x) => x.id === s.id);
      const n = ((CourseRuntime.getCourse() || {}).sessions || [])[idx + 1];
      if (n) {
        setExplicitNav(true);
        goSession(packId, n.id);
      } else {
        setExplicitNav(true);
        go("home");
      }
    };

  _animateBanner(main.querySelector(".mode-banner"));

  // Paint اول را آزاد کن، بعد enrich کن
  requestAnimationFrame(() => {
    _initSessToc(s);
    if (typeof _tocPremiumEnter === "function") {
      _tocPremiumEnter(document.getElementById("viewerToc"));
    }
    _setupSessDropdownToggle(s);
  });

  main.querySelectorAll("[data-tool='hl']").forEach((b) => {
    b.onclick = () => {
      const notesEl = document.getElementById("sessNotes");
      const sel = window.getSelection();
      const text = sel ? String(sel.toString()).trim() : "";
      if (!text) {
        if (typeof toast === "function") toast("اول یک متن را انتخاب کن", "warn");
        return;
      }
      if (!notesEl) {
        if (typeof toast === "function") toast("یادداشت در این جلسه نیست", "warn");
        return;
      }
      notesEl.open = true;
      const ta = notesEl.querySelector("textarea");
      if (!ta) return;
      const cur = (ta.value || "").trim();
      const next = cur ? cur + "\n\n— " + text : "— " + text;
      ta.value = next;
      ta.dispatchEvent(new Event("input", { bubbles: true }));
      _noteFlush();
      const y = notesEl.getBoundingClientRect().top + window.scrollY - 90;
      window.scrollTo({ top: y, behavior: "smooth" });
      setTimeout(() => ta.focus(), 320);
      if (typeof toast === "function") toast("به یادداشت‌ها افزوده شد", "ok");
    };
  });
  main.querySelectorAll("[data-tool='note']").forEach((b) => {
    b.onclick = () => {
      const notesEl = document.getElementById("sessNotes");
      if (!notesEl) {
        if (typeof toast === "function") toast("یادداشت در این جلسه نیست", "warn");
        return;
      }
      notesEl.open = true;
      const ta = notesEl.querySelector("textarea");
      const y = notesEl.getBoundingClientRect().top + window.scrollY - 90;
      window.scrollTo({ top: y, behavior: "smooth" });
      if (ta) setTimeout(() => ta.focus(), 320);
    };
  });

  _initSessionScroll();

  const _animH = (el, oldH) => {
    if (!el || oldH <= 0) return;
    const newH = el.offsetHeight;
    if (oldH !== newH) {
      el.style.height = oldH + "px";
      el.style.overflow = "hidden";
      void el.offsetHeight;
      el.style.transition = "height 0.3s cubic-bezier(.22,1,.36,1)";
      el.style.height = newH + "px";
      setTimeout(() => {
        el.style.height = "";
        el.style.overflow = "";
        el.style.transition = "";
      }, 310);
    }
  };
  _animH(document.getElementById("prevS"), _oldPrevH);
  _animH(document.getElementById("nextS"), _oldNextH);

  if (anchor) {
    setTimeout(() => {
      _lzEnsureId(anchor);
      const el = document.getElementById(anchor);
      if (el) {
        el.scrollIntoView({ behavior: "smooth", block: "center" });
        el.classList.add("flash");
        setTimeout(() => el.classList.remove("flash"), 1700);
      }
    }, 120);
  }

  if (typeof ArchetypeRegistry !== "undefined" && ArchetypeRegistry.applySession) {
    try {
      ArchetypeRegistry.applySession(s, mode);
    } catch (_) {}
  }
}

export function _briefBodyHTML(s) {
  const parts = [];

  if (s.summary) {
    parts.push(`<div class="rd-callout rd-key"><b>خلاصه</b><div>${escHtml(s.summary)}</div></div>`);
  }

  if (s.concepts && s.concepts.length) {
    parts.push(`<section class="rd-sec"><h2><span class="rd-sec-num">۱</span>مفاهیم</h2>`);
    parts.push(
      `<div class="sess-cards-list">${s.concepts.map((c, i) => _conceptCard(s, c, i)).join("")}</div>`,
    );
    parts.push(`</section>`);
  }

  if (s.formulas && s.formulas.length) {
    parts.push(`<section class="rd-sec"><h2><span class="rd-sec-num">۲</span>فرمول‌ها</h2>`);
    parts.push(
      `<div class="sess-formulas single-col" data-count="${s.formulas.length}">${s.formulas.map((f, i) => formulaCard(f, s, i)).join("")}</div>`,
    );
    parts.push(`</section>`);
  }

  if (s.tips && s.tips.length) {
    parts.push(`<section class="rd-sec"><h2><span class="rd-sec-num">۳</span>نکات کلیدی</h2>`);
    parts.push(
      `<div class="sess-tips"><ol>${s.tips.map((t) => `<li>${t}</li>`).join("")}</ol></div>`,
    );
    parts.push(`</section>`);
  }

  return parts.join("");
}

export function _reviewBodyHTML(s) {
  const parts = [];
  const hasDetail = !!(s.detail && s.detail.sections && s.detail.sections.length);

  parts.push(`<section class="rd-sec"><h2><span class="rd-sec-num">۱</span>فرمول‌های کلیدی</h2>`);
  if (s.formulas && s.formulas.length) {
    parts.push(`<div class="rd-review-formulas">
      ${s.formulas
        .map(
          (f, i) => `
        <article class="rd-review-formula">
          <header class="rd-rf-head">
            <span class="rd-rf-num">${toFa(i + 1)}</span>
            <b class="rd-rf-title">${escHtml(f.t)}</b>
          </header>
          ${f.tex ? `<div class="rd-rf-tex" dir="ltr" data-tex="${escHtml(f.tex)}"></div>` : ""}
          ${f.use ? `<p class="rd-rf-use">${escHtml(f.use)}</p>` : ""}
        </article>`,
        )
        .join("")}
    </div>`);
  } else {
    parts.push(`<p class="rd-p" style="color:var(--mut)">فرمولی برای این جلسه تعریف نشده.</p>`);
  }
  parts.push(`</section>`);

  if (s.tips && s.tips.length) {
    parts.push(`<section class="rd-sec"><h2><span class="rd-sec-num">۲</span>نکات کلیدی</h2>`);
    parts.push(
      `<div class="rd-keys-block"><div class="rd-keys-grid">${s.tips
        .map(
          (t, i) => `
      <div class="rd-key">
        <span class="rd-key-n">${toFa(i + 1)}</span>
        <span class="rd-key-tx">${escHtml(t)}</span>
      </div>`,
        )
        .join("")}</div></div>`,
    );
    parts.push(`</section>`);
  }

  if (s.concepts && s.concepts.length && s.review !== "off") {
    parts.push(`<section class="rd-sec"><h2><span class="rd-sec-num">۳</span>فلش‌کارت</h2>`);
    parts.push(
      `<div class="rd-flash-grid">${s.concepts
        .slice(0, 6)
        .map(
          (c, i) => `
      <div class="rd-flash" data-flash="${i}" role="button" tabindex="0" aria-label="کارت ${i + 1}">
        <div class="rd-flash-in">
          <div class="rd-flash-f">
            <span class="rd-flash-kick">روی کارت</span>
            <span class="rd-flash-tx">${escHtml(c.t || "")}</span>
          </div>
          <div class="rd-flash-b">
            <span class="rd-flash-kick">پشت کارت</span>
            <span class="rd-flash-tx">${escHtml((c.def || "").slice(0, 120))}</span>
          </div>
        </div>
      </div>`,
        )
        .join("")}</div>`,
    );
    parts.push(`</section>`);
  }

  const _checklist = [
    "فرمول‌های بالا را از حفظ می‌نویسم.",
    "شرط مرزی و دامنهٔ اعتبار هر رابطه را می‌دانم.",
    "یک مسئله را از ابتدا تا پاسخ نهایی حل کرده‌ام.",
    "خطاهای رایج این مبحث را فهرست کرده‌ام.",
  ];
  parts.push(`<section class="rd-sec"><h2><span class="rd-sec-num">۴</span>چک‌لیست تسلط</h2>`);
  parts.push(`<div class="rd-checklist" data-checklist>
    <header class="rd-checklist-head">
      <b>چهار مورد، چهار تأیید</b>
      <span class="rd-checklist-count" data-cl-count>۰ از ${toFa(_checklist.length)}</span>
    </header>
    <div class="rd-checklist-bar"><i data-cl-bar></i></div>
    <div class="rd-checklist-items">
      ${_checklist
        .map(
          (t) => `<label class="rd-check">
        <input type="checkbox" data-cl-item>
        <span class="rd-check-box" aria-hidden="true">${icon("check")}</span>
        <span class="rd-check-tx">${escHtml(t)}</span>
      </label>`,
        )
        .join("")}
    </div>
  </div>`);
  parts.push(`</section>`);

  if (hasDetail) {
    parts.push(`<div class="mode-banner" style="margin-top:var(--s-6)">
      ${icon("info")}
      <div>برای متن کامل و استدلال‌ها، <b>حالت مفصل</b> را انتخاب کنید.</div>
    </div>`);
  }

  return parts.join("");
}

export function _initSessToc(s) {
  const list = document.getElementById("sessTocList");
  if (!list) return;
  const links = Array.from(list.querySelectorAll("[data-target]"));
  if (!links.length) return;

  const prog = document.getElementById("vwTocProgBar");
  let targets = links.map((a) => document.getElementById(a.dataset.target)).filter(Boolean);

  // کش: فقط موقع resize یا تغییر ارتفاع (KaTeX/Mermaid) بازاندازه‌گیری می‌شود
  let _offsets = [];
  let _docH = 1;
  const _measure = () => {
    targets = links.map((a) => document.getElementById(a.dataset.target)).filter(Boolean);
    const topbar = document.querySelector("header.top");
    const vwbar = document.querySelector(".vw-bar");
    const topbarH = topbar ? topbar.getBoundingClientRect().height : 0;
    const vwbarH = vwbar ? vwbar.getBoundingClientRect().height : 0;
    const refOff = topbarH + vwbarH + 24 + 15;
    _offsets = targets.map((t) => t.getBoundingClientRect().top + window.scrollY - refOff);
    _docH = Math.max(1, document.documentElement.scrollHeight - window.innerHeight);
  };

  window._sessRemeasure = _measure;
  // اندازه‌گیری اولیه بعد از paint، سپس چند بار برای KaTeX/Mermaid که ارتفاع را تغییر می‌دهند
  requestAnimationFrame(() => requestAnimationFrame(_measure));
  const _measureTimers = [setTimeout(_measure, 400), setTimeout(_measure, 1200), setTimeout(_measure, 2500)];

  let _rzTimer = 0;
  const _onResize = () => {
    clearTimeout(_rzTimer);
    _rzTimer = setTimeout(_measure, 150);
  };
  window.addEventListener("resize", _onResize, { passive: true });

  let raf = 0;
  const onScroll = () => {
    if (raf) return;
    raf = requestAnimationFrame(() => {
      raf = 0;
      const top = window.scrollY || document.documentElement.scrollTop;

      if (prog) {
        const p = Math.min(1, Math.max(0, top / _docH));
        prog.style.width = p * 100 + "%";
      }

      let active = 0;
      for (let i = 0; i < _offsets.length; i++) {
        if (_offsets[i] <= top) active = i;
        else break;
      }
      links.forEach((a, i) => a.classList.toggle("on", i === active));
    });
  };

  window.addEventListener("scroll", onScroll, { passive: true });
  onScroll();

  const prev = window._sessCleanup;
  window._sessCleanup = () => {
    if (prev) try { prev(); } catch (_) {}
    window.removeEventListener("scroll", onScroll);
    window.removeEventListener("resize", _onResize);
    if (raf) cancelAnimationFrame(raf);
    if (_rzTimer) clearTimeout(_rzTimer);
    _measureTimers.forEach((t) => clearTimeout(t));
  };

  links.forEach((a) => {
    a.addEventListener("click", () => {
      const el = document.getElementById(a.dataset.target);
      if (!el) return;
      const topbar = document.querySelector("header.top");
      const vwbar = document.querySelector(".vw-bar");
      const topbarH = topbar ? topbar.getBoundingClientRect().height : 0;
      const vwbarH = vwbar ? vwbar.getBoundingClientRect().height : 0;
      const y = el.getBoundingClientRect().top + window.scrollY - (topbarH + vwbarH + 24);
      window.scrollTo({ top: y, behavior: "smooth" });
    });
  });
}

export function _setupSessDropdownToggle(s) {
  const toggle = document.getElementById("vwSessToggle");
  if (!toggle) return;
  let pop = null;

  const build = () => {
    const C = CourseRuntime.getCourse() || {};
    const sessions = C.sessions || [];
    const itemsHTML = sessions
      .map((ss) => {
        const on = ss.id === s.id;
        const done = readSet.has(ss.id);
        const cls = "vw-sess-item" + (on ? " on" : "") + (done ? " done" : "");
        return `<button type="button" class="${cls}" data-sid="${escHtml(ss.id)}">
        <span class="vw-sess-n">${done ? icon("check") : toFa(ss.num)}</span>
        <span class="vw-sess-b">
          <span class="vw-sess-t">${escHtml(ss.title)}</span>
          <span class="vw-sess-m">${toFa((ss.concepts || []).length)} مفهوم · ${toFa((ss.formulas || []).length)} فرمول</span>
        </span>
      </button>`;
      })
      .join("");
    pop = document.createElement("div");
    pop.className = "vw-sess-pop";
    pop.setAttribute("role", "dialog");
    pop.setAttribute("aria-label", "فهرست جلسات");
    pop.innerHTML =
      `<div class="vw-sess-pop-h">${icon("book")}<span>فهرست جلسات</span></div>` +
      `<div class="vw-sess-pop-list">${itemsHTML}</div>`;
    const bar = document.querySelector(".vw-bar");
    (bar || document.body).appendChild(pop);
    pop.querySelectorAll(".vw-sess-item").forEach((b) => {
      b.addEventListener("click", () => {
        const sid = b.dataset.sid;
        pop.classList.remove("on");
        toggle.setAttribute("aria-expanded", "false");
        if (sid && sid !== s.id) {
          setExplicitNav(true);
          goSession(CourseRuntime.getActivePackId(), sid);
        }
      });
    });
    const closer = (ev) => {
      if (pop.contains(ev.target) || toggle.contains(ev.target)) return;
      pop.classList.remove("on");
      toggle.setAttribute("aria-expanded", "false");
    };
    document.addEventListener("click", closer);
    const prev = window._sessCleanup;
    window._sessCleanup = () => {
      if (prev)
        try {
          prev();
        } catch (_) {}
      document.removeEventListener("click", closer);
      if (pop) {
        pop.remove();
        pop = null;
      }
    };
  };

  toggle.addEventListener("click", (e) => {
    e.stopPropagation();
    if (!pop) build();
    const willOpen = !pop.classList.contains("on");
    pop.classList.toggle("on", willOpen);
    toggle.setAttribute("aria-expanded", willOpen ? "true" : "false");
  });
}

export function _initSessionScroll() {
  const vm = document.getElementById("viewerMain");
  const vwMain = document.getElementById("doc");
  if (!vm || !vwMain) return;

  const onScroll = () => {};

  window.addEventListener("scroll", onScroll, { passive: true });

  const prev = window._sessCleanup;
  window._sessCleanup = () => {
    if (prev)
      try {
        prev();
      } catch (_) {}
    window.removeEventListener("scroll", onScroll);
  };

  onScroll();
}

export function _moveSegPill(seg) {
  const a = seg.querySelector(".seg-b.active");
  const p = seg.querySelector(".seg-pill");
  if (!a || !p) return;
  if (typeof Motion === "undefined") {
    p.style.opacity = "0";
    return;
  }
  p.style.opacity = "1";
  const cs = getComputedStyle(seg);
  const z = parseFloat(getComputedStyle(document.documentElement).zoom) || 1;
  const segRect = seg.getBoundingClientRect();
  const aRect = a.getBoundingClientRect();
  const borderLeft = parseFloat(cs.borderLeftWidth) || 0;
  const x = (aRect.left - segRect.left - borderLeft) / z;
  const w = aRect.width / z;

  if (p._x == null) {
    Motion.initPill(p, x, w);
    return;
  }
  Motion.movePill(p, a, seg);
}


// هدر جلسه: دکمهٔ وسط نوار بالا (فقط در صفحهٔ جلسه) نوار عنوان را جمع/باز می‌کند
document.addEventListener("click", (e) => {
  const btn = e.target.closest && e.target.closest("#vwHeadToggle");
  if (!btn) return;
  const bar = document.querySelector("#viewerMain .vw-bar");
  if (!bar) return;
  const collapsed = bar.classList.toggle("vw-collapsed");
  btn.setAttribute("aria-expanded", collapsed ? "false" : "true");
  btn.setAttribute("aria-label", collapsed ? "باز کردن عنوان جلسه" : "جمع کردن عنوان جلسه");
});
