// ثابت‌های زمان اجرا برای نوع بلاک‌ها. تعریف تایپ‌ها در types.ts است (منبع واحد).
import type { BlockType, CalloutTone, HeadingLevel } from "./types.js";

export type { BlockType, CalloutTone, HeadingLevel } from "./types.js";

export interface BlockTypesApi {
  BLOCK_TYPES: readonly BlockType[];
  CALLOUT_TONES: readonly CalloutTone[];
  HEADING_LEVELS: readonly HeadingLevel[];
}

declare global {
  interface Window {
    BlockTypes: BlockTypesApi;
  }
  var BlockTypes: BlockTypesApi;
}

export const BLOCK_TYPES: readonly BlockType[] = Object.freeze<BlockType[]>([
  "p",
  "h",
  "list",
  "math",
  "formula",
  "widget",
  "callout",
  "quote",
  "table",
  "hr",
  "define",
  "figure",
  "mermaid",
  "quiz",
  "flash",
  "compare",
  "steps",
  "keys",
  "disclose",
  "check",
]);
export const CALLOUT_TONES: readonly CalloutTone[] = Object.freeze<CalloutTone[]>([
  "note",
  "ex",
  "warn",
  "key",
]);
export const HEADING_LEVELS: readonly HeadingLevel[] = Object.freeze<HeadingLevel[]>([3, 4]);

// سازگاری با کدهای غیرماژولی که از global استفاده می‌کنند
globalThis.BlockTypes = Object.freeze({
  BLOCK_TYPES,
  CALLOUT_TONES,
  HEADING_LEVELS,
});
