// رندررهای تعاملی (Phase 5.7): quiz، flash، check.
// خروجی نشانه‌گذاری است؛ رفتار (انتخاب گزینه، برگرداندن کارت) در ویوور است.
// تنها رفتار DOM این ماژول، تفویض کلیک برای خودآزمایی (check) است و تابع خالص applySelfCheckClick دارد.
import { escHtml } from "../escape.js";
import type { BlockMap, FlashCard, Renderer } from "../types.js";

const LETTERS = ["A", "B", "C", "D", "E", "F"];

// شناسهٔ پایدار پرسش: هش متن پرسش و گزینه‌ها؛ به ترتیب DOM یا وضعیت رندر تنبل وابسته نیست.
export function questionHash(str: string): string {
  let h = 5381;
  for (let i = 0; i < str.length; i++) h = ((h << 5) + h + str.charCodeAt(i)) | 0;
  return (h >>> 0).toString(36);
}

export const renderQuiz: Renderer<BlockMap["quiz"]> = (b) => {
  const answer = Number.isInteger(b.answer) ? (b.answer as number) : 0;
  const options = (b.options || [])
    .map((o, i) => {
      const letter = LETTERS[i] || String(i + 1);
      return (
        `<button type="button" class="rd-quiz-o" data-k="${i}">` +
        `<span class="lt">${letter}</span>` +
        `<span class="rd-quiz-tx">${escHtml(o)}</span>` +
        `</button>`
      );
    })
    .join("");
  const explain = b.explain ? `<div class="rd-quiz-exp" hidden>${escHtml(b.explain)}</div>` : "";
  const title = b.q || b.question || b.title || "پرسش";
  return (
    `<div class="rd-quiz" data-quiz="${answer}" data-qid="q${questionHash(String(title) + "|" + (b.options || []).join("|"))}">` +
    `<b class="rd-quiz-title">${escHtml(title)}</b>` +
    options +
    explain +
    `</div>`
  );
};

export const renderFlash: Renderer<BlockMap["flash"]> = (b) => {
  const cards = Array.isArray(b.cards) ? b.cards : [];
  if (!cards.length) return "";
  const inner = cards
    .map((raw, i) => {
      const c: FlashCard = raw || {};
      return (
        `<div class="rd-flash" data-flash="${i}" role="button" tabindex="0" aria-label="کارت ${i + 1}">` +
        `<div class="rd-flash-in">` +
        `<div class="rd-flash-f">` +
        `<span class="rd-flash-kick">روی کارت</span>` +
        `<span class="rd-flash-tx">${escHtml(c.front || c.q || "")}</span>` +
        `</div>` +
        `<div class="rd-flash-b">` +
        `<span class="rd-flash-kick">پشت کارت</span>` +
        `<span class="rd-flash-tx">${escHtml(c.back || c.a || "")}</span>` +
        `</div>` +
        `</div>` +
        `</div>`
      );
    })
    .join("");
  const title = b.title ? `<div class="rd-flash-title">${escHtml(b.title)}</div>` : "";
  return `<div class="rd-flash-deck">${title}<div class="rd-flash-grid">${inner}</div></div>`;
};

export const renderCheck: Renderer<BlockMap["check"]> = (b) => {
  const q = escHtml(b.q || b.question || "پرسش");
  const ans =
    b.answerHtml != null ? b.answerHtml : escHtml(String(b.a != null ? b.a : b.answer || ""));
  return (
    `<div class="rd-selfcheck" data-selfcheck>` +
    `<div class="rd-selfcheck-q"><span class="rd-selfcheck-kick">خودآزمایی</span><b>${q}</b></div>` +
    `<button type="button" class="rd-selfcheck-btn" data-selfcheck-reveal aria-expanded="false">نشان بده</button>` +
    `<div class="rd-selfcheck-a" hidden>` +
    `<div class="rd-selfcheck-ans">${ans}</div>` +
    `<div class="rd-selfcheck-self" role="group" aria-label="ارزیابی خود">` +
    `<span>چقدر بلد بودی؟</span>` +
    `<button type="button" class="rd-selfcheck-s" data-self="know">بلد بودم</button>` +
    `<button type="button" class="rd-selfcheck-s" data-self="again">دوباره مرور کنم</button>` +
    `</div>` +
    `</div>` +
    `</div>`
  );
};

// حداقل سطحی از Element که تفویض کلیک لازم دارد. نمونهٔ واقعی Element این را برآورده می‌کند.
export interface SelfCheckTarget {
  closest(selector: string): SelfCheckTarget | null;
  querySelector<E = unknown>(selector: string): E | null;
  querySelectorAll(selector: string): { forEach(fn: (el: SelfCheckTarget) => void): void };
  getAttribute(name: string): string | null;
  setAttribute(name: string, value: string): void;
  classList: { add(...c: string[]): void; remove(...c: string[]): void };
  textContent: string | null;
}

interface RevealTarget extends SelfCheckTarget {
  hidden?: boolean;
}

// منطق کلیک خودآزمایی: نشان‌دادن/پنهان‌کردن پاسخ و ثبت «بلد بودم» یا «دوباره مرور کنم».
export function applySelfCheckClick(target: unknown): void {
  if (!target || typeof (target as SelfCheckTarget).closest !== "function") return;
  const el = target as SelfCheckTarget;

  const rev = el.closest("[data-selfcheck-reveal]");
  if (rev) {
    const box = rev.closest("[data-selfcheck]");
    const a = box ? (box.querySelector<RevealTarget>(".rd-selfcheck-a") ?? null) : null;
    if (!a) return;
    const willOpen = !!a.hidden;
    a.hidden = !willOpen;
    rev.setAttribute("aria-expanded", willOpen ? "true" : "false");
    rev.textContent = willOpen ? "پنهان کن" : "نشان بده";
    return;
  }

  const self = el.closest("[data-self]");
  if (self) {
    const box = self.closest("[data-selfcheck]");
    if (!box) return;
    const v = self.getAttribute("data-self");
    box.classList.remove("is-know", "is-again");
    box.classList.add(v === "know" ? "is-know" : "is-again");
    box
      .querySelectorAll("[data-self]")
      .forEach((x) => x.setAttribute("aria-pressed", x === self ? "true" : "false"));
  }
}

// تفویض کلیک روی document؛ فقط وقتی میزبان DOM دارد صدا زده می‌شود.
export function bindSelfCheckDelegation(doc: {
  addEventListener(type: "click", fn: (e: { target: unknown }) => void): void;
}): void {
  doc.addEventListener("click", (e) => applySelfCheckClick(e.target));
}
