// رندررهای ساختاری (Phase 5.6): table، compare، steps، keys، disclose.
import { escHtml } from "../escape.js";
import type { BlockMap, ListItemObject, Renderer } from "../types.js";

// سلول‌های table خام‌اند (HTML) و عمداً escape نمی‌شوند؛ همان قرارداد پک‌ها.
export const renderTable: Renderer<BlockMap["table"]> = (b) => {
  const head = (b.head || []).map((h) => `<th>${h}</th>`).join("");
  const rows = (b.rows || [])
    .map((r) => `<tr>${(r || []).map((c) => `<td>${c}</td>`).join("")}</tr>`)
    .join("");
  return `<div class="rd-table-wrap"><table class="rd-table"><thead><tr>${head}</tr></thead><tbody>${rows}</tbody></table></div>`;
};

export const renderCompare: Renderer<BlockMap["compare"]> = (b) => {
  const cols = (Array.isArray(b.columns) ? b.columns : []).map((c) => c || {});
  if (!cols.length) return "";
  const head = cols.map((c) => `<th>${escHtml(c.title || "")}</th>`).join("");
  const maxRows = cols.reduce((m, c) => Math.max(m, (c.items || []).length), 0);
  let body = "";
  for (let i = 0; i < maxRows; i++) {
    body +=
      "<tr>" + cols.map((c) => `<td>${escHtml((c.items || [])[i] || "")}</td>`).join("") + "</tr>";
  }
  return `<div class="rd-compare-wrap"><table class="rd-compare"><thead><tr>${head}</tr></thead><tbody>${body}</tbody></table></div>`;
};

export const renderSteps: Renderer<BlockMap["steps"]> = (b) => {
  const items = (b.items || [])
    .map((raw, i) => {
      const it: ListItemObject = raw || {};
      const title = it.title ? `<b class="rd-steps-t">${escHtml(it.title)}</b>` : "";
      const body = it.body != null ? it.body : it.html != null ? it.html : escHtml(it.text || "");
      return (
        `<div class="rd-steps-item">` +
        `<span class="rd-steps-n">${i + 1}</span>` +
        `<div class="rd-steps-c">${title}${body}</div>` +
        `</div>`
      );
    })
    .join("");
  const title = b.title ? `<div class="rd-steps-title">${escHtml(b.title)}</div>` : "";
  return `<div class="rd-steps-block">${title}<div class="rd-steps-list">${items}</div></div>`;
};

export const renderKeys: Renderer<BlockMap["keys"]> = (b) => {
  const items = (b.items || [])
    .map((raw, i) => {
      const k = raw ?? "";
      const text =
        typeof k === "string" ? escHtml(k) : k.html != null ? k.html : escHtml(k.text || "");
      return (
        `<div class="rd-key">` +
        `<span class="rd-key-n">${i + 1}</span>` +
        `<span class="rd-key-tx">${text}</span>` +
        `</div>`
      );
    })
    .join("");
  const title = b.title ? `<div class="rd-keys-title">${escHtml(b.title)}</div>` : "";
  return `<div class="rd-keys-block">${title}<div class="rd-keys-grid">${items}</div></div>`;
};

export const renderDisclose: Renderer<BlockMap["disclose"]> = (b, ctx, renderChild) => {
  const title = escHtml(b.title || "جزئیات");
  const inner = (Array.isArray(b.blocks) ? b.blocks : []).map((c) => renderChild(c, ctx)).join("");
  const open = b.open === true ? " open" : "";
  return (
    `<details class="rd-disclose"${open}>` +
    `<summary><span class="rd-disclose-ic" aria-hidden="true"></span><span class="rd-disclose-t">${title}</span></summary>` +
    `<div class="rd-disclose-body">${inner}</div>` +
    `</details>`
  );
};
