// بارگذاری پک از منبع (local یا json) و فعال‌سازی آن.
// این ماژول هیچ شبکه‌ای ندارد: دریافت از راه دور به لایهٔ Client (فاز ۱۰) تعلق دارد.

import type { Pack } from "../contract/types.js";
import { normalizePack } from "../contract/normalize.js";
import { runPackValidation } from "../contract/validate.js";
import { engineEvents } from "../events.js";
import { activatePack, getRawPack } from "./active.js";
import { getPackById, listSources, registerPack } from "./registry.js";

export type LoadMode = "local" | "json";

export interface LoadOptions {
  mode?: LoadMode | string;
  id?: string;
  file?: JsonFileLike | string;
  activate?: boolean;
}

// شیء شبه‌فایل (File / Blob) که متن آن قابل خواندن است
export interface JsonFileLike {
  text?: () => Promise<string>;
}

export interface LoaderApi {
  load(options?: LoadOptions): Promise<Pack>;
  activate(id: string): Promise<Pack>;
}

async function readJson(file: JsonFileLike | string | undefined): Promise<unknown> {
  if (!file) throw new Error("[Loader] json mode requires file");
  const text =
    typeof file === "object" && typeof file.text === "function" ? await file.text() : String(file);
  return JSON.parse(text);
}

function firstPackId(): string | undefined {
  const first = listSources()[0];
  return first ? first.id : undefined;
}

export const Loader: LoaderApi = Object.freeze({
  async load(options: LoadOptions = {}): Promise<Pack> {
    const mode = options.mode || "local";
    let raw: unknown;
    if (mode === "local") raw = getRawPack(options.id || firstPackId());
    else if (mode === "json") raw = await readJson(options.file);
    else throw new Error("[Loader] Unknown mode: " + mode);

    if (!raw) throw new Error("[Loader] Pack source not found");
    const pack = normalizePack(raw);
    registerPack(pack);
    runPackValidation(pack);
    engineEvents.emit("pack:loaded", { id: pack.id });
    if (options.activate !== false) activatePack(pack.id);
    return pack;
  },

  async activate(id: string): Promise<Pack> {
    const pack = getPackById(id);
    if (!pack) throw new Error("[Loader] Pack not loaded: " + id);
    activatePack(id);
    return pack;
  },
});

declare global {
  var Loader: LoaderApi;
}

globalThis.Loader = Loader;
