// رندرر بلاک widget (Phase 5.8). در فهرست 5.1–5.7 نیست اما برای «همه ویجت‌ها از طریق رجیستری» لازم است.
// ویجت و آیکون را میزبان از طریق ctx تزریق می‌کند؛ بدون آن، سرصفحه بدون آیکون و ویجت ناشناخته هشدار است.
import { escHtml } from "../escape.js";
import type { BlockMap, Renderer } from "../types.js";

export const renderWidget: Renderer<BlockMap["widget"]> = (b, ctx) => {
  const w = ctx.widget ? ctx.widget(String(b.ref)) : null;
  if (!w) {
    return `<aside class="rd-callout rd-warn"><b>ویجت</b><div>ویجت «${escHtml(b.ref || "")}» در این درس تعریف نشده.</div></aside>`;
  }
  const icon = ctx.icon ? ctx.icon("flask") : "";
  return (
    `<div class="widget rd-widget"><div class="wt"><span class="wt-ic">${icon}</span>` +
    `<h3>${escHtml(w.title || b.ref)}</h3><span class="wbadge">تعاملی</span></div>` +
    `${w.desc ? `<div class="wd">${w.desc}</div>` : ""}` +
    `<div data-widget="${escHtml(b.ref)}"></div></div>`
  );
};
