// بررسی پاسخ (Answer check) — خالص و بدون DOM.
// هر مسئله می‌تواند answerSpec داشته باشد؛ نبودنش یعنی «فقط خودارزیابی» (status: unchecked).
//
// answerSpec ها:
//   { type: "choice",  options: [str...], answer: <index> }
//   { type: "numeric", value: <number>, tol?: <abs>, relTol?: <ratio>, unit?: "W/m^2", requireUnit?: bool }
//        پیش‌فرض: relTol = 0.01 (۱٪) اگر tol و relTol هر دو نباشند.
//   { type: "text",    accept: [str...] }
//   هر کدام می‌تواند rules (قانون‌های تشخیصی) داشته باشد.
//
// نتایج status: correct | incorrect | invalid | unit-missing | unit-mismatch | unchecked

export type CheckStatus =
  "correct" | "incorrect" | "invalid" | "unit-missing" | "unit-mismatch" | "unchecked";

// نتیجهٔ checkAnswer.
export interface AnswerResult {
  status: CheckStatus;
  reason?: string;
  chosen?: number;
  expected?: string;
  got?: string;
  value?: number;
  ratio?: number | null;
}

// نتیجهٔ تجزیهٔ عدد از ورودی کاربر (ممکن است واحد هم داشته باشد).
export interface ParsedNumber {
  value: number;
  unit: string;
}

// قانون تشخیصی: اگر شرط برقرار بود، متن say به کاربر نشان داده می‌شود.
export interface DiagnosticRule {
  if?: {
    status?: CheckStatus;
    ratioMin?: number;
    ratioMax?: number;
    ratioPow10?: boolean;
  };
  say: string;
}

interface SpecBase {
  rules?: DiagnosticRule[];
}
export interface ChoiceSpec extends SpecBase {
  type: "choice";
  options: string[];
  answer: number;
}
export interface NumericSpec extends SpecBase {
  type: "numeric";
  value: number;
  tol?: number;
  relTol?: number;
  unit?: string;
  requireUnit?: boolean;
}
export interface TextSpec extends SpecBase {
  type: "text";
  accept: string[];
}
export type AnswerSpec = ChoiceSpec | NumericSpec | TextSpec;

type SpecRecord = Record<string, unknown>;

export const DEFAULT_REL_TOL = 0.01;
const FA_DIGITS = "۰۱۲۳۴۵۶۷۸۹";
const AR_DIGITS = "٠١٢٣٤٥٦٧٨٩";

function isRecord(v: unknown): v is SpecRecord {
  return typeof v === "object" && v !== null;
}

function isFiniteNumber(v: unknown): v is number {
  return Number.isFinite(v);
}

function isIntegerNumber(v: unknown): v is number {
  return Number.isInteger(v);
}

function isStringArray(v: unknown): v is string[] {
  return Array.isArray(v) && v.every((x) => typeof x === "string");
}

// طول options/answer؛ مقدار غیرقابل‌اندازه‌گیری NaN می‌شود (همان رفتار مقایسهٔ undefined)
function lengthOf(v: unknown): number {
  if (!v) return 0;
  if (typeof v === "string") return v.length;
  if (isRecord(v) && typeof v.length === "number") return v.length;
  return NaN;
}

// ارقام فارسی/عربی → لاتین
export function toAsciiDigits(s: unknown): string {
  return String(s)
    .replace(/[۰-۹]/g, (d) => String(FA_DIGITS.indexOf(d)))
    .replace(/[٠-٩]/g, (d) => String(AR_DIGITS.indexOf(d)));
}

// نرمال‌سازی متن فارسی برای مقایسهٔ پاسخ متنی:
// ارقام، ی/ک عربی، حذف ZWNJ/کشیده/اعراب، فاصلهٔ اضافه، حروف کوچک لاتین.
export function normalizeText(s: unknown): string {
  return toAsciiDigits(s == null ? "" : s)
    .replace(/[‌‍ـ]/g, "")
    .replace(/[\u064B-\u065F\u0670]/g, "")
    .replace(/ي/g, "ی")
    .replace(/ك/g, "ک")
    .replace(/\s+/g, " ")
    .trim()
    .toLowerCase();
}

// تجزیهٔ عدد از ورودی کاربر. ورودی می‌تواند واحد هم داشته باشد: «1353 W/m^2».
// برمی‌گرداند { value, unit } یا null.
export function parseNumber(raw: unknown): ParsedNumber | null {
  let t = toAsciiDigits(raw == null ? "" : raw).trim();
  t = t.replace(/[٬‌]/g, "").replace(/٫/g, ".");
  // «1,5» (کاما + غیر از ۳ رقم) → ممیز؛ «1,500» → هزارگان
  if (!t.includes(".") && /^[+-]?\d+,\d+/.test(t) && !/^[+-]?\d+,\d{3}(?!\d)/.test(t)) {
    t = t.replace(",", ".");
  }
  t = t.replace(/,/g, "");
  const m = t.match(/^([+-]?(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?)\s*(.*)$/);
  if (!m) return null;
  const value = Number(m[1]);
  if (!Number.isFinite(value)) return null;
  return { value, unit: (m[2] ?? "").trim() };
}

function normUnit(u: unknown): string {
  return String(u || "")
    .replace(/\s+/g, "")
    .replace(/[·⋅]/g, "")
    .replace(/\^/g, "")
    .replace(/²/g, "2")
    .replace(/³/g, "3")
    .toLowerCase();
}

function checkChoice(spec: SpecRecord, input: unknown): AnswerResult {
  const n = typeof input === "string" && input.trim() !== "" ? Number(input) : input;
  if (!isIntegerNumber(n) || n < 0 || n >= lengthOf(spec.options || [])) {
    return { status: "invalid", reason: "no-choice" };
  }
  return {
    status: n === spec.answer ? "correct" : "incorrect",
    chosen: n,
  };
}

function checkNumeric(spec: SpecRecord, input: unknown): AnswerResult {
  const parsed: ParsedNumber | null =
    typeof input === "number" ? { value: input, unit: "" } : parseNumber(input);
  if (!parsed) return { status: "invalid", reason: "not-a-number" };

  if (spec.unit) {
    if (!parsed.unit) {
      if (spec.requireUnit) return { status: "unit-missing", expected: String(spec.unit) };
    } else if (normUnit(parsed.unit) !== normUnit(spec.unit)) {
      return { status: "unit-mismatch", expected: String(spec.unit), got: parsed.unit };
    }
  }

  const target = Number(spec.value);
  const absTol = isFiniteNumber(spec.tol) ? spec.tol : 0;
  // relTol صریح؛ اگر فقط tol داده شده باشد، همان مطلق کافی است؛ وگرنه پیش‌فرض ۱٪
  const relTol = isFiniteNumber(spec.relTol)
    ? spec.relTol
    : isFiniteNumber(spec.tol)
      ? 0
      : DEFAULT_REL_TOL;
  const allowed = Math.max(absTol, relTol * Math.abs(target));
  const delta = Math.abs(parsed.value - target);
  const ok = delta <= allowed;
  // نسبت پاسخ به جواب درست: برای تشخیص خطای پیشوند (مثلاً ×۱۰۰۰) در قانون‌های تشخیصی
  const ratio = target !== 0 ? parsed.value / target : null;
  return { status: ok ? "correct" : "incorrect", value: parsed.value, ratio };
}

function checkText(spec: SpecRecord, input: unknown): AnswerResult {
  const got = normalizeText(input);
  if (!got) return { status: "invalid", reason: "empty" };
  const accept: string[] = Array.isArray(spec.accept) ? spec.accept.map(normalizeText) : [];
  return { status: accept.includes(got) ? "correct" : "incorrect" };
}

// بررسی یک پاسخ در برابر answerSpec. spec ناشناخته یا نبود آن → unchecked.
export function checkAnswer(spec: unknown, input: unknown): AnswerResult {
  if (!isRecord(spec)) return { status: "unchecked" };
  switch (spec.type) {
    case "choice":
      return checkChoice(spec, input);
    case "numeric":
      return checkNumeric(spec, input);
    case "text":
      return checkText(spec, input);
    default:
      return { status: "unchecked", reason: "unknown-type" };
  }
}

// ── تشخیص خطا (Diagnostic) ───────────────────────────────
// پیام‌های فارسی علت خطا را برمی‌گرداند. ترتیب: پیام‌های داخلی بر اساس وضعیت، سپس rules مسئله.
// ratioPow10: اگر true باشد، قانون فقط وقتی اجرا می‌شود که ratio توان ۱۰ باشد (خطای پیشوند).
export function prefixPower(ratio: number): number | null {
  if (!Number.isFinite(ratio) || ratio <= 0) return null;
  const k = Math.round(Math.log10(ratio));
  if (k === 0 || Math.abs(k) > 12) return null;
  return Math.abs(ratio / Math.pow(10, k) - 1) <= 0.01 ? k : null;
}

function matchesRule(cond: NonNullable<DiagnosticRule["if"]>, r: AnswerResult): boolean {
  if (cond.status !== undefined && cond.status !== r.status) return false;
  if (cond.ratioMin !== undefined || cond.ratioMax !== undefined || cond.ratioPow10) {
    const ratio = r.ratio;
    if (typeof ratio !== "number") return false;
    if (cond.ratioMin !== undefined && ratio < Number(cond.ratioMin)) return false;
    if (cond.ratioMax !== undefined && ratio > Number(cond.ratioMax)) return false;
    if (cond.ratioPow10 && prefixPower(ratio) === null) return false;
  }
  return true;
}

export function diagnose(spec: unknown, input: unknown, result?: AnswerResult | null): string[] {
  const msgs: string[] = [];
  const r = result || checkAnswer(spec, input);
  if (!isRecord(spec)) return msgs;

  if (r.status === "invalid") {
    msgs.push(
      spec.type === "numeric"
        ? "فقط عدد وارد کنید؛ ارقام فارسی هم پذیرفته می‌شود."
        : "پاسخ خالی است؛ یکی از گزینه‌ها یا یک پاسخ بنویسید.",
    );
  } else if (r.status === "unit-mismatch") {
    msgs.push("واحد باید «" + r.expected + "» باشد؛ شما «" + r.got + "» نوشته‌اید.");
  } else if (r.status === "unit-missing") {
    msgs.push("واحد را هم بنویسید (" + r.expected + ").");
  } else if (r.status === "incorrect" && spec.type === "numeric" && typeof r.ratio === "number") {
    const k = prefixPower(r.ratio);
    if (k !== null) {
      msgs.push(
        "اندازه حدود ۱۰^" +
          k +
          " برابر جواب است؛ احتمالاً پیشوند یکا (کیلو، میلی، …)، ممیز یا توان ۱۰ جابه‌جا شده است.",
      );
    } else if (r.ratio < 0 && Math.abs(Math.abs(r.ratio) - 1) <= 0.01) {
      msgs.push("اندازه درست است، اما علامت برعکس است؛ جهت یا علامت کمیت را بررسی کنید.");
    }
  }

  const rules: unknown[] = Array.isArray(spec.rules) ? spec.rules : [];
  rules.forEach((rule) => {
    if (!isRecord(rule) || typeof rule.say !== "string") return;
    const cond: SpecRecord = isRecord(rule.if) ? rule.if : {};
    if (!matchesRule(cond as NonNullable<DiagnosticRule["if"]>, r)) return;
    msgs.push(rule.say);
  });
  return msgs;
}

// اعتبارسنجی ساختار answerSpec. برمی‌گرداند آرایهٔ پیام خطا (خالی یعنی معتبر).
export function validateSpec(spec: unknown): string[] {
  const errs: string[] = [];
  if (spec == null) return errs;
  if (!isRecord(spec)) return ["answerSpec باید شیء باشد"];
  if (spec.type === "choice") {
    if (!Array.isArray(spec.options) || spec.options.length < 2)
      errs.push("choice نیازمند options با حداقل دو گزینه است");
    if (
      !isIntegerNumber(spec.answer) ||
      spec.answer < 0 ||
      spec.answer >= lengthOf(spec.options || [])
    )
      errs.push("choice.answer باید اندیس معتبر options باشد");
  } else if (spec.type === "numeric") {
    if (!Number.isFinite(spec.value)) errs.push("numeric.value باید عدد باشد");
    if (spec.tol != null && (!isFiniteNumber(spec.tol) || spec.tol < 0))
      errs.push("numeric.tol باید عدد نامنفی باشد");
    if (spec.relTol != null && (!isFiniteNumber(spec.relTol) || spec.relTol < 0))
      errs.push("numeric.relTol باید عدد نامنفی باشد");
  } else if (spec.type === "text") {
    if (!isStringArray(spec.accept) || spec.accept.length === 0)
      errs.push("text.accept باید آرایهٔ غیرخالی از رشته باشد");
  } else {
    errs.push("answerSpec.type باید choice، numeric یا text باشد");
  }
  if (spec.rules != null) {
    if (!Array.isArray(spec.rules)) errs.push("answerSpec.rules باید آرایه باشد");
    else {
      const rules: unknown[] = spec.rules;
      rules.forEach((rule, i) => {
        if (!isRecord(rule) || typeof rule.say !== "string" || !rule.say.trim())
          errs.push("rules[" + i + "].say باید متن غیرخالی باشد");
        if (isRecord(rule) && rule.if != null && typeof rule.if !== "object")
          errs.push("rules[" + i + "].if باید شیء باشد");
      });
    }
  }
  return errs;
}

// ── سازگاری با کد JS موجود: نام global «AnswerCheck» ───────────────────
// validate.ts و practice.js هنوز از این نام استفاده می‌کنند.
const legacyApi = Object.freeze({
  toAsciiDigits,
  normalizeText,
  parseNumber,
  checkAnswer,
  diagnose,
  prefixPower,
  validateSpec,
  DEFAULT_REL_TOL,
});
Object.assign(globalThis, { AnswerCheck: legacyApi });
