// زمان‌بندی کار سنگین بدون افت پاسخ‌گویی (Performance Engineering).
// runChunked: آیتم‌ها را در تکه‌های زمانی (budget) و در زمان idle پردازش می‌کند.
//   - eager آیتم اول را همان لحظه (برای محتوای بالای صفحه) انجام می‌دهد.
//   - هر تکه حداکثر budgetMs طول می‌کشد تا Long Task ایجاد نشود.
//   - timeout در requestIdleCallback تضمین می‌کند کار گرسنه نماند حتی وقتی صفحه مشغول است.
//   - cancel برای توقف هنگام تغییر مسیر.
// onVisible: یک IntersectionObserver مشترک که کار را فقط وقتی عنصر به viewport نزدیک می‌شود اجرا می‌کند.

type IdleHandle =
  { kind: "idle"; id: number } | { kind: "timeout"; id: ReturnType<typeof globalThis.setTimeout> };

export interface RunChunkedOptions {
  budgetMs?: number;
  eager?: number;
  done?: () => void;
}

export interface ChunkedRun {
  cancel(): void;
  readonly remaining: number;
}

export interface VisibilityWatcher {
  observe(el: Element): void;
  unobserve(el: Element): void;
  disconnect(): void;
}

const g: typeof globalThis = typeof window !== "undefined" ? window : globalThis;
const hasIdle = typeof g.requestIdleCallback === "function";

function scheduleIdle(fn: () => void): IdleHandle {
  if (hasIdle) return { kind: "idle", id: g.requestIdleCallback(fn, { timeout: 300 }) };
  return { kind: "timeout", id: g.setTimeout(() => fn(), 16) };
}

function cancelIdle(handle: IdleHandle | null): void {
  if (!handle) return;
  if (handle.kind === "idle" && hasIdle) g.cancelIdleCallback(handle.id);
  else if (handle.kind === "timeout") g.clearTimeout(handle.id);
}

function runChunked<T>(
  items: readonly T[],
  work: (item: T, index: number) => void,
  options?: RunChunkedOptions,
): ChunkedRun {
  const opts: RunChunkedOptions = options || {};
  const budgetMs = Number.isFinite(opts.budgetMs) ? (opts.budgetMs as number) : 6;
  const eager = Math.min(items.length, Number.isInteger(opts.eager) ? (opts.eager as number) : 0);
  let next = 0;
  let handle: IdleHandle | null = null;
  let cancelled = false;

  function finish(): void {
    if (!cancelled && opts.done) opts.done();
  }

  function step(): void {
    handle = null;
    if (cancelled) return;
    const t0 = g.performance.now();
    while (next < items.length) {
      work(items[next] as T, next);
      next += 1;
      if (g.performance.now() - t0 > budgetMs) break;
    }
    if (next < items.length) handle = scheduleIdle(step);
    else finish();
  }

  for (let i = 0; i < eager; i += 1) {
    work(items[i] as T, i);
    next = i + 1;
  }
  if (next < items.length) handle = scheduleIdle(step);
  else finish();

  return {
    cancel() {
      cancelled = true;
      cancelIdle(handle);
      handle = null;
    },
    get remaining() {
      return items.length - next;
    },
  };
}

// اجرای کار فقط وقتی عنصر نزدیک viewport است. برمی‌گرداند observer تا بتوان disconnect کرد.
function onVisible(fn: (el: Element) => void, rootMargin?: string): VisibilityWatcher {
  if (!("IntersectionObserver" in g)) {
    // بدون IntersectionObserver همان لحظه اجرا می‌شود (سازگاری، نه مسیر خاص)
    return {
      observe: (el: Element) => fn(el),
      unobserve() {},
      disconnect() {},
    };
  }
  const obs: IntersectionObserver = new g.IntersectionObserver(
    (entries) => {
      entries.forEach((en) => {
        if (!en.isIntersecting) return;
        obs.unobserve(en.target);
        fn(en.target);
      });
    },
    { rootMargin: rootMargin || "600px 0px" },
  );
  return obs;
}

const SchedulerApi = Object.freeze({ runChunked, onVisible });

declare global {
  var Scheduler: typeof SchedulerApi;
}

globalThis.Scheduler = SchedulerApi;
