// گذرگاه رویداد نوع‌امن برای جدا کردن UI از موتور.
// موتور رویداد منتشر می‌کند؛ UI با on() گوش می‌دهد و مستقیم به موتور وابسته نیست.

type Listener = (payload: never) => void;

export class Emitter<E extends { [K in keyof E]: unknown }> {
  private readonly listeners = new Map<keyof E, Set<Listener>>();

  // ثبت شنونده؛ تابع برگشتی شنونده را حذف می‌کند
  on<K extends keyof E>(event: K, fn: (payload: E[K]) => void): () => void {
    let set = this.listeners.get(event);
    if (!set) {
      set = new Set();
      this.listeners.set(event, set);
    }
    set.add(fn as Listener);
    return () => this.off(event, fn);
  }

  off<K extends keyof E>(event: K, fn: (payload: E[K]) => void): void {
    this.listeners.get(event)?.delete(fn as Listener);
  }

  // خطای یک شنونده نباید بقیهٔ شنونده‌ها یا فرستنده را متوقف کند
  emit<K extends keyof E>(event: K, payload: E[K]): void {
    const set = this.listeners.get(event);
    if (!set) return;
    for (const fn of Array.from(set)) {
      try {
        (fn as (payload: E[K]) => void)(payload);
      } catch (err) {
        console.error("[Events] listener failed for " + String(event), err);
      }
    }
  }

  listenerCount<K extends keyof E>(event: K): number {
    return this.listeners.get(event)?.size ?? 0;
  }
}

// رویدادهای استاندارد موتور
export type EngineEvents = {
  "pack:loaded": { id: string };
  "pack:activated": { id: string };
  "session:rendered": { packId: string; sessionId: string };
  "attempt:recorded": { packId: string; problemId: string };
};

export const engineEvents = new Emitter<EngineEvents>();
