/*
 * ثبت Service Worker و جریان به‌روزرسانی.
 * - نسخهٔ جدید بلافاصله فعال نمی‌شود؛ در پس‌زمینه نصب و با پیام کوتاه اعلام می‌شود.
 * - وقتی کاربر تب را ترک کند، نسخهٔ جدید فعال می‌شود و صفحه یک‌بار بازمی‌شود.
 * - هیچ reload ای در نصب اولیه (بدون کنترل‌گر قبلی) رخ نمی‌دهد.
 */
(function initSwRegister(global) {
  "use strict";

  if (!("serviceWorker" in navigator)) return;
  const host = location.hostname;
  const secure = location.protocol === "https:" || host === "localhost" || host === "127.0.0.1";
  if (!secure) return;

  const hadController = !!navigator.serviceWorker.controller;
  let reloading = false;
  let waitingReg = null;

  // API عمومی برای release.js: آیا نسخهٔ جدید منتظر فعال‌سازی است، و اعمال آن
  global.SwUpdate = Object.freeze({
    hasWaiting: () => !!(waitingReg && waitingReg.waiting),
    apply: () => {
      if (waitingReg && waitingReg.waiting) waitingReg.waiting.postMessage({ type: "SKIP_WAITING" });
    },
  });

  navigator.serviceWorker.addEventListener("controllerchange", () => {
    if (!hadController || reloading) return;
    reloading = true;
    location.reload();
  });

  function notifyUpdate(reg) {
    waitingReg = reg;
    global.dispatchEvent(new Event("lector:sw-update"));
    // توست حذف شد چون پیل شناور سمت راست (release.js) این کار را انجام می‌دهد
    const onHidden = () => {
      if (document.visibilityState !== "hidden") return;
      document.removeEventListener("visibilitychange", onHidden);
      if (reg.waiting) reg.waiting.postMessage({ type: "SKIP_WAITING" });
    };
    document.addEventListener("visibilitychange", onHidden);
  }

  global.addEventListener("load", async () => {
    let reg;
    try {
      reg = await navigator.serviceWorker.register("./sw.js", { scope: "./" });
    } catch (_) {
      return;
    }

    waitingReg = reg;
    if (reg.waiting && hadController) notifyUpdate(reg);

    reg.addEventListener("updatefound", () => {
      const next = reg.installing;
      if (!next) return;
      next.addEventListener("statechange", () => {
        if (next.state === "installed" && navigator.serviceWorker.controller) notifyUpdate(reg);
      });
    });

    document.addEventListener("visibilitychange", () => {
      if (document.visibilityState === "visible") reg.update().catch(() => {});
    });
  });
})(window);
