// مدل تسلط (Mastery) — Phase 4 (4.3).
// خالص: بدون DOM، بدون storage، بدون وابستگی به window. ورودی‌ها را بیرون می‌گیرد؛ در Node قابل تست است.
//
// شواهد (evidence): فقط پاسخ‌های نمره‌دار و مرور فلش‌کارت.
//   - پاسخ مسئله (AttemptLog): correct / incorrect / unit-missing / unit-mismatch. «unchecked» و «invalid» شاهد نیستند.
//   - مرور فلش‌کارت (flash event): again / hard / good / easy.
//   - خواندن جلسه، علامت «حل‌شده» دستی، نشانک و یادداشت شاهد نیستند.
//
// هر شاهد: { unit, q (0..1), w (وزن), at (ms) }.
// هر unit یک «مفهوم» است: کلید knowledge اگر در پک تعریف شده؛ وگرنه بخش مسئله (sec:k) یا جلسه (sess:id).
//
// وضعیت‌ها:
//   unseen     : هیچ شاهدی نیست
//   learning   : شاهد کم یا نمره‌ها هنوز پایین‌اند
//   practicing : شاهد کافی؛ نمرهٔ زوال‌یافته ≥ practiceScore اما هنوز به «مسلط» نرسیده
//   mastered   : شاهد کافی، روزهای متمایز، نمرهٔ خام و زوال‌یافته ≥ masterScore، و مرور به‌موقع
//   decaying   : قبلاً شواهد قوی داشته ولی حالا زوال‌یافته یا عقب‌افتادهٔ مرور است
// uncertain=true یعنی شاهد کمتر از minEvidence است؛ چنین مفهومی هرگز «مسلط» نمی‌شود.

// نوع هر unit: مفهوم (knowledge)، جلسه، بخش مسئله یا دیگر.
export type UnitKind = "session" | "concept" | "section" | "other";

// وضعیت یک unit (مطابق توضیح بالای فایل).
export type UnitStatus = "unseen" | "learning" | "practicing" | "mastered" | "decaying";

// شاهد نمره‌دار برای یک unit.
export interface Evidence {
  unit: string;
  q: number;
  w: number;
  at: number;
}

// ورودی شاهد برای buildReport: w اختیاری است و پیش‌فرض ۱ دارد.
export interface EvidenceInput {
  unit: string;
  q: number;
  w?: number;
  at: number;
}

// تعریف یک unit در universe (ورودی buildReport).
export interface UnitInput {
  id: string;
  label?: string;
  kind?: UnitKind;
  prereq?: string[];
}

// unit به‌همراه خروجی کلاس‌بندی (Unit + UnitState).
export interface Unit {
  id: string;
  label: string;
  kind: UnitKind;
  prereq: string[];
}

// نتیجهٔ classifyUnit برای یک unit.
export interface UnitState {
  n: number;
  uncertain: boolean;
  lastAt: number | null;
  nextDueAt: number | null;
  ivl: number;
  reps: number;
  ease: number;
  status: UnitStatus;
  score: number;
  rawScore: number;
  strength: number;
  overdueDays: number;
}

export type UnitReport = Unit & UnitState;

// گزارش کامل تسلط.
export interface MasteryReport {
  now: number;
  total: number;
  counts: Record<UnitStatus, number>;
  units: UnitReport[];
}

// وضعیت یک مسئله برای پیشنهاد گام بعدی.
export interface ProblemState {
  id: string;
  packId: string;
  title: string;
  units: string[];
  wrong: number;
  tried: number;
  solved: boolean;
}

export type NextAction = "review" | "practice" | "learn";

// یک پیشنهاد گام بعدی.
export interface NextStep {
  unitId: string;
  label: string;
  status: UnitStatus;
  action: NextAction;
  reason: string;
  problem: { id: string; title: string; wrong: number } | null;
}

// ورودی پاسخ (از AttemptLog). at و status و pid نوع‌بندی‌شده‌اند؛ hintsUsed خام است.
export interface AttemptEvidenceInput {
  pid: string;
  packId?: string;
  status: string;
  hintsUsed?: unknown;
  at: number;
}

// رویداد مرور فلش‌کارت.
export interface FlashEventInput {
  t?: unknown;
  cardId?: unknown;
  result?: unknown;
  ts?: unknown;
  packId?: string;
}

export interface SessionInput {
  id: string;
  title?: string;
  hasCards?: boolean;
}

export interface KnowledgeInput {
  id: string;
  title?: string;
  prereq?: string[];
}

export interface SectionInput {
  k: string | number;
  t?: string;
}

export interface ProblemInput {
  id: string;
  title?: string;
  section?: string | number;
  concepts?: string[];
}

// داده‌های خام یک پک.
export interface PackInput {
  id: string;
  sessions?: SessionInput[];
  knowledge?: KnowledgeInput[];
  sections?: SectionInput[];
  problems?: ProblemInput[];
}

// ورودی کامل collect.
export interface CollectInput {
  packs?: PackInput[];
  activePackId?: string;
  attempts?: AttemptEvidenceInput[];
  flashEvents?: FlashEventInput[];
  solvedIds?: Set<string> | readonly string[];
}

export interface CollectResult {
  units: Unit[];
  evidence: Evidence[];
  problems: ProblemState[];
}

export interface MasteryConfig {
  halfLifeDays: number;
  priorWeight: number;
  minEvidence: number;
  minDays: number;
  masterScore: number;
  practiceScore: number;
  decayScore: number;
  successQ: number;
  cardWeight: number;
  quizWeight: number;
  hintStep: number;
  hintFloor: number;
}

export interface ScheduleState {
  ease: number;
  reps: number;
  ivl: number;
  lastAt: number | null;
  nextDueAt: number | null;
}

export interface MasteryModelApi {
  CONFIG: Readonly<MasteryConfig>;
  STATUSES: readonly UnitStatus[];
  attemptQuality: (status: string, hintsUsed: unknown) => number | null;
  cardQuality: (grade: unknown) => number | null;
  replay: (evidence: Evidence[]) => ScheduleState;
  classifyUnit: (evidence: Evidence[], now: number) => UnitState;
  buildReport: (input: {
    units?: UnitInput[];
    evidence?: EvidenceInput[];
    now?: number;
  }) => MasteryReport;
  nextSteps: (
    report: MasteryReport,
    options?: { limit?: number; problems?: ProblemState[] },
  ) => NextStep[];
  collect: (input: CollectInput) => CollectResult;
}

const DAY = 86400000;

export const CONFIG: Readonly<MasteryConfig> = Object.freeze({
  halfLifeDays: 14, // نیمه‌عمر یادآوری: شاهدِ ۱۴ روز پیش نصف وزن دارد
  priorWeight: 1, // شبه‌شاهد با کیفیت ۰٫۵ تا شواهد کم، نمره را به سمت «نامشخص» می‌کشد
  minEvidence: 3,
  minDays: 2, // مسلط شدن باید در حداقل دو روز متفاوت دیده شود
  masterScore: 0.85,
  practiceScore: 0.6,
  decayScore: 0.7,
  successQ: 0.6,
  cardWeight: 0.5, // خودارزیابی فلش‌کارت کمتر از پاسخ نمره‌دار وزن دارد
  quizWeight: 0.5, // پرسش چندگزینه‌ای حدس‌پذیر است؛ وزنش کمتر از پاسخ مسئله
  hintStep: 0.15, // هر راهنمایی، نمرهٔ پاسخ درست را این‌قدر کم می‌کند
  hintFloor: 0.5,
});
export const STATUSES: readonly UnitStatus[] = Object.freeze([
  "unseen",
  "learning",
  "practicing",
  "mastered",
  "decaying",
] as const);
const ATTEMPT_Q: Readonly<Record<string, number>> = Object.freeze({
  correct: 1,
  "unit-missing": 0.4,
  "unit-mismatch": 0.3,
  incorrect: 0,
});
const CARD_Q: Readonly<Record<string, number>> = Object.freeze({
  again: 0,
  hard: 0.5,
  good: 0.8,
  easy: 1,
});

function has(obj: object, k: PropertyKey): boolean {
  return Object.prototype.hasOwnProperty.call(obj, k);
}

// کیفیت یک پاسخ در بازهٔ 0..1، یا null اگر شاهد نیست.
export function attemptQuality(status: string, hintsUsed: unknown): number | null {
  if (!has(ATTEMPT_Q, status)) return null;
  if (status !== "correct") return ATTEMPT_Q[status] ?? null;
  const h = Math.max(0, Math.floor(Number(hintsUsed) || 0));
  return Math.max(CONFIG.hintFloor, 1 - CONFIG.hintStep * h);
}

export function cardQuality(grade: unknown): number | null {
  if (typeof grade !== "string" || !has(CARD_Q, grade)) return null;
  return CARD_Q[grade] ?? null;
}

// زمان‌بندی SM-2 ساده، با پخش مجدد شواهد به ترتیب زمان. خالص و قابل بازتولید.
export function replay(evidence: Evidence[]): ScheduleState {
  const ev = sortByTime(evidence);
  let ease = 2.5;
  let reps = 0;
  let ivl = 0;
  let lastAt: number | null = null;
  ev.forEach((e) => {
    const q5 = Math.round(e.q * 5);
    if (q5 >= 3) {
      reps += 1;
      ivl = reps === 1 ? 1 : reps === 2 ? 3 : Math.max(1, Math.round(ivl * ease));
    } else {
      reps = 0;
      ivl = 1;
    }
    ease = Math.max(1.3, ease + (0.1 - (5 - q5) * (0.08 + (5 - q5) * 0.02)));
    lastAt = e.at;
  });
  return {
    ease,
    reps,
    ivl,
    lastAt,
    nextDueAt: lastAt == null ? null : lastAt + ivl * DAY,
  };
}

function sortByTime(evidence: Evidence[]): Evidence[] {
  return evidence.slice().sort((a, b) => a.at - b.at);
}

function decayedWeight(e: Evidence, now: number): number {
  const ageDays = Math.max(0, (now - e.at) / DAY);
  return e.w * Math.pow(0.5, ageDays / CONFIG.halfLifeDays);
}

// میانگین وزنی کیفیت با شبه‌شاهد. decay=false یعنی نمرهٔ خام (بدون زوال).
function weightedScore(
  evidence: Evidence[],
  now: number,
  decay: boolean,
): { score: number; strength: number } {
  let num = CONFIG.priorWeight * 0.5;
  let den = CONFIG.priorWeight;
  let strength = 0;
  evidence.forEach((e) => {
    const w = decay ? decayedWeight(e, now) : e.w;
    num += w * e.q;
    den += w;
    strength += w;
  });
  return { score: num / den, strength };
}

function dayKey(ts: number): string {
  const d = new Date(ts);
  return d.getFullYear() + "-" + (d.getMonth() + 1) + "-" + d.getDate();
}

// طبقه‌بندی یک مفهوم بر اساس شواهدش.
export function classifyUnit(evidence: Evidence[], now: number): UnitState {
  const ev = sortByTime(evidence);
  const n = ev.length;
  const sched = replay(ev);
  const base = {
    n,
    uncertain: n < CONFIG.minEvidence,
    lastAt: sched.lastAt,
    nextDueAt: sched.nextDueAt,
    ivl: sched.ivl,
    reps: sched.reps,
    ease: Math.round(sched.ease * 100) / 100,
  };
  if (n === 0) {
    return {
      ...base,
      status: "unseen",
      score: 0,
      rawScore: 0,
      strength: 0,
      overdueDays: 0,
      uncertain: true,
    };
  }
  const decayed = weightedScore(ev, now, true);
  const raw = weightedScore(ev, now, false);
  const days = new Set(ev.filter((e) => e.q >= CONFIG.successQ).map((e) => dayKey(e.at))).size;
  const strong =
    n >= CONFIG.minEvidence && raw.score >= CONFIG.masterScore && days >= CONFIG.minDays;
  const overdueDays =
    sched.nextDueAt == null
      ? 0
      : Math.max(0, (now - sched.nextDueAt) / DAY - Math.max(1, sched.ivl));
  const overdue = overdueDays > 0;

  let status: UnitStatus;
  if (strong && (overdue || decayed.score < CONFIG.decayScore)) status = "decaying";
  else if (strong && decayed.score >= CONFIG.masterScore) status = "mastered";
  else if (n >= CONFIG.minEvidence && decayed.score >= CONFIG.practiceScore) status = "practicing";
  else status = "learning";

  return {
    ...base,
    status,
    score: round3(decayed.score),
    rawScore: round3(raw.score),
    strength: round3(decayed.strength),
    overdueDays: Math.round(overdueDays * 10) / 10,
  };
}

function round3(x: number): number {
  return Math.round(x * 1000) / 1000;
}

// گزارش کامل: universe مفاهیم + شواهد. مفاهیمی که شاهد دارند ولی در universe نیستند هم می‌آیند.
export function buildReport(input: {
  units?: UnitInput[];
  evidence?: EvidenceInput[];
  now?: number;
}): MasteryReport {
  const now = typeof input.now === "number" && Number.isFinite(input.now) ? input.now : Date.now();
  const meta = new Map<string, UnitInput>();
  (input.units || []).forEach((u) => meta.set(u.id, u));
  const byUnit = new Map<string, Evidence[]>();
  (input.evidence || []).forEach((e) => {
    if (!e || typeof e.unit !== "string" || !Number.isFinite(e.q) || !Number.isFinite(e.at)) return;
    const w = typeof e.w === "number" && Number.isFinite(e.w) ? e.w : 1;
    let bucket = byUnit.get(e.unit);
    if (!bucket) {
      bucket = [];
      byUnit.set(e.unit, bucket);
    }
    bucket.push({ unit: e.unit, q: Math.min(1, Math.max(0, e.q)), w, at: e.at });
    if (!meta.has(e.unit))
      meta.set(e.unit, { id: e.unit, label: e.unit, kind: "other", prereq: [] });
  });
  const list: UnitReport[] = [];
  meta.forEach((u) => {
    const state = classifyUnit(byUnit.get(u.id) || [], now);
    list.push({
      id: u.id,
      label: u.label || u.id,
      kind: u.kind || "other",
      prereq: u.prereq || [],
      ...state,
    });
  });
  const counts = {} as Record<UnitStatus, number>;
  STATUSES.forEach((s) => (counts[s] = 0));
  list.forEach((u) => (counts[u.status] += 1));
  return { now, total: list.length, counts, units: list };
}

// پیشنهاد گام بعدی، قانون‌محور:
//   ۱) مفاهیم زوال‌یافته (مرورشان عقب افتاده)
//   ۲) مفاهیم در حال یادگیری/تمرین که پیش‌نیازهایشان مسلط است
//   ۳) مفاهیم شروع‌نشده با پیش‌نیاز آماده
// مفهومی که پیش‌نیازش مسلط نیست پیشنهاد نمی‌شود.
export function nextSteps(
  report: MasteryReport,
  options?: { limit?: number; problems?: ProblemState[] },
): NextStep[] {
  const opts = options || {};
  const limit = typeof opts.limit === "number" && Number.isInteger(opts.limit) ? opts.limit : 3;
  const problems = Array.isArray(opts.problems) ? opts.problems : [];
  const units = report.units || [];
  const byId = new Map(units.map((u) => [u.id, u] as const));
  const mastered = new Set(units.filter((u) => u.status === "mastered").map((u) => u.id));
  const ready = (u: UnitReport): boolean => u.prereq.every((p) => mastered.has(p) || !byId.has(p));

  type Suggestion = {
    rank: number;
    sort: number;
    unit: UnitReport;
    action: NextAction;
    reason: string;
  };
  const out: Suggestion[] = [];
  units.forEach((u) => {
    if (u.status === "decaying") {
      out.push({
        rank: 0,
        sort: -u.overdueDays,
        unit: u,
        action: "review",
        reason: "مرورش عقب افتاده؛ قبل از فراموشی کامل بازش کن.",
      });
    } else if (!ready(u)) {
      return;
    } else if (u.status === "learning" || u.status === "practicing") {
      const reason =
        u.status === "practicing"
          ? "نمره‌هایت هنوز به تسلط نرسیده؛ تمرین بیشتر."
          : u.uncertain
            ? "شواهد کافی نیست؛ چند تمرین یا کارت دیگر لازم است."
            : "نمره‌ها پایین‌اند؛ دوباره تمرین کن.";
      out.push({ rank: 1, sort: u.score, unit: u, action: "practice", reason });
    } else if (u.status === "unseen") {
      out.push({
        rank: 2,
        sort: 0,
        unit: u,
        action: "learn",
        reason: "هنوز شروع نشده؛ از کارت‌ها یا تمرین‌های این بخش شروع کن.",
      });
    }
  });
  out.sort((a, b) => a.rank - b.rank || a.sort - b.sort);

  return out.slice(0, limit).map((s) => {
    const candidates = problems.filter((p) => !p.solved && p.units.indexOf(s.unit.id) !== -1);
    // مسئلهٔ پیشنهادی: اول آنکه بیشترین خطا را داشته، بعد آنکه تلاش نشده
    candidates.sort((a, b) => b.wrong - a.wrong || a.tried - b.tried);
    const pick = candidates[0] || null;
    return {
      unitId: s.unit.id,
      label: s.unit.label,
      status: s.unit.status,
      action: s.action,
      reason: s.reason,
      problem: pick ? { id: pick.id, title: pick.title, wrong: pick.wrong } : null,
    };
  });
}

// تبدیل داده‌های خام (پک‌ها، تلاش‌ها، رویدادهای فلش‌کارت) به universe + شواهد. خالص.
//   packs: [{ id, sessions:[{id,title,hasCards}], knowledge:[{id,title,prereq}], sections:[{k,t}],
//             problems:[{id,title,section,concepts}] }]
//   attempts: [{pid, packId, status, hintsUsed, at}]
//   flashEvents: [{t:"flash", cardId, result, ts, packId?}]
//   activePackId, solvedIds (Set of pid فعال)
export function collect(input: CollectInput): CollectResult {
  const packs = Array.isArray(input.packs) ? input.packs : [];
  const active = input.activePackId || (packs[0] && packs[0].id) || "";
  const solved = input.solvedIds instanceof Set ? input.solvedIds : new Set(input.solvedIds || []);
  type PackIndex = {
    problems: Map<string, { id: string; title: string; units: string[] }>;
    sections: Map<string, string>;
  };
  const byPack = new Map<string, PackIndex>();
  const units = new Map<string, Unit>();
  const problems = new Map<string, ProblemState>(); // key = packId + "\u0001" + pid
  const sessionUnit = new Map<string, string>(); // packId + "\u0001" + sid -> unit id
  const sessionTitle = new Map<string, string>(); // packId + "\u0001" + sid -> title (همهٔ جلسه‌ها، حتی بدون کارت)

  const addUnit = (id: string, label: string, kind: UnitKind, prereq?: string[]): void => {
    if (!units.has(id)) units.set(id, { id, label, kind, prereq: prereq || [] });
  };

  packs.forEach((pk) => {
    const pindex: PackIndex = { problems: new Map(), sections: new Map() };
    byPack.set(pk.id, pindex);
    (pk.sessions || []).forEach((s) => {
      if (!s) return;
      sessionTitle.set(pk.id + "\u0001" + s.id, s.title || s.id);
      if (!s.hasCards) return;
      const uid = pk.id + "/sess:" + s.id;
      sessionUnit.set(pk.id + "\u0001" + s.id, uid);
      addUnit(uid, s.title || s.id, "session", []);
    });
    const hasKnowledge = (pk.knowledge || []).length > 0;
    (pk.knowledge || []).forEach((k) => {
      if (!k || typeof k.id !== "string") return;
      addUnit(
        pk.id + "/" + k.id,
        k.title || k.id,
        "concept",
        (k.prereq || []).map((r) => pk.id + "/" + r),
      );
    });
    const secTitle = new Map<string, string | undefined>(
      (pk.sections || []).map((s): [string, string | undefined] => [String(s.k), s.t]),
    );
    (pk.problems || []).forEach((p) => {
      if (!p || typeof p.id !== "string") return;
      const concepts = (p.concepts || []).filter((c) => typeof c === "string" && c);
      let us: string[];
      if (hasKnowledge && concepts.length) {
        us = concepts.map((c) => pk.id + "/" + c);
      } else {
        const sk = String(p.section == null ? "0" : p.section);
        const sid = pk.id + "/sec:" + sk;
        addUnit(sid, secTitle.get(sk) || "بخش " + sk, "section", []);
        us = [sid];
      }
      pindex.problems.set(p.id, { id: p.id, title: p.title || p.id, units: us });
      problems.set(pk.id + "\u0001" + p.id, {
        id: p.id,
        packId: pk.id,
        title: p.title || p.id,
        units: us,
        wrong: 0,
        tried: 0,
        solved: pk.id === active && solved.has(p.id),
      });
    });
  });

  const evidence: Evidence[] = [];
  (input.attempts || []).forEach((a) => {
    if (!a || typeof a.pid !== "string") return;
    const pack = a.packId || active;
    // پرسش quiz درون جلسه: شناسه به شکل quiz:<sid>:<index>. فقط برای پاسخ اول ثبت می‌شود.
    if (a.pid.indexOf("quiz:") === 0) {
      const cut = a.pid.lastIndexOf(":");
      const sid = a.pid.slice(5, cut);
      const key = pack + "\u0001" + sid;
      const q = attemptQuality(a.status, 0);
      if (q == null || !sessionTitle.has(key)) return;
      const uid = pack + "/sess:" + sid;
      addUnit(uid, sessionTitle.get(key) ?? "", "session", []);
      evidence.push({ unit: uid, q, w: CONFIG.quizWeight, at: a.at });
      return;
    }
    const packIdx = byPack.get(pack);
    const rec = packIdx ? packIdx.problems.get(a.pid) : null;
    if (!rec) return;
    const q = attemptQuality(a.status, a.hintsUsed);
    if (q == null) return;
    const pr = problems.get(pack + "\u0001" + a.pid);
    if (pr) {
      pr.tried += 1;
      if (a.status === "incorrect") pr.wrong += 1;
    }
    rec.units.forEach((u) => evidence.push({ unit: u, q, w: 1, at: a.at }));
  });

  (input.flashEvents || []).forEach((ev) => {
    if (!ev || ev.t !== "flash") return;
    const q = cardQuality(ev.result);
    if (q == null) return;
    const sid =
      typeof ev.cardId === "string" ? /^[cf]:([^:]+):\d+$/.exec(ev.cardId)?.[1] : undefined;
    if (sid === undefined) return;
    const pack = ev.packId || active;
    const uid = sessionUnit.get(pack + "\u0001" + sid);
    if (!uid) return;
    evidence.push({
      unit: uid,
      q,
      w: CONFIG.cardWeight,
      at: typeof ev.ts === "number" && Number.isFinite(ev.ts) ? ev.ts : 0,
    });
  });

  return {
    units: [...units.values()],
    evidence,
    problems: [...problems.values()],
  };
}

// ── سازگاری با کد JS موجود: نام global «MasteryModel» ─────────────────
const legacyApi: MasteryModelApi = Object.freeze({
  CONFIG,
  STATUSES,
  attemptQuality,
  cardQuality,
  replay,
  classifyUnit,
  buildReport,
  nextSteps,
  collect,
});
Object.assign(globalThis, { MasteryModel: legacyApi });

