import { main } from "../preferences/prefs.js";
import { escHtml, katexify } from "../core.js";
import { ArchetypeRegistry } from "./registry.js";
import type { Archetype, ArchetypeSession } from "./registry.js";
ArchetypeRegistry.register({
  id: "stem",
  version: 1,
  extends: "base",
  resolveMode(mode, session) {
    return (ArchetypeRegistry.get("base") as Archetype).resolveMode(mode, session);
  },

  decorateSession(s: ArchetypeSession, mode: string | undefined) {
    const inSess = document.body.classList.contains("in-session");
    const page =
      main.querySelector<HTMLElement>(".session-page") ||
      (inSess ? main.querySelector<HTMLElement>(".page") : null);
    if (!page || page.dataset.v2Upgraded) return;

    page.dataset.v2Upgraded = "1";
    page.dataset.v2Mode = mode || "cards";
    page.classList.add("v2-session-page");

    let toc: Element | null = page.querySelector(".sess-toc, [data-toc]");
    if (!toc) toc = main.querySelector(".sess-toc");

    const mainCol = document.createElement("div");
    mainCol.className = "v2-session-main";

    Array.from(page.children).forEach((child) => {
      if (child !== toc) mainCol.appendChild(child);
    });

    page.appendChild(mainCol);

    if (toc) {
      toc.classList.add("v2-toc");
      page.appendChild(toc);
    } else {
      page.classList.add("v2-no-toc");
    }

    const oldHead = mainCol.querySelector(".shead, .sess-head, .session-head, header");
    const titleEl = mainCol.querySelector("h1, h2");
    const title = escHtml(
      (titleEl && titleEl.textContent ? titleEl.textContent.trim() : "") || s.title || "",
    );
    const summary = escHtml(s.summary || "");
    const topics = Array.isArray(s.topics) ? s.topics.slice(0, 4) : [];
    const prereq = Array.isArray(s.prereq) ? s.prereq.slice(0, 3) : [];

    const heroShowSummary = mode === "cards";
    const heroShowChips = mode === "detail";

    const topbar = document.createElement("div");
    topbar.className = "v2-topbar";
    topbar.innerHTML = `
      <div class="v2-crumb">
      <span class="v2-chapter">جلسه ${escHtml(String(s.num || ""))}</span>
      ${s.date ? `<span class="v2-dot">•</span><span>${escHtml(s.date)}</span>` : ""}
      ${s.time ? `<span class="v2-dot">•</span><span>${escHtml(s.time)}</span>` : ""}
      </div>
      <div class="v2-top-actions"></div>
      `;

    const actions = topbar.querySelector<HTMLElement>(".v2-top-actions") as HTMLElement;
    const readBtn = mainCol.querySelector("#readBtn");
    const bmBtn = mainCol.querySelector("#bmBtn");
    const modeSw = mainCol.querySelector(".mode-switch");
    const notesEl = mainCol.querySelector(".sess-notes");

    if (readBtn) actions.appendChild(readBtn);
    if (bmBtn) {
      bmBtn.classList.add("sess-bm-btn");
      actions.appendChild(bmBtn);
    }
    if (modeSw) actions.appendChild(modeSw);

    const hero = document.createElement("section");
    hero.className = "v2-hero";
    hero.innerHTML = `
      <h1 class="v2-title">${title}</h1>
      ${heroShowSummary && summary ? `<p class="v2-objective">${summary}</p>` : ""}
      ${
        heroShowChips
          ? `<div class="v2-meta">
      ${topics.map((t) => `<span class="v2-chip">${escHtml(t)}</span>`).join("")}
      ${prereq.length ? `<span class="v2-chip v2-prereq">پیش‌نیاز: ${prereq.map((x) => escHtml(x)).join("، ")}</span>` : ""}
      </div>`
          : ""
      }
      `;

    mainCol.insertBefore(hero, mainCol.firstChild);
    mainCol.insertBefore(topbar, hero);
    if (notesEl) {
      notesEl.classList.add("sess-notes-v2");
      if (notesEl.parentNode) notesEl.parentNode.removeChild(notesEl);
      if (hero.nextSibling) mainCol.insertBefore(notesEl, hero.nextSibling);
      else mainCol.appendChild(notesEl);
    }

    if (oldHead) oldHead.classList.add("v2-old-head");
    if (titleEl) titleEl.classList.add("v2-old-title");

    mainCol.querySelectorAll(".rd-formula, .fcard").forEach((el) => {
      el.classList.add("v2-formula");
    });

    mainCol.querySelectorAll(".widget").forEach((el) => {
      el.classList.add("v2-lab");
      const stage = el.querySelector(".wstage, canvas, svg");
      if (stage) stage.classList.add("v2-stage");
    });

    mainCol.querySelectorAll(".rd-callout, .notebox, .exbox").forEach((el) => {
      el.classList.add("v2-callout");
    });

    mainCol.querySelectorAll(".sess-sec > h2, .sec-title h2").forEach((el) => {
      el.classList.add("v2-section-title");
    });

    if (typeof katexify === "function") katexify(mainCol);
  },
});
