(function initMotion(global) {
  "use strict";

  const EASE = {
    standard: "cubic-bezier(.22,1,.36,1)",
    ios: "cubic-bezier(.32,.72,0,1)",
    spring: "cubic-bezier(.34,1.56,.64,1)",
    soft: "cubic-bezier(.4,.1,.2,1)",
  };

  function _prefersReduced() {
    const dm = document.documentElement.dataset.motion;
    if (dm === "off" || dm === "reduced") return true;
    return global.matchMedia && global.matchMedia("(prefers-reduced-motion: reduce)").matches;
  }

  function _durations() {
    const dm = document.documentElement.dataset.motion;
    if (dm === "off") return { instant: 0, fast: 0, base: 0, slow: 0, slower: 0 };
    const cs = getComputedStyle(document.documentElement);
    const parse = (k, d) => parseFloat(cs.getPropertyValue(k)) || d;
    return {
      instant: parse("--dur-instant", 80),
      fast: parse("--dur-fast", 180),
      base: parse("--dur-base", 300),
      slow: parse("--dur-slow", 500),
      slower: parse("--dur-slower", 800),
    };
  }

  function _supports(el) {
    return el && typeof el.animate === "function";
  }

  function play(el, keyframes, options) {
    if (!el) return null;
    if (!_supports(el)) return null;
    const opts = Object.assign({}, options);
    if (opts.duration == null) opts.duration = _durations().base;
    if (opts.easing == null) opts.easing = EASE.standard;
    if (opts.fill == null) opts.fill = "both";
    if (_prefersReduced()) {
      opts.duration = 0;
      opts.delay = 0;
    }
    try {
      return el.animate(keyframes, opts);
    } catch (_) {
      return null;
    }
  }

  function toastEnter(el) {
    return play(
      el,
      [
        { opacity: 0, transform: "translateY(22px) scale(.94)" },
        { opacity: 1, transform: "none" },
      ],
      { duration: _durations().slow, easing: EASE.spring },
    );
  }
  function toastExit(el) {
    return play(
      el,
      [
        { opacity: 1, transform: "none" },
        { opacity: 0, transform: "translateY(12px) scale(.94)" },
      ],
      { duration: _durations().fast },
    );
  }

  function cardRise(elements) {
    if (!elements || !elements.length) return Promise.resolve();
    const arr = Array.from(elements);
    const total = arr.length;
    if (_prefersReduced()) return Promise.resolve();

    const maxDelay = Math.min(240, total * 22);
    // اگر تعداد زیاد است، تنها عناصر بالای صفحه animate می‌شوند تا کار
    // سنگین CSS-animation روی صدها عنصرِ خارج از دید ساخته نشود
    const vh = (window.innerHeight || 800) + 200;

    // ۱) همهٔ خواندن‌ها در یک مرحله (یک layout)؛ قبلاً برای هر کارت یک reflow جداگانه می‌شد
    const visible = [];
    for (let i = 0; i < total; i++) {
      if (arr[i].getBoundingClientRect().top <= vh) visible.push(i);
    }
    // ۲) نوشتن استایل‌ها و حذف کلاس برای همهٔ عناصر قابل‌دید
    for (const i of visible) {
      const el = arr[i];
      const delay = total < 2 ? 0 : (i / Math.max(1, total - 1)) * maxDelay;
      el.style.setProperty("--rise-i", String(Math.round(delay)));
      el.classList.remove("animate-rise");
    }
    // ۳) یک reflow برای ری‌استارت انیمیشن، سپس افزودن کلاس‌ها
    if (visible.length) void arr[visible[0]].offsetWidth;
    for (const i of visible) arr[i].classList.add("animate-rise");
    // پاک‌سازی پس از اتمام تا will-change آزاد شود
    const onEnd = (ev) => {
      if (ev.animationName !== "_cardRiseCss") return;
      const el = ev.target;
      el.classList.remove("animate-rise");
      el.classList.add("animate-rise--done");
      el.removeEventListener("animationend", onEnd);
    };
    arr.forEach((el) => el.addEventListener("animationend", onEnd));
    return Promise.resolve();
  }

  function movePill(pill, targetBtn, container) {
    if (!pill || !targetBtn || !container || !_supports(pill)) return;
    const cs = getComputedStyle(container);
    const z = parseFloat(getComputedStyle(document.documentElement).zoom) || 1;
    const segRect = container.getBoundingClientRect();
    const btnRect = targetBtn.getBoundingClientRect();
    const borderLeft = parseFloat(cs.borderLeftWidth) || 0;
    const paddingBoxLeft = segRect.left + borderLeft;
    const x = Math.round((btnRect.left - paddingBoxLeft) / z);
    const w = Math.round(btnRect.width / z);
    const fromX = pill._x != null ? pill._x : x;
    const fromW = pill._w != null ? pill._w : w;
    const anim = play(
      pill,
      [
        { transform: `translateX(${fromX}px)`, width: fromW + "px" },
        { transform: `translateX(${x}px)`, width: w + "px" },
      ],
      { duration: 320, easing: EASE.standard, fill: "forwards" },
    );
    pill.style.width = w + "px";
    pill._x = x;
    pill._w = w;
    return anim;
  }

  function initPill(pill, x, w) {
    if (!pill) return;
    pill._x = x;
    pill._w = w;
    pill.style.transform = `translateX(${x}px)`;
    pill.style.width = w + "px";
  }

  function withInstant(fn) {
    const html = document.documentElement;
    html.classList.add("theme-instant");
    void html.offsetWidth;
    try {
      fn();
    } catch (_) {}
    requestAnimationFrame(() =>
      requestAnimationFrame(() => {
        html.classList.remove("theme-instant");
      }),
    );
  }

  const api = Object.freeze({
    EASE,
    play,
    toastEnter,
    toastExit,
    cardRise,
    movePill,
    initPill,
    withInstant,
    prefersReduced: _prefersReduced,
  });

  global.Motion = api;
})(typeof window !== "undefined" ? window : globalThis);
