(function () {
  "use strict";
  const K = window.PackWidgetKit;
  const wpal = K.wpal;
  let P = wpal();
  globalThis.addEventListener("lector:theme", () => {
    P = wpal();
  });
  const W = {
    title: "موج ایستاده — گره و شکم",
    desc: "برهم‌نهی دو موج هم‌دامنه در خلاف جهت؛ گره‌ها ثابت‌اند و $\\lambda/2$ فاصله دارند.",
    sess: ["s14", "s15"],
    mount(box) {
      box.innerHTML = `<div class="wstage"><canvas width="700" height="280"></canvas></div><div style="display:flex;gap:14px;align-items:center;margin-top:12px;flex-wrap:wrap"><div class="ctls" style="flex:1;min-width:170px;margin:0"></div><label style="display:flex;gap:8px;align-items:center;font-size:13px;color:var(--text-secondary);cursor:pointer"><input type="checkbox" id="swComp" checked> نمایش دو موج مؤلف</label><button class="btn" id="swPlay">${icon("pause")} توقف</button></div>`;
      const cv = box.querySelector("canvas"),
        x = setupHD(cv, 700, 280),
        comp = box.querySelector("#swComp");
      let t = 0,
        lam = 175,
        play = true;
      ctl(box.querySelector(".ctls"), "طول‌موج", 100, 260, 5, 175, "واحد", (v) => (lam = v));
      box.querySelector("#swPlay").onclick = (e) => {
        play = !play;
        e.target.innerHTML = play ? `${icon("pause")} توقف` : `${icon("play")} پخش`;
      };
      const A = 62,
        cy = 140,
        k = () => (2 * Math.PI) / lam;
      function wave(fn, col, w = 2.5, dash) {
        x.strokeStyle = col;
        x.lineWidth = w;
        x.setLineDash(dash || []);
        x.beginPath();
        for (let X = 30; X <= 670; X++) {
          const Y = cy - fn(X);
          X === 30 ? x.moveTo(X, Y) : x.lineTo(X, Y);
        }
        x.stroke();
        x.setLineDash([]);
      }
      let _visible = true;
      try {
        const _io = new IntersectionObserver(
          (entries) => entries.forEach((e) => { _visible = e.isIntersecting; }),
          { threshold: 0 },
        );
        _io.observe(cv);
      } catch (_) {}

      function frame() {
        if (!cv.isConnected) return;
        if (!_visible || document.hidden || window.__APP_PAUSED) {
          requestAnimationFrame(frame);
          return;
        }
        if (play) t += 0.045;
        x.fillStyle = P.bg;
        x.fillRect(0, 0, 700, 280);
        x.strokeStyle = P.axis;
        x.lineWidth = 1;
        x.beginPath();
        x.moveTo(30, cy);
        x.lineTo(670, cy);
        x.stroke();
        const f1 = (X) => A * Math.sin(k() * (X - 30) - t),
          f2 = (X) => A * Math.sin(k() * (X - 30) + t);
        if (comp.checked) {
          wave(f1, "rgba(251,191,36,.4)", 1.5, [5, 5]);
          wave(f2, "rgba(167,139,250,.4)", 1.5, [5, 5]);
        }
        wave((X) => f1(X) + f2(X), "#22d3ee", 3);
        const half = lam / 2;
        for (let X = 30; X <= 670; X += half) {
          x.fillStyle = "#fb7185";
          x.beginPath();
          x.arc(X, cy, 5, 0, 7);
          x.fill();
        }
        x.font = "11px Vazirmatn";
        x.textAlign = "center";
        x.fillStyle = "#fb7185";
        if (670 - 30 > half) {
          x.fillText("گره‌ها — دامنهٔ صفر — فاصلهٔ متوالی λ/2", 350, 266);
        }
        requestAnimationFrame(frame);
      }
      frame();
    },
  };
  CourseRuntime.registerPackSource("optics", { widgets: { standing: W } });
})();
