// تاریخچهٔ پاسخ‌ها (Attempt log).
// چرا جدا از localStorage؟ هر پاسخ یک رکورد است؛ انباشت هزاران رکورد در یک کلید JSON
// هم سقف حجم دارد و هم هر بار کل آرایه را parse/stringify می‌کند. IndexedDB برای این کار مناسب است.
//
// Backend ها هم‌رابط‌اند: { name, put(row), all() } — async.
//  - memoryBackend: برای تست و وقتی IndexedDB در دسترس نیست (داده با بستن صفحه از بین می‌رود).
//  - indexedDbBackend: مرورگر. اگر باز کردن DB شکست بخورد، AttemptLog خودکار به memory سقوط می‌کند
//    و فلگ fellBack را true می‌کند.
//
// پس از ثبت موفق، رویداد «attempt:recorded» از گذرگاه رویداد موتور منتشر می‌شود.

import { engineEvents } from "../events.js";

// وضعیت یک پاسخ: نتیجهٔ بررسی پاسخ کاربر.
export type AttemptStatus =
  "correct" | "incorrect" | "invalid" | "unit-missing" | "unit-mismatch" | "unchecked";

// رکورد ذخیره‌شدهٔ یک پاسخ (Attempt).
export interface Attempt {
  id: string;
  pid: string;
  packId: string;
  at: number;
  status: AttemptStatus;
  input: string;
  hintsUsed: number;
}

// ورودی ثبت پاسخ، پیش از اعتبارسنجی در normalizeAttempt (مقادیر خام).
export interface AttemptInput {
  pid?: unknown;
  packId?: unknown;
  at?: unknown;
  status?: unknown;
  input?: unknown;
  hintsUsed?: unknown;
}

export interface AttemptBackend {
  readonly name: "memory" | "indexeddb";
  put(row: Attempt): Promise<void>;
  all(): Promise<Attempt[]>;
}

export interface AttemptSummary {
  attempts: number;
  correct: number;
  lastAt: number | null;
  lastStatus: AttemptStatus | null;
}

export interface AttemptLogOptions {
  now?: () => number;
}

export const STATUSES: readonly AttemptStatus[] = Object.freeze([
  "correct",
  "incorrect",
  "invalid",
  "unit-missing",
  "unit-mismatch",
  "unchecked",
] as const);

export const MAX_INPUT = 500;
const DB_NAME = "lector-learning";
const STORE = "attempts";
const DB_VERSION = 1;

function isAttemptStatus(x: unknown): x is AttemptStatus {
  return typeof x === "string" && (STATUSES as readonly unknown[]).includes(x);
}

export function memoryBackend(): AttemptBackend {
  const rows: Attempt[] = [];
  return {
    name: "memory",
    async put(row) {
      rows.push(row);
    },
    async all() {
      return rows.slice();
    },
  };
}

// IndexedDB؛ در محیطی که indexedDB ندارد (Node، تست) null برمی‌گرداند.
export function indexedDbBackend(dbName: string, store: string): AttemptBackend | null {
  if (typeof indexedDB === "undefined" || !indexedDB) return null;
  const db_name = dbName || DB_NAME;
  const store_name = store || STORE;
  let dbPromise: Promise<IDBDatabase> | null = null;

  function open(): Promise<IDBDatabase> {
    if (!dbPromise) {
      dbPromise = new Promise<IDBDatabase>((resolve, reject) => {
        const req = indexedDB.open(db_name, DB_VERSION);
        req.onupgradeneeded = () => {
          const db = req.result;
          if (!db.objectStoreNames.contains(store_name)) {
            const os = db.createObjectStore(store_name, { keyPath: "id" });
            os.createIndex("pid", "pid", { unique: false });
          }
        };
        req.onsuccess = () => resolve(req.result);
        req.onerror = () => reject(req.error || new Error("indexedDB open failed"));
        req.onblocked = () => reject(new Error("indexedDB blocked"));
      });
      dbPromise.catch(() => {
        dbPromise = null;
      });
    }
    return dbPromise;
  }

  return {
    name: "indexeddb",
    async put(row: Attempt): Promise<void> {
      const db = await open();
      await new Promise<void>((resolve, reject) => {
        const tx = db.transaction(store_name, "readwrite");
        tx.objectStore(store_name).put(row);
        tx.oncomplete = () => resolve();
        tx.onerror = () => reject(tx.error);
        tx.onabort = () => reject(tx.error || new Error("tx aborted"));
      });
    },
    async all(): Promise<Attempt[]> {
      const db = await open();
      return new Promise<Attempt[]>((resolve, reject) => {
        const req: IDBRequest<Attempt[]> = db
          .transaction(store_name, "readonly")
          .objectStore(store_name)
          .getAll();
        req.onsuccess = () => resolve(req.result || []);
        req.onerror = () => reject(req.error);
      });
    },
  };
}

function makeId(): string {
  return Date.now().toString(36) + "-" + Math.random().toString(36).slice(2, 10);
}

// اعتبارسنجی و نرمال‌سازی یک پاسخ پیش از ذخیره.
export function normalizeAttempt(a: AttemptInput | null | undefined, now: () => number): Attempt {
  if (!a || typeof a !== "object") throw new TypeError("attempt باید شیء باشد");
  const pid = a.pid;
  if (typeof pid !== "string" || !pid.trim()) throw new TypeError("attempt.pid لازم است");
  const status: AttemptStatus = isAttemptStatus(a.status) ? a.status : "unchecked";
  const hu = a.hintsUsed;
  const hints = typeof hu === "number" && Number.isInteger(hu) && hu > 0 ? hu : 0;
  const packId = a.packId;
  const at = a.at;
  return {
    id: makeId(),
    pid: pid.trim(),
    packId: typeof packId === "string" ? packId : "",
    at: typeof at === "number" && Number.isFinite(at) ? at : now(),
    status,
    input: String(a.input == null ? "" : a.input).slice(0, MAX_INPUT),
    hintsUsed: hints,
  };
}

export class AttemptLog {
  backend: AttemptBackend;
  fellBack: boolean;
  private readonly _now: () => number;

  constructor(backend?: AttemptBackend | null, options?: AttemptLogOptions) {
    const opts: AttemptLogOptions = options || {};
    this.backend = backend || memoryBackend();
    this.fellBack = false;
    this._now = typeof opts.now === "function" ? opts.now : () => Date.now();
  }

  // اگر backend غیر از حافظه خراب شود، به حافظه برمی‌گردیم. حافظه هرگز سقوط نمی‌کند.
  private _fallback(): boolean {
    if (this.backend.name === "memory") return false;
    this.backend = memoryBackend();
    this.fellBack = true;
    return true;
  }

  async record(attempt: AttemptInput): Promise<Attempt> {
    const row = normalizeAttempt(attempt, this._now);
    try {
      await this.backend.put(row);
    } catch (err) {
      if (!this._fallback()) throw err;
      await this.backend.put(row);
    }
    engineEvents.emit("attempt:recorded", { packId: row.packId, problemId: row.pid });
    return row;
  }

  async all(): Promise<Attempt[]> {
    try {
      return await this.backend.all();
    } catch {
      this._fallback();
      return [];
    }
  }

  // جدیدترین اول
  async forProblem(pid: string): Promise<Attempt[]> {
    return (await this.all()).filter((r) => r.pid === pid).sort((x, y) => y.at - x.at);
  }

  async summary(pid: string): Promise<AttemptSummary> {
    const rows = await this.forProblem(pid);
    const first = rows[0];
    return {
      attempts: rows.length,
      correct: rows.filter((r) => r.status === "correct").length,
      lastAt: first ? first.at : null,
      lastStatus: first ? first.status : null,
    };
  }
}

// برای مرورگر: IndexedDB اگر باشد، وگرنه حافظه.
export function createDefaultLog(options?: AttemptLogOptions): AttemptLog {
  const idb = indexedDbBackend(DB_NAME, STORE);
  return new AttemptLog(idb || memoryBackend(), options);
}

// ── سازگاری با کد JS موجود: نام global «AttemptLogModule» ─────────────
// UI هنوز از این نام استفاده می‌کند؛ حذفش در فاز UI انجام می‌شود.
const legacyApi = Object.freeze({
  AttemptLog,
  memoryBackend,
  indexedDbBackend,
  createDefaultLog,
  normalizeAttempt,
  STATUSES,
  MAX_INPUT,
});
Object.assign(globalThis, { AttemptLogModule: legacyApi });
