import { KATEX_DELIMS, escHtml, toFa } from "../../core.js";
import { main } from "../../preferences/prefs.js";
import { icon } from "../components/icons.js";
export function pageGlossary() {
  const items = (CourseRuntime.getCourse() || {}).glossary || [];

  const cards = items
    .map((g) => {
      const term = escHtml(String(g.t || ""));
      const sess = escHtml(String(g.s || ""));
      const def = String(g.d || "");
      const _norm = (s) =>
        String(s || "")
          .toLowerCase()
          .replace(/ي/g, "ی")
          .replace(/ك/g, "ک")
          .replace(/[۰-۹]/g, (d) => String("۰۱۲۳۴۵۶۷۸۹".indexOf(d)))
          .replace(/[٠-٩]/g, (d) => String("٠١٢٣٤٥٦٧٨٩".indexOf(d)))
          .replace(/[\u200c\u200e\u200f\u064b-\u0652\u0654\u0670]/g, "")
          .replace(/\s+/g, " ")
          .trim();
      const search = _norm(String(g.t || "") + " " + String(g.d || "") + " " + String(g.s || ""));
      return `<article class="glos-card" data-search="${escHtml(search)}">
      <div class="glos-head">
        <h3 class="glos-term">${term}</h3>
        ${sess ? `<span class="glos-sess">${sess}</span>` : ""}
      </div>
      <div class="glos-def">${def}</div>
    </article>`;
    })
    .join("");

  main.innerHTML = `<div class="page glos-page">
    <header class="glos-hero">
      <div class="glos-hero-tx">
        <span class="glos-kicker">${icon("book")}واژه‌نامه</span>
        <h1 class="glos-h1">اصطلاحات کلیدی دوره</h1>
        <p class="glos-sub">
          ${toFa(items.length)} اصطلاح تخصصی از تمام جلسات — برای مرور سریع پیش از آزمون.
        </p>
      </div>
      <div class="glos-search">
        ${icon("search")}
        <input type="text" id="glosQ" placeholder="جستجو در واژه‌ها…"
               autocomplete="off" aria-label="جستجو در واژه‌نامه" />
      </div>
    </header>
    <div class="glos-grid" id="glosGrid">${cards}</div>
  </div>`;

  main.querySelectorAll(".glos-card").forEach((card) => {
    if (window.renderMathInElement) {
      renderMathInElement(card, {
        delimiters: KATEX_DELIMS,
        throwOnError: false,
        ignoredTags: ["script", "noscript", "style", "textarea", "pre", "code"],
      });
    }
  });

  const q = main.querySelector("#glosQ");
  const grid = main.querySelector("#glosGrid");
  if (q && grid) {
    let empty = null;
    let timer = 0;
    q.addEventListener("input", () => {
      clearTimeout(timer);
      timer = setTimeout(() => {
        const needle = (() => {
          let s = q.value.trim().toLowerCase();
          s = s.replace(/ي/g, "ی").replace(/ك/g, "ک");
          s = s.replace(/[\u200c\u200e\u200f\u064b-\u0652\u0654\u0670]/g, "");
          return s.replace(/\s+/g, " ");
        })();
        let shown = 0;
        grid.querySelectorAll(".glos-card").forEach((c) => {
          const hit = !needle || (c.dataset.search || "").indexOf(needle) >= 0;
          c.style.display = hit ? "" : "none";
          if (hit) shown++;
        });
        if (!shown) {
          if (!empty) {
            empty = document.createElement("div");
            empty.className = "glos-empty";
            empty.textContent = "واژه‌ای با این عبارت یافت نشد.";
            grid.appendChild(empty);
          }
          empty.style.display = "";
        } else if (empty) {
          empty.style.display = "none";
        }
      }, 120);
    });
  }
}
