import { ArchetypeRegistry } from "./registry.js";
import type { ArchetypeSession } from "./registry.js";

ArchetypeRegistry.register({
  id: "base",
  version: 1,
  resolveMode(mode: string | undefined, session: ArchetypeSession | undefined): string {
    if (
      mode === "detail" &&
      !(session && session.detail && session.detail.sections && session.detail.sections.length)
    )
      return "cards";
    return ["overview", "cards", "detail"].includes(mode ?? "") ? (mode as string) : "cards";
  },
});
