import { _pcal, _persianMonthDays, _persianMonthStartTs, _persianNavMonth, _startOfDay, addTask, escHtml, loadTasks, notificationPermission, removeTask, requestNotificationPermission, stagger, tasksForDay, tasksOverdue, tasksToday, tasksUpcoming, toFa, toast, toggleTask, uiConfirm, updateTask } from "../../core.js";
import { icon } from "../components/icons.js";
import { _dtpFaFull, main, openDateTimePicker } from "../../preferences/prefs.js";
export let _planMonth = null;

export function _planDayKey(ts) {
  const d = new Date(ts);
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const dd = String(d.getDate()).padStart(2, "0");
  return y + "-" + m + "-" + dd;
}

export function _startOfMonth(ts) {
  const d = new Date(ts);
  d.setDate(1);
  d.setHours(0, 0, 0, 0);
  return d.getTime();
}

export function _planFaMonthYear(ts) {
  try {
    const fmt = new Intl.DateTimeFormat("fa-IR", { month: "long", year: "numeric" });
    return fmt.format(new Date(ts));
  } catch (_) {
    return new Date(ts).toLocaleDateString();
  }
}

export function _planFaDayNum(ts) {
  return toFa(_pcal(ts).day);
}

export function _planCalendarHTML(monthTs) {
  const p0 = _pcal(monthTs);
  const days = _persianMonthDays(p0.year, p0.month);
  if (!days.length) return "";

  const jsDay = new Date(days[0].ts).getDay();
  const offset = (jsDay + 1) % 7;
  const today = _startOfDay();

  const byDay = {};
  loadTasks().forEach((t) => {
    const due = Number.isFinite(t.dueAt) ? t.dueAt : t.createdAt;
    const k = _planDayKey(due);
    if (!byDay[k]) byDay[k] = { total: 0, done: 0 };
    byDay[k].total++;
    if (t.done) byDay[k].done++;
  });

  const heads = ["ش", "ی", "د", "س", "چ", "پ", "ج"];
  let html = '<div class="plan-grid-h">';
  heads.forEach((h) => {
    html += `<span>${h}</span>`;
  });
  html += '</div><div class="plan-grid">';
  for (let i = 0; i < offset; i++) {
    html += '<span class="plan-day plan-day--empty"></span>';
  }
  days.forEach(({ ts, day }) => {
    const key = _planDayKey(ts);
    const info = byDay[key] || { total: 0, done: 0 };
    const isToday = _startOfDay(ts) === today;
    const allDone = info.total > 0 && info.done === info.total;
    const isSelected = _planSelectedDay && _startOfDay(_planSelectedDay) === _startOfDay(ts);
    const hasSelection = !!_planSelectedDay;
    const cls = [
      "plan-day",
      isToday && !hasSelection ? "plan-day--today" : "",
      isToday && hasSelection && !isSelected ? "is-today-quiet" : "",
      isSelected ? "is-selected" : "",
      info.total ? "plan-day--has" : "",
      allDone ? "plan-day--done" : "",
    ]
      .filter(Boolean)
      .join(" ");
    const persianDay = toFa(day);
    const countBadge = info.total
      ? `<span class="plan-day-c">${toFa(info.done)}/${toFa(info.total)}</span>`
      : "";
    html += `<button class="${cls}" data-plan-day="${ts}"
      aria-label="روز ${persianDay}${info.total ? " — " + toFa(info.total) + " تسک" : ""}">
      <span class="plan-day-n">${persianDay}</span>
      ${countBadge}
    </button>`;
  });
  html += "</div>";
  return html;
}

export function _planWeekStripHTML() {
  const dayNames = ["ی", "د", "س", "چ", "پ", "ج", "ش"];
  const today = _startOfDay();
  const byDay = {};
  loadTasks().forEach((t) => {
    const due = Number.isFinite(t.dueAt) ? t.dueAt : t.createdAt;
    const k = _planDayKey(due);
    if (!byDay[k]) byDay[k] = { total: 0, done: 0 };
    byDay[k].total++;
    if (t.done) byDay[k].done++;
  });
  let html = "";
  for (let i = 0; i < 7; i++) {
    const ts = today + i * 864e5;
    const d = new Date(ts);
    const key = _planDayKey(ts);
    const info = byDay[key] || { total: 0, done: 0 };
    const isToday = i === 0;
    const allDone = info.total > 0 && info.done === info.total;
    const isSelected = _planSelectedDay && _startOfDay(_planSelectedDay) === ts;
    const hasSelection = !!_planSelectedDay;
    const cls = [
      "plan-week-cell",
      isToday && !hasSelection ? "today" : "",
      isToday && hasSelection && !isSelected ? "is-today-quiet" : "",
      isSelected ? "is-selected" : "",
      allDone ? "done" : "",
    ]
      .filter(Boolean)
      .join(" ");
    const dayName = dayNames[d.getDay()];
    const countCls = info.total ? "plan-week-count" : "plan-week-count empty";
    const countTxt = info.total ? toFa(info.total) : "—";
    html += `<button class="${cls}" data-plan-day="${ts}"
      aria-label="${dayName} — ${_planFaDayNum(ts)}${info.total ? " — " + toFa(info.total) + " تسک" : ""}">
      <span class="plan-week-day">${dayName}</span>
      <span class="plan-week-num">${_planFaDayNum(ts)}</span>
      <span class="${countCls}">${countTxt}</span>
    </button>`;
  }
  return html;
}

export function _planTodayStats() {
  const today = _startOfDay();
  const from = today,
    to = today + 864e5;
  const all = loadTasks().filter((t) => {
    const due = Number.isFinite(t.dueAt) ? t.dueAt : t.createdAt;
    return due >= from && due < to;
  });
  const total = all.length;
  const done = all.filter((t) => t.done).length;
  const pct = total ? Math.round((done / total) * 100) : 0;
  return { total, done, pct };
}
export function _planTaskRow(t) {
  const due = Number.isFinite(t.dueAt) ? t.dueAt : t.createdAt;
  const time = new Date(due);
  const hh = String(time.getHours()).padStart(2, "0");
  const mm = String(time.getMinutes()).padStart(2, "0");
  const dateLb =
    _planFaDayNum(due) +
    " " +
    (() => {
      try {
        return new Intl.DateTimeFormat("fa-IR", { month: "short" }).format(time);
      } catch (_) {
        return "";
      }
    })();
  const overdue = !t.done && due < Date.now();
  const session = t.sessionId && t.packId ? CourseRuntime.getPackById(t.packId) : null;
  const sessionTitle = session
    ? ((session.course && session.course.sessions) || []).find((s) => s.id === t.sessionId)
    : null;

  return `<div class="plan-task${t.done ? " done" : ""}${overdue ? " overdue" : ""}" data-plan-task="${escHtml(t.id)}">
    <button class="task-tick" data-task-toggle="${escHtml(t.id)}"
            aria-label="${t.done ? "برگرداندن به انجام‌نشده" : "علامت انجام‌شده"}">
      ${icon("check")}
    </button>
    <div class="plan-task-tx">
      <b class="plan-task-text" data-task-edit="${escHtml(t.id)}" tabindex="0" role="button">${escHtml(t.text)}</b>
      <span class="plan-task-m">
        ${icon("clock")}
        <span>${toFa(hh)}:${toFa(mm)} · ${toFa(dateLb)}</span>
        ${overdue ? `<span class="overdue-tag">عقب‌افتاده</span>` : ""}
        ${sessionTitle ? `<span>· ${escHtml(sessionTitle.title)}</span>` : ""}
      </span>
    </div>
    <button class="task-menu" data-task-menu="${escHtml(t.id)}"
            aria-label="گزینه‌های تسک" aria-haspopup="true">${icon("more")}</button>
  </div>`;
}
export function _planTasksListHTML() {
  const overdue = typeof tasksOverdue === "function" ? tasksOverdue() : [];
  const today = typeof tasksToday === "function" ? tasksToday() : [];
  const upcoming = typeof tasksUpcoming === "function" ? tasksUpcoming(7) : [];
  const sections = [
    { id: "overdue", title: "عقب‌افتاده", icon: "warn", list: overdue, hl: true },
    { id: "today", title: "امروز", icon: "clock", list: today, hl: false },
    { id: "week", title: "این هفته", icon: "cal", list: upcoming, hl: false },
  ];
  let html = "";
  sections.forEach((s) => {
    if (!s.list.length) return;
    const badgeCls = s.hl ? "badge b-ros" : "badge";
    html += `<div class="plan-sec">
      <div class="plan-sec-h">
        ${icon(s.icon)}<b>${s.title}</b>
        <span class="${badgeCls}">${toFa(s.list.length)}</span>
      </div>
      ${s.list.map(_planTaskRow).join("")}
    </div>`;
  });
  if (!html) {
    html = `<div class="plan-empty">
      ${icon("cal")}
      <b>تسکی برای این هفته نداری</b>
      <span>از کادر بالا یک تسک جدید بساز. می‌توانی زمان دقیق بدهی یا خالی بگذاری.</span>
    </div>`;
  }
  return html;
}
export let _planSelectedDay = null;
export let _planCalAnimCount = 0;

export let _planMenuEl = null;
export function _closePlanTaskMenu() {
  if (_planMenuEl) _planMenuEl.classList.remove("open");
}
export function _openPlanTaskMenu(taskId, anchorEl) {
  const t = loadTasks().find((x) => x.id === taskId);
  if (!t) return;
  if (!_planMenuEl) {
    _planMenuEl = document.createElement("div");
    _planMenuEl.className = "plan-task-menu";
    _planMenuEl.setAttribute("role", "menu");
    document.body.appendChild(_planMenuEl);
    _planMenuEl.addEventListener("click", async (e) => {
      const b = e.target.closest("[data-pm-act]");
      if (!b) return;
      e.stopPropagation();
      const act = b.dataset.pmAct;
      const tid = _planMenuEl._taskId;
      const cur = loadTasks().find((x) => x.id === tid);
      _closePlanTaskMenu();
      if (!cur) return;

      if (act === "edit") {
        const el = document.querySelector(`[data-task-edit="${tid}"]`);
        if (el) _startInlineEdit(el, tid);
      } else if (act === "date") {
        const picked = await openDateTimePicker({
          initial: Number.isFinite(cur.dueAt) ? cur.dueAt : cur.createdAt,
          title: "تغییر زمان تسک",
          subtitle: "زمان جدید را انتخاب کن",
          okText: "ثبت",
        });
        if (picked != null) {
          updateTask(tid, { dueAt: picked });
          if (typeof toast === "function") toast("زمان تسک به‌روز شد", "ok");
          _renderPlanBody();
        }
      } else if (act === "today") {
        const todayTs = _startOfDay();
        const old = new Date(Number.isFinite(cur.dueAt) ? cur.dueAt : cur.createdAt);
        const newDue = todayTs + old.getHours() * 3600000 + old.getMinutes() * 60000;
        updateTask(tid, { dueAt: newDue });
        if (typeof toast === "function") toast("تسک به امروز منتقل شد", "ok");
        _renderPlanBody();
      } else if (act === "del") {
        const ok = await uiConfirm({
          title: "حذف تسک",
          message: `تسک «<b>${escHtml(cur.text.slice(0, 80))}</b>» حذف شود؟`,
          okText: "حذف",
          danger: true,
        });
        if (ok) {
          removeTask(tid);
          if (typeof toast === "function") toast("تسک حذف شد", "ok");
          _renderPlanBody();
        }
      }
    });
  }
  _planMenuEl._taskId = taskId;
  _planMenuEl.innerHTML = `
    <button type="button" data-pm-act="edit">${icon("pencil")}<span>ویرایش متن</span></button>
    <button type="button" data-pm-act="date">${icon("cal")}<span>تغییر زمان</span></button>
    <button type="button" data-pm-act="today">${icon("clock")}<span>انتقال به امروز</span></button>
    <button type="button" data-pm-act="del" class="danger">${icon("x")}<span>حذف تسک</span></button>
  `;
  _planMenuEl.classList.add("open");

  const r = anchorEl.getBoundingClientRect();
  const z = parseFloat(getComputedStyle(document.documentElement).zoom) || 1;
  const vw = innerWidth / z,
    vh = innerHeight / z;
  const mw = _planMenuEl.offsetWidth,
    mh = _planMenuEl.offsetHeight;
  let x = r.right / z - mw;
  let y = r.bottom / z + 6;
  if (y + mh > vh - 8) y = r.top / z - mh - 6;
  x = Math.max(8, Math.min(x, vw - mw - 8));
  y = Math.max(8, Math.min(y, vh - mh - 8));
  _planMenuEl.style.left = x + "px";
  _planMenuEl.style.top = y + "px";

  setTimeout(() => {
    const onDoc = (e) => {
      if (_planMenuEl.contains(e.target) || e.target === anchorEl) return;
      _closePlanTaskMenu();
      document.removeEventListener("click", onDoc);
      document.removeEventListener("keydown", onEsc);
    };
    const onEsc = (e) => {
      if (e.key === "Escape") {
        _closePlanTaskMenu();
        document.removeEventListener("click", onDoc);
        document.removeEventListener("keydown", onEsc);
      }
    };
    document.addEventListener("click", onDoc);
    document.addEventListener("keydown", onEsc);
  }, 0);
}

export function _startInlineEdit(el, taskId) {
  if (el.dataset.editing === "1") return;
  el.dataset.editing = "1";
  const t = loadTasks().find((x) => x.id === taskId);
  if (!t) return;
  const orig = t.text;
  const input = document.createElement("input");
  input.type = "text";
  input.className = "plan-task-input";
  input.value = orig;
  input.maxLength = 140;
  el.replaceWith(input);
  input.focus();
  input.select();

  let settled = false;
  const commit = () => {
    if (settled) return;
    settled = true;
    const v = input.value.trim();
    if (v && v !== orig) {
      updateTask(taskId, { text: v });
      if (typeof toast === "function") toast("تسک ویرایش شد", "ok");
    }
    _renderPlanBody();
  };
  const cancel = () => {
    if (settled) return;
    settled = true;
    _renderPlanBody();
  };
  input.addEventListener("blur", commit);
  input.addEventListener("keydown", (e) => {
    if (e.key === "Enter") {
      e.preventDefault();
      commit();
    } else if (e.key === "Escape") {
      e.preventDefault();
      cancel();
    }
  });
}

