export function _bindPlanBody() {
  const body = document.getElementById("plan-body");
  if (!body) return;
  body.querySelectorAll("[data-task-toggle]").forEach((b) => {
    b.addEventListener("click", (e) => {
      e.stopPropagation();
      if (typeof toggleTask === "function") toggleTask(b.dataset.taskToggle);
      _renderPlanBody();
    });
  });
  body.querySelectorAll("[data-task-menu]").forEach((b) => {
    b.addEventListener("click", (e) => {
      e.stopPropagation();
      _openPlanTaskMenu(b.dataset.taskMenu, b);
    });
  });
  body.querySelectorAll("[data-task-edit]").forEach((b) => {
    b.addEventListener("click", (e) => {
      e.stopPropagation();
      _startInlineEdit(b, b.dataset.taskEdit);
    });
    b.addEventListener("keydown", (e) => {
      if (e.key === "Enter" || e.key === " ") {
        e.preventDefault();
        _startInlineEdit(b, b.dataset.taskEdit);
      }
    });
  });
  const prev = body.querySelector("#planPrev");
  const next = body.querySelector("#planNext");
  const todayBtn = body.querySelector("#planToday");
  if (prev)
    prev.addEventListener("click", () => {
      _planMonth = _persianNavMonth(_planMonth, -1);
      _renderPlanBody(true);
    });
  if (next)
    next.addEventListener("click", () => {
      _planMonth = _persianNavMonth(_planMonth, 1);
      _renderPlanBody(true);
    });
  if (todayBtn)
    todayBtn.addEventListener("click", () => {
      const n = _pcal(Date.now());
      _planMonth = _persianMonthStartTs(n.year, n.month) || Date.now();
      _planSelectedDay = _startOfDay(Date.now());
      _renderPlanBody(true);
    });
  body.querySelectorAll("[data-plan-day]").forEach((b) => {
    b.addEventListener("click", () => {
      const ts = _startOfDay(+b.dataset.planDay);
      _planSelectedDay =
        _planSelectedDay && _startOfDay(_planSelectedDay) === ts ? null : +b.dataset.planDay;
      _renderPlanBody();
    });
  });
}

if (typeof window !== "undefined") window.pagePlan = pagePlan;

export function _planDayTitleFa(ts) {
  try {
    return new Intl.DateTimeFormat("fa-IR", {
      weekday: "long",
      day: "numeric",
      month: "long",
    }).format(new Date(ts));
  } catch (_) {
    return _planFaDayNum(ts);
  }
}

