import { toFa } from "../../core.js";
import { esc } from "../components/search/search.js";
import { route } from "./router.js";
(function initSessionRail(global) {
  "use strict";

  const ROW = 30;
  const W = 44;
  const H = 240;
  const HEIGHT = H;
  const CENTER = HEIGHT / 2;
  const REDUCED = () =>
    !!(global.matchMedia && global.matchMedia("(prefers-reduced-motion: reduce)").matches);

  function trapezoidPath() {
    const pts = [
      [0, 30],
      [W, 0],
      [W, H],
      [0, H - 30],
    ];
    const radius = [8, 6, 6, 8];
    const n = pts.length;
    const seg = (a, b, r) => {
      const dx = b[0] - a[0],
        dy = b[1] - a[1];
      const len = Math.hypot(dx, dy);
      const t = Math.min(r / len, 0.5);
      return [a[0] + dx * t, a[1] + dy * t];
    };
    let d = "";
    for (let i = 0; i < n; i++) {
      const V = pts[i],
        P = pts[(i - 1 + n) % n],
        N = pts[(i + 1) % n];
      const a = seg(V, P, radius[i]);
      const b = seg(V, N, radius[i]);
      d += (i === 0 ? "M" : "L") + a[0].toFixed(2) + " " + a[1].toFixed(2);
      d += " Q" + V[0] + " " + V[1] + " " + b[0].toFixed(2) + " " + b[1].toFixed(2);
    }
    return d + " Z";
  }

  let el = null;
  let list = null;
  let builtFor = null;
  let shown = false;
  let _idleTimer = null;
  let _endTimer = null;
  let _isProgrammaticScroll = false;

  // توقف هر اسکرول در حال اجرا: با نوشتن موقعیت فعلی با behavior=instant
  // این کار بدون حلقهٔ rAF و بدون نوشتن scrollTop در هر فریم انجام می‌شود.
  function stopScroll(element) {
    clearTimeout(_endTimer);
    _isProgrammaticScroll = false;
    try {
      element.scrollTo({ top: element.scrollTop, behavior: "instant" });
    } catch (_) {
      element.scrollTop = element.scrollTop;
    }
  }

  // اسکرول نرم با موتور مرورگر (compositor). پایان حرکت با scrollend یا سقف زمانی گرفته می‌شود.
  function animateScroll(element, targetTop) {
    const startTop = element.scrollTop;
    if (Math.abs(targetTop - startTop) < 2 || REDUCED()) {
      stopScroll(element);
      element.scrollTop = targetTop;
      return;
    }

    stopScroll(element);
    _isProgrammaticScroll = true;

    const done = () => {
      clearTimeout(_endTimer);
      element.removeEventListener("scrollend", done);
      _isProgrammaticScroll = false;
    };
    element.addEventListener("scrollend", done, { once: true });
    _endTimer = setTimeout(done, 900);

    element.scrollTo({ top: targetTop, behavior: "smooth" });
  }

  function snapToCenter() {
    if (!el || !el.classList.contains("on") || !list) return;
    const wheelEl = el.querySelector(".sr-wheel");
    if (!wheelEl) return;

    const curItem = list.querySelector(".sr-i.is-cur");
    if (!curItem) return;

    const li = curItem.closest(".sr-li");
    const items = Array.from(list.querySelectorAll(".sr-li"));
    const domIdx = items.indexOf(li);
    if (domIdx < 0) return;

    const targetTop = domIdx * ROW + ROW / 2 - CENTER;
    const maxScroll = Math.max(0, wheelEl.scrollHeight - wheelEl.clientHeight);
    const clamped = Math.max(0, Math.min(targetTop, maxScroll));

    animateScroll(wheelEl, clamped);
  }

  function ensure() {
    if (el && el.isConnected) return el;
    el = document.createElement("nav");
    el.id = "sessRail";
    el.className = "sess-rail";
    el.setAttribute("aria-label", "پیمایش بین جلسات");
    const d = trapezoidPath();
    el.style.setProperty("--sr-clip", 'path("' + d + '")');
    el.innerHTML =
      '<div class="sr-body">' +
      '<svg class="sr-face" viewBox="0 0 ' +
      W +
      " " +
      H +
      '" width="' +
      W +
      '" height="' +
      H +
      '" aria-hidden="true">' +
      '<path d="' +
      d +
      '"/>' +
      "</svg>" +
      '<div class="sr-wheel"><ol class="sr-list"></ol></div>' +
      "</div>";
    list = el.querySelector(".sr-list");
    (document.querySelector(".app-sheet") || document.body).appendChild(el);

    const wheel = el.querySelector(".sr-wheel");
    if (wheel && !wheel.dataset.smartBound) {
      wheel.dataset.smartBound = "1";

      // کاربر وارد عمل شد: تویین را قطع کن
      const takeOver = () => {
        clearTimeout(_idleTimer);
        if (_isProgrammaticScroll) stopScroll(wheel);
      };

      wheel.addEventListener(
        "scroll",
        () => {
          if (_isProgrammaticScroll) return;
          clearTimeout(_idleTimer);
          _idleTimer = setTimeout(snapToCenter, 2500);
        },
        { passive: true },
      );
      wheel.addEventListener("pointerdown", takeOver, { passive: true });
      wheel.addEventListener("touchstart", takeOver, { passive: true });
      wheel.addEventListener(
        "wheel",
        () => {
          takeOver();
          _idleTimer = setTimeout(snapToCenter, 2500);
        },
        { passive: true },
      );
    }

    return el;
  }

  function parse(hash) {
    const h = String(hash || "").replace(/^#\/?/, "");
    const m = /^(?:p\/([^\/]+)\/)?s\/([^\/@]+)/.exec(h);
    if (!m) return null;
    return { pack: m[1] ? decodeURIComponent(m[1]) : null, sid: decodeURIComponent(m[2]) };
  }

  function sessionsOf() {
    try {
      const C = global.CourseRuntime && global.CourseRuntime.getCourse();
      const arr = ((C && C.sessions) || []).slice();
      return arr.sort((a, b) => (a.num || 0) - (b.num || 0));
    } catch (_) {
      return [];
    }
  }

  const T = (x) => (typeof toFa === "function" ? toFa(x) : String(x));
  const esc = (s) =>
    String(s || "").replace(
      /[&<>"]/g,
      (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c],
    );

  function build(pack, sessions) {
    const base = pack ? "p/" + encodeURIComponent(pack) + "/" : "";
    const PAD = 4;
    let html = "";

    for (let i = 0; i < PAD; i++) {
      html += `<li class="sr-li"><div class="sr-i sr-i--dummy"><span></span></div></li>`;
    }

    html += sessions
      .map((s, i) => {
        const label = `جلسهٔ ${T(s.num)}: ${s.title || ""}`;
        return (
          `<li class="sr-li"><a class="sr-i" data-idx="${i}" data-sid="${esc(s.id)}" ` +
          `href="#/${base}s/${encodeURIComponent(s.id)}" title="${esc(label)}" aria-label="${esc(label)}">` +
          `<span>${T(s.num)}</span></a></li>`
        );
      })
      .join("");

    for (let i = 0; i < PAD; i++) {
      html += `<li class="sr-li"><div class="sr-i sr-i--dummy"><span></span></div></li>`;
    }

    list.innerHTML = html;
    builtFor = (pack || "") + "|" + sessions.length;
  }

  function place(idx, animate) {
    const items = list.querySelectorAll(".sr-i");
    const PAD = 4;
    const domIdx = idx + PAD;

    items.forEach((a, i) => {
      if (a.classList.contains("sr-i--dummy")) return;
      const cur = i === domIdx;
      if (a.classList.contains("is-cur") !== cur) a.classList.toggle("is-cur", cur);
      if (cur) a.setAttribute("aria-current", "page");
      else a.removeAttribute("aria-current");
    });

    const wheelEl = el.querySelector(".sr-wheel");
    if (!wheelEl) return;

    const targetTop = domIdx * ROW + ROW / 2 - CENTER;
    const maxScroll = Math.max(0, wheelEl.scrollHeight - wheelEl.clientHeight);
    const clamped = Math.max(0, Math.min(targetTop, maxScroll));

    if (animate) {
      clearTimeout(_idleTimer);
      animateScroll(wheelEl, clamped);
    } else {
      stopScroll(wheelEl);
      wheelEl.scrollTop = clamped;
    }
  }

  function sync(hash) {
    const route = parse(hash);
    const root = ensure();
    const sessions = route ? sessionsOf() : [];
    const idx = route ? sessions.findIndex((s) => s.id === route.sid) : -1;

    if (!route || idx < 0) {
      root.classList.remove("on");
      shown = false;
      return;
    }

    const key = (route.pack || "") + "|" + sessions.length;
    if (key !== builtFor) build(route.pack, sessions);

    if (!shown) {
      place(idx, false);
      requestAnimationFrame(() => requestAnimationFrame(() => root.classList.add("on")));
      shown = true;
    } else {
      place(idx, true);
    }
  }

  global.SessionRail = Object.freeze({
    sync,
    hide: () => {
      if (el) {
        el.classList.remove("on");
        shown = false;
      }
    },
    ROW,
    HEIGHT,
  });
})(typeof window !== "undefined" ? window : globalThis);
