/* ── Idle-aware KaTeX scheduler ────────────────────────────────────────
 * - بالای صفحه: sync (توسط caller)
 * - پایین صفحه: deferKatex() صف می‌کند برای idle-time pre-render
 * - با هر تعامل کاربر (mousemove/scroll/wheel/touch/key): idle متوقف می‌شود
 * - ~350ms بی‌حرکتی: idle خودش ادامه می‌دهد
 * - observer نازک فقط تور نجات است: اگر کاربر سریع اسکرول کرد و idle فرصت نکرد
 */
export const _pendingKatex = new WeakMap(); // el -> { run }
export const _idleKatexQueue = [];
export let _idleKatexScheduled = false;
export let _lastActivityTs = 0;

export const _markActivity = () => {
  _lastActivityTs = performance.now();
};
// mousemove و pointerdown حذف شدند: تکاندادن موس main thread را اشغال نمی‌کند
["mousedown", "wheel", "scroll", "touchstart", "touchmove", "keydown"]
  .forEach((evt) =>
    window.addEventListener(evt, _markActivity, { passive: true, capture: true }),
  );

  export let _katexWorker = null;
export let _katexWorkerFailed = false;
export const _katexWorkerPending = new Map();
export let _katexWorkerNextId = 0;

export function _ensureKatexWorker() {
  if (_katexWorker) return _katexWorker;
  if (_katexWorkerFailed || typeof Worker === "undefined") return null;
  try {
    _katexWorker = new Worker(katexWorkerUrl);
    _katexWorker.postMessage({ init: new URL(katexUrl, location.href).href });
  } catch (_) {
    _katexWorkerFailed = true;
    return null;
  }
  _katexWorker.onmessage = (e) => {
    const { id, ok, html } = e.data;
    const cb = _katexWorkerPending.get(id);
    _katexWorkerPending.delete(id);
    if (cb) cb(ok ? html : null);
  };
  _katexWorker.onerror = () => {
    _katexWorkerFailed = true;
    _katexWorker = null;
  };
  return _katexWorker;
}

export function katexRenderAsync(tex, display) {
  return new Promise((resolve) => {
    const w = _ensureKatexWorker();
    if (!w) {
      try {
        resolve(
          katex.renderToString(tex, {
            displayMode: !!display,
            throwOnError: false,
            strict: false,
          }),
        );
      } catch (_) {
        resolve(null);
      }
      return;
    }
    const id = ++_katexWorkerNextId;
    _katexWorkerPending.set(id, resolve);
    w.postMessage({ id, tex, display: !!display });
  });
}

export function deferKatexTex(el, tex, display) {
  if (!el || !tex) return;
  deferKatex(el, async () => {
    const html = await katexRenderAsync(tex, display);
    if (!el.isConnected) return;
    if (html) el.innerHTML = html;
    else el.textContent = tex;
  });
}

