export const _ric =
  typeof window.requestIdleCallback === "function"
    ? window.requestIdleCallback.bind(window)
    : (cb) => setTimeout(() => cb({ timeRemaining: () => 8, didTimeout: true }), 80);

export const _safetyKatexIO =
  typeof IntersectionObserver !== "undefined"
    ? new IntersectionObserver(
        (entries) => {
          entries.forEach((e) => {
            if (!e.isIntersecting) return;
            const el = e.target;
            _safetyKatexIO.unobserve(el);
            if (!_pendingKatex.has(el)) return;
            // اگر کاربر فعال است، در فریم جاری رندر نکن؛ به جلوی صف idle بفرست
            if (performance.now() - _lastActivityTs < 350) {
              _idleKatexQueue.unshift(el);
              _scheduleIdleKatex();
              return;
            }
            _runKatexJob(el);
          });
        },
        { rootMargin: "400px 0px" },
      )
    : null;

export function _runKatexJob(el) {
  const job = _pendingKatex.get(el);
  if (!job || !el.isConnected) return;
  _pendingKatex.delete(el);
  if (_safetyKatexIO) _safetyKatexIO.unobserve(el);
  try {
    job.run();
  } catch (_) {}
}

export function _scheduleIdleKatex() {
  if (_idleKatexScheduled || !_idleKatexQueue.length) return;
  _idleKatexScheduled = true;
  _ric(_runIdleKatex, { timeout: 3000 });
}

export function _runIdleKatex(deadline) {
  _idleKatexScheduled = false;
  // گیت ۱۰۰ms جای ۳۵۰ms — زودتر شروع می‌کند
  if (performance.now() - _lastActivityTs < 100) {
    _idleKatexScheduled = true;
    _ric(_runIdleKatex, { timeout: 2000 });
    return;
  }
  // بودجه ۸؛ چک timeRemaining را برداشتیم چون روی سیستم ضعیف بعد از یک render
  // همیشه ۰ می‌شود و budget هرگز تمام نمی‌شد
  let budget = 8;
  while (_idleKatexQueue.length && budget-- > 0) {
    const el = _idleKatexQueue.shift();
    if (!el || !el.isConnected) continue;
    _runKatexJob(el);
    if (performance.now() - _lastActivityTs < 100) break;
  }
  if (_idleKatexQueue.length) _scheduleIdleKatex();
}

export function deferKatex(el, run) {
  if (!el || typeof run !== "function") return;
  _pendingKatex.set(el, { run });
  _idleKatexQueue.push(el);
  if (_safetyKatexIO) _safetyKatexIO.observe(el);
  _scheduleIdleKatex();
}

export function clearDeferredKatex() {
  _idleKatexQueue.length = 0;
}

window.deferKatex = deferKatex;
window.clearDeferredKatex = clearDeferredKatex;

