export const _lazyMmdIO =
  typeof IntersectionObserver !== "undefined"
    ? new IntersectionObserver(
        (entries) => {
          entries.forEach((entry) => {
            if (!entry.isIntersecting) return;
            _lazyMmdIO.unobserve(entry.target);
            _runOneMmd(entry.target);
          });
        },
        { rootMargin: "600px 0px" },
      )
    : null;

export function _runOneMmd(n) {
  if (!n || n.dataset.done || n.hasAttribute("data-processed")) return;
  if (!window.mermaid) {
    ensureMermaid().then((ok) => {
      if (ok) _runOneMmd(n);
    });
    return;
  }
  if (!n.dataset.src) n.dataset.src = n.textContent.trim();
  n.dataset.done = "1";
  n.removeAttribute("id");
  mermaid.run({ nodes: [n] }).then(() => _fixMmdSvgSize(n)).catch(() => {});
}

export function runMmd(el) {
  const nodes = [...el.querySelectorAll(".mmd")].filter(
    (n) => !n.dataset.done && !n.hasAttribute("data-processed"),
  );
  if (!nodes.length) return;
  const vh = (window.innerHeight || 800) + 600;
  const items = nodes.map((n) => {
    const r = n.getBoundingClientRect();
    return { n, inView: r.top < vh && r.bottom > -600 };
  });
  items.forEach(({ n, inView }) => {
    if (inView || !_lazyMmdIO) _runOneMmd(n);
    else _lazyMmdIO.observe(n);
  });
}

export function _fixMmdSvgSize(root) {
  const scope = root || document;
  scope.querySelectorAll(".mmd > svg").forEach((svg) => {
    const vb = svg.getAttribute("viewBox");
    if (!vb) return;
    const parts = vb.trim().split(/\s+/).map(Number);
    if (parts.length !== 4 || !parts[2]) return;
    const w = parts[2];

    svg.style.removeProperty("max-width");
    svg.style.removeProperty("width");
    svg.style.removeProperty("height");

    svg.style.width = w + "px";
    svg.style.height = "auto";
    svg.style.maxWidth = "none";
  });
}

