// پاسخ اول ثبت می‌شود؛ پاسخ دوم (بعد از بازگشت به جلسه) فقط بازخورد UI است.
export function _recordQuizAnswer(qid, correct, questionText) {
  if (!qid || typeof LearningState === "undefined") return;
  LearningState.attemptsFor(qid)
    .then((rows) => {
      if (rows && rows.length) return;
      return LearningState.recordAttempt({
        pid: qid,
        packId: (typeof CourseRuntime !== "undefined" && CourseRuntime.getActivePackId()) || "",
        status: correct ? "correct" : "incorrect",
        input: "",
        hintsUsed: 0,
      }).then(() => {
        if (!correct && typeof markMistake === "function") {
          markMistake(qid, { title: questionText, section: "" });
        }
      });
    })
    .catch(() => {});
}

export function _wireQuiz(scope) {
  scope.querySelectorAll(".rd-quiz").forEach((q) => {
    if (q.dataset.wired === "1") return;
    q.dataset.wired = "1";
    const right = +q.dataset.quiz;
    const exp = q.querySelector(".rd-quiz-exp");
    const qid = _quizRecordId(scope, q);
    const questionText = (q.querySelector(".rd-quiz-title") || {}).textContent || "";
    q.querySelectorAll(".rd-quiz-o").forEach((o) => {
      o.addEventListener("click", () => {
        if (q.dataset.locked === "1") return;
        q.dataset.locked = "1";
        const k = +o.dataset.k;
        _recordQuizAnswer(qid, k === right, questionText.trim());
        q.querySelectorAll(".rd-quiz-o").forEach((x, j) => {
          if (j === right) x.classList.add("right");
        });
        if (k !== right) o.classList.add("wrong");
        if (exp) {
          exp.hidden = false;
        }
        if (typeof toast === "function") {
          toast(
            k === right ? "پاسخ درست" : "پاسخ نادرست — توضیح را ببینید",
            k === right ? "ok" : "err",
          );
        }
      });
      o.addEventListener("keydown", (e) => {
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          o.click();
        }
      });
    });
  });
}

export function _wireFlash(scope) {
  scope.querySelectorAll(".rd-flash").forEach((f) => {
    if (f.dataset.wired === "1") return;
    f.dataset.wired = "1";
    const flip = () => f.classList.toggle("flipped");
    f.addEventListener("click", flip);
    f.addEventListener("keydown", (e) => {
      if (e.key === "Enter" || e.key === " ") {
        e.preventDefault();
        flip();
      }
    });
  });
}

export function svgEl(t, a = {}, p) {
  const e = document.createElementNS("http://www.w3.org/2000/svg", t);
  for (const k in a) e.setAttribute(k, a[k]);
  if (p) p.appendChild(e);
  return e;
}

export function ctl(box, label, min, max, step, val, unit, cb) {
  const w = document.createElement("div");
  w.className = "ctl";
  w.innerHTML = `<label><span>${label}</span><span class="cv"></span></label>`;
  const r = document.createElement("input");
  r.type = "range";
  r.min = min;
  r.max = max;
  r.step = step;
  r.value = val;
  const cv = w.querySelector(".cv");
  const upd = () => {
    cv.textContent =
      unit === "nm" ? toFa(r.value) + " نانومتر" : toFa(r.value) + (unit ? " " + unit : "");
  };
  let _pending = 0;
  r.addEventListener("input", () => {
    upd();
    if (_pending) return;
    _pending = requestAnimationFrame(() => {
      _pending = 0;
      cb(+r.value);
    });
  });
  upd();
  w.appendChild(r);
  box.appendChild(w);
  return r;
}

export function updateSolvedProg() {
  const total = problemIds().size;
  const solved = solvedCount();
  const r = 50.3;

  const ring = $("#solvedRing");
  const check = $("#solvedCheck");

  if (!ring || !check) return;
  if (total === 0) {
    ring.style.display = "none";
    check.style.display = "none";
    return;
  }
  if (solved >= total) {
    ring.style.display = "none";
    check.style.display = "inline";
  } else {
    ring.style.display = "block";
    check.style.display = "none";
    ring.style.strokeDashoffset = r - (solved / total) * r;
  }
}

