export function _dayKey(ts) {
  const d = new Date(ts);
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const dd = String(d.getDate()).padStart(2, "0");
  return y + "-" + m + "-" + dd;
}

export function dailyStats(days) {
  const n = days || 182;
  const map = new Map();
  const now = Date.now();
  const since = now - n * 864e5;
  loadEvents().forEach((ev) => {
    if (ev.ts < since) return;
    const key = _dayKey(ev.ts);
    const cur = map.get(key) || { read: 0, solve: 0, note: 0, flash: 0, study: 0, total: 0 };
    if (ev.t === "read") cur.read++;
    else if (ev.t === "solve") cur.solve++;
    else if (ev.t === "note") cur.note++;
    else if (ev.t === "flash") cur.flash++;
    else if (ev.t === "study") cur.study += ev.minutes || 0;
    cur.total = cur.read + cur.solve + cur.note + cur.flash;
    map.set(key, cur);
  });
  const out = [];
  for (let i = n - 1; i >= 0; i--) {
    const ts = now - i * 864e5;
    const key = _dayKey(ts);
    out.push({
      key,
      ts,
      ...(map.get(key) || { read: 0, solve: 0, note: 0, flash: 0, study: 0, total: 0 }),
    });
  }
  return out;
}

export function lifetimeStats() {
  const evs = loadEvents();
  const out = { read: 0, solve: 0, note: 0, flash: 0, study: 0, streak: 0, last: 0 };
  const days = new Set();
  evs.forEach((ev) => {
    if (ev.t === "read") out.read++;
    else if (ev.t === "solve") out.solve++;
    else if (ev.t === "note") out.note++;
    else if (ev.t === "flash") out.flash++;
    else if (ev.t === "study") out.study += ev.minutes || 0;
    days.add(_dayKey(ev.ts));
  });
  const today = new Date();
  let streak = 0;
  for (let i = 0; i < 365; i++) {
    const d = new Date(today.getTime() - i * 864e5);
    const key = _dayKey(d.getTime());
    if (days.has(key)) streak++;
    else if (i > 0) break;
  }
  out.streak = streak;
  out.last = evs.length ? evs[evs.length - 1].ts : 0;
  return out;
}

