    doneAt: 0,
    dueAt: Number.isFinite(+o.dueAt) ? +o.dueAt : now,
    packId: typeof o.packId === "string" ? o.packId : null,
    sessionId: typeof o.sessionId === "string" ? o.sessionId : null,
