export function toggleTask(id) {
  const arr = loadTasks();
  const i = arr.findIndex((x) => x.id === id);
  if (i < 0) return null;
  arr[i].done = !arr[i].done;
  arr[i].doneAt = arr[i].done ? Date.now() : 0;
  if (!arr[i].done) arr[i].notified = false;
  saveTasks(arr);
  recordEvent(arr[i].done ? "task-done" : "task-undone", { tid: id });
  return arr[i];
}

export function removeTask(id) {
  const arr = loadTasks().filter((x) => x.id !== id);
  saveTasks(arr);
  recordEvent("task-remove", { tid: id });
}

export function updateTask(id, patch) {
  const arr = loadTasks();
  const i = arr.findIndex((x) => x.id === id);
  if (i < 0) return null;
  const before = arr[i];
  const after = Object.assign({}, before, patch || {});
  if (patch && "dueAt" in patch && patch.dueAt !== before.dueAt) {
    after.notified = false;
  }
  if (patch && "done" in patch && !patch.done && before.done) {
    after.notified = false;
    after.doneAt = 0;
  }
  arr[i] = after;
  saveTasks(arr);
  return arr[i];
}

export function _startOfDay(ts) {
  const d = new Date(ts || Date.now());
  d.setHours(0, 0, 0, 0);
  return d.getTime();
}

export function tasksInRange(fromTs, toTs, includeDone) {
  return loadTasks()
    .filter((t) => {
      if (!includeDone && t.done) return false;
      const due = Number.isFinite(t.dueAt) ? t.dueAt : t.createdAt;
      return due >= fromTs && due < toTs;
    })
    .sort((a, b) => {
      const da = Number.isFinite(a.dueAt) ? a.dueAt : a.createdAt;
      const db = Number.isFinite(b.dueAt) ? b.dueAt : b.createdAt;
      return da - db;
    });
}

export function tasksToday() {
  const s = _startOfDay();
  return tasksInRange(s, s + 864e5, false);
}

export function tasksOverdue() {
  const s = _startOfDay();
  return tasksInRange(0, s, false);
}

export function tasksUpcoming(days) {
  const s = _startOfDay();
  const d = days || 7;
  return tasksInRange(s + 864e5, s + (d + 1) * 864e5, false);
}

export function tasksForDay(ts) {
  const s = _startOfDay(ts);
  return tasksInRange(s, s + 864e5, true);
}

export function computeXP() {
  const evs = loadEvents();
  let xp = 0;
  evs.forEach((ev) => {
    if (ev.t === "read") xp += 40;
    else if (ev.t === "solve") xp += 60;
    else if (ev.t === "note") xp += 15;
    else if (ev.t === "flash") xp += 8;
    else if (ev.t === "task-done") xp += 20;
  });
  return xp;
}

export function notificationSupported() {
  return typeof Notification !== "undefined";
}

export function notificationPermission() {
  if (!notificationSupported()) return "unsupported";
  return Notification.permission;
}

export async function requestNotificationPermission() {
  if (!notificationSupported()) return "unsupported";
  if (Notification.permission === "granted") return "granted";
  if (Notification.permission === "denied") return "denied";
  try {
    const p = await Notification.requestPermission();
    return p;
  } catch (_) {
    return "denied";
  }
}

export function _showNotification(title, body) {
  if (!notificationSupported()) return false;
  if (Notification.permission !== "granted") return false;
  try {
    const n = new Notification(title, { body, icon: undefined, silent: false });
    setTimeout(() => {
      try {
        n.close();
      } catch (_) {}
    }, 8000);
    return true;
  } catch (_) {
    return false;
  }
}

export function checkTaskReminders() {
  if (Notification.permission !== "granted") return;
  if (typeof getPref === "function" && getPref("notifyTasks", "on") !== "on") return;
  const now = Date.now();
  const win = 15 * 60 * 1000;
  const arr = loadTasks();
  let changed = false;
  arr.forEach((t) => {
    if (t.done || t.notified) return;
    const due = Number.isFinite(t.dueAt) ? t.dueAt : t.createdAt;
    if (due > now && due - now <= win) {
      _showNotification("لِکتور — یادآور", t.text);
      t.notified = true;
      changed = true;
    }
  });
  if (changed) saveTasks(arr);
}

export const LEITNER_INTERVALS = [0, 1, 2, 4, 8, 16];

export function leitnerGetState() {
  const s = loadReviewState() || {};
  if (!s.boxes) s.boxes = {};
  return s;
}

export function leitnerRecord(cardId, result) {
  const s = leitnerGetState();
  const now = Date.now();
  const cur = s.boxes[cardId] || { box: 1, due: now, last: 0, seen: 0 };
  if (result === "known") {
    cur.box = Math.min(5, (cur.box || 1) + 1);
    cur.due = now + LEITNER_INTERVALS[cur.box] * 86400 * 1000;
  } else if (result === "unknown") {
    cur.box = 1;
    cur.due = now;
  } else if (result === "later") {
    cur.due = now;
  }
  cur.last = now;
  cur.seen = (cur.seen || 0) + 1;
  s.boxes[cardId] = cur;
  saveReviewState(s);
  return cur;
}

export function leitnerDue(cards) {
  const s = leitnerGetState();
  const now = Date.now();
  return cards.filter((c) => {
    const b = s.boxes[c.id];
    return !b || b.due <= now;
  });
}

export function leitnerStats(cards) {
  const s = leitnerGetState();
  const byBox = [0, 0, 0, 0, 0, 0];
  let due = 0,
    seen = 0;
  const now = Date.now();
  cards.forEach((c) => {
    const b = s.boxes[c.id];
    if (!b) {
      byBox[1]++;
      due++;
      return;
    }
    byBox[b.box] = (byBox[b.box] || 0) + 1;
    if (b.due <= now) due++;
    if (b.seen > 0) seen++;
  });
  return { byBox, due, seen, total: cards.length };
}

export function texFromFcard(el) {
  const idMatch = el.id && el.id.match(/^f-(.+)-(\d+)$/);
  if (idMatch) {
    const C = CourseRuntime.getCourse() || {};
    const sess = (C.sessions || []).find((s) => s.id === idMatch[1]);
    const f = sess && sess.formulas[+idMatch[2]];
    if (f) return f.tex;
  }
  const ref = el.dataset && el.dataset.ref;
  if (ref) {
    for (const s of (CourseRuntime.getCourse() || {}).sessions || []) {
      const f = s.formulas.find((x) => x.t === ref);
      if (f) return f.tex;
    }
  }
  return null;
}

export function cleanTextFrom(node) {
  const box = document.createElement("div");
  box.appendChild(node.cloneNode(true));
  box.querySelectorAll(".katex").forEach((k) => {
    const ann = k.querySelector('annotation[encoding="application/x-tex"]');
    const tex = ann ? ann.textContent.trim() : "";
    k.replaceWith(document.createTextNode(tex ? "$" + tex + "$" : ""));
  });
  box.style.cssText =
    "position:absolute;left:-10000px;top:0;width:700px;opacity:0;pointer-events:none";
  document.body.appendChild(box);
  const out = box.innerText.replace(/\n{3,}/g, "\n").trim();
  box.remove();
  return out;
}

document.addEventListener("copy", (e) => {
  const sel = window.getSelection();
  if (!sel || sel.isCollapsed) return;
  const anchor = sel.anchorNode;
  const node = anchor && (anchor.nodeType === 1 ? anchor : anchor.parentElement);
  const fcard = node && node.closest(".fcard, .rd-formula");
  if (fcard) {
    const tex = texFromFcard(fcard);
    if (tex) {
      e.clipboardData.setData("text/plain", tex);
      e.preventDefault();
      toast("فرمول به‌صورت LaTeX کپی شد");
      return;
    }
  }
  e.clipboardData.setData("text/plain", cleanTextFrom(sel.getRangeAt(0).cloneContents()));
  e.preventDefault();
});

export function copyText(txt, msg) {
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(txt).then(
      () => toast(msg),
      () => legacyCopy(txt, msg),
    );
  } else legacyCopy(txt, msg);
}

export function legacyCopy(txt, msg) {
  const ta = document.createElement("textarea");
  ta.value = txt;
  ta.style.cssText = "position:fixed;opacity:0;top:0;left:0";
  document.body.appendChild(ta);
  ta.select();
  try {
    document.execCommand("copy");
    toast(msg);
  } catch (err) {
    toast("کپی ناموفق بود", "err");
  }
  ta.remove();
}

