export const AI_PROMPT_PREFIX = "دربارهٔ این متن توضیح بده و اگر فرمول یا مفهوم فنی داشت، بازش کن:";

export const CTX_NATIVE_ZONES = "input, textarea, [contenteditable=true], a[href]";

export const CTX_COPYABLE =
  ".fcard, .rd-formula, .concept, .exbox, .notebox, .ccard, " +
  "pre.code, code, .rd-callout, .rd-define, .rd-quote, " +
  ".home-continue, .home-recent-item, .explore-card, " +
  ".mmd, .glos-card";

export let ctxMenu = null;

export let _pendingCtxMenu = null;
export let _touchDown = false;
export let _ctxOpenedAt = 0;

export function _tryOpenPendingCtxMenu() {
  if (!_pendingCtxMenu) return;
  if (_touchDown) return;
  const p = _pendingCtxMenu;
  _pendingCtxMenu = null;
  if (Date.now() - p.ts > 2000) return;

  const sel = window.getSelection();
  const selText = sel ? String(sel.toString()).trim() : "";
  const parent = p.target && p.target.closest ? p.target.closest(CTX_COPYABLE) : null;

  requestAnimationFrame(() => {
    if (selText) {
      ctxOpen(p.x, p.y, parent, selText);
      _ctxOpenedAt = Date.now();
    } else if (parent) {
      ctxOpen(p.x, p.y, parent, "");
      _ctxOpenedAt = Date.now();
    }
  });
}

export function _getMmdTitle(svgEl) {
  const mmdEl = svgEl.closest(".mmd");
  if (!mmdEl) return "";
  const card = mmdEl.closest(".diagram-card");
  if (card) {
    const h4 = card.querySelector("h4");
    if (h4) {
      const clone = h4.cloneNode(true);
      clone.querySelectorAll("svg").forEach((s) => s.remove());
      return (clone.textContent || "").trim();
    }
  }
  const fig = mmdEl.closest(".rd-figure");
  if (fig) {
    const cap = fig.querySelector("figcaption");
    if (cap) return (cap.textContent || "").trim();
  }
  return "";
}

export async function _rasterizeSvg(svgEl, scale = 2) {
  if (!svgEl || svgEl.tagName.toLowerCase() !== "svg") {
    throw new Error("not an svg");
  }
  const vb = svgEl.viewBox && svgEl.viewBox.baseVal;
  const w = (vb && vb.width) || svgEl.clientWidth || 800;
  const h = (vb && vb.height) || svgEl.clientHeight || 400;

  const title = _getMmdTitle(svgEl);
  const TITLE_H = title ? 48 : 0;

  const clone = svgEl.cloneNode(true);
  clone.setAttribute("xmlns", "http://www.w3.org/2000/svg");
  clone.setAttribute("xmlns:xlink", "http://www.w3.org/1999/xlink");
  clone.setAttribute("width", String(w));
  clone.setAttribute("height", String(h));
  clone.removeAttribute("style");
  clone.style.cssText = "";

  clone.querySelectorAll("foreignObject").forEach((fo) => {
    const textContent = (fo.textContent || "").trim();
    const parent = fo.parentNode;
    if (!parent) return;
    if (!textContent) {
      fo.remove();
      return;
    }
    const x = parseFloat(fo.getAttribute("x")) || 0;
    const y = parseFloat(fo.getAttribute("y")) || 0;
    const ww = parseFloat(fo.getAttribute("width")) || 0;
    const hh = parseFloat(fo.getAttribute("height")) || 0;
    const ns = "http://www.w3.org/2000/svg";
    const txt = document.createElementNS(ns, "text");
    txt.setAttribute("x", String(x + ww / 2));
    txt.setAttribute("y", String(y + hh / 2));
    txt.setAttribute("text-anchor", "middle");
    txt.setAttribute("dominant-baseline", "middle");
    txt.setAttribute(
      "font-family",
      "system-ui, -apple-system, 'Segoe UI', 'Vazirmatn', sans-serif",
    );
    txt.setAttribute("font-size", "14");
    txt.setAttribute(
      "fill",
      getComputedStyle(document.documentElement).getPropertyValue("--text-primary").trim() ||
        "#000",
    );
    txt.textContent = textContent;
    parent.replaceChild(txt, fo);
  });

  const PROPS = [
    "fill",
    "fill-opacity",
    "fill-rule",
    "stroke",
    "stroke-width",
    "stroke-opacity",
    "stroke-dasharray",
    "stroke-dashoffset",
    "stroke-linecap",
    "stroke-linejoin",
    "opacity",
    "visibility",
    "display",
    "color",
    "font-family",
    "font-size",
    "font-weight",
    "font-style",
    "letter-spacing",
    "line-height",
    "text-anchor",
    "dominant-baseline",
    "paint-order",
    "shape-rendering",
    "background-color",
    "border-radius",
    "padding",
    "margin",
    "white-space",
    "text-decoration",
    "text-align",
    "vertical-align",
  ];
  const origAll = [svgEl, ...svgEl.querySelectorAll("*")];
  const cloneAll = [clone, ...clone.querySelectorAll("*")];
  origAll.forEach((el, i) => {
    const tgt = cloneAll[i];
    if (!tgt || tgt.nodeType !== 1) return;
    let cs;
    try {
      cs = getComputedStyle(el);
    } catch (_) {
      return;
    }
    PROPS.forEach((p) => {
      const v = cs.getPropertyValue(p);
      if (v && v !== "" && v !== "auto") {
        try {
          tgt.style.setProperty(p, v, "important");
        } catch (_) {}
      }
    });
  });

  const xml = new XMLSerializer().serializeToString(clone);
  const svgBlob = new Blob([xml], { type: "image/svg+xml;charset=utf-8" });
  const url = URL.createObjectURL(svgBlob);

  const img = new Image();
  img.decoding = "sync";
  await new Promise((res, rej) => {
    img.onload = () => res();
    img.onerror = () => rej(new Error("svg image load failed"));
    img.src = url;
  });

  const pxW = Math.max(1, Math.ceil(w * scale));
  const pxH = Math.max(1, Math.ceil((h + TITLE_H) * scale));
  const canvas = document.createElement("canvas");
  canvas.width = pxW;
  canvas.height = pxH;
  const ctx = canvas.getContext("2d");

  const svgBg = getComputedStyle(svgEl).backgroundColor;
  const bg =
    svgBg && svgBg !== "transparent" && svgBg !== "rgba(0, 0, 0, 0)"
      ? svgBg
      : getComputedStyle(document.documentElement).getPropertyValue("--surface-raised").trim() ||
        "#ffffff";

  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, pxW, pxH);

  if (title) {
    const rootCS = getComputedStyle(document.documentElement);
    const titleColor = rootCS.getPropertyValue("--text-primary").trim() || "#1f2430";
    const accColor = rootCS.getPropertyValue("--accent").trim() || "#7c3aed";
    const lineColor = rootCS.getPropertyValue("--border-subtle").trim() || "rgba(0,0,0,.12)";

    const padPx = Math.round(20 * scale);
    const titleFontPx = Math.round(15 * scale);
    ctx.font = `700 ${titleFontPx}px system-ui, -apple-system, 'Segoe UI', 'Vazirmatn', sans-serif`;
    ctx.textAlign = "right";
    ctx.textBaseline = "middle";
    ctx.fillStyle = titleColor;

    const maxTextW = pxW - padPx * 2;
    let display = title;
    if (ctx.measureText(display).width > maxTextW) {
      while (display.length > 1 && ctx.measureText(display + "…").width > maxTextW) {
        display = display.slice(0, -1);
      }
      display = display.trimEnd() + "…";
    }

    const titleY = Math.round((TITLE_H / 2) * scale);
    ctx.fillText(display, pxW - padPx, titleY);

    ctx.save();
    ctx.strokeStyle = accColor;
    ctx.globalAlpha = 0.28;
    ctx.lineWidth = Math.max(1, Math.round(scale));
    ctx.beginPath();
    ctx.moveTo(padPx, TITLE_H * scale - 0.5);
    ctx.lineTo(pxW - padPx, TITLE_H * scale - 0.5);
    ctx.stroke();
    ctx.restore();
  }

  ctx.drawImage(img, 0, TITLE_H * scale, pxW, h * scale);
  URL.revokeObjectURL(url);

  try {
    return await new Promise((res, rej) => {
      canvas.toBlob(
        (b) => (b ? res(b) : rej(new Error("toBlob returned null"))),
        "image/png",
        0.95,
      );
    });
  } catch (taintErr) {
    if (window.console) console.warn("[mmd png] canvas tainted, fallback to svg:", taintErr);
    return {
      blob: new Blob([xml], { type: "image/svg+xml;charset=utf-8" }),
      ext: "svg",
      fallback: true,
    };
  }
}

export async function copyPngBlob(blob, filename) {
  try {
    if (
      navigator.clipboard &&
      typeof ClipboardItem !== "undefined" &&
      window.isSecureContext !== false
    ) {
      await navigator.clipboard.write([new ClipboardItem({ "image/png": blob })]);
      toast("تصویر نمودار کپی شد");
      return true;
    }
  } catch (_) {}

  try {
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = filename || "diagram.png";
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(url);
    toast("تصویر ذخیره شد");
    return true;
  } catch (_) {
    toast("کپی تصویر ناموفق بود", "err");
    return false;
  }
}

export function ctxBuild() {
  if (ctxMenu) return ctxMenu;
  ctxMenu = document.createElement("div");
  ctxMenu.className = "ctx-menu";
  ctxMenu.setAttribute("role", "menu");
  document.body.appendChild(ctxMenu);

  ctxMenu.addEventListener("click", (e) => {
    const it = e.target.closest(".ctx-item");
    if (!it) return;
    const act = it.dataset.act;

    if (act === "ai-toggle") {
      e.stopPropagation();
      it.parentElement.classList.toggle("open");
      ctxReposition();
      return;
    }
    if (it.closest(".ctx-submenu")) {
      const url = it.dataset.url;
      if (url) window.open(url, "_blank", "noopener,noreferrer");
      ctxClose();
      return;
    }

    const el = ctxMenu._target;
    const sel = ctxMenu._selection;

    if (act === "tex") {
      const tex = texFromFcard(el);
      if (tex) copyText(tex, "فرمول به‌صورت LaTeX کپی شد");
    } else if (act === "text") {
      copyText(cleanTextFrom(el), "کپی شد");
    } else if (act === "selection") {
      copyText(sel, "متن کپی شد");
    } else if (act === "google") {
      const q = encodeURIComponent((sel || "").slice(0, 500));
      window.open("https://www.google.com/search?q=" + q, "_blank", "noopener,noreferrer");
    } else if (act === "link-open") {
      const href = el && el.getAttribute && el.getAttribute("href");
      if (href) window.open(href, "_blank", "noopener,noreferrer");
    } else if (act === "link-copy") {
      const href = el && el.getAttribute && el.getAttribute("href");
      if (href) {
        const abs = new URL(href, location.href).href;
        copyText(abs, "لینک کپی شد");
      }
    } else if (act === "mmd-png") {
      const svg = el && el.querySelector && el.querySelector("svg");
      if (svg) {
        toast("در حال آماده‌سازی تصویر…");
        const dpr = Math.max(2, window.devicePixelRatio || 1);
        _rasterizeSvg(svg, dpr)
          .then((blob) => copyPngBlob(blob, "diagram.png"))
          .catch((err) => {
            if (window.console) console.warn("[mmd png]", err);
            toast("آماده‌سازی تصویر ناموفق بود", "err");
          });
      }
    }
    ctxClose();
  });

  return ctxMenu;
}

export function _ctxItem(act, ico, label, extra) {
  return (
    `<button class="ctx-item" data-act="${act}" role="menuitem" type="button" ${extra || ""}>` +
    `<span class="ci">${icon(ico)}</span>` +
    `<span class="cl">${escHtml(label)}</span>` +
    `</button>`
  );
}

export function _ctxAISubmenu(sel) {
  const q = encodeURIComponent((AI_PROMPT_PREFIX + " " + sel).slice(0, 800));
  const subs = AI_TARGETS.map((t) =>
    _ctxItem("ai-go", t.icon, t.label, `data-url="${escHtml(t.url.replace("%s", q))}"`),
  ).join("");
  return (
    `<div class="ctx-submenu" role="menu">` +
    `<button class="ctx-item" data-act="ai-toggle" role="menuitem" type="button" aria-haspopup="true" aria-expanded="false">` +
    `<span class="ci">${icon("sparkles")}</span>` +
    `<span class="cl">پرسش از AI</span>` +
    `<span class="cx">${icon("chevLeft")}</span>` +
    `</button>` +
    `<div class="ctx-submenu-panel" role="menu">${subs}</div>` +
    `</div>`
  );
}

export function ctxOpen(x, y, target, selection) {
  const m = ctxBuild();
  m._target = target || null;
  m._selection = (selection || "").trim() || "";

  const isFormula =
    target && (target.classList.contains("fcard") || target.classList.contains("rd-formula"));
  const isCode = target && target.matches && target.matches("pre.code, code");
  const hasSel = m._selection.length > 0;

  const isLink = target && target.matches && target.matches("a[href]");
  const isMmd = target && target.classList && target.classList.contains("mmd");
  const isGlos = !!(target && target.classList && target.classList.contains("glos-card"));
  const items = [];

  if (isMmd) {
    items.push(_ctxItem("mmd-png", "copy", "کپی تصویر نمودار (PNG)"));
  } else if (isLink) {
    items.push(_ctxItem("link-open", "link", "باز کردن در تب جدید"));
    items.push(_ctxItem("link-copy", "copy", "کپی لینک"));
  } else if (isFormula) {
    items.push(_ctxItem("tex", "sigma", "کپی فرمول LaTeX"));
    items.push(_ctxItem("text", "copy", "کپی متن کارت"));
  } else if (isCode) {
    items.push(_ctxItem("text", "copy", "کپی کد"));
  } else if (isGlos) {
    items.push(_ctxItem("text", "copy", "کپی متن کارت"));
  } else if (hasSel) {
    items.push(_ctxItem("selection", "copy", "کپی متن انتخاب"));
  }

  if (hasSel || isCode) {
    items.push(_ctxItem("google", "search", "جست‌وجو در گوگل"));
  }

  if ((hasSel || isFormula || isGlos) && !isCode) {
    const aiSel = isFormula
      ? texFromFcard(target) || m._selection
      : isGlos && !hasSel
        ? cleanTextFrom(target)
        : m._selection;
    items.push(_ctxAISubmenu(aiSel));
  }

  if (!items.length) {
    ctxClose();
    return;
  }

  if (IS_TOUCH_DEVICE) {
    const sel = window.getSelection();
    if (sel && !sel.isCollapsed && sel.rangeCount) {
      const r = sel.getRangeAt(0).getBoundingClientRect();
      y = r.bottom + 14;
      x = r.left + Math.min(r.width / 2, 120);
    } else if (typeof y === "number") {
      y += 56;
    }
  }

  m.innerHTML = items.join("");
  m.style.display = "block";
  m.classList.remove("open");

  void m.offsetWidth;
  m.classList.add("open");
  ctxReposition(x, y);
}

export function ctxReposition(x, y) {
  const m = ctxMenu;
  if (!m) return;
  if (typeof x === "number") m._px = x;
  if (typeof y === "number") m._py = y;
  const cx = m._px ?? innerWidth / 2;
  const cy = m._py ?? innerHeight / 2;

  const z = parseFloat(getComputedStyle(document.documentElement).zoom) || 1;
  const lx = cx / z,
    ly = cy / z;
  const rw = m.offsetWidth,
    rh = m.offsetHeight;
  const vw = innerWidth / z,
    vh = innerHeight / z;

  let px = lx + rw > vw - 8 ? lx - rw : lx;
  let py;
  if (ly + rh > vh - 8) {
    if (IS_TOUCH_DEVICE) {
      py = vh - rh - 8;
    } else {
      py = ly - rh;
    }
  } else {
    py = ly;
  }
  px = Math.max(8, Math.min(px, vw - rw - 8));
  py = Math.max(8, Math.min(py, vh - rh - 8));
  m.style.left = px + "px";
  m.style.top = py + "px";

  const originX = Math.max(0, Math.min(rw, lx - px));
  const originY = Math.max(0, Math.min(rh, ly - py));
  m.style.setProperty("--ox", originX + "px");
  m.style.setProperty("--oy", originY + "px");
}

export function ctxClose() {
  if (!ctxMenu) return;
  ctxMenu.classList.remove("open");
  ctxMenu.style.display = "none";
  ctxMenu._target = null;
  ctxMenu._selection = "";
  ctxMenu.querySelectorAll(".ctx-submenu.open").forEach((s) => s.classList.remove("open"));
}

document.addEventListener(
  "mousedown",
  (e) => {
    if (e.button !== 2) return;
    if (!ctxShouldSuppress(e)) return;
    e.preventDefault();
  },
  { capture: true },
);

export const IS_TOUCH_DEVICE =
  "ontouchstart" in window ||
  navigator.maxTouchPoints > 0 ||
  matchMedia("(pointer: coarse)").matches;

export function ctxShouldSuppress(e) {
  if (e.shiftKey) return false;

  const t = e.target;
  if (!t || !t.closest) return true;
  if (t.closest("input, textarea, [contenteditable=true]")) return false;
  if (t.closest(".mmd")) return true;
  if (t.closest("a[href]")) {
    if (t.closest(".home-continue, .home-recent-item, .explore-card")) return true;
    return false;
  }

  return true;
}

document.addEventListener("contextmenu", (e) => {
  if (!ctxShouldSuppress(e)) {
    ctxClose();
    return;
  }

  if (IS_TOUCH_DEVICE) {
    e.preventDefault();
    if (_lpActive) return;
    _pendingCtxMenu = {
      x: e.clientX,
      y: e.clientY,
      target: e.target,
      ts: Date.now(),
    };
    if (!_touchDown) _tryOpenPendingCtxMenu();
    return;
  }

  const sel = window.getSelection();
  const selText = sel ? String(sel.toString()).trim() : "";
  if (selText) {
    e.preventDefault();
    const parent = e.target.closest(CTX_COPYABLE);
    ctxOpen(e.clientX, e.clientY, parent, selText);
    return;
  }
  const t = e.target.closest(CTX_COPYABLE);
  if (t) {
    e.preventDefault();
    ctxOpen(e.clientX, e.clientY, t, "");
    return;
  }
  e.preventDefault();
  ctxClose();
});

document.addEventListener(
  "touchstart",
  () => {
    _touchDown = true;
  },
  { passive: true },
);

document.addEventListener(
  "touchend",
  () => {
    _touchDown = false;
    if (_pendingCtxMenu) _tryOpenPendingCtxMenu();
  },
  { passive: true },
);

document.addEventListener(
  "touchcancel",
  () => {
    _touchDown = false;
    _pendingCtxMenu = null;
  },
  { passive: true },
);

// ── نگه‌داشتن انگشت: منو باز می‌شود؛ با کشیدن روی گزینه و رها کردن، همان اجرا می‌شود ──
export const LP_MS = 420;
export const LP_MOVE = 10;
export const LP_TARGET = ".rd-sec, .allow-select, .glos-card, " + CTX_COPYABLE;
export let _lpTimer = 0;
export let _lpActive = false;
export let _lpStartX = 0,
  _lpStartY = 0,
  _lpX = 0,
  _lpY = 0;
export let _lpHot = null;

export function _lpItemAt(x, y) {
  const el = document.elementFromPoint(x, y);
  return el && el.closest ? el.closest(".ctx-item") : null;
}

export function _lpSetHot(item) {
  if (_lpHot === item) return;
  if (_lpHot) _lpHot.classList.remove("is-hot");
  _lpHot = item || null;
  if (!item) return;
  item.classList.add("is-hot");
  if (item.dataset.act === "ai-toggle") {
    item.parentElement.classList.add("open");
    ctxReposition();
  }
}

document.addEventListener(
  "touchstart",
  (e) => {
    clearTimeout(_lpTimer);
    _lpTimer = 0;
    _lpActive = false;
    if (!IS_TOUCH_DEVICE || !e.touches || e.touches.length !== 1) return;
    const t = e.touches[0];
    _lpStartX = _lpX = t.clientX;
    _lpStartY = _lpY = t.clientY;
    const tgt = e.target;
    if (!tgt || !tgt.closest) return;
    if (tgt.closest("input, textarea, [contenteditable=true], a[href]")) return;
    if (!tgt.closest(LP_TARGET)) return;
    _lpTimer = setTimeout(() => {
      _lpTimer = 0;
      const sel = window.getSelection();
      const selText = sel ? String(sel.toString()).trim() : "";
      const parent = tgt.closest(CTX_COPYABLE);
      if (!selText && !parent) return;
      _pendingCtxMenu = null;
      _lpActive = true;
      _lpHot = null;
      ctxOpen(_lpX, _lpY, parent, selText);
      _ctxOpenedAt = Date.now();
    }, LP_MS);
  },
  { passive: true },
);

document.addEventListener(
  "touchmove",
  (e) => {
    const t = e.touches && e.touches[0];
    if (!t) return;
    _lpX = t.clientX;
    _lpY = t.clientY;
    if (_lpTimer && (Math.abs(_lpX - _lpStartX) > LP_MOVE || Math.abs(_lpY - _lpStartY) > LP_MOVE)) {
      clearTimeout(_lpTimer);
      _lpTimer = 0;
    }
    if (!_lpActive) return;
    e.preventDefault();
    _lpSetHot(_lpItemAt(_lpX, _lpY));
  },
  { passive: false },
);

document.addEventListener(
  "touchend",
  (e) => {
    clearTimeout(_lpTimer);
    _lpTimer = 0;
    if (!_lpActive) return;
    e.preventDefault();
    _lpActive = false;
    const item = _lpItemAt(_lpX, _lpY);
    _lpSetHot(null);
    if (!item) return ctxClose();
    if (item.dataset.act === "ai-toggle") return;
    item.click();
  },
  { passive: false },
);

document.addEventListener(
  "touchcancel",
  () => {
    clearTimeout(_lpTimer);
    _lpTimer = 0;
    _lpActive = false;
    _lpSetHot(null);
  },
  { passive: true },
);

export let _touchStartX = 0,
  _touchStartY = 0;
document.addEventListener(
  "touchstart",
  (e) => {
    const t = e.touches && e.touches[0];
    if (t) {
      _touchStartX = t.clientX;
      _touchStartY = t.clientY;
    }
  },
  { passive: true },
);

document.addEventListener(
  "touchmove",
  (e) => {
    if (!_pendingCtxMenu) return;
    const t = e.touches && e.touches[0];
    if (!t) return;
    const dx = t.clientX - _touchStartX;
    const dy = t.clientY - _touchStartY;
    if (dx * dx + dy * dy > 144) {
      _pendingCtxMenu = null;
    }
  },
  { passive: true },
);

document.addEventListener("click", (e) => {
  if (!e.target.closest(".ctx-menu")) {
    if (Date.now() - _ctxOpenedAt < 400) return;
    ctxClose();
  }
});
document.addEventListener("keydown", (e) => {
  if (e.key === "Escape") ctxClose();
  if (e.key === "ContextMenu" || (e.shiftKey && e.key === "F10")) {
    const focused = document.activeElement;
    if (!focused || focused === document.body) return;
    const r = focused.getBoundingClientRect();
    e.preventDefault();
    const t = focused.closest(CTX_COPYABLE) || focused;
    const sel = window.getSelection();
    const selText = sel ? String(sel.toString()).trim() : "";
    ctxOpen(r.left + 20, r.top + 20, t, selText);
  }
});
// اسکرول تصادفی (مثلاً هنگام باز شدن منو یا وقتی انگشت روی صفحه است) نباید منوی تازه‌باز را ببندد
window.addEventListener(
  "scroll",
  () => {
    if (_lpActive || Date.now() - _ctxOpenedAt < 500) return;
    ctxClose();
  },
  { passive: true },
);
window.addEventListener("resize", ctxClose);

export let toastEl;
export function toast(msg, kind) {
  if (window.Shell && typeof window.Shell.toast === "function") {
    return window.Shell.toast(msg, kind);
  }
  if (!toastEl) {
    toastEl = document.createElement("div");
    toastEl.className = "toast";
    toastEl.innerHTML =
      '<svg class="toast-ic" viewBox="0 0 32 32" aria-hidden="true">' +
      '<circle class="tc" cx="16" cy="16" r="13"/>' +
      '<path class="tk" d="M9.5 16.5 L14 21 L22.5 11.5"/>' +
      '<path class="tx1" d="M10.5 10.5 L21.5 21.5"/>' +
      '<path class="tx2" d="M21.5 10.5 L10.5 21.5"/>' +
      "</svg>" +
      '<span class="toast-txt"></span>';
    document.body.appendChild(toastEl);
  }
  toastEl.classList.toggle("err", kind === "err");
  toastEl.querySelector(".toast-txt").textContent = msg;
  toastEl.classList.remove("show");
  void toastEl.offsetWidth;
  toastEl.classList.add("show");
  clearTimeout(toastEl._t);
  toastEl._t = setTimeout(() => toastEl.classList.remove("show"), kind === "err" ? 2600 : 1800);
}

export let undoToastEl = null,
  undoFn = null;

export function toastWithUndo(msg, fn, ms) {
  if (!undoToastEl) undoToastEl = document.getElementById("toastUndo");
  if (!undoToastEl) return;
  const dur = ms || 5000;
  const txtEl = document.getElementById("toastUndoTxt");
  if (txtEl) txtEl.textContent = msg;
  undoFn = fn;
  if (toastEl) toastEl.classList.remove("show");
  undoToastEl.hidden = false;
  undoToastEl.classList.remove("show");
  undoToastEl.style.setProperty("--undo-dur", dur + "ms");
  void undoToastEl.offsetWidth;
  undoToastEl.classList.add("show");
}

export function hideUndoToast() {
  if (!undoToastEl) return;
  undoToastEl.classList.remove("show");
  undoFn = null;
}

(function bindUndoToast() {
  const el = document.getElementById("toastUndo");
  if (!el) return;
  const btn = document.getElementById("toastUndoBtn");
  if (btn)
    btn.addEventListener("click", () => {
      if (typeof undoFn === "function") {
        const fn = undoFn;
        hideUndoToast();
        try {
          fn();
        } catch (_) {}
      }
    });
  const bar = el.querySelector(".undo-progress");
  if (bar)
    bar.addEventListener("animationend", () => {
      if (el.classList.contains("show")) hideUndoToast();
    });
})();

export let _dlgResolve = null,
  _dlgMode = "confirm";

export function _dlgRestoreFoot() {
  const foot = document.querySelector("#dialogBack .dialog-foot");
  if (!foot) return;
  foot.innerHTML =
    '<button class="btn ghost" id="dialogCancel" type="button">انصراف</button>' +
    '<button class="btn g" id="dialogOk" type="button">تأیید</button>';
  const okBtn = document.getElementById("dialogOk");
  const cancelBtn = document.getElementById("dialogCancel");
  if (okBtn)
    okBtn.onclick = () => {
      if (_dlgMode === "prompt") closeDialog(document.getElementById("dialogField").value);
      else closeDialog(true);
    };
  if (cancelBtn) cancelBtn.onclick = () => closeDialog(_dlgMode === "prompt" ? null : false);
}

export function openDialog(opts) {
  return new Promise((resolve) => {
    _dlgRestoreFoot();
    _dlgResolve = resolve;
    _dlgMode = opts.mode || "confirm";

    const back = document.getElementById("dialogBack");
    const modal = document.getElementById("dialogModal");
    if (modal) modal.classList.remove("is-danger", "is-help", "is-down");

    const ic = document.getElementById("dialogIcon");
    if (ic) ic.innerHTML = opts.iconSvg || "";
    if (opts.danger && modal) modal.classList.add("is-danger");
    if (opts.help && modal) modal.classList.add("is-help");

    document.getElementById("dialogTitle").textContent = opts.title || "تأیید";
    document.getElementById("dialogMsg").innerHTML = opts.message || "";
    document.getElementById("dialogOk").textContent = opts.okText || "تأیید";

    const fw = document.getElementById("dialogFieldWrap");
    if (_dlgMode === "prompt") {
      if (fw) fw.style.display = "";
      const lbl = document.getElementById("dialogFieldLabel");
      if (lbl) lbl.textContent = opts.label || "مقدار";
      const fi = document.getElementById("dialogField");
      if (fi) {
        fi.value = opts.value || "";
        fi.placeholder = opts.placeholder || "";
        setTimeout(() => fi.focus(), 100);
      }
    } else {
      if (fw) fw.style.display = "none";
    }

    if (back) {
      back.hidden = false;
      back.classList.add("open");
    }
    document.addEventListener("keydown", _dlgKey, true);
    if (_dlgMode !== "prompt") {
      setTimeout(() => {
        const ok = document.getElementById("dialogOk");
        if (ok) ok.focus();
      }, 100);
    }
  });
}

// Esc فقط دیالوگ را می‌بندد و به پنل تنظیمات زیرش نمی‌رسد
export function _dlgKey(e) {
  if (e.key !== "Escape") return;
  e.preventDefault();
  e.stopPropagation();
  closeDialog(false);
}

export function closeDialog(value) {
  const back = document.getElementById("dialogBack");
  if (!back || !back.classList.contains("open")) return;
  back.classList.remove("open");
  back.hidden = true;
  document.removeEventListener("keydown", _dlgKey, true);
  const r = _dlgResolve;
  _dlgResolve = null;
  if (r) r(value);
}

export function uiConfirm(opts) {
  return openDialog(Object.assign({ mode: "confirm" }, opts));
}

export function uiPrompt(opts) {
  return openDialog(Object.assign({ mode: "prompt" }, opts));
}

export function createNumStepper(opts) {
  const cfg = Object.assign(
    {
      min: 0,
      max: 100,
      value: 0,
      step: 1,
      suffix: "",
      onChange: null,
      noButtons: false,
      pad: false,
      infinite: false,
    },
    opts,
  );

  const mod = (n, m) => ((n % m) + m) % m;
  const easeOut = (t) => 1 - Math.pow(1 - t, 3);
  const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
  const fmt = (v) => {
    const s = cfg.pad ? String(v).padStart(2, "0") : String(v);
    return typeof toFa === "function" ? toFa(s) : s;
  };

  const values = [];
  for (let v = cfg.min; v <= cfg.max; v += cfg.step) values.push(v);
  const N = values.length;
  if (!N) {
    const empty = document.createElement("div");
    empty.className = "num-stepper num-stepper--bare";
    return { el: empty, getValue: () => cfg.min, setValue: () => {} };
  }

  let current = values.reduce((best, v) =>
    Math.abs(v - cfg.value) < Math.abs(best - cfg.value) ? v : best,
  values[0]);
  let idx = Math.max(0, values.indexOf(current));
  if (idx < 0) idx = 0;

  const ITEM_H = 44;
  const stepAng = 360 / Math.max(N, 3);
  /* زاویهٔ نمایش — مشابه Tempus */
  let ang = -idx * stepAng;
  let vel = 0;
  let raf = 0;

  const wrap = document.createElement("div");
  wrap.className = "num-stepper" + (cfg.noButtons ? " num-stepper--bare" : "");
  wrap.style.setProperty("--item-h", ITEM_H + "px");
  wrap.setAttribute("role", "group");

  let decBtn = null,
    incBtn = null;
  if (!cfg.noButtons) {
    decBtn = document.createElement("button");
    decBtn.type = "button";
    decBtn.className = "num-stepper-btn";
    decBtn.setAttribute("aria-label", "کاهش");
    decBtn.innerHTML =
      '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" width="18" height="18" aria-hidden="true"><path d="M6 12h12"/></svg>';
    incBtn = document.createElement("button");
    incBtn.type = "button";
    incBtn.className = "num-stepper-btn";
    incBtn.setAttribute("aria-label", "افزایش");
    incBtn.innerHTML =
      '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" width="18" height="18" aria-hidden="true"><path d="M12 6v12M6 12h12"/></svg>';
  }

  const wheel = document.createElement("div");
  wheel.className = "num-stepper-wheel num-stepper-wheel--drum";
  wheel.tabIndex = 0;
  wheel.setAttribute("role", "slider");
  wheel.setAttribute("aria-valuemin", String(cfg.min));
  wheel.setAttribute("aria-valuemax", String(cfg.max));
  wheel.setAttribute("aria-valuenow", String(current));
  wheel.setAttribute("aria-label", cfg.suffix ? "مقدار — " + cfg.suffix : "مقدار");

  const rotor = document.createElement("div");
  rotor.className = "num-stepper-rotor";
  const items = values.map((v, i) => {
    const el = document.createElement("div");
    el.className = "num-stepper-item";
    el.dataset.v = String(v);
    el.dataset.i = String(i);
    el.textContent = fmt(v);
    el.addEventListener("click", () => {
      if (Date.now() < suppressClickUntil) return;
      setIndex(i, true);
    });
    rotor.appendChild(el);
    return el;
  });

  const band = document.createElement("div");
  band.className = "num-stepper-frame";
  band.setAttribute("aria-hidden", "true");
  const fadeT = document.createElement("div");
  fadeT.className = "num-stepper-fade num-stepper-fade-t";
  fadeT.setAttribute("aria-hidden", "true");
  const fadeB = document.createElement("div");
  fadeB.className = "num-stepper-fade num-stepper-fade-b";
  fadeB.setAttribute("aria-hidden", "true");

  wheel.appendChild(rotor);
  wheel.appendChild(band);
  wheel.appendChild(fadeT);
  wheel.appendChild(fadeB);
  if (decBtn) wrap.appendChild(decBtn);
  wrap.appendChild(wheel);
  if (incBtn) wrap.appendChild(incBtn);

  const radius = ITEM_H / 2 / Math.tan(Math.PI / Math.max(N, 3));

  function emit(v) {
    if (v === current) return;
    current = v;
    wheel.setAttribute("aria-valuenow", String(current));
    if (typeof cfg.onChange === "function") cfg.onChange(current);
  }

  function apply() {
    const v = -ang / stepAng;
    const half = N / 2;
    const stepRad = (stepAng * Math.PI) / 180;
    for (let i = 0; i < N; i++) {
      let di = mod(i - v, N);
      if (di > half) di -= N;
      const a = di * stepRad;
      const y = Math.sin(a) * radius;
      const sy = Math.max(0.12, Math.cos(a));
      const op = clamp(1.15 - Math.abs(di) / 2.4, 0, 1);
      const el = items[i];
      el.style.transform = "translateY(" + y.toFixed(2) + "px) scaleY(" + sy.toFixed(3) + ")";
      el.style.opacity = op.toFixed(2);
      el.classList.toggle("selected", Math.round(mod(v, N)) === i || Math.abs(di) < 0.5);
    }
    const nearest = mod(Math.round(v), N);
    emit(values[nearest]);
  }

  function stopAnim() {
    if (raf) {
      cancelAnimationFrame(raf);
      raf = 0;
    }
  }

  function animateTo(target, dur) {
    dur = dur || 280;
    stopAnim();
    const start = ang;
    let d = target - start;
    if (cfg.infinite || true) {
      /* کوتاه‌ترین مسیر زاویه‌ای */
      d = mod(d + 180, 360) - 180;
    }
    if (Math.abs(d) < 0.01) {
      ang = target;
      vel = 0;
      apply();
      return;
    }
    const t0 = performance.now();
    const tick = (ts) => {
      const p = Math.min(1, (ts - t0) / dur);
      ang = start + d * easeOut(p);
      apply();
      if (p < 1) raf = requestAnimationFrame(tick);
      else {
        raf = 0;
        vel = 0;
        ang = target;
        apply();
      }
    };
    raf = requestAnimationFrame(tick);
  }

  function setIndex(i, animate) {
    i = mod(i, N);
    idx = i;
    const target = -i * stepAng;
    if (animate) animateTo(target, 300);
    else {
      stopAnim();
      ang = target;
      vel = 0;
      apply();
    }
  }

  function stepBy(dir) {
    const cur = mod(Math.round(-ang / stepAng), N);
    setIndex(cur + dir, true);
  }

  /* درگ + اینرسی — فیزیک Tempus */
  let drag = null;
  let suppressClickUntil = 0;
  wheel.addEventListener("pointerdown", (e) => {
    if (e.pointerType === "mouse" && e.button !== 0) return;
    stopAnim();
    drag = {
      id: e.pointerId,
      y: e.clientY,
      ang0: ang,
      lastY: e.clientY,
      lastT: performance.now(),
      vy: 0,
      moved: false,
    };
    wheel.classList.add("is-dragging");
    try {
      wheel.setPointerCapture(e.pointerId);
    } catch (_) {}
  });
  wheel.addEventListener("pointermove", (e) => {
    if (!drag || drag.id !== e.pointerId) return;
    const now = performance.now();
    const dy = e.clientY - drag.y;
    if (Math.abs(dy) > 2) drag.moved = true;
    ang = drag.ang0 + dy * (stepAng / ITEM_H) * 1.15;
    const dt = Math.max(1, now - drag.lastT);
    const inst = ((e.clientY - drag.lastY) * (stepAng / ITEM_H) * 1.15) / dt;
    drag.vy = drag.vy * 0.5 + inst * 0.5;
    drag.vy = clamp(drag.vy, -3.2, 3.2);
    drag.lastY = e.clientY;
    drag.lastT = now;
    apply();
  });
  const endDrag = (e) => {
    if (!drag || (e.pointerId != null && drag.id !== e.pointerId)) return;
    const vy = drag.vy;
    const moved = drag.moved;
    drag = null;
    wheel.classList.remove("is-dragging");
    try {
      if (e.pointerId != null) wheel.releasePointerCapture(e.pointerId);
    } catch (_) {}
    if (moved) suppressClickUntil = Date.now() + 280;
    if (Math.abs(vy) > 0.04) {
      let v = vy;
      const last = { t: performance.now() };
      const inertia = (ts) => {
        const dt = Math.min(48, ts - last.t);
        last.t = ts;
        ang += v * dt;
        v *= Math.exp(-dt / 170);
        apply();
        if (Math.abs(v) < 0.012) {
          raf = 0;
          const nearest = mod(Math.round(-ang / stepAng), N);
          animateTo(-nearest * stepAng, 240);
          return;
        }
        raf = requestAnimationFrame(inertia);
      };
      raf = requestAnimationFrame(inertia);
    } else {
      const nearest = mod(Math.round(-ang / stepAng), N);
      animateTo(-nearest * stepAng, 240);
    }
  };
  wheel.addEventListener("pointerup", endDrag);
  wheel.addEventListener("pointercancel", endDrag);

  wheel.addEventListener(
    "wheel",
    (e) => {
      e.preventDefault();
      stopAnim();
      const snapped = Math.round(ang / stepAng) * stepAng;
      animateTo(snapped - stepAng * Math.sign(e.deltaY), 180);
    },
    { passive: false },
  );

  wheel.addEventListener("keydown", (e) => {
    if (e.key === "ArrowUp" || e.key === "ArrowLeft") {
      e.preventDefault();
      stepBy(-1);
    } else if (e.key === "ArrowDown" || e.key === "ArrowRight") {
      e.preventDefault();
      stepBy(1);
    } else if (e.key === "PageUp") {
      e.preventDefault();
      stepBy(-5);
    } else if (e.key === "PageDown") {
      e.preventDefault();
      stepBy(5);
    } else if (e.key === "Home") {
      e.preventDefault();
      setIndex(0, true);
    } else if (e.key === "End") {
      e.preventDefault();
      setIndex(N - 1, true);
    }
  });

  if (decBtn) decBtn.addEventListener("click", () => stepBy(-1));
  if (incBtn) incBtn.addEventListener("click", () => stepBy(1));

  apply();

  return {
    el: wrap,
    getValue: () => current,
    setValue: (v) => {
      let best = 0;
      let bestD = Infinity;
      for (let i = 0; i < N; i++) {
        const d = Math.abs(values[i] - v);
        if (d < bestD) {
          bestD = d;
          best = i;
        }
      }
      setIndex(best, true);
    },
  };
}

export function uiStepperPair(opts) {
  return new Promise((resolve) => {
    const back = document.getElementById("dialogBack");
    const modal = document.getElementById("dialogModal");
    if (!back || !modal) {
      resolve(null);
      return;
    }

    const prev = modal.querySelector(".num-stepper-pair");
    if (prev) prev.remove();

    document.getElementById("dialogTitle").textContent = opts.title || "تنظیم مقادیر";
    const msgEl = document.getElementById("dialogMsg");
    msgEl.innerHTML = opts.subtitle || "";
    document.getElementById("dialogFieldWrap").style.display = "none";
    const ic = document.getElementById("dialogIcon");
    if (ic) ic.innerHTML = opts.iconSvg || "";

    const container = document.createElement("div");
    container.className = "num-stepper-pair";

    function makeItem(label, min, max, value, suffix) {
      const wrapItem = document.createElement("div");
      wrapItem.className = "num-stepper-item-wrap";
      const lb = document.createElement("span");
      lb.className = "num-stepper-label";
      lb.textContent = label;
      const s = createNumStepper({ min, max, value, suffix });
      wrapItem.appendChild(lb);
      wrapItem.appendChild(s.el);
      container.appendChild(wrapItem);
      return s;
    }

    const s1 = makeItem(
      opts.label1 || "مقدار ۱",
      opts.min1,
      opts.max1,
      opts.value1,
      opts.suffix1 || "",
    );
    const s2 = makeItem(
      opts.label2 || "مقدار ۲",
      opts.min2,
      opts.max2,
      opts.value2,
      opts.suffix2 || "",
    );

    msgEl.parentNode.insertBefore(container, msgEl.nextSibling);

    const foot = modal.querySelector(".dialog-foot");
    foot.innerHTML =
      '<button class="btn ghost" id="dialogCancel" type="button">انصراف</button>' +
      '<button class="btn g" id="dialogOk" type="button">' +
      (opts.okText || "ذخیره") +
      "</button>";

    let settled = false;
    function finish(value) {
      if (settled) return;
      settled = true;
      document.removeEventListener("keydown", onEsc, true);
      back.classList.remove("open");
      back.hidden = true;
      container.remove();
      resolve(value);
    }
    function onEsc(e) {
      if (e.key === "Escape") {
        e.preventDefault();
        e.stopPropagation();
        finish(null);
      }
    }
    document.addEventListener("keydown", onEsc, true);

    foot.querySelector("#dialogCancel").onclick = () => finish(null);
    foot.querySelector("#dialogOk").onclick = () =>
      finish({ v1: s1.getValue(), v2: s2.getValue() });

    back.hidden = false;
    back.classList.add("open");
    setTimeout(() => {
      try {
        foot.querySelector("#dialogOk").focus();
      } catch (_) {}
    }, 80);
  });
}

(function setupGlobalTooltips() {
  const tip = document.getElementById("gtip");
  if (!tip) return;
  let activeEl = null,
    hideTimer = null;
  const isTouch = matchMedia("(hover: none)").matches;

  function position(el) {
    const z = parseFloat(getComputedStyle(document.documentElement).zoom) || 1;
    const r = el.getBoundingClientRect();
    const w = tip.offsetWidth,
      h = tip.offsetHeight,
      gap = 9;
    const vh = window.innerHeight / z;
    const vw = window.innerWidth / z;

    if (el.closest("#sidebar, .rail")) {
      const rLeft = r.left / z;
      const rRight = r.right / z;
      const centerY = (r.top + r.height / 2) / z;
      let x = rLeft - gap - w / 2;
      let y = centerY - h / 2;
      if (x - w / 2 < 4) x = rRight + gap + w / 2;
      if (y < 4) y = 4;
      if (y + h > vh - 4) y = vh - h - 4;
      tip.classList.remove("below");
      tip.style.left = x + "px";
      tip.style.top = y + "px";
      return;
    }

    const top = r.top / z,
      bottom = r.bottom / z,
      left = r.left / z,
      width = r.width / z;
    let y,
      below = false;
    if (top - h - gap >= 4) y = top - h - gap;
    else if (bottom + gap + h <= vh - 4) {
      y = bottom + gap;
      below = true;
    } else y = Math.max(4, top - h - gap);
    let x = left + width / 2;
    const halfW = w / 2;
    if (x - halfW < 4) x = halfW + 4;
    if (x + halfW > vw - 4) x = vw - halfW - 4;
    tip.classList.toggle("below", below);
    tip.style.left = x + "px";
    tip.style.top = y + "px";
  }

  function show(el) {
    const t = el.getAttribute("data-tip");
    if (!t) return;
    activeEl = el;
    tip.textContent = t;
    tip.hidden = false;
    position(el);
    requestAnimationFrame(() => {
      if (activeEl !== el) return;
      position(el);
      tip.classList.add("show");
    });
    clearTimeout(hideTimer);
  }

  function hide() {
    if (!tip.classList.contains("show")) {
      tip.hidden = true;
      activeEl = null;
      return;
    }
    tip.classList.remove("show");
    activeEl = null;
    clearTimeout(hideTimer);
    hideTimer = setTimeout(() => {
      if (activeEl === null) tip.hidden = true;
    }, 180);
  }

  document.addEventListener("mouseover", (e) => {
    if (isTouch) return;
    const el = e.target.closest("[data-tip]");
    if (!el || el === activeEl) return;
    if (e.relatedTarget && el.contains(e.relatedTarget)) return;
    show(el);
  });
  document.addEventListener("mouseout", (e) => {
    if (isTouch) return;
    const el = e.target.closest("[data-tip]");
    if (!el) return;
    if (e.relatedTarget && el.contains(e.relatedTarget)) return;
    hide();
  });
  document.addEventListener(
    "focusin",
    (e) => {
      if (isTouch) return;
      const el = e.target.closest("[data-tip]");
      if (el) show(el);
    },
    true,
  );
  document.addEventListener(
    "focusout",
    (e) => {
      if (isTouch) return;
      if (e.target.closest("[data-tip]")) hide();
    },
    true,
  );

  let tTimer = null,
    tEl = null;
  document.addEventListener(
    "touchstart",
    (e) => {
      const el = e.target.closest("[data-tip]");
      if (!el) return;
      clearTimeout(tTimer);
      tEl = el;
      tTimer = setTimeout(() => {
        if (tEl === el) show(el);
      }, 220);
    },
    { passive: true },
  );
  const endTouch = () => {
    clearTimeout(tTimer);
    tTimer = null;
    tEl = null;
    setTimeout(hide, 80);
  };
  document.addEventListener("touchend", endTouch, { passive: true });
  document.addEventListener("touchcancel", endTouch, { passive: true });
  document.addEventListener(
    "touchmove",
    () => {
      clearTimeout(tTimer);
      tTimer = null;
      tEl = null;
      hide();
    },
    { passive: true },
  );
  document.addEventListener("scroll", hide, { passive: true });
})();

export let _mmdResizeTimer = 0;
window.addEventListener(
  "resize",
  () => {
    clearTimeout(_mmdResizeTimer);
    _mmdResizeTimer = setTimeout(() => {
      if (document.querySelector(".mmd > svg")) _fixMmdSvgSize();
    }, 200);
  },
  { passive: true },
);

/* ─── Window Resize Animation Pauser ────────────────────────────── */
(function setupResizePause() {
  let isResizing = false;
  let endTimer = 0;

  const startResize = () => {
    if (isResizing) return;
    isResizing = true;
    document.documentElement.classList.add("is-resizing");
    window.__APP_PAUSED = true;
  };

  const endResize = () => {
    if (!isResizing) return;
    clearTimeout(endTimer);
    isResizing = false;
    document.documentElement.classList.remove("is-resizing");
    window.__APP_PAUSED = false;
  };

  window.addEventListener("resize", () => {
    startResize();
    clearTimeout(endTimer);
    endTimer = setTimeout(endResize, 600);
  }, { passive: true });

  window.addEventListener("pointermove", (e) => {
    if (isResizing && e.buttons === 0) {
      endResize();
    }
  }, { passive: true });

  window.addEventListener("pointerup", () => {
    if (isResizing) endResize();
  }, { passive: true });
})();
