/*
 * Fx — تعیین سطح جلوه‌های بصری.
 *
 * تنظیم کاربر (pref "fx"):
 *   auto  → حالت خودکار: اگر دستگاه ضعیف باشد یا فریم‌ها کند باشند، «سبک» می‌شود
 *   full  → همهٔ جلوه‌ها
 *   lite  → بدون هاله، بدون blur، بدون ماسک ریل
 *
 * خروجی روی <html>:
 *   data-fx        = انتخاب کاربر
 *   data-fx-eff    = سطح واقعی اعمال‌شده (full | lite)
 * رویداد «lector:fx» بعد از هر تغییر منتشر می‌شود.
 */
(function initFx(global) {
  "use strict";

  const root = document.documentElement;
  const SLOW_FRAME_MS = 34; // میانهٔ فریم بالاتر از این (کمتر از ~۳۰fps) = دستگاه کند
  const SAMPLE_FRAMES = 45;

  let pref = "auto";
  let measured = null; // "full" | "lite" | null

  function lowHint() {
    const nav = global.navigator || {};
    const cores = nav.hardwareConcurrency;
    const mem = nav.deviceMemory;
    return (cores && cores <= 4) || (mem && mem <= 4);
  }

  function resolve(p) {
    if (p === "full" || p === "lite") return p;
    if (measured) return measured;
    return lowHint() ? "lite" : "full";
  }

  function apply(nextPref) {
    pref = nextPref === "full" || nextPref === "lite" ? nextPref : "auto";
    const level = resolve(pref);
    root.setAttribute("data-fx", pref);
    if (root.getAttribute("data-fx-eff") !== level) {
      root.setAttribute("data-fx-eff", level);
    }
    global.dispatchEvent(new Event("lector:fx"));
  }

  // نمونه‌برداری کوتاه از فریم‌ها بعد از لود؛ فقط وقتی کاربر «خودکار» گذاشته
  function probe() {
    let last = 0;
    const deltas = [];
    function tick(t) {
      if (last) deltas.push(t - last);
      last = t;
      if (deltas.length < SAMPLE_FRAMES) {
        requestAnimationFrame(tick);
        return;
      }
      deltas.sort((a, b) => a - b);
      const median = deltas[deltas.length >> 1];
      const next = median > SLOW_FRAME_MS ? "lite" : "full";
      if (measured !== next) {
        measured = next;
        if (pref === "auto") apply(pref);
      }
    }
    requestAnimationFrame(tick);
  }

  function startProbe() {
    // کمی بعد از لود تا کار اولیهٔ صفحه تمام شود
    setTimeout(() => {
      if (document.visibilityState === "visible") probe();
    }, 1200);
  }
  if (document.readyState === "complete") startProbe();
  else global.addEventListener("load", startProbe, { once: true });

  global.Fx = Object.freeze({
    apply,
    resolve: (p) => resolve(p),
    level: () => root.getAttribute("data-fx-eff") || "full",
  });
})(window);
