import { main } from "../../preferences/prefs.js";
import { K, escHtml, toFa, toast, uiConfirm } from "../../core.js";
import { icon } from "../components/icons.js";
import { go } from "../layout/router.js";
export function pageShop() {
  if (typeof ShopAPI === "undefined") {
    main.innerHTML = `<div class="page"><div class="card" style="padding:24px;text-align:center">shop.js بارگذاری نشده است.</div></div>`;
    return;
  }

  const state = { q: "", category: "همه", sort: "popular", all: [] };

  function _cover(kind) {
    const u = "sc" + Math.random().toString(36).slice(2, 8);
    const cx = 200, cy = 125;
    const K = {
      atom: `
        <ellipse cx="${cx}" cy="${cy}" rx="150" ry="42" fill="none" stroke="#6d8bff" stroke-opacity=".4" stroke-width="1.6"/>
        <ellipse cx="${cx}" cy="${cy}" rx="150" ry="42" fill="none" stroke="#a06bff" stroke-opacity=".36" stroke-width="1.6" transform="rotate(60 ${cx} ${cy})"/>
        <ellipse cx="${cx}" cy="${cy}" rx="150" ry="42" fill="none" stroke="#22d3ee" stroke-opacity=".32" stroke-width="1.6" transform="rotate(-60 ${cx} ${cy})"/>
        <circle cx="${cx}" cy="${cy}" r="46" fill="url(#g${u})" opacity=".6"/>
        <circle cx="${cx}" cy="${cy}" r="14" fill="#ffeec2"/>`,
      spiral: (() => {
        let d = `M${cx} ${cy}`;
        for (let i = 0; i < 170; i++) {
          const a = i * 0.17, r = 2.4 * i * 0.2;
          d += " L" + (cx + Math.cos(a) * r).toFixed(1) + " " + (cy + Math.sin(a) * r).toFixed(1);
        }
        return `<g stroke="#f0c46a" stroke-opacity=".18" stroke-width="1">
            ${Array.from({ length: 6 }, (_, i) => `<circle cx="${cx}" cy="${cy}" r="${22 + i * 22}" fill="none"/>`).join("")}
          </g>
          <path d="${d}" fill="none" stroke="#f5cf7a" stroke-width="2.4" stroke-linecap="round" stroke-opacity=".9"/>`;
      })(),
      orbit: `
        <g stroke="#8fb4ff" stroke-opacity=".24" fill="none">
          ${Array.from({ length: 6 }, (_, i) => `<circle cx="${cx}" cy="${cy}" r="${28 + i * 22}" stroke-width="1"/>`).join("")}
        </g>
        <circle cx="${cx}" cy="${cy}" r="20" fill="#ffe9b8"/>
        <circle cx="${cx + 100}" cy="${cy}" r="9" fill="#38bdf8"/>
        <circle cx="${cx + 130}" cy="${cy}" r="5" fill="#f472b6"/>`,
      wave: (() => {
        const mk = (y, amp, ph, col, op) => {
          let d = "";
          for (let x = 20; x <= 380; x += 6) d += (x === 20 ? "M" : "L") + x + " " + (y + Math.sin(x * 0.04 + ph) * amp).toFixed(1) + " ";
          return `<path d="${d}" fill="none" stroke="${col}" stroke-width="2.4" stroke-opacity="${op}"/>`;
        };
        return mk(65, 30, 0, "#22d3ee", ".9") + mk(125, 30, 1, "#a78bfa", ".6") + mk(185, 30, -1, "#34d399", ".6");
      })(),
      molecule: (() => {
        let hex = "", dots = "";
        for (let r = 0; r < 2; r++)
          for (let c = 0; c < 4; c++) {
            const x = 50 + c * 90 + (r % 2 ? 45 : 0), y = 75 + r * 90;
            if (x > 380) continue;
            let p = "";
            for (let k = 0; k < 6; k++) {
              const a = (Math.PI / 3) * k + Math.PI / 6;
              p += (k ? "L" : "M") + (x + 32 * Math.cos(a)).toFixed(1) + " " + (y + 32 * Math.sin(a)).toFixed(1) + " ";
            }
            hex += `<path d="${p}Z" fill="none" stroke="#39e0e8" stroke-opacity=".5" stroke-width="1.6"/>`;
            dots += `<circle cx="${x}" cy="${y}" r="4.5" fill="#7ef9ff"/>`;
          }
        return hex + dots;
      })(),
      dna: (() => {
        let p1 = "", p2 = "", rungs = "";
        for (let x = 20; x <= 380; x += 5) {
          const ph = (x - 20) * 0.055;
          const y1 = cy + Math.sin(ph) * 42;
          const y2 = cy - Math.sin(ph) * 42;
          p1 += (x === 20 ? "M" : "L") + x + " " + y1.toFixed(1) + " ";
          p2 += (x === 20 ? "M" : "L") + x + " " + y2.toFixed(1) + " ";
          if ((x - 20) % 20 === 0)
            rungs += `<line x1="${x}" y1="${y1.toFixed(1)}" x2="${x}" y2="${y2.toFixed(1)}" stroke="#9fe8b6" stroke-opacity=".35" stroke-width="1.6"/>`;
        }
        return rungs +
          `<path d="${p1}" fill="none" stroke="#57e39a" stroke-width="3" stroke-linecap="round" opacity=".9"/>` +
          `<path d="${p2}" fill="none" stroke="#a8e05f" stroke-width="3" stroke-linecap="round" opacity=".65"/>`;
      })(),
      prism: `
        <polygon points="${cx},30 ${cx + 120},220 ${cx - 120},220" fill="url(#g${u})" opacity=".14"/>
        <polygon points="${cx},30 ${cx + 120},220 ${cx - 120},220" fill="none" stroke="#8fb4ff" stroke-opacity=".65" stroke-width="2"/>
        <line x1="20" y1="${cy}" x2="${cx - 40}" y2="${cy}" stroke="#fcd34d" stroke-width="2.6" stroke-opacity=".75" stroke-linecap="round"/>
        <line x1="${cx + 40}" y1="${cy}" x2="380" y2="${cy - 80}" stroke="#f472b6" stroke-width="2.6" stroke-opacity=".7" stroke-linecap="round"/>
        <line x1="${cx + 40}" y1="${cy}" x2="380" y2="${cy}" stroke="#38bdf8" stroke-width="2.6" stroke-opacity=".7" stroke-linecap="round"/>
        <line x1="${cx + 40}" y1="${cy}" x2="380" y2="${cy + 80}" stroke="#34d399" stroke-width="2.6" stroke-opacity=".7" stroke-linecap="round"/>`,
    };
    const inner = K[kind] || K.atom;
    return `<svg viewBox="0 0 400 250" preserveAspectRatio="xMidYMid slice" aria-hidden="true">
      <defs>
        <linearGradient id="b${u}" x1="0" y1="0" x2="1" y2="1">
          <stop offset="0%" stop-color="#141c3d"/>
          <stop offset="55%" stop-color="#0a1030"/>
          <stop offset="100%" stop-color="#05070f"/>
        </linearGradient>
        <radialGradient id="g${u}">
          <stop offset="0%" stop-color="#ffe9b8" stop-opacity=".9"/>
          <stop offset="100%" stop-color="#f2b544" stop-opacity="0"/>
        </radialGradient>
      </defs>
      <rect width="400" height="250" fill="url(#b${u})"/>
      ${inner}
    </svg>`;
  }

  function _filtered() {
    const q = (state.q || "").trim().toLowerCase();
    const list = state.all.filter((p) => {
      if (state.category !== "همه" && p.category !== state.category) return false;
      if (!q) return true;
      return `${p.title} ${p.subtitle} ${p.author} ${p.category} ${(p.tags || []).join(" ")}`.toLowerCase().includes(q);
    });
    if (state.sort === "popular") list.sort((a, b) => (b.students || 0) - (a.students || 0));
    else if (state.sort === "rating") list.sort((a, b) => (b.rating || 0) - (a.rating || 0));
    else if (state.sort === "cheap") list.sort((a, b) => (a.price || 0) - (b.price || 0));
    else if (state.sort === "newest") list.sort((a, b) => String(b.updatedAt || "").localeCompare(String(a.updatedAt || "")));
    return list;
  }

  function _cardHTML(p, featured) {
    const cover = _cover((p.cover && p.cover.kind) || "atom");
    const owned = ShopAPI.isPurchased(p.id) || p.installed;
    const paid = (p.price || 0) > 0;
    const hasDiscount = p.oldPrice && p.oldPrice > p.price;
    const pct = hasDiscount ? Math.round((1 - p.price / p.oldPrice) * 100) : 0;

    let badge = "";
    if (owned) badge = `<span class="shop-owned-badge">${icon("check")} در کتابخانه</span>`;
    else if (hasDiscount) badge = `<span class="shop-discount">${toFa(pct)}٪ تخفیف</span>`;
    else if (p.badge) badge = `<span class="shop-ribbon">${escHtml(p.badge)}</span>`;

    const tags = (p.tags || []).slice(0, 2).map((t) => `<span class="pk-tag">${escHtml(t)}</span>`).join("");
    const price = paid
      ? `<div class="shop-price"><span class="shop-price-now">${toFa(p.price)} <small>تومان</small></span>${hasDiscount ? `<span class="shop-price-old">${toFa(p.oldPrice)}</span>` : ""}</div>`
      : `<div class="shop-price shop-price--free"><span class="shop-price-now">رایگان</span></div>`;
    const action = owned
      ? `<button class="btn btn-sm" data-open="${escHtml(p.id)}" type="button">${icon("eye")} در کتابخانه</button>`
      : `<button class="btn btn-sm g" data-buy="${escHtml(p.id)}" type="button">${icon(paid ? "bookmark" : "plus")} ${paid ? "خرید" : "افزودن"}</button>`;

    return `<article class="pk-card${featured ? " pk-card--featured" : ""}" data-id="${escHtml(p.id)}">
      <div class="pk-cov">${cover}${badge}</div>
      <div class="pk-body">
        <div class="pk-head">
          ${p.category ? `<span class="pk-cat">${escHtml(p.category)}</span>` : ""}
          ${p.rating ? `<span class="pk-rating">${icon("starFilled")} ${toFa(p.rating)}</span>` : ""}
          ${p.students ? `<span class="pk-stud">${icon("user")} ${toFa(p.students)}</span>` : ""}
        </div>
        <h3 class="pk-title">${escHtml(p.title)}</h3>
        <p class="pk-sub">${escHtml(p.subtitle || "")}</p>
        ${tags ? `<div class="pk-tags">${tags}</div>` : ""}
        <div class="pk-foot">${price}<div class="pk-acts">${action}</div></div>
      </div>
    </article>`;
  }

  function _renderStats() {
    const el = main.querySelector("#shopStats");
    if (!el) return;
    const total = state.all.length;
    const cats = new Set(state.all.map((p) => p.category)).size;
    const students = state.all.reduce((a, p) => a + (p.students || 0), 0);
    const kfmt = (n) => (n >= 1000 ? (Math.round(n / 100) / 10).toFixed(0) + "K" : String(n));
    el.innerHTML = `
      <div class="shop-stat"><b>${toFa(total)}</b><span>درس‌نامه</span></div>
      <div class="shop-stat"><b>${toFa(cats)}</b><span>دسته</span></div>
      <div class="shop-stat"><b>${kfmt(students)}</b><span>دانشجو</span></div>`;
  }

  function _renderCats() {
    const wrap = main.querySelector("#shopCats");
    if (!wrap) return;
    wrap.innerHTML = ShopAPI.categories()
      .map((c) => {
        const n = c === "همه" ? state.all.length : state.all.filter((p) => p.category === c).length;
        return `<button class="shop-chip${c === state.category ? " on" : ""}" data-cat="${escHtml(c)}" type="button">${escHtml(c)}${c !== "همه" ? `<i>${toFa(n)}</i>` : ""}</button>`;
      })
      .join("");
    wrap.querySelectorAll("[data-cat]").forEach((b) => {
      b.onclick = () => {
        state.category = b.dataset.cat;
        wrap.querySelectorAll("[data-cat]").forEach((x) => x.classList.toggle("on", x === b));
        _renderResults();
      };
    });
  }

  function _renderResults() {
    const grid = main.querySelector("#shopGrid");
    const featSec = main.querySelector("#shopFeatured");
    const featGrid = main.querySelector("#shopFeaturedGrid");
    if (!grid) return;

    const list = _filtered();
    if (!list.length) {
      grid.innerHTML = `<div class="shop-empty">${icon("search")}<b>پکی پیدا نشد</b><span>عبارت جستجو یا فیلتر دسته را تغییر بده.</span></div>`;
      if (featSec) featSec.hidden = true;
      return;
    }

    const featured = list.filter((p) => p.featured);
    const others = list.filter((p) => !p.featured);

    if (featSec && featGrid) {
      featSec.hidden = !featured.length;
      if (featured.length) featGrid.innerHTML = featured.map((p) => _cardHTML(p, true)).join("");
    }

    grid.innerHTML = others.map((p) => _cardHTML(p, false)).join("");
    if (!others.length) {
      grid.innerHTML = `<div class="shop-empty">${icon("info")}<b>همهٔ نتایج در بخش پیشنهاد ویژه نمایش داده شده‌اند</b></div>`;
    }

    main.querySelectorAll("[data-buy]").forEach((b) => {
      b.onclick = (e) => { e.stopPropagation(); _handleBuy(b.dataset.buy); };
    });
    main.querySelectorAll("[data-open]").forEach((b) => {
      b.onclick = (e) => { e.stopPropagation(); go("library"); };
    });
  }

  async function _handleBuy(id) {
    const pack = state.all.find((x) => x.id === id);
    if (!pack) return;
    const paid = (pack.price || 0) > 0;
    const ok = await uiConfirm({
      title: paid ? "خرید پک" : "افزودن پک",
      message: paid
        ? `پک «<b>${escHtml(pack.title)}</b>» به قیمت ${toFa(pack.price)} تومان خریداری شود؟<br><span style="color:var(--text-tertiary);font-size:var(--font-size-xs)">پرداخت در حالت آزمایشی شبیه‌سازی می‌شود.</span>`
        : `پک رایگان «<b>${escHtml(pack.title)}</b>» به کتابخانهٔ شما افزوده شود؟`,
      okText: paid ? "خرید" : "افزودن",
      iconSvg: icon("library"),
    });
    if (!ok) return;

    const btn = main.querySelector(`[data-buy="${id}"]`);
    if (btn) {
      btn.disabled = true;
      btn.innerHTML = `<span class="shop-loading-spin" style="width:12px;height:12px;border-width:2px"></span>`;
    }
    try {
      const res = await ShopAPI.purchase(id);
      if (!res.ok && res.reason === "already_owned") toast("قبلاً در کتابخانه‌ات هست", "warn");
      else if (!res.ok) toast("خرید ناموفق بود", "err");
      else toast(paid ? "پک خریداری شد" : "پک افزوده شد", "ok");
    } catch (_) {
      toast("خطای غیرمنتظره", "err");
    }
    _renderResults();
  }

  async function _boot() {
    main.innerHTML = `<div class="page shop-page">
      <header class="shop-hero">
        <span class="shop-kicker">${icon("layers")} فروشگاه</span>
        <h1 class="shop-hero-h1">پک‌های آمادهٔ نصب</h1>
        <p class="shop-hero-sub">درس‌نامه‌های تعاملی با مفاهیم، فرمول، نمودار و شبیه‌سازی. با یک کلیک به کتابخانهٔ شما افزوده می‌شوند.</p>
        <div class="shop-stats" id="shopStats"></div>
        <div class="shop-search">
          <span class="ic">${icon("search")}</span>
          <input type="text" id="shopQ" placeholder="جستجو در عنوان، نویسنده یا موضوع…" autocomplete="off" maxlength="80" />
        </div>
      </header>

      <div class="shop-devnote">${icon("info")}<span>این صفحه در حالت نمایشی است؛ خرید و دریافت پک هنوز فعال نیست.</span></div>

      <div class="shop-filters">
        <div class="shop-cats" id="shopCats"></div>
        <span class="shop-filters-spacer"></span>
        <div class="shop-sort-wrap" id="shopSortWrap">
          <button class="shop-sort-btn" type="button" aria-haspopup="listbox" aria-expanded="false">
            <span id="shopSortLabel">محبوب‌ترین</span>
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><polyline points="6 9 12 15 18 9"/></svg>
          </button>
          <div class="shop-sort-menu" role="listbox" id="shopSortMenu">
            <button class="shop-sort-item on" data-val="popular" role="option">محبوب‌ترین</button>
            <button class="shop-sort-item" data-val="rating" role="option">بهترین امتیاز</button>
            <button class="shop-sort-item" data-val="newest" role="option">جدیدترین</button>
            <button class="shop-sort-item" data-val="cheap" role="option">ارزان‌ترین</button>
          </div>
        </div>
      </div>

      <section class="shop-featured" id="shopFeatured" hidden>
        <h2 class="shop-section-h">پیشنهاد ویژه</h2>
        <div class="shop-featured-grid" id="shopFeaturedGrid"></div>
      </section>

      <section class="shop-all">
        <h2 class="shop-section-h">همهٔ پک‌ها</h2>
        <div class="shop-grid" id="shopGrid">
          <div class="shop-loading"><span class="shop-loading-spin"></span><span>در حال بارگذاری…</span></div>
        </div>
      </section>

      <div class="shop-trust">
        <div class="shop-trust-item">${icon("bolt")}<b>دریافت فوری</b><span>بلافاصله پس از خرید</span></div>
        <div class="shop-trust-item">${icon("check")}<b>پرداخت امن</b><span>درگاه معتبر</span></div>
        <div class="shop-trust-item">${icon("refresh")}<b>به‌روزرسانی رایگان</b><span>همیشه آخرین نسخه</span></div>
        <div class="shop-trust-item">${icon("bellRing")}<b>پشتیبانی</b><span>پاسخ در ۲۴ ساعت</span></div>
      </div>
    </div>`;

    const q = main.querySelector("#shopQ");
    let timer = 0;
    if (q)
      q.addEventListener("input", () => {
        clearTimeout(timer);
        timer = setTimeout(() => {
          state.q = q.value;
          _renderResults();
        }, 220);
      });

    const sortWrap = main.querySelector("#shopSortWrap");
    const sortBtn = sortWrap.querySelector(".shop-sort-btn");
    const sortMenu = sortWrap.querySelector(".shop-sort-menu");
    const sortLabel = sortWrap.querySelector("#shopSortLabel");

    if (sortBtn && sortMenu) {
      sortBtn.onclick = (e) => {
        e.stopPropagation();
        const isOpen = sortMenu.classList.contains("on");
        sortMenu.classList.toggle("on", !isOpen);
        sortBtn.setAttribute("aria-expanded", !isOpen);
      };

      sortMenu.querySelectorAll(".shop-sort-item").forEach((item) => {
        item.onclick = () => {
          state.sort = item.dataset.val;
          sortLabel.textContent = item.textContent;
          
          sortMenu.querySelectorAll(".shop-sort-item").forEach((x) => x.classList.toggle("on", x === item));
          sortMenu.classList.remove("on");
          sortBtn.setAttribute("aria-expanded", "false");
          _renderResults();
        };
      });

      document.addEventListener("click", (e) => {
        if (!sortWrap.contains(e.target)) {
          sortMenu.classList.remove("on");
          sortBtn.setAttribute("aria-expanded", "false");
        }
      });
    }

    try {
      state.all = await ShopAPI.list({ sort: "popular" });
    } catch (_) {
      const g = main.querySelector("#shopGrid");
      if (g) g.innerHTML = `<div class="shop-empty">${icon("warn")}<b>بارگذاری ناموفق بود</b><span>اتصال را بررسی کن.</span></div>`;
      return;
    }

    _renderStats();
    _renderCats();
    _renderResults();
  }

  _boot();
}
if (typeof window !== "undefined") window.pageShop = pageShop;