import { _packReadCount } from "./_shared.js";
import { escHtml, stagger, toFa, toast } from "../../core.js";
import { icon } from "../components/icons.js";
import { applyPrefs, main } from "../../preferences/prefs.js";
import { applyBrand } from "../../brand.js";
import { go, refreshShellSidebar } from "../layout/router.js";
export function _coverKindFor(p) {
  const m = p.meta || {};
  if (m.cover && m.cover.kind) return m.cover.kind;
  if (m.archetype === "narrative") return "spiral";
  return "generic";
}

export function _libStatus(p) {
  const ss = (p.course && p.course.sessions) || [];
  const readN = _packReadCount(p.id, ss);
  const total = ss.length;
  const pct = total ? Math.round((readN / total) * 100) : 0;
  let st = "new";
  if (total && readN >= total) st = "done";
  else if (readN > 0) st = "going";
  return { readN, total, pct, st };
}

export function _libItemHTML(p, i) {
  const m = p.meta || {};
  const isActive = CourseRuntime.getActivePackId() === p.id;
  const kind = _coverKindFor(p);
  const cover = typeof coverArt === "function" ? coverArt(kind, p.id) : "";
  const { readN, total, pct, st } = _libStatus(p);
  const name = m.appName || m.title || p.id;
  const stLabel = { new: "تازه", going: "در حال مطالعه", done: "تمام‌شده" }[st];
  const primary = isActive
    ? `<button class="btn btn-sm g" data-pk-open="${escHtml(p.id)}">${icon("play")}<span>${st === "new" ? "شروع" : "ادامه"}</span></button>`
    : `<button class="btn btn-sm" data-pk-activate="${escHtml(p.id)}">${icon("check")}<span>فعال‌سازی</span></button>`;
  return `<article class="lib-item${isActive ? " is-active" : ""}" data-open="${escHtml(p.id)}" data-lib-name="${escHtml(name.toLowerCase())}" data-lib-st="${st}${isActive ? " active" : ""}" style="animation-delay:${i * 50}ms">
    <div class="lib-cov">${cover}</div>
    <div class="lib-main">
      <div class="lib-top">
        <div class="lib-head-text">
          <h3 class="lib-name">${escHtml(name)}</h3>
          <p class="lib-desc">${escHtml(m.subtitle || "")}${m.author ? " — " + escHtml(m.author) : ""}</p>
        </div>
        ${isActive ? `<span class="lib-badge lib-badge--active">${icon("check")} فعال</span>` : `<span class="lib-badge">${stLabel}</span>`}
      </div>
      
      <div class="lib-prog-wrap">
        <div class="lib-prog-tx">
          <span>پیشرفت مطالعه</span>
          <span dir="ltr">${total ? toFa(readN) + " / " + toFa(total) : "—"}</span>
        </div>
        <div class="lib-bar"><i data-w="${total ? pct : 0}"></i></div>
      </div>

      <div class="lib-item-foot">
        <span class="lib-meta">${[m.category, m.level]
          .filter(Boolean)
          .map((x) => escHtml(x))
          .join(" · ")}</span>
        <div class="lib-acts">${primary}</div>
      </div>
    </div>
  </article>`;
}

export function pageLibrary() {
  const packs = CourseRuntime.listRegisteredPacks();
  if (!packs.length) {
    main.innerHTML = `<div class="page">
      <div class="lib-empty">
        ${icon("library")}
        <h2>کتابخانه خالی است</h2>
        <p>هنوز هیچ پکی نصب نکرده‌اید. می‌توانید از فروشگاه پک اضافه کنید یا یک فایل درسنامه ایمپورت کنید.</p>
        <button class="btn g" onclick="go('shop')">رفتن به فروشگاه</button>
      </div>
    </div>`;
    return;
  }

  let totalSess = 0,
    totalRead = 0,
    nDone = 0,
    nGoing = 0;
  packs.forEach((p) => {
    const x = _libStatus(p);
    totalSess += x.total;
    totalRead += x.readN;
    if (x.st === "done") nDone++;
    else if (x.st === "going") nGoing++;
  });
  const overall = totalSess ? Math.round((totalRead / totalSess) * 100) : 0;

  main.innerHTML = `<div class="page lib-page">
    <header class="lib-hero">
      <div class="lib-hero-top">
        <div class="lib-hero-tx">
          <span class="lib-kicker">${icon("library")}کتابخانه</span>
          <h1 class="lib-h1">پک‌های من</h1>
          <p class="lib-sub">پک فعال همان است که در سایدبار و داشبورد دیده می‌شود.</p>
        </div>
        <div class="lib-stats" role="list">
          <div class="lib-stat" role="listitem"><b dir="ltr">${toFa(packs.length)}</b><span>پک نصب‌شده</span></div>
          <div class="lib-stat" role="listitem"><b dir="ltr">${toFa(overall)}٪</b><span>پیشرفت کل</span></div>
          <div class="lib-stat" role="listitem"><b dir="ltr">${toFa(nDone)}</b><span>تمام‌شده</span></div>
        </div>
      </div>
      <div class="lib-hero-search">
        <label class="lib-search">
          ${icon("search")}
          <input id="libQ" type="search" placeholder="جست‌وجو در پک‌ها…" autocomplete="off" />
        </label>
      </div>
    </header>

    <div class="lib-tools">
      <div class="lib-chips" role="group" aria-label="فیلتر وضعیت">
        <button class="lib-chip on" data-libf="all" type="button">همه</button>
        <button class="lib-chip" data-libf="going" type="button">در حال مطالعه${nGoing ? ` (${toFa(nGoing)})` : ""}</button>
        <button class="lib-chip" data-libf="new" type="button">تازه</button>
        <button class="lib-chip" data-libf="done" type="button">تمام‌شده</button>
      </div>
    </div>

    <div class="lib-grid" id="libGrid">${packs.map((p, i) => _libItemHTML(p, i)).join("")}</div>
    <p class="lib-none" id="libNone" hidden>پکی با این مشخصات پیدا نشد.</p>

    <div class="lib-bento-grid">
      
      <!-- کارت اول: فروشگاه -->
      <article class="lib-bento-card lib-bento-store">
        <div class="lib-bento-icon">${icon("layers")}</div>
        <div class="lib-bento-content">
          <h3 class="lib-bento-title">کتابخانه خود را گسترش دهید</h3>
          <p class="lib-bento-desc">پک‌های آماده با نمودارها و شبیه‌سازی‌های تعاملی را از فروشگاه دریافت کنید.</p>
          <button class="lib-bento-btn btn-main" data-lib-go="store">
            ${icon("layers")} مشاهده فروشگاه
          </button>
        </div>
      </article>

      <!-- کارت دوم: ایمپورت -->
      <article class="lib-bento-card lib-bento-import">
        <div class="lib-bento-icon">${icon("up")}</div>
        <div class="lib-bento-content">
          <h3 class="lib-bento-title">درسنامه شخصی خود را بیاورید</h3>
          <p class="lib-bento-desc">فایل‌های JSON خود را با یک کلیک ایمپورت کنید و محتوای اختصاصی خود را مطالعه کنید.</p>
          <button class="lib-bento-btn btn-sec" data-lib-go="import">
            ${icon("up")} انتخاب فایل
          </button>
        </div>
      </article>

    </div>
  </div>`;

  requestAnimationFrame(() => {
    main.querySelectorAll(".lib-bar > i").forEach((el) => {
      el.style.width = (el.dataset.w || "0") + "%";
    });
  });

  let _libFilter = "all";
  const applyFilter = () => {
    const q = (document.getElementById("libQ").value || "").trim().toLowerCase();
    let shown = 0;
    main.querySelectorAll(".lib-item").forEach((el) => {
      const okQ = !q || el.dataset.libName.indexOf(q) >= 0;
      const okF = _libFilter === "all" || el.dataset.libSt.indexOf(_libFilter) === 0;
      const on = okQ && okF;
      el.hidden = !on;
      if (on) shown++;
    });
    document.getElementById("libNone").hidden = shown > 0;
  };
  document.getElementById("libQ").addEventListener("input", applyFilter);
  main.querySelectorAll("[data-libf]").forEach((b) => {
    b.addEventListener("click", () => {
      _libFilter = b.dataset.libf;
      main.querySelectorAll("[data-libf]").forEach((x) => x.classList.toggle("on", x === b));
      applyFilter();
    });
  });

  main.querySelectorAll("[data-lib-go]").forEach((b) => {
    b.addEventListener("click", () => {
      const t = b.dataset.libGo;
      if (t === "store") go("shop");
      else if (typeof toast === "function")
        toast("ایمپورت پک از فایل در این نسخه فعال نیست", "warn");
    });
  });

  const openPack = async (id) => {
    try {
      if (typeof Loader !== "undefined" && typeof Loader.activate === "function") {
        await Loader.activate(id);
        applyBrand();
      } else {
        CourseRuntime.activatePack(id);
      }
      if (typeof applyPrefs === "function") applyPrefs();
      refreshShellSidebar();
      go("p/" + encodeURIComponent(id));
    } catch (_) {
      if (typeof toast === "function") toast("فعال‌سازی ناموفق بود", "err");
    }
  };
  main.querySelectorAll("[data-pk-open]").forEach((b) => {
    b.addEventListener("click", (e) => {
      e.stopPropagation();
      openPack(b.dataset.pkOpen);
    });
  });
  main.querySelectorAll("[data-pk-activate]").forEach((b) => {
    b.addEventListener("click", async (e) => {
      e.stopPropagation();
      const id = b.dataset.pkActivate;
      try {
        if (typeof Loader !== "undefined" && typeof Loader.activate === "function") {
          await Loader.activate(id);
          applyBrand();
        } else {
          CourseRuntime.activatePack(id);
        }
        if (typeof applyPrefs === "function") applyPrefs();
        refreshShellSidebar();
        pageLibrary();
      } catch (_) {
        if (typeof toast === "function") toast("فعال‌سازی ناموفق بود", "err");
      }
    });
  });
  main.querySelectorAll(".lib-item[data-open]").forEach((card) => {
    card.addEventListener("click", (e) => {
      if (e.target.closest("button")) return;
      openPack(card.dataset.open);
    });
  });
  stagger(main);
}
if (typeof window !== "undefined") window.pageLibrary = pageLibrary;
