import { KATEX_DELIMS, chip, clearMistake, escHtml, loadMistakes, markMistake, problemIds, saveSolved, solvedCount, solvedSet, toFa, toast, updateSolvedProg } from "../../core.js";
import { icon } from "../components/icons.js";
import { main } from "../../preferences/prefs.js";
export function _updateProbProgressBanner() {
  const total = problemIds().size;
  const solved = solvedCount();
  const pct = total ? Math.round((solved / total) * 100) : 0;

  const ring = document.querySelector(".pss-prog-fg");
  if (ring) {
    ring.dataset.pct = String(pct);
    const C = 2 * Math.PI * 50;
    ring.style.strokeDashoffset = C * (1 - pct / 100);
  }
  const pctTx = document.querySelector(".pss-prog-tx b");
  if (pctTx) pctTx.textContent = toFa(pct) + "٪";
  const metaB = document.querySelectorAll(".pss-prog-meta b");
  if (metaB && metaB.length >= 2) {
    metaB[0].textContent = toFa(solved);
    metaB[1].textContent = toFa(total);
  }
}
window._updateProbProgressBanner = _updateProbProgressBanner;

export let _mistOpen = false;
export function _buildMistCard() {
  const mistakes = typeof loadMistakes === "function" ? loadMistakes() : {};
  const n = Object.keys(mistakes).length;
  if (n === 0) {
    return `
      <div class="pss-head">${icon("warn")}<b>دفتر اشتباهات</b></div>
      <div class="pss-empty">هنوز مسئله‌ای علامت نخورده.</div>`;
  }
  const list = Object.entries(mistakes)
    .map(([pid, meta]) => {
      const title = (meta && meta.title) || pid;
      const cnt = (meta && meta.count) || 1;
      const secName = meta && meta.section ? escHtml(meta.section) : "";
      return `<div class="pss-mist-item">
        <a class="pss-mist-main" href="#${escHtml(pid)}" data-anchor="${escHtml(pid)}">
          <span class="pss-mist-title">${escHtml(title)}</span>
          ${secName ? `<span class="pss-mist-sec">${secName}</span>` : ""}
        </a>
        <span class="pss-mist-badge" aria-label="تعداد ثبت">${toFa(cnt)}×</span>
        <button type="button" class="pss-mist-del" data-mist-del="${escHtml(pid)}" aria-label="حذف از دفتر اشتباهات" title="حذف">
          ${icon("x")}
        </button>
      </div>`;
    })
    .join("");
  return `
    <button type="button" class="pss-head pss-head--toggle" data-mist-toggle aria-expanded="${_mistOpen ? "true" : "false"}">
      ${icon("warn")}<b>دفتر اشتباهات</b>
      <span class="pss-count">${toFa(n)}</span>
      <span class="pss-chev" aria-hidden="true">${icon("chevLeft")}</span>
    </button>
    <nav class="pss-mist-list" ${_mistOpen ? "" : "hidden"}>${list}</nav>`;
}

export function pageProblems() {
  if (typeof window._sessCleanup === "function") {
    try {
      window._sessCleanup();
    } catch (_) {}
    window._sessCleanup = null;
  }
  if (typeof window.clearDeferredKatex === "function") window.clearDeferredKatex();

  // اسکلت فوری — قبل از ساخت کامل DOM تا کاربر بلافاصله «صفحه‌ی حل تمرین» را ببیند
  main.innerHTML = `<div class="page prob-page"><div class="prob-grid"><div class="prob-main prob-wrap">
    <header class="prob-hero">
      <span class="prob-kicker">حل تمرین</span>
      <h1 class="prob-h1">در حال آماده‌سازی…</h1>
    </header>
  </div></div></div>`;

  const _totalP = problemIds().size;
  const _solvedP = solvedCount();
  const _pctP = _totalP ? Math.round((_solvedP / _totalP) * 100) : 0;
  const _sections = CourseRuntime.getProblemSections();
  const _allProblems = CourseRuntime.getProblems();
  const _sideNav = _sections
    .map((s, i) => {
      const list = _allProblems.filter((p) => p.section === s.k);
      const done = list.filter((p) => solvedSet.has(p.id)).length;
      const pct = list.length ? Math.round((done / list.length) * 100) : 0;
      return `<a class="pss-item" href="#sec-${escHtml(String(s.k))}" data-anchor="sec-${escHtml(String(s.k))}" data-sec="${escHtml(String(s.k))}">
    <span class="pss-num">${toFa(i + 1)}</span>
    <span class="pss-body">
      <b>${escHtml(s.t)}</b>
      <span class="pss-meta" data-sec-meta>${toFa(done)} از ${toFa(list.length)}</span>
      <span class="pss-bar"><i style="width:${pct}%" data-sec-bar></i></span>
    </span>
  </a>`;
    })
    .join("");
  main.innerHTML = `<div class="page prob-page"><div class="prob-grid"><div class="prob-main prob-wrap">
<header class="prob-hero">
  <span class="prob-kicker">${icon("pencil")}حل تمرین</span>
  <h1 class="prob-h1">${escHtml((CourseRuntime.getCourse() || {}).meta.problemsTitle || "حل تمرین منتخب")}</h1>
  <p class="prob-sub">هر بخش به سرفصل و جلسات درسنامه پیوند دارد</p>
</header>
${CourseRuntime.getProblemNote()}
${_sections
  .map(
    (s) => `
<section class="prob-section" id="sec-${escHtml(String(s.k))}">
<h2>${s.t}</h2>
<div class="prob-map">${chip("سرفصل: " + s.map, "hl")}${(s.links || [])
      .map((id) => {
        const ss = ((CourseRuntime.getCourse() || {}).sessions || []).find((x) => x.id === id);
        return ss
          ? `<span class="chip" style="cursor:pointer" onclick="go('s/${id}')">جلسهٔ ${toFa(ss.num)} — ${ss.title}</span>`
          : "";
      })
      .join("")}</div>
<div class="prob-sk" aria-hidden="true"><span></span><span></span><span></span></div>
</section>`,
  )
  .join("")}
</div>
<aside class="prob-side" aria-label="پیمایش و آمار مسائل">
  <div class="pss-card pss-card--prog pss-card--ring">
    <div class="pss-prog-ring">
      <svg viewBox="0 0 120 120" aria-hidden="true">
        <defs>
          <linearGradient id="pssProgGrad" x1="0" y1="0" x2="1" y2="1">
            <stop offset="0%" stop-color="var(--accent)"/>
            <stop offset="100%" stop-color="var(--color-cyan)"/>
          </linearGradient>
        </defs>
        <circle class="pss-prog-bg" cx="60" cy="60" r="50"/>
        <circle class="pss-prog-fg" cx="60" cy="60" r="50"
                stroke-dasharray="314.159"
                stroke-dashoffset="314.159"
                data-pct="${_pctP}"/>
      </svg>
      <div class="pss-prog-tx">
        <b>${toFa(_pctP)}٪</b>
        <span>حل شده</span>
      </div>
    </div>
    <div class="pss-prog-meta">
      <b>${toFa(_solvedP)}</b>
      <span>از</span>
      <b>${toFa(_totalP)}</b>
      <span>مسئله</span>
    </div>
  </div>
  <div class="pss-card pss-card--toc">
    <div class="pss-head">${icon("list")}<b>بخش‌ها</b></div>
    <nav class="pss-nav">${_sideNav}</nav>
  </div>
  <div class="pss-card pss-card--mist" data-mistakes-card>
    ${_buildMistCard()}
  </div>
</aside>
</div>
</div>`;
  const _refsMap = CourseRuntime.getProblemRefs() || {};
  const _RM_OPTS = {
    delimiters: KATEX_DELIMS,
    throwOnError: false,
    ignoredTags: ["script", "noscript", "style", "textarea", "pre", "code"],
  };
  // KaTeX: کارت‌ها وقتی به viewport نزدیک شوند رندر می‌شوند (یک observer مشترک، بدون خواندن layout).
  // کارت بعد از پردازش عنوان ثبت می‌شود؛ پس فرمول روی عنوان خام رندر نمی‌شود.
  const _mathObs = window.renderMathInElement
    ? Scheduler.onVisible((el) => renderMathInElement(el, _RM_OPTS), "600px 0px")
    : null;
  if (window.renderMathInElement) {
    main.querySelectorAll(".prob-hero, .prob-wrap > .note").forEach((el) => renderMathInElement(el, _RM_OPTS));
  }

  function _updateProbSidebar() {
    const mistCard = document.querySelector("[data-mistakes-card]");
    if (mistCard) {
      mistCard.innerHTML = _buildMistCard();
    }

    const all = typeof CourseRuntime !== "undefined" ? CourseRuntime.getProblems() : [];
    main.querySelectorAll(".pss-item[data-sec]").forEach((item) => {
      const key = item.dataset.sec;
      const list = all.filter((p) => String(p.section) === key);
      const done = list.filter((p) => solvedSet.has(p.id)).length;
      const pct = list.length ? Math.round((done / list.length) * 100) : 0;

      const meta = item.querySelector("[data-sec-meta]");
      if (meta) meta.textContent = `${toFa(done)} از ${toFa(list.length)}`;

      const bar = item.querySelector("[data-sec-bar]");
      if (bar) bar.style.width = pct + "%";
    });
  }
  if (typeof window !== "undefined") window._updateProbSidebar = _updateProbSidebar;

  if (!window._mistDelegBound) {
    window._mistDelegBound = true;
    document.addEventListener("click", (e) => {
      const toggle = e.target.closest("[data-mist-toggle]");
      if (toggle) {
        e.preventDefault();
        const card = toggle.closest("[data-mistakes-card]");
        if (!card) return;
        _mistOpen = !_mistOpen;
        card.innerHTML = _buildMistCard();
        return;
      }

      const del = e.target.closest("[data-mist-del]");
      if (del) {
        e.preventDefault();
        e.stopPropagation();
        const pid = del.getAttribute("data-mist-del");
        if (!pid || typeof clearMistake !== "function") return;
        clearMistake(pid);
        if (typeof toast === "function") toast("از دفتر اشتباهات برداشته شد", "ok");
        if (typeof window._updateProbSidebar === "function") window._updateProbSidebar();
        return;
      }

      const main = e.target.closest(".pss-mist-main");
      if (main) {
        const anc = main.dataset.anchor;
        const el = anc && document.getElementById(anc);
        if (!el) return;
        e.preventDefault();
        const y = el.getBoundingClientRect().top + window.scrollY - 96;
        window.scrollTo({ top: y, behavior: "smooth" });
      }
    });
  }

  // کارت‌ها پس از آماده‌شدن بخش‌ها. سه‌تای اول همان لحظه، بقیه در idle. mistakes یک‌بار خوانده می‌شود.
  let _chunk = null;
  const _mistakesNow = typeof loadMistakes === "function" ? loadMistakes() : {};
  const _enhanceCard = (art) => {
    const pid = art.id;
    if (!pid) return;
    const _mb = art.querySelector(".meta-box");
    const _refs = _refsMap[pid];
    if (_mb && _refs) {
      art.querySelectorAll(".frefs").forEach((e) => e.remove());
      const box = document.createElement("div");
      box.className = "frefs";
      box.innerHTML =
        '<span class="frefs-label">روابط مرتبط:</span>' +
        _refs.map(([sid, t]) => `<span class="fchip" data-s="${sid}" data-t="${t}">${t}</span>`).join("");
      _mb.after(box);
    }
    const h3 = art.querySelector("h3");
    if (!h3) return;

    const _rawTitle = (h3.textContent || "").replace(/✔/g, "").trim();
    h3.textContent = "";
    const titleSpan = document.createElement("span");
    titleSpan.className = "prob-title";
    titleSpan.textContent = _rawTitle || pid;
    h3.appendChild(titleSpan);

    if (
      typeof markMistake === "function" &&
      typeof clearMistake === "function" &&
      typeof loadMistakes === "function"
    ) {
      const mb = document.createElement("button");
      mb.type = "button";
      mb.className = "prob-act mistake";
      const _isMarked = !!_mistakesNow[pid];
      mb.setAttribute("aria-pressed", _isMarked ? "true" : "false");
      mb.setAttribute(
        "aria-label",
        _isMarked ? "در دفتر اشتباهات — برای برداشتن کلیک کن" : "ثبت در دفتر اشتباهات",
      );
      mb.setAttribute("data-tip", _isMarked ? "در دفتر اشتباهات" : "ثبت در دفتر اشتباهات");
      mb.innerHTML = icon("warn");
      mb.onclick = (e) => {
        e.stopPropagation();
        const marked = mb.getAttribute("aria-pressed") === "true";
        if (marked) {
          clearMistake(pid);
          mb.setAttribute("aria-pressed", "false");
          mb.setAttribute("aria-label", "ثبت در دفتر اشتباهات");
          mb.setAttribute("data-tip", "ثبت در دفتر اشتباهات");
          if (typeof toast === "function") toast("از دفتر اشتباهات برداشته شد");
        } else {
          markMistake(pid, {
            title: _rawTitle || pid,
            section:
              (art.closest(".prob-section") &&
                (art.closest(".prob-section").querySelector("h2") || {}).textContent) ||
              "",
          });
          mb.setAttribute("aria-pressed", "true");
          mb.setAttribute("aria-label", "در دفتر اشتباهات — برای برداشتن کلیک کن");
          mb.setAttribute("data-tip", "در دفتر اشتباهات");
          if (typeof toast === "function") toast("در دفتر اشتباهات ثبت شد");
        }
        if (typeof window._updateProbSidebar === "function") window._updateProbSidebar();
      };
      h3.appendChild(mb);
    }

    {
      const isSolved = solvedSet.has(pid);
      const sb = document.createElement("button");
      sb.type = "button";
      sb.className = "prob-act solve";
      sb.setAttribute("aria-pressed", isSolved ? "true" : "false");
      sb.setAttribute(
        "aria-label",
        isSolved ? "حل شده — برای برداشتن کلیک کن" : "علامت به‌عنوان حل‌شده",
      );
      sb.setAttribute("data-tip", isSolved ? "حل شده" : "علامت به‌عنوان حل‌شده");
      sb.innerHTML = icon("check");
      sb.onclick = () => {
        const wasSolved = sb.getAttribute("aria-pressed") === "true";
        if (wasSolved) {
          solvedSet.delete(pid);
          sb.setAttribute("aria-pressed", "false");
          sb.setAttribute("aria-label", "علامت به‌عنوان حل‌شده");
          sb.setAttribute("data-tip", "علامت به‌عنوان حل‌شده");
        } else {
          solvedSet.add(pid);
          sb.setAttribute("aria-pressed", "true");
          sb.setAttribute("aria-label", "حل شده — برای برداشتن کلیک کن");
          sb.setAttribute("data-tip", "حل شده");
        }
        saveSolved();
        updateSolvedProg();
        _updateProbProgressBanner();
        if (typeof window._updateProbSidebar === "function") window._updateProbSidebar();
      };
      h3.appendChild(sb);
    }

    const acts = document.createElement("div");
    acts.className = "prob-actions";
    Array.from(h3.querySelectorAll(".prob-act")).forEach((b) => acts.appendChild(b));
    h3.appendChild(acts);

    const _isSolved = solvedSet.has(pid);
    const _isMis = !!_mistakesNow[pid];
    art.dataset.state = _isMis ? "mistake" : _isSolved ? "solved" : "unsolved";

    if (typeof mountPractice === "function") mountPractice(art);
    if (_mathObs) _mathObs.observe(art);
  };
  const _startCards = () => {
    _chunk = Scheduler.runChunked(Array.from(main.querySelectorAll("article.card")), _enhanceCard, {
      eager: 3,
      budgetMs: 6,
    });
  };
  // بخش‌ها یکی‌یکی پر می‌شوند: اولی همان لحظه (بالای صفحه)، بقیه در تکه‌های idle
  const _secChunk = Scheduler.runChunked(_sections, (sec) => {
    const sk = document.getElementById("sec-" + sec.k)?.querySelector(".prob-sk");
    if (!sk) return;
    sk.insertAdjacentHTML("afterend", problemsForSection(sec.k));
    sk.remove();
  }, { eager: 1, budgetMs: 6, done: _startCards });
  window._sessCleanup = () => {
    _secChunk.cancel();
    if (_chunk) _chunk.cancel();
    if (_mathObs) _mathObs.disconnect();
  };

  requestAnimationFrame(() => {
    const ring = main.querySelector(".pss-prog-fg");
    if (!ring) return;
    const pct = +ring.dataset.pct || 0;
    const C = 2 * Math.PI * 50;
    ring.style.strokeDashoffset = C * (1 - pct / 100);
  });

  main.querySelectorAll(".pss-item").forEach((a) => {
    a.addEventListener("click", (e) => {
      const t = a.dataset.anchor;
      const el = t && document.getElementById(t);
      if (!el) return;
      e.preventDefault();
      const y = el.getBoundingClientRect().top + window.scrollY - 96;
      window.scrollTo({ top: y, behavior: "smooth" });
    });
  });

  _initProbScrollSpy();
}

export function _initProbScrollSpy() {
  const sidebar = main.querySelector(".prob-side");
  if (!sidebar) return;
  const links = Array.from(sidebar.querySelectorAll(".pss-item[data-sec]"));
  if (!links.length) return;
  const targets = links.map((a) => document.getElementById("sec-" + a.dataset.sec)).filter(Boolean);
  if (!targets.length) return;

  let raf = 0;
  const tick = () => {
    raf = 0;
    const ref = (window.scrollY || document.documentElement.scrollTop) + 140;
    let active = -1;
    for (let i = 0; i < targets.length; i++) {
      if (targets[i].offsetTop <= ref) active = i;
      else break;
    }
    links.forEach((a, i) => a.classList.toggle("on", i === active));
  };
  const onScroll = () => {
    if (!raf) raf = requestAnimationFrame(tick);
  };

  window.addEventListener("scroll", onScroll, { passive: true });
  tick();

  const prev = window._sessCleanup;
  window._sessCleanup = () => {
    if (prev)
      try {
        prev();
      } catch (_) {}
    window.removeEventListener("scroll", onScroll);
    if (raf) cancelAnimationFrame(raf);
  };
}
