// رجیستری رندررهای بلاک (Phase 5.1): register، get، render، types.
// هر نمونه مستقل است؛ defaultBlockRegistry همان نقشهٔ پیش‌فرض است که برنامه استفاده می‌کند.
import type {
  BlockContext,
  BlockMap,
  BlockType,
  LooseRenderer,
  Renderer,
  RenderChild,
} from "./types.js";
import { DEFAULT_RENDERERS } from "./renderers/index.js";

export interface BlockRegistry {
  /** ثبت رندرر تایپ‌شده برای یک نوع بلاک. ثبت مجدد جایگزین می‌کند. */
  register<T extends BlockType>(type: T, renderer: Renderer<BlockMap[T]>): void;
  /** ثبت رندرر برای نوع رشته‌ای دلخواه (افزونه‌ها و کدهای قدیمی). */
  registerAny(type: string, renderer: LooseRenderer): void;
  get(type: string): LooseRenderer | undefined;
  has(type: string): boolean;
  types(): string[];
  /** رندر یک بلاک؛ نوع ناشناخته یا بلاک تهی رشتهٔ خالی برمی‌گرداند. */
  render(block: unknown, ctx?: BlockContext | null): string;
}

export function createBlockRegistry(): BlockRegistry {
  const renderers = new Map<string, LooseRenderer>();

  function registerAny(type: string, renderer: LooseRenderer): void {
    if (!type || typeof renderer !== "function")
      throw new Error("[BlockRegistry] invalid renderer");
    renderers.set(type, renderer);
  }

  function render(block: unknown, ctx?: BlockContext | null): string {
    const type =
      typeof block === "object" && block !== null ? (block as { type?: unknown }).type : undefined;
    if (typeof type !== "string" || !type) return "";
    const fn = renderers.get(type);
    if (!fn) return "";
    return fn(block as never, ctx || {}, render as RenderChild);
  }

  return {
    register: (type, renderer) => registerAny(type, renderer),
    registerAny,
    get: (type) => renderers.get(type),
    has: (type) => renderers.has(type),
    types: () => Array.from(renderers.keys()),
    render,
  };
}

/** رجیستری با همهٔ رندررهای پیش‌فرض (نوع‌های BlockType). */
export function createDefaultBlockRegistry(): BlockRegistry {
  const registry = createBlockRegistry();
  for (const type of Object.keys(DEFAULT_RENDERERS) as BlockType[]) {
    registry.registerAny(type, DEFAULT_RENDERERS[type]);
  }
  return registry;
}

export const defaultBlockRegistry: BlockRegistry = createDefaultBlockRegistry();
