// جدول بدون بررسی کلید: رفتار قبلی (THEMES[id] || پیش‌فرض) حفظ می‌شود.
const THEME_LOOKUP: Readonly<Record<string, ThemePreset | undefined>> = THEMES;

// پریست فعال از تنظیمات؛ مقدار نامعتبر یا ناموجود یعنی «academic».
function currentPresetId(): unknown {
  return typeof getPref === "function" ? getPref("preset", "academic") : "academic";
}

function presetFor(id: unknown): ThemePreset {
  return (typeof id === "string" ? THEME_LOOKUP[id] : undefined) || THEMES.academic;
}

export function getThemePreset(): ThemePreset {
  return presetFor(currentPresetId());
}

export function isPrefAllowed(key: string): boolean {
  // کلیدهای سراسری (پوسته/جلوه‌ها) هیچ‌وقت توسط پریست قفل نمی‌شوند
  if (key === "preset" || key === "theme" || key === "halo" || key === "fx") return true;
  const t = getThemePreset();
  return !t.allowed || t.allowed.indexOf(key) >= 0;
}

export function applyThemePreset(): void {
  const preset = presetFor(currentPresetId());
  document.documentElement.setAttribute("data-preset", preset.id);
}

export function listThemes(): ThemeListItem[] {
  return Object.values(THEMES).map((t) => ({
    id: t.id,
    label: t.label,
    hint: t.hint || "",
    tags: t.tags || [],
    accent: t.accent || { dark: "", light: "" },
    preview: typeof t.preview === "function" ? t.preview() : "",
  }));
}

declare global {
  var THEMES: Record<ThemeId, ThemePreset>;
  var listThemes: () => ThemeListItem[];
  var getThemePreset: () => ThemePreset;
  var isPrefAllowed: (key: string) => boolean;
  var applyThemePreset: () => void;
}

if (typeof window !== "undefined") {
  window.THEMES = THEMES;
  window.listThemes = listThemes;
  window.getThemePreset = getThemePreset;
  window.isPrefAllowed = isPrefAllowed;
  window.applyThemePreset = applyThemePreset;
}
