import { esc } from "../ui/components/search/search.js";
import { chip, ctl, toast } from "../core.js";
/*
 * Release — نسخه، به‌روزرسانی، نصب PWA و تاریخچهٔ تغییرات.
 *
 * منابع داده:
 *  - meta[name=app-version] و meta[name=app-build] در index.html (هنگام build جایگزین می‌شوند)
 *  - release.json (تولیدشده در build): شناسهٔ انتشار، تاریخ و تاریخچهٔ تغییرات به‌تفکیک نسخه
 *  - window.SwUpdate (sw-register.js): آیا Service Worker جدید منتظر فعال‌سازی است
 *  - GET_VERSION از Service Worker: ساختار کش (schema) و فهرست کش‌های فعال
 *
 * به‌روزرسانی: SW جدید → فعال‌سازی فوری؛ release.json با شناسهٔ متفاوت → بارگذاری مجدد.
 * نصب: Chromium/Edge/Android → beforeinstallprompt؛ iOS Safari → راهنمای افزودن به صفحهٔ اصلی.
 */
(function initRelease(global) {
  "use strict";

  const doc = document;
  const meta = (name) => {
    const el = doc.querySelector('meta[name="' + name + '"]');
    return el ? el.getAttribute("content") || "" : "";
  };
  const clean = (v) => (v && !v.startsWith("__") ? v : "dev");
  const VERSION = clean(meta("app-version"));
  const BUILD = clean(meta("app-build"));
  const DISMISS_KEY = "lector:install:dismissed";
  const CHECK_EVERY_MS = 30 * 60 * 1000;

  const state = {
    remote: null, // { version, build, builtAt, changelog }
    checkedAt: 0,
    checking: false,
    checkFailed: false,
    installEvt: null,
    sw: null, // { version, build, schema, caches } از Service Worker
  };

  const ua = navigator.userAgent || "";
  const isStandalone = () =>
    (global.matchMedia && matchMedia("(display-mode: standalone)").matches) ||
    navigator.standalone === true;
  const isIOS = () =>
    /iPhone|iPad|iPod/.test(ua) || (navigator.platform === "MacIntel" && navigator.maxTouchPoints > 1);
  const isSafari = () => /Safari/.test(ua) && !/CriOS|FxiOS|EdgiOS|Chrome|Chromium|Android/.test(ua);

  function esc(s) {
    return String(s == null ? "" : s).replace(
      /[&<>"']/g,
      (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c],
    );
  }
  // `code` → <code>؛ بقیه escape می‌شود
  function inline(s) {
    return esc(s).replace(/`([^`]+)`/g, "<code>$1</code>");
  }
  function num(n) {
    return Number(n).toLocaleString("fa-IR");
  }
  function fmtDate(iso) {
    if (!iso) return "—";
    try {
      return new Date(iso).toLocaleDateString("fa-IR", { year: "numeric", month: "long", day: "numeric" });
    } catch (_) {
      return iso;
    }
  }
  function ago(ts) {
    if (!ts) return "هنوز نه";
    const min = Math.round((Date.now() - ts) / 60000);
    if (min < 1) return "هم‌اکنون";
    if (min < 60) return num(min) + " دقیقه پیش";
    const h = Math.round(min / 60);
    if (h < 24) return num(h) + " ساعت پیش";
    return fmtDate(new Date(ts).toISOString());
  }

  // ── به‌روزرسانی ────────────────────────────────────────────────
  function updateKind() {
    if (global.SwUpdate && global.SwUpdate.hasWaiting()) return "sw";
    if (BUILD !== "dev" && state.remote && state.remote.build && state.remote.build !== BUILD) {
      return "remote";
    }
    return null;
  }

  // هم‌ارز parseChangelog در scripts/post-build-seo.mjs؛ فقط برای حالت توسعه (سورس)
  function parseChangelogMd(text) {
    const versions = [];
    let ver = null;
    let grp = null;
    for (const raw of String(text).split(/\r?\n/)) {
      const line = raw.trimEnd();
      if (line.startsWith("## ")) {
        const head = line.slice(3).trim();
        const m = head.match(/^v?(\d+(?:\.\d+)+[\w.-]*)\s*[—–-]\s*(.+)$/);
        ver = { version: m ? m[1] : "", title: m ? m[2].trim() : head, groups: [] };
        versions.push(ver);
        grp = null;
      } else if (ver && line.startsWith("### ")) {
        grp = { title: line.slice(4).trim(), items: [] };
        ver.groups.push(grp);
      } else if (ver && /^\s*[-*] /.test(line)) {
        if (!grp) {
          grp = { title: "", items: [] };
          ver.groups.push(grp);
        }
        grp.items.push(line.replace(/^\s*[-*] /, "").trim());
      }
    }
    return versions
      .map((v) => ({ ...v, groups: v.groups.filter((g) => g.items.length) }))
      .filter((v) => v.groups.length);
  }

  // در سورس (بدون build) release.json نیست؛ CHANGELOG.md از ریشهٔ پروژه خوانده می‌شود
  async function loadDevChangelog() {
    const res = await fetch("./CHANGELOG.md", { cache: "no-store" });
    if (!res.ok) throw new Error("http " + res.status);
    return { build: "dev", builtAt: null, changelog: parseChangelogMd(await res.text()) };
  }

  async function check(force) {
    if (state.checking) return;
    if (!force && Date.now() - state.checkedAt < 60 * 1000) return;
    state.checking = true;
    state.checkFailed = false;
    emit();
    try {
      const res = await fetch("./release.json", { cache: "no-store" });
      if (!res.ok) throw new Error("http " + res.status);
      state.remote = await res.json();
    } catch (_) {
      if (BUILD === "dev") {
        try {
          state.remote = await loadDevChangelog();
        } catch (_e) {
          state.checkFailed = true;
        }
      } else {
        state.checkFailed = true;
      }
    } finally {
      state.checking = false;
      state.checkedAt = Date.now();
      emit();
    }
  }

  function queryVersion() {
    if (!("serviceWorker" in navigator)) return;
    const ctl = navigator.serviceWorker.controller;
    if (!ctl) return;
    const ch = new MessageChannel();
    ch.port1.onmessage = (e) => {
      if (e.data && e.data.type === "VERSION") {
        state.sw = e.data;
        emit();
      }
    };
    ctl.postMessage({ type: "GET_VERSION" }, [ch.port2]);
  }

  function applyUpdate() {
    if (updateKind() === "sw") {
      global.SwUpdate.apply(); // controllerchange → reload در sw-register
      return;
    }
    global.location.reload(); // index.html شبکه‌محور است و نسخهٔ جدید را می‌گیرد
  }

  // ── نصب ───────────────────────────────────────────────────────
  global.addEventListener("beforeinstallprompt", (e) => {
    e.preventDefault();
    state.installEvt = e;
    emit();
  });
  global.addEventListener("appinstalled", () => {
    state.installEvt = null;
    emit();
  });

  function installKind() {
    if (isStandalone()) return "installed";
    if (state.installEvt) return "prompt";
    if (isIOS()) return isSafari() ? "ios" : "ios-other";
    return "none";
  }

  async function install() {
    const evt = state.installEvt;
    if (!evt) return;
    try {
      evt.prompt();
      await evt.userChoice;
    } catch (_) {}
    state.installEvt = null;
    emit();
  }

  function dismissed() {
    try {
      return global.localStorage.getItem(DISMISS_KEY) === "1";
    } catch (_) {
      return false;
    }
  }
  function dismiss() {
    try {
      global.localStorage.setItem(DISMISS_KEY, "1");
    } catch (_) {}
    emit();
  }

  // ── شناور: فقط وقتی به‌روزرسانی یا نصب لازم است ───────────────────
  const pill = doc.createElement("div");
  pill.id = "relPill";
  pill.className = "rel-pill";
  pill.hidden = true;
  doc.body.appendChild(pill);

  const sheet = doc.createElement("div");
  sheet.id = "relSheet";
  sheet.className = "rel-sheet-back";
  sheet.hidden = true;
  sheet.innerHTML =
    '<div class="rel-sheet" role="dialog" aria-modal="true" aria-labelledby="relSheetTitle">' +
    '<h3 id="relSheetTitle">افزودن به صفحهٔ اصلی</h3>' +
    '<ol class="rel-steps">' +
    '<li>دکمهٔ <b>اشتراک‌گذاری</b> ⬆ پایین صفحه را بزن.</li>' +
    '<li>گزینهٔ <b>Add to Home Screen</b> (افزودن به صفحهٔ اصلی) را انتخاب کن.</li>' +
    "<li>روی <b>Add</b> بزن. برنامه با آیکن خودش کنار بقیهٔ برنامه‌ها قرار می‌گیرد.</li>" +
    "</ol>" +
    '<button type="button" class="rel-btn" data-rel-action="close-sheet">متوجه شدم</button>' +
    "</div>";
  doc.body.appendChild(sheet);

function renderPill() {
    const kind = updateKind();
    const inst = installKind();
    pill.classList.remove("is-update");
    if (kind) {
      // پیل مخفی می‌شود تا فقط از توست استفاده کنیم
      pill.hidden = true;
      return;
    }
    if ((inst === "prompt" || inst === "ios") && !dismissed()) {
      const isIos = inst === "ios";
      pill.hidden = false;
      pill.innerHTML =
        '<span class="rel-pill-tx">برنامه را روی دستگاهت نصب کن</span>' +
        '<button type="button" class="rel-pill-btn" data-rel-action="' + (isIos ? "ios-help" : "install") + '">' +
        (isIos ? "راهنما" : "نصب") +
        "</button>" +
        '<button type="button" class="rel-pill-x" data-rel-action="dismiss" aria-label="بستن">×</button>';
      return;
    }
    pill.hidden = true;
    pill.innerHTML = "";
  }

  // ── بخش «نسخه و به‌روزرسانی» در تنظیمات ─────────────────────────
  function statusInfo() {
    if (updateKind()) return { tone: "warn", label: "نسخهٔ جدید آماده است" };
    if (state.checking) return { tone: "info", label: "در حال بررسی…" };
    if (state.checkFailed) return { tone: "err", label: "بررسی انجام نشد" };
    if (state.checkedAt) return { tone: "ok", label: "به‌روز هستی" };
    return { tone: "idle", label: "بررسی نشده" };
  }

  function chip(label, value, ltr) {
    return (
      '<div class="rel-chip"><dt>' + esc(label) + "</dt><dd" + (ltr ? ' dir="ltr"' : "") + ">" + esc(value) + "</dd></div>"
    );
  }

  function heroHTML() {
    const st = statusInfo();
    const schema = state.sw && state.sw.schema ? "s" + state.sw.schema : "—";
    const remote = state.remote || {};
    return (
      '<section class="rel-hero">' +
      '<div class="rel-hero-top">' +
      '<div><p class="rel-kicker">نسخهٔ نصب‌شده</p>' +
      '<div class="rel-ver" dir="ltr">' + (VERSION === "dev" ? "dev" : "v" + esc(VERSION)) + "</div></div>" +
      '<span class="rel-status is-' + st.tone + '"><i></i>' + esc(st.label) + "</span>" +
      "</div>" +
      '<dl class="rel-chips">' +
      chip("شناسهٔ انتشار", BUILD, true) +
      chip("ساختار کش", schema, true) +
      chip("تاریخ انتشار", fmtDate(remote.builtAt)) +
      chip("آخرین بررسی", ago(state.checkedAt)) +
      "</dl></section>"
    );
  }

  function updateCardHTML() {
    if (updateKind()) {
      return (
        '<section class="rel-card is-up"><div class="rel-card-body"><b>نسخهٔ جدید آماده است</b>' +
        "<p>با اعمال آن، برنامه یک‌بار دوباره بارگذاری می‌شود.</p></div>" +
        '<button type="button" class="rel-btn" data-rel-action="apply">اعمال به‌روزرسانی</button></section>'
      );
    }
    return (
      '<section class="rel-card"><div class="rel-card-body"><b>به‌روزرسانی</b>' +
      "<p>برنامه هر ۳۰ دقیقه و هنگام بازگشت به برگه بررسی می‌کند.</p></div>" +
      '<button type="button" class="rel-btn ghost" data-rel-action="check"' +
      (state.checking ? " disabled" : "") +
      ">" +
      (state.checking ? "در حال بررسی…" : "بررسی اکنون") +
      "</button></section>"
    );
  }

  function installCardHTML() {
    const k = installKind();
    let title;
    let text;
    let action = "";
    if (k === "installed") {
      title = "نصب شده";
      text = "برنامه روی این دستگاه نصب است و از صفحهٔ اصلی باز می‌شود.";
    } else if (k === "prompt") {
      title = "نصب روی دستگاه";
      text = "با نصب، برنامه از صفحهٔ اصلی باز می‌شود و بدون اینترنت هم در دسترس است.";
      action = '<button type="button" class="rel-btn" data-rel-action="install">نصب برنامه</button>';
    } else if (k === "ios") {
      title = "افزودن به صفحهٔ اصلی";
      text = "در Safari دکمهٔ نصب نیست؛ از دکمهٔ اشتراک‌گذاری ⬆ گزینهٔ افزودن را بزن.";
      action = '<button type="button" class="rel-btn ghost" data-rel-action="ios-help">راهنما</button>';
    } else if (k === "ios-other") {
      title = "نصب روی iPhone";
      text = "این صفحه را در Safari باز کن تا گزینهٔ افزودن به صفحهٔ اصلی دیده شود.";
    } else {
      title = "نصب";
      text = "مرورگر این دستگاه دکمهٔ نصب ارائه نمی‌دهد. از منوی مرورگر گزینهٔ «نصب» یا «افزودن به صفحهٔ اصلی» را بزن.";
    }
    return (
      '<section class="rel-card"><div class="rel-card-body"><b>' + esc(title) + "</b><p>" + esc(text) + "</p></div>" +
      action +
      "</section>"
    );
  }

  // تاریخچهٔ تغییرات: خط زمان عمودی؛ هر نسخه یک کارت با گروه‌های داخلی
  function timelineHTML() {
    const list = (state.remote && state.remote.changelog) || [];
    if (!list.length) {
      if (state.checkFailed) {
        return (
          '<div class="rl-state is-err"><b>فهرست تغییرات بارگذاری نشد.</b>' +
          '<button class="rel-btn ghost" type="button" data-rel-action="check">تلاش دوباره</button></div>'
        );
      }
      // هنوز دریافت نشده: اسکلت شیمری، و درخواست دریافت (یک‌بار)
      if (!state.checking) setTimeout(() => check(true), 0);
      return (
        '<div class="rl-skel" aria-label="در حال بارگذاری">' +
        '<span></span><span></span><span></span></div>'
      );
    }
    return (
      '<ol class="rl-log">' +
      list
        .map((v) => {
          const cur = v.version && v.version === VERSION;
          const groups = (v.groups || [])
            .map(
              (g) =>
                '<section class="rl-grp">' +
                (g.title ? "<h5>" + esc(g.title) + "</h5>" : "") +
                "<ul>" +
                g.items.map((it) => "<li>" + inline(it) + "</li>").join("") +
                "</ul></section>",
            )
            .join("");
          return (
            '<li class="rl-ver' + (cur ? " is-current" : "") + '">' +
            '<span class="rl-dot" aria-hidden="true"></span>' +
            '<header class="rl-head">' +
            '<span class="rl-tag' + (cur ? " on" : "") + '" dir="ltr">' +
            esc(v.version ? "v" + v.version : "—") +
            "</span>" +
            "<h4>" + esc(v.title) + "</h4>" +
            (cur ? '<span class="rl-badge">نسخهٔ فعلی</span>' : "") +
            "</header>" +
            (groups ? '<div class="rl-groups">' + groups + "</div>" : "") +
            "</li>"
          );
        })
        .join("") +
      "</ol>"
    );
  }

  function sectionHTML() {
    return (
      heroHTML() +
      updateCardHTML() +
      installCardHTML() +
      '<div class="rel-sec-head"><h3>تاریخچهٔ تغییرات</h3></div>' +
      timelineHTML()
    );
  }

  function refreshSection() {
    const body = doc.querySelector('#setSheetBody [data-sec="release"] .set-section-body');
    if (body) body.innerHTML = sectionHTML();
  }

  function emit() {
    renderPill();
    refreshSection();
    global.dispatchEvent(new Event("lector:release"));
  }

  // ── رویدادها ───────────────────────────────────────────────────
  doc.addEventListener("click", (e) => {
    const b = e.target.closest && e.target.closest("[data-rel-action]");
    if (!b) return;
    const act = b.getAttribute("data-rel-action");
    if (act === "apply") applyUpdate();
    else if (act === "check") check(true);
    else if (act === "install") install();
    else if (act === "dismiss") dismiss();
    else if (act === "ios-help") sheet.hidden = false;
    else if (act === "close-sheet") sheet.hidden = true;
  });
  sheet.addEventListener("click", (e) => {
    if (e.target === sheet) sheet.hidden = true;
  });

  global.addEventListener("lector:sw-update", () => {
    queryVersion();
    emit();
    
    // نمایش توست استاندارد به جای پیل شناور
    if (typeof toast === "function" && !sessionStorage.getItem("lector:update-toast")) {
      sessionStorage.setItem("lector:update-toast", "1");
      toast("نسخهٔ جدید آماده است. برای اعمال فوری دکمه «اعمال» را بزنید. این پیام بعداً در بخش اعلان‌ها (زنگوله) در دسترس خواهد بود.", "info", {
        title: "به‌روزرسانی در دسترس",
        icon: "refresh",
        duration: 12000,
        action: { label: "اعمال", run: () => global.SwUpdate.apply() },
      });
    }
  });
  if ("serviceWorker" in navigator) {
    navigator.serviceWorker.addEventListener("controllerchange", () => setTimeout(queryVersion, 300));
  }
  doc.addEventListener("visibilitychange", () => {
    if (doc.visibilityState === "visible" && Date.now() - state.checkedAt > CHECK_EVERY_MS) check(false);
  });
  setInterval(() => check(false), CHECK_EVERY_MS);

  global.addEventListener("load", () => {
    setTimeout(() => check(false), 3000);
    setTimeout(queryVersion, 1500);
  });

  global.Release = Object.freeze({
    check: () => check(true),
    apply: applyUpdate,
    sectionHTML,
    updateHTML: () => `
      ${heroHTML()}
      ${updateCardHTML()}
    `,
    installHTML: () => `
      ${installCardHTML()}
    `,
    changelogHTML: () => `
      ${timelineHTML()}
    `,
    info: () => ({
      version: VERSION,
      build: BUILD,
      schema: state.sw ? state.sw.schema : null,
      updateKind: updateKind(),
      install: installKind(),
    }),
  });

  renderPill();
})(window);
