import { pageLibrary } from "./library.js";
import { escHtml, getReadSet, readSet, stagger, toFa, toast } from "../../core.js";
import { _packReadCount } from "./_shared.js";
import { icon } from "../components/icons.js";
import { applyPrefs, main } from "../../preferences/prefs.js";
import { applyBrand } from "../../brand.js";
import { go, refreshShellSidebar } from "../layout/router.js";
export function pagePackOverview(packId) {
  const p = CourseRuntime.getPackById(packId);
  if (!p) {
    pageLibrary();
    return;
  }
  const m = (p.course && p.course.meta) || {};
  const sessions = (p.course && p.course.sessions) || [];
  const isActive = CourseRuntime.getActivePackId() === packId;
  const readSet = typeof getReadSet === "function" ? getReadSet() : new Set();
  const readN =
    typeof _packReadCount === "function"
      ? _packReadCount(packId, sessions)
      : sessions.filter((s) => readSet.has(s.id)).length;
  const pct = sessions.length ? Math.round((readN / sessions.length) * 100) : 0;
  const firstUnread = sessions.find((s) => !readSet.has(s.id)) || sessions[0];

  const sessionCards = sessions
    .map((s) => {
      const isRead = readSet.has(s.id);
      const nc = (s.concepts || []).length;
      const nf = (s.formulas || []).length;
      return `<a class="pack-sess${isRead ? " read" : ""}" href="#/p/${encodeURIComponent(packId)}/s/${encodeURIComponent(s.id)}">
      <span class="pack-sess-n">${toFa(s.num)}</span>
      <span class="pack-sess-body">
        <b class="pack-sess-t">${escHtml(s.title)}</b>
        <span class="pack-sess-m">${toFa(nc)} مفهوم · ${toFa(nf)} فرمول</span>
      </span>
      ${isRead ? `<span class="pack-sess-ck">${icon("check")}</span>` : ""}
    </a>`;
    })
    .join("");

  main.innerHTML = `<div class="page">
    <div class="pack-hero">
      <div class="pack-hero-bg" aria-hidden="true"></div>
      <div class="pack-hero-in">
        <p class="pack-hero-kick">${escHtml(m.uni || "")}${m.term ? " · " + escHtml(m.term) : ""}</p>
        <h1 class="pack-hero-t">${escHtml(m.appName || m.title || packId)}</h1>
        <p class="pack-hero-sub">${escHtml(m.subtitle || "")}</p>
        <div class="pack-hero-chips">
          <span class="chip">${escHtml(m.archetype || "stem")}</span>
          <span class="chip">${escHtml(m.layout || "classic")}</span>
          ${m.ver ? `<span class="chip num">${escHtml(m.ver)}</span>` : ""}
          <span class="chip ac">${toFa(sessions.length)} جلسه</span>
          ${isActive ? `<span class="chip ac">${icon("check")} پک فعال</span>` : ""}
        </div>
        <div class="pack-hero-acts">
          ${
            isActive
              ? firstUnread
                ? `<button class="btn g" data-act="start">${icon("play")} شروع مطالعه</button>`
                : `<span class="chip ac">${icon("check")} همهٔ جلسه‌ها خوانده شده</span>`
              : `<button class="btn g" data-act="activate" data-pack="${escHtml(packId)}">${icon("check")} فعال‌سازی این پک</button>`
          }
          <button class="btn" onclick="go('library')">${icon("library")} کتابخانه</button>
        </div>
        <div class="pack-hero-prog">
          <div class="pack-hero-prog-lb">
            <span>پیشرفت مطالعه</span>
            <span class="num">${toFa(readN)} از ${toFa(sessions.length)} — ${toFa(pct)}٪</span>
          </div>
          <div class="pack-hero-prog-bar"><i data-w="${pct}"></i></div>
        </div>
      </div>
    </div>
    <h2 class="pack-sec-h">جلسه‌ها</h2>
    <div class="pack-sess-grid">${sessionCards || `<p style="color:var(--text-secondary);padding:1rem">جلسه‌ای ثبت نشده است.</p>`}</div>
  </div>`;

  stagger(main);
  requestAnimationFrame(() => {
    main.querySelectorAll(".pack-hero-prog-bar > i").forEach((el) => {
      el.style.width = (el.dataset.w || "0") + "%";
    });
  });

  main.querySelectorAll("[data-act='activate']").forEach((b) => {
    b.addEventListener("click", async () => {
      try {
        if (typeof Loader !== "undefined" && typeof Loader.activate === "function") {
          await Loader.activate(b.dataset.pack);
          applyBrand();
        } else {
          CourseRuntime.activatePack(b.dataset.pack);
        }
        if (typeof applyPrefs === "function") applyPrefs();
        refreshShellSidebar();
        pagePackOverview(b.dataset.pack);
      } catch (_) {
        if (typeof toast === "function") toast("فعال‌سازی ناموفق بود", "err");
      }
    });
  });

  main.querySelectorAll("[data-act='start']").forEach((b) => {
    b.addEventListener("click", () => {
      if (firstUnread) {
        go("p/" + encodeURIComponent(packId) + "/s/" + encodeURIComponent(firstUnread.id));
      }
    });
  });
}
if (typeof window !== "undefined") window.pagePackOverview = pagePackOverview;
