import { chip, escHtml, stagger, toFa, toast } from "../../core.js";
import { icon } from "../components/icons.js";
import { main } from "../../preferences/prefs.js";
import { buildCoursePackData, downloadCoursePack } from "../../system/publish.js";
export const _codeBlock = (s) => `<pre class="docs-code">${escHtml(s)}</pre>`;

export function pageDEV(initialTab) {
  const M = (CourseRuntime.getCourse() || {}).meta || {};
  const T = depthTarget();
  const issues = getValidationIssues();
  const nErr = issues.filter((i) => i.lvl === "error").length;
  const nWarn = issues.length - nErr;
  const code = (arr) => (arr.length ? arr.map((k) => `<code>${escHtml(k)}</code>`).join(" ") : "—");

  const nSess = ((CourseRuntime.getCourse() || {}).sessions || []).length;
  const nFormulas = ((CourseRuntime.getCourse() || {}).sessions || []).reduce(
    (a, s) => a + (s.formulas || []).length,
    0,
  );
  const nConcepts = ((CourseRuntime.getCourse() || {}).sessions || []).reduce(
    (a, s) => a + (s.concepts || []).length,
    0,
  );
  const nDetailSess = ((CourseRuntime.getCourse() || {}).sessions || []).filter(
    (s) => s.detail && s.detail.sections && s.detail.sections.length,
  ).length;

  const tabs = [
    { id: "g-start", title: "شروع سریع", ic: "bolt" },
    { id: "g-course", title: "ساختار دوره", ic: "book" },
    { id: "g-session", title: "جلسه و حالت‌ها", ic: "pencil" },
    { id: "g-problems", title: "مسائل و ویجت‌ها", ic: "target" },
    { id: "g-health", title: "سلامت داده", ic: nErr ? "warn" : "check" },
    { id: "g-depth", title: "عمق محتوا", ic: "network" },
    { id: "g-export", title: "خروجی Course Pack", ic: "up" },
  ];

  const validTab = tabs.some((t) => t.id === initialTab) ? initialTab : tabs[0].id;

  const nav = tabs
    .map(
      (t) =>
        `<button type="button" class="docs-nav-item${t.id === validTab ? " on" : ""}" data-docs="${t.id}">
      <span class="dn-i">${icon(t.ic)}</span>
      <span class="dn-t">${t.title}</span>
    </button>`,
    )
    .join("");

  const panels = {
    "g-start": _guidePanelStart({ M, nSess, nConcepts, nFormulas, nDetailSess }),
    "g-course": _guidePanelCourse({ code }),
    "g-session": _guidePanelSession({ code }),
    "g-problems": _guidePanelProblems(),
    "g-health": _guidePanelHealth({ nErr, nWarn }),
    "g-depth": _guidePanelDepth({ T }),
    "g-export": _guidePanelExport(),
  };

  const panelHTML = tabs
    .map(
      (t) =>
        `<section class="docs-panel${t.id === validTab ? " on" : ""}" id="${t.id}" data-docs-panel="${t.id}">
      ${panels[t.id]}
    </section>`,
    )
    .join("");

  const contractVer = typeof CONTRACT_VERSION !== "undefined" ? CONTRACT_VERSION : 1;

  main.innerHTML = `<div class="page docs-page">
    <header class="docs-top">
      <div class="docs-top-text">
        <p class="docs-kicker">صفحهٔ DEV · قرارداد نسخهٔ ${toFa(contractVer)}</p>
        <h1>ابزار توسعه‌دهنده</h1>
        <p class="docs-sub">
          راهنمای تدوین درس‌نامه، اعتبارسنجی داده و خروجی Course Pack.
          این صفحه از ناوبری کاربر عادی مخفی است — فقط با تایپ مستقیم
          مسیر <code dir="ltr" style="font-family:var(--font-mono);font-size:calc(12px * var(--fs-scale, 1))">#/D_E_V</code> باز می‌شود.
        </p>
      </div>
      <div class="docs-badges">
        ${chip(escHtml(M.appName || "درس"))}
        ${chip(toFa(nSess) + " جلسه")}
        ${nErr ? chip(toFa(nErr) + " خطا", "hl") : chip("سالم", "hl")}
      </div>
    </header>
    <div class="docs-layout">
      <nav class="docs-side" aria-label="فهرست DEV">${nav}</nav>
      <div class="docs-main">${panelHTML}</div>
    </div>
  </div>`;

  const side = main.querySelector(".docs-side");
  const show = (id) => {
    main
      .querySelectorAll(".docs-nav-item")
      .forEach((b) => b.classList.toggle("on", b.dataset.docs === id));
    main
      .querySelectorAll(".docs-panel")
      .forEach((p) => p.classList.toggle("on", p.dataset.docsPanel === id));
    window.scrollTo({ top: 0, behavior: "smooth" });
    if (id === "g-export") requestAnimationFrame(_bindExportPanel);
  };
  side.querySelectorAll(".docs-nav-item").forEach((b) => {
    b.addEventListener("click", () => show(b.dataset.docs));
  });

  if (validTab === "g-export") requestAnimationFrame(_bindExportPanel);

  stagger(main);
}
if (typeof window !== "undefined") {
  window.pageDEV = pageDEV;
  window.pageGuide = pageDEV;
}

