export function _guidePanelDepth({ T }) {
  const rows = ((CourseRuntime.getCourse() || {}).sessions || [])
    .map((s) => {
      const d = {
        concepts: (s.concepts || []).length,
        formulas: (s.formulas || []).length,
        tips: (s.tips || []).length,
        summary: (s.summary || "").length,
      };
      const hasDetail = !!(s.detail && s.detail.sections && s.detail.sections.length);
      const score = Math.min(
        100,
        Math.round(
          (d.concepts / Math.max(1, T.concepts)) * 25 +
            (d.formulas / Math.max(1, T.formulas)) * 25 +
            (d.tips / Math.max(1, T.tips)) * 25 +
            (d.summary / Math.max(1, T.summary)) * 25,
        ),
      );
      const tone = score >= 75 ? "good" : score >= 45 ? "mid" : "low";
      return `<li class="depth-item">
      <div class="di-head">
        <span class="di-num">${toFa(s.num)}</span>
        <span class="di-title">${escHtml(s.title)}</span>
        ${hasDetail ? `<span class="di-tag">مفصل</span>` : ""}
      </div>
      <div class="di-body">
        <div class="di-meta">
          ${toFa(d.concepts)} مفهوم · ${toFa(d.formulas)} فرمول · ${toFa(d.tips)} نکته
        </div>
        <div class="di-bar"><i class="${tone}" style="width:${score}%"></i></div>
        <span class="di-pct">${toFa(score)}٪</span>
      </div>
    </li>`;
    })
    .join("");

  return `
    <div class="docs-panel-head"><h2>عمق محتوا</h2></div>
    <p class="docs-lead">هدف از <code>meta.depthTarget</code> — هر جلسه به‌اندازهٔ کافی پر است یا کم؟</p>

    <div class="depth-targets">
      <div class="dt"><b>${toFa(T.concepts)}</b><span>مفهوم در جلسه</span></div>
      <div class="dt"><b>${toFa(T.formulas)}</b><span>فرمول در جلسه</span></div>
      <div class="dt"><b>${toFa(T.tips)}</b><span>نکته در جلسه</span></div>
      <div class="dt"><b>${toFa(T.summary)}</b><span>کاراکتر خلاصه</span></div>
    </div>

    <ul class="depth-list">${rows}</ul>

    <div class="docs-note">
      <b>راهنمای خواندن:</b> رنگ نوار بر اساس فاصله از هدف است. سبز (≥۷۵٪): جلسه به‌اندازهٔ کافی پر است. زرد (۴۵-۷۵٪): نیاز به تکمیل. قرمز (<۴۵٪): جلسه هنوز خام است.
    </div>`;
}

export function _guidePanelExport() {
  if (typeof buildCoursePackData !== "function") {
    return `
      <div class="docs-panel-head"><h2>خروجی Course Pack</h2></div>
      <p class="docs-lead">publish.js بارگذاری نشده است.</p>`;
  }

  const data = buildCoursePackData();
  const m = data.manifest;
  const counts = m.counts;

  const summaryRows = [
    ["جلسات", toFa(counts.sessions)],
    ["فصل‌ها", toFa(counts.chapters)],
    ["مفاهیم کل", toFa(counts.concepts)],
    ["فرمول‌ها کل", toFa(counts.formulas)],
    ["واژه‌ها", toFa(counts.glossary)],
    ["ویجت‌ها", toFa(counts.widgets)],
    ["مسائل ساختارمند", toFa(counts.problemsStructured)],
    ["بخش‌های مسئله", toFa(counts.problemSections)],
  ]
    .map(([k, v]) => `<div class="row"><span>${k}</span><b>${v}</b></div>`)
    .join("");

  const jsonPreview = JSON.stringify(data, null, 2);
  const previewSnippet =
    jsonPreview.length > 600 ? jsonPreview.slice(0, 600) + "\n… (نمایش کوتاه‌شده)" : jsonPreview;

  return `
    <div class="docs-panel-head"><h2>خروجی Course Pack</h2></div>
    <p class="docs-lead">
      خروجی JSON خالص از محتوای درس — بدون هیچ داده‌ای از پیشرفت شخصی شما.
      برای آرشیو، انتقال بین نسخه‌ها، یا ورودی ابزار تدوین استفاده می‌شود.
    </p>

    <div class="docs-note" style="margin-bottom:18px">
      <b>تفاوت با پشتیبان:</b> این فایل فقط محتوای درس را دارد.
      برای پشتیبان از مطالعه، حل، نشانک، یادداشت و تنظیمات، به
      تنظیمات → حساب کاربری بروید.
    </div>

    <div class="ov-panel" style="margin-bottom:18px">
      <div class="ov-head">
        <div class="ov-head-text">
          <b class="ov-kicker">Manifest</b>
          <p class="ov-lead">خلاصهٔ محتوای بسته — قبل از تأیید دوم بازبینی کنید.</p>
        </div>
      </div>
      <div class="ov-stats" style="grid-template-columns:repeat(auto-fit,minmax(140px,1fr))">
        <div class="ov-stat"><b>${escHtml(m.id)}</b><span>شناسه</span></div>
        <div class="ov-stat"><b>${escHtml(m.ver || "—")}</b><span>نسخه</span></div>
        <div class="ov-stat"><b>v${m.contract}</b><span>قرارداد</span></div>
      </div>
      <div class="winfo">${summaryRows}</div>
    </div>

    <div class="ov-panel" style="margin-bottom:18px">
      <div class="ov-head">
        <div class="ov-head-text">
          <b class="ov-kicker">پیش‌نمایش JSON</b>
          <p class="ov-lead">۶۰۰ کاراکتر اول — برای محتوای کامل روی دکمهٔ پایین بزنید.</p>
        </div>
      </div>
      <pre class="exp-dev-pre">${escHtml(previewSnippet)}</pre>
    </div>

    <div class="exp-dev-confirm" id="expDevConfirm">
      <div class="ov-head">
        <div class="ov-head-text">
          <b class="ov-kicker">تأیید نهایی</b>
          <p class="ov-lead">
            فایل JSON آمادهٔ دانلود است. این فایل شامل محتوای درس
            بدون هیچ داده‌ای از پیشرفت شخصی شماست.
          </p>
        </div>
      </div>
      <div style="display:flex;gap:10px;flex-wrap:wrap;margin-top:12px">
        <button type="button" class="btn" id="expDevArm">آماده‌سازی دانلود</button>
        <button type="button" class="btn g" id="expDevConfirmBtn" disabled aria-disabled="true">
          تأیید نهایی و دانلود
        </button>
        <button type="button" class="btn ghost" onclick="go('home')">انصراف</button>
      </div>
      <div class="exp-dev-warn" id="expDevWarn" hidden>
        برای فعال شدن دکمهٔ دانلود، ابتدا روی «آماده‌سازی دانلود» بزنید.
      </div>
    </div>`;
}

export function _bindExportPanel() {
  const armBtn = document.getElementById("expDevArm");
  const confirmBtn = document.getElementById("expDevConfirmBtn");
  const warnEl = document.getElementById("expDevWarn");
  if (!armBtn || !confirmBtn) return;

  armBtn.onclick = () => {
    armBtn.disabled = true;
    armBtn.textContent = "آماده شد";
    confirmBtn.disabled = false;
    confirmBtn.removeAttribute("aria-disabled");
    if (warnEl) warnEl.hidden = true;
    if (typeof toast === "function") toast("دانلود آماده است — تأیید نهایی را بزنید");
  };

  confirmBtn.onclick = () => {
    if (confirmBtn.disabled) return;
    if (typeof downloadCoursePack === "function") downloadCoursePack();
  };
}
