(function initCoverArt(global) {
  "use strict";
  let uid = 0;

  function rng(seed) {
    let h = 2166136261;
    const s = String(seed || "cover");
    for (let i = 0; i < s.length; i++) {
      h ^= s.charCodeAt(i);
      h = Math.imul(h, 16777619);
    }
    return function () {
      h += 0x6d2b79f5;
      let t = h;
      t = Math.imul(t ^ (t >>> 15), t | 1);
      t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }

  const KINDS = ["atom", "spiral", "molecule", "dna", "orbit", "prism", "wave", "generic"];

  function coverArt(kind, seed) {
    const k = KINDS.includes(kind) ? kind : "generic";
    const u = "cv" + ++uid;
    const r = rng(seed || k);
    const defs = `<defs>
      <linearGradient id="bg${u}" x1="0" y1="0" x2="1" y2="1">
        <stop offset="0%" stop-color="#141c3d"/>
        <stop offset="55%" stop-color="#0a1030"/>
        <stop offset="100%" stop-color="#05070f"/>
      </linearGradient>
      <radialGradient id="glow${u}">
        <stop offset="0%" stop-color="#ffe9b8" stop-opacity=".9"/>
        <stop offset="100%" stop-color="#f2b544" stop-opacity="0"/>
      </radialGradient>
    </defs>`;
    const bg = `<rect width="400" height="500" fill="url(#bg${u})"/>`;

    let inner = "";
    if (k === "atom") {
      inner = `<g opacity=".5">${Array.from(
        { length: 40 },
        () =>
          `<circle cx="${(r() * 400).toFixed(1)}" cy="${(r() * 500).toFixed(1)}" r="${(r() * 1.4 + 0.3).toFixed(2)}" fill="#cfe0ff" opacity="${(r() * 0.65 + 0.2).toFixed(2)}"/>`,
      ).join("")}</g>
        <g style="transform-origin:200px 250px;transform-box:view-box;animation:spin 26s linear infinite">
          <ellipse cx="200" cy="250" rx="140" ry="50" fill="none" stroke="#f2b544" stroke-opacity=".6" stroke-width="1.4"/>
          <circle cx="340" cy="250" r="5" fill="#ffe6a8"/>
        </g>
        <g style="transform-origin:200px 250px;transform-box:view-box;animation:spin 34s linear infinite reverse;transform:rotate(60deg)">
          <ellipse cx="200" cy="250" rx="140" ry="50" fill="none" stroke="#8fb4ff" stroke-opacity=".55" stroke-width="1.4" transform="rotate(60 200 250)"/>
          <circle cx="340" cy="250" r="4.4" fill="#bcd4ff" transform="rotate(60 200 250)"/>
        </g>
        <g style="transform-origin:200px 250px;transform-box:view-box;animation:spin 44s linear infinite">
          <ellipse cx="200" cy="250" rx="140" ry="50" fill="none" stroke="#ff9d6b" stroke-opacity=".45" stroke-width="1.4" transform="rotate(-60 200 250)"/>
          <circle cx="340" cy="250" r="4" fill="#ffcdb0" transform="rotate(-60 200 250)"/>
        </g>
        <circle cx="200" cy="250" r="48" fill="url(#glow${u})" style="animation:pulseN 4s ease-in-out infinite"/>
        <circle cx="200" cy="250" r="16" fill="#ffeec2"/>`;
    } else if (k === "spiral") {
      let d = "M200 250";
      for (let i = 0; i < 220; i++) {
        const a = i * 0.14,
          rad = 2.6 * i * 0.24;
        d +=
          " L" + (200 + Math.cos(a) * rad).toFixed(1) + " " + (250 + Math.sin(a) * rad).toFixed(1);
      }
      inner = `<g stroke="#f0c46a" stroke-opacity=".15" stroke-width="1">${Array.from({ length: 9 }, (_, i) => `<circle cx="200" cy="250" r="${24 + i * 24}" fill="none"/>`).join("")}</g>
        <path d="${d}" fill="none" stroke="#f5cf7a" stroke-width="2" stroke-linecap="round" stroke-dasharray="2600" stroke-dashoffset="2600" style="animation:drawP 3.6s var(--ease) forwards"/>
        <path d="${d}" fill="none" stroke="#7fe6d0" stroke-opacity=".35" stroke-width="6" stroke-linecap="round" filter="blur(4px)"/>`;
    } else if (k === "molecule") {
      let hex = "";
      const nodes = [];
      for (let row = 0; row < 4; row++)
        for (let col = 0; col < 3; col++) {
          const cx = 90 + col * 110 + (row % 2 ? 55 : 0),
            cy = 110 + row * 95;
          if (cy > 470) continue;
          nodes.push([cx, cy]);
          let p = "";
          for (let kk = 0; kk < 6; kk++) {
            const a = (Math.PI / 3) * kk + Math.PI / 6;
            p +=
              (kk ? "L" : "M") +
              (cx + 38 * Math.cos(a)).toFixed(1) +
              " " +
              (cy + 38 * Math.sin(a)).toFixed(1) +
              " ";
          }
          hex += `<path d="${p}Z" fill="none" stroke="#39e0e8" stroke-opacity=".5" stroke-width="1.6"/>`;
        }
      inner =
        hex +
        nodes
          .map(
            (n, i) =>
              `<circle cx="${n[0]}" cy="${n[1]}" r="${i % 3 === 0 ? 6 : 4}" fill="${i % 3 === 0 ? "#7ef9ff" : "#c9a4ff"}" style="animation:pulseN ${3 + (i % 4)}s ease-in-out ${(i * 0.16).toFixed(2)}s infinite"/>`,
          )
          .join("") +
        `<circle cx="200" cy="250" r="120" fill="#39e0e8" opacity=".09" filter="blur(40px)"/>`;
    } else if (k === "dna") {
      let s1 = "M",
        s2 = "M",
        rungs = "";
      for (let y = 40; y <= 470; y += 6) {
        const x = 200 + Math.sin(y * 0.035) * 62;
        s1 += x.toFixed(1) + " " + y + " L";
        s2 += (400 - x).toFixed(1) + " " + y + " L";
        if (y % 36 === 0)
          rungs += `<line x1="${x.toFixed(1)}" y1="${y}" x2="${(400 - x).toFixed(1)}" y2="${y}" stroke="#9fe8b6" stroke-opacity=".4" stroke-width="2"/>`;
      }
      inner =
        rungs +
        `<path d="${s1.slice(0, -2)}" fill="none" stroke="#57e39a" stroke-width="3.4" stroke-linecap="round" opacity=".9"/>
         <path d="${s2.slice(0, -2)}" fill="none" stroke="#a8e05f" stroke-width="3.4" stroke-linecap="round" opacity=".7"/>`;
    } else if (k === "orbit") {
      inner = `<g stroke="#8fb4ff" stroke-opacity=".2" fill="none">${Array.from({ length: 8 }, (_, i) => `<circle cx="200" cy="250" r="${30 + i * 28}" stroke-width="1"/>`).join("")}</g>
        <circle cx="200" cy="250" r="26" fill="#ffe9b8"/>
        <g style="transform-origin:200px 250px;transform-box:view-box;animation:spin 20s linear infinite">
          <circle cx="316" cy="250" r="11" fill="#38bdf8"/>
        </g>
        <g style="transform-origin:200px 250px;transform-box:view-box;animation:spin 30s linear infinite reverse">
          <circle cx="368" cy="250" r="7" fill="#f472b6"/>
        </g>`;
    } else if (k === "prism") {
      const stars = Array.from(
        { length: 30 },
        () =>
          `<circle cx="${(r() * 400).toFixed(1)}" cy="${(r() * 500).toFixed(1)}" r="${(r() * 1.2 + 0.3).toFixed(2)}" fill="#cfe0ff" opacity="${(r() * 0.6 + 0.2).toFixed(2)}"/>`,
      ).join("");
      inner = `<g opacity=".45">${stars}</g>
        <polygon points="200,80 320,380 80,380" fill="url(#glow${u})" opacity=".14"/>
        <polygon points="200,80 320,380 80,380" fill="none" stroke="#8fb4ff" stroke-opacity=".7" stroke-width="2"/>
        <g stroke-linecap="round" fill="none">
          <path d="M20 210 Q100 210 180 210" stroke="#fcd34d" stroke-width="6" stroke-opacity=".35" filter="blur(3px)"/>
          <line x1="20" y1="210" x2="180" y2="210" stroke="#fcd34d" stroke-width="2.4"/>
          <line x1="220" y1="210" x2="380" y2="130" stroke="#f472b6" stroke-width="2.4"/>
          <line x1="220" y1="220" x2="380" y2="220" stroke="#38bdf8" stroke-width="2.4"/>
          <line x1="220" y1="230" x2="380" y2="310" stroke="#34d399" stroke-width="2.4"/>
        </g>
        <circle cx="200" cy="250" r="26" fill="url(#glow${u})" opacity=".55"/>`;
    } else if (k === "wave") {
      let d1 = "M20 250",
        d2 = "M20 280",
        d3 = "M20 220";
      for (let x = 20; x <= 380; x += 6) {
        d1 += " L" + x + " " + (250 + Math.sin(x * 0.04) * 40).toFixed(1);
        d2 += " L" + x + " " + (280 + Math.sin(x * 0.04 + 1) * 40).toFixed(1);
        d3 += " L" + x + " " + (220 + Math.sin(x * 0.04 - 1) * 40).toFixed(1);
      }
      inner = `<path d="${d1}" fill="none" stroke="#22d3ee" stroke-width="2.4" stroke-opacity=".9"/>
         <path d="${d2}" fill="none" stroke="#a78bfa" stroke-width="2" stroke-opacity=".7"/>
         <path d="${d3}" fill="none" stroke="#34d399" stroke-width="2" stroke-opacity=".7"/>`;
    } else {
      inner = `<g opacity=".5">
        <rect x="60" y="80" width="280" height="340" rx="20" fill="none" stroke="#8fb4ff" stroke-opacity=".35" stroke-width="1.5"/>
        <line x1="100" y1="160" x2="300" y2="160" stroke="#8fb4ff" stroke-opacity=".55" stroke-width="2"/>
        <line x1="100" y1="200" x2="260" y2="200" stroke="#8fb4ff" stroke-opacity=".35" stroke-width="1.5"/>
        <line x1="100" y1="240" x2="280" y2="240" stroke="#8fb4ff" stroke-opacity=".35" stroke-width="1.5"/>
        <line x1="100" y1="280" x2="240" y2="280" stroke="#8fb4ff" stroke-opacity=".35" stroke-width="1.5"/>
      </g>
      <circle cx="200" cy="370" r="36" fill="url(#glow${u})"/>`;
    }
    return `<svg viewBox="0 0 400 500" preserveAspectRatio="xMidYMid slice" aria-hidden="true" width="100%" height="100%">${defs}${bg}${inner}</svg>`;
  }

  global.coverArt = coverArt;
})(typeof window !== "undefined" ? window : globalThis);
