(function () {
  "use strict";
  const W = {
    title: "مقیاس دما و نقطهٔ سه‌گانهٔ آب",
    desc: "روی نوار دما حرکت کنید تا موقعیت نقطهٔ انجماد، نقطهٔ جوش، و نقطهٔ سه‌گانهٔ آب روی چهار مقیاس (کلوین، سلسیوس، فارنهایت، رانکین) را ببینید. با تغییر خاصیت ترمومتریک فرضی، رابطهٔ خطی θ(X)=aX را آزمایش کنید.",
    sess: ["s01"],
    mount(box) {
      box.innerHTML = `<div class="wgrid" style="--wctl:260px">
  <div class="wstage"><canvas width="680" height="380"></canvas></div>
  <div>
  <div class="ctls"></div>
  <div class="winfo"></div>
  </div>
  </div>`;

      const cv = box.querySelector("canvas");
      const ctx = setupHD(cv, 680, 380);
      const ct = box.querySelector(".ctls");
      const info = box.querySelector(".winfo");

      let T_K = 300;
      let X_val = 1.0;

      const CW = 680,
        CH = 380;
      const BAR_X = 60,
        BAR_W = 60;
      const BAR_Y = 60,
        BAR_H = 260;

      function wpalLocal() {
        if (window.__APP_PRINTING)
          return {
            bg: "rgba(0,0,0,0)",
            axis: "#4b5563",
            grid: "rgba(55,65,81,.14)",
            txt: "#1f2430",
            dim: "#5b6472",
          };
        const light = document.documentElement.getAttribute("data-theme") === "light";
        return light
          ? {
              bg: "#f7f5ef",
              axis: "#9a9488",
              grid: "rgba(70,64,55,.18)",
              txt: "#4a463d",
              dim: "#8a8578",
            }
          : {
              bg: "#05070f",
              axis: "#3b4770",
              grid: "rgba(103,115,155,.18)",
              txt: "#eaeefb",
              dim: "#67739b",
            };
      }

      function draw() {
        const P = wpalLocal();
        ctx.clearRect(0, 0, CW, CH);
        ctx.fillStyle = P.bg;
        ctx.fillRect(0, 0, CW, CH);

        const TMAX = 500;
        const frac = Math.max(0, Math.min(1, T_K / TMAX));
        const y = BAR_Y + BAR_H - frac * BAR_H;

        const grd = ctx.createLinearGradient(0, BAR_Y + BAR_H, 0, BAR_Y);
        grd.addColorStop(0.0, "#0b1226");
        grd.addColorStop(0.2, "#1e293b");
        grd.addColorStop(0.4, "#dc2626");
        grd.addColorStop(0.55, "#fb923c");
        grd.addColorStop(0.75, "#fcd34d");
        grd.addColorStop(1.0, "#f0f9ff");
        ctx.fillStyle = grd;
        ctx.fillRect(BAR_X, BAR_Y, BAR_W, BAR_H);

        const points = [
          { T: 0, label: "صفر مطلق", color: "#c7d2fe" },
          { T: 273.15, label: "انجماد آب", color: "#22d3ee" },
          { T: 273.16, label: "نقطهٔ سه‌گانه", color: "#a78bfa" },
          { T: 373.124, label: "جوش عادی آب", color: "#fbbf24" },
          { T: 500, label: "انتهای بازه", color: "#94a3b8" },
        ];
        points.forEach((p) => {
          const yp = BAR_Y + BAR_H - (p.T / TMAX) * BAR_H;
          ctx.strokeStyle = p.color;
          ctx.lineWidth = 2;
          ctx.beginPath();
          ctx.moveTo(BAR_X - 8, yp);
          ctx.lineTo(BAR_X + BAR_W + 8, yp);
          ctx.stroke();
          ctx.fillStyle = p.color;
          ctx.font = "11px Vazirmatn";
          ctx.textAlign = "left";
          ctx.fillText(p.label, BAR_X + BAR_W + 14, yp + 4);
        });

        ctx.strokeStyle = "#f472b6";
        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.moveTo(BAR_X - 14, y);
        ctx.lineTo(BAR_X + BAR_W + 14, y);
        ctx.stroke();
        ctx.fillStyle = "#f472b6";
        ctx.beginPath();
        ctx.arc(BAR_X + BAR_W / 2, y, 8, 0, 2 * Math.PI);
        ctx.fill();

        const TK = T_K;
        const TC = TK - 273.15;
        const TF = (9 / 5) * TC + 32;
        const TR = (9 / 5) * TK;
        ctx.textAlign = "center";
        ctx.fillStyle = P.txt;
        ctx.font = "11px Vazirmatn";
        ctx.fillText(`${TK.toFixed(2)} K`, BAR_X + BAR_W + 90, y - 4);
        ctx.fillText(`${TC.toFixed(2)} °C`, BAR_X + BAR_W + 90, y + 12);
        ctx.fillText(`${TF.toFixed(2)} °F`, BAR_X + BAR_W + 90, y + 28);
        ctx.fillText(`${TR.toFixed(2)} R`, BAR_X + BAR_W + 90, y + 44);

        const panX = 360,
          panY = 60,
          panW = 280,
          panH = 260;
        ctx.strokeStyle = P.grid;
        ctx.lineWidth = 1;
        ctx.strokeRect(panX, panY, panW, panH);

        ctx.fillStyle = P.dim;
        ctx.font = "11px Vazirmatn";
        ctx.textAlign = "center";
        ctx.fillText("خاصیت ترمومتریک X در حجم ثابت", panX + panW / 2, panY - 8);

        const xNorm = (X_val - 0.5) / 1.5;
        const px = panX + 20 + xNorm * (panW - 40);
        const py = panY + panH - 30;

        ctx.fillStyle = "#22d3ee";
        ctx.beginPath();
        ctx.arc(px, py, 6, 0, 2 * Math.PI);
        ctx.fill();

        ctx.fillStyle = P.txt;
        ctx.font = "12px Vazirmatn";
        ctx.textAlign = "left";
        ctx.fillText(`X = ${X_val.toFixed(3)}`, panX + 12, panY + panH - 10);
        ctx.fillText(`θ(X) = a·X  →  a = ${(TK / X_val).toFixed(2)}`, panX + 12, panY + 20);

        info.innerHTML = `
  <div class="row"><span>دما (کلوین)</span><b>${toFa(TK.toFixed(2))} K</b></div>
  <div class="row"><span>دما (سلسیوس)</span><b>${toFa(TC.toFixed(2))} °C</b></div>
  <div class="row"><span>دما (فارنهایت)</span><b>${toFa(TF.toFixed(2))} °F</b></div>
  <div class="row"><span>دما (رانکین)</span><b>${toFa(TR.toFixed(2))} R</b></div>
  <div class="row"><span>خاصیت ترمومتریک X</span><b>${toFa(X_val.toFixed(3))}</b></div>
  <div class="row"><span>ثابت مقیاس a = θ/X</span><b>${toFa((TK / X_val).toFixed(2))}</b></div>
  <div class="props">
    <span class="badge b-cyn">θ(X) = aX</span>
    <span class="badge b-blu">رابطهٔ خطی</span>
  </div>`;
      }

      ctl(ct, "دما (کلوین)", 1, 500, 1, 300, "K", (v) => {
        T_K = v;
        draw();
      });
      ctl(ct, "خاصیت ترمومتریک X", 0.1, 2.0, 0.01, 1.0, "", (v) => {
        X_val = v;
        draw();
      });

      draw();
    },
  };
  CourseRuntime.registerPackSource("thermo", { widgets: { thermometer: W } });
})();
