import { $, reRenderMmd } from "../../core.js";
import { setPref } from "../../preferences/prefs.js";
import { go } from "../layout/router.js";
(function () {
  const b = $("#themeToggle");
  if (!b) return;
  b.onclick = async () => {
    const cur = document.documentElement.getAttribute("data-theme") || "dark";
    const next = cur === "light" ? "dark" : "light";
    setPref("theme", next);
    if (typeof reRenderMmd === "function") await reRenderMmd();
  };
})();

export function _packReadCount(packId, sessions) {
  if (!sessions || !sessions.length) return 0;
  try {
    const key = packId + "Read";
    const raw = localStorage.getItem(key);
    if (!raw) return 0;
    const arr = JSON.parse(raw);
    if (!Array.isArray(arr)) return 0;
    const set = new Set(arr);
    return sessions.filter((s) => set.has(s.id)).length;
  } catch (_) {
    return 0;
  }
}

(function () {
  if (document.getElementById("fpop")) return;
  const pop = document.createElement("div");
  pop.id = "fpop";
  pop.innerHTML =
    '<div class="fp-t"></div><div class="fp-x" dir="ltr"></div><div class="fp-u"></div>';
  document.body.appendChild(pop);
  const fpT = pop.querySelector(".fp-t"),
    fpX = pop.querySelector(".fp-x"),
    fpU = pop.querySelector(".fp-u");

  function show(c) {
    const s = ((CourseRuntime.getCourse() || {}).sessions || []).find((x) => x.id === c.dataset.s);
    const i = s ? s.formulas.findIndex((f) => f.t === c.dataset.t) : -1;
    if (!s || i < 0) {
      pop.style.display = "none";
      return;
    }
    const f = s.formulas[i];
    fpT.textContent = f.t;
    if (window.katex) katex.render(f.tex, fpX, { displayMode: true, throwOnError: false });
    else fpX.textContent = f.tex;
    fpU.textContent = (f.use ? f.use + " · " : "") + "کلیک کنید";
    if (window.renderMathInElement) {
      renderMathInElement(fpU, {
        delimiters: [{ left: "$", right: "$", display: false }],
        throwOnError: false,
      });
    }
    pop.style.display = "block";
    const z = parseFloat(getComputedStyle(document.documentElement).zoom) || 1;
    const r = c.getBoundingClientRect(),
      pr = pop.getBoundingClientRect();
    const rw = pr.width / z,
      rh = pr.height / z,
      vw = innerWidth / z,
      vh = innerHeight / z;
    const x = Math.min(Math.max(8, (r.left + r.width / 2) / z - rw / 2), vw - rw - 8);
    let y = r.bottom / z + 10;
    if (y + rh > vh - 8) y = r.top / z - rh - 10;
    pop.style.left = x + "px";
    pop.style.top = y + "px";
  }

  document.addEventListener("mouseover", (e) => {
    const c = e.target.closest(".fchip");
    if (c) show(c);
  });

  document.addEventListener("mouseout", (e) => {
    if (e.target.closest(".fchip") && !("ontouchstart" in window)) pop.style.display = "none";
  });

  window.addEventListener("scroll", () => (pop.style.display = "none"), { passive: true });

  let _fpTouchT = 0;
  document.addEventListener("click", (e) => {
    const c = e.target.closest(".fchip");
    if (!c) {
      if (!e.target.closest("#fpop")) pop.style.display = "none";
      return;
    }
    const now = Date.now();
    const s = ((CourseRuntime.getCourse() || {}).sessions || []).find((x) => x.id === c.dataset.s);
    const i = s ? s.formulas.findIndex((f) => f.t === c.dataset.t) : -1;
    if (i < 0) return;
    if (!("ontouchstart" in window) && matchMedia("(hover:hover)").matches) {
      go("s/" + s.id, "f-" + s.id + "-" + i);
      return;
    }
    if (
      pop.style.display === "block" &&
      pop.dataset.fid === c.dataset.s + ":" + c.dataset.t &&
      now - _fpTouchT < 2000
    ) {
      go("s/" + s.id, "f-" + s.id + "-" + i);
      pop.style.display = "none";
      return;
    }
    show(c);
    pop.dataset.fid = c.dataset.s + ":" + c.dataset.t;
    _fpTouchT = now;
  });
})();
