// API عمومی قرارداد پک (Contract v3).
// فایل‌ها: types / constants / normalize / derive / validate / schema / presentation.
// این فایل توابع را روی globalThis هم می‌گذارد، چون کدهای JS موجود به آن‌ها به‌صورت global وابسته‌اند.

import { BLOCK_TYPES, CALLOUT_TONES, HEADING_LEVELS } from "../blocks/block-types.js";
import { getCategories, getPack } from "../runtime/active.js";
import { getUnitErrors } from "../runtime/registry.js";
import {
  ACCEPTED_CONTRACTS,
  CONTRACT_VERSION,
  EXPERIENCE_KINDS,
  FALLBACK_CAT,
  FEATURE_DEFAULTS,
} from "./constants.js";
import { deriveFeatures, deriveProblemRefs, depthTarget, sessionDepth } from "./derive.js";
import { normalizeCourse, normalizePack, normalizeProblems } from "./normalize.js";
import type { FeatureSet, Pack, ValidationIssue } from "./types.js";
import { runPackValidation, validatePack } from "./validate.js";

export * from "./types.js";
export * from "./constants.js";
export { normalizeCourse, normalizePack, normalizeProblems } from "./normalize.js";
export { deriveFeatures, deriveProblemRefs, depthTarget, sessionDepth } from "./derive.js";
export { runPackValidation, validatePack, validateSession, validateFormula } from "./validate.js";
export { checkPackShape, courseSchema, packSchema, sessionSchema } from "./schema.js";
export { normalizePresentationMeta, resolvePresentation } from "./presentation.js";

declare global {
  var getValidationIssues: () => ValidationIssue[];
}

export function getCat(k: string): unknown {
  const cats = getCategories() as Record<string, unknown>;
  return cats[k] || FALLBACK_CAT;
}

// ── قابلیت‌ها: نتیجه برای هر پک یک‌بار محاسبه و کش می‌شود ─────────────
let resolvedFeatures: FeatureSet | null = null;
let lastPack: Partial<Pack> | null = null;

function resolveFeatures(pack?: Partial<Pack> | null): FeatureSet {
  const p = (pack || getPack() || {}) as Partial<Pack>;
  if (p !== lastPack) {
    resolvedFeatures = null;
    lastPack = p;
  }
  if (resolvedFeatures) return resolvedFeatures;
  resolvedFeatures = deriveFeatures(p);
  return resolvedFeatures;
}

export function featureEnabled(name: keyof FeatureSet): boolean {
  return !!resolveFeatures()[name];
}
export function hasWidgets(): boolean {
  return featureEnabled("labs");
}
export function hasProblems(): boolean {
  return featureEnabled("problems");
}

const api = Object.freeze({
  CONTRACT_VERSION,
  ACCEPTED_CONTRACTS,
  EXPERIENCE_KINDS,
  FALLBACK_CAT,
  BLOCK_TYPES,
  CALLOUT_TONES,
  HEADING_LEVELS,
  FEATURE_DEFAULTS,
  getCat,
  normalizeCourse,
  normalizeProblems,
  deriveProblemRefs,
  normalizePack,
  validatePack,
  runPackValidation,
  featureEnabled,
  hasWidgets,
  hasProblems,
  sessionDepth,
  depthTarget,
});

// توابع قرارداد روی global هم در دسترس‌اند (سازگاری با کدهای JS)
Object.assign(globalThis, api);

// فهرست مسائل پک فعال به‌علاوهٔ خطاهای ثبت واحد (runtime)
globalThis.getValidationIssues = (): ValidationIssue[] => {
  const p = getPack() as (Pack & { validation?: unknown }) | null;
  const base = (p && Array.isArray(p.validation) ? p.validation : []) as ValidationIssue[];
  const unitIssues = getUnitErrors().map((e) => ({
    lvl: "error",
    where: [e.packId, e.kind, e.id].filter(Boolean).join(" / "),
    msg: e.msg,
  }));
  return base.concat(unitIssues);
};
