// پک فعال و دسترسی به داده‌های آن. همهٔ خواننده‌ها روی پک فعال (یا پک مشخص با id) کار می‌کنند.

import type { Pack, Course, Meta, Category } from "../contract/types.js";
import { engineEvents } from "../events.js";
import { getPackById, getRawPack as getSourceById, registerPack } from "./registry.js";

let activePackId: string | null = null;
let activePack: Pack | null = null;

const ACTIVE_PACK_KEY = "lector:activePack";

function persistActivePack(pack: Pack): void {
  try {
    const course: Course | Pack = pack.course || pack;
    const meta: Meta = (course.meta as Meta | undefined) || {};
    const look = meta.look || {};
    const theme = ["dark", "light", "system"].includes(String(look.theme))
      ? String(look.theme)
      : null;
    localStorage.setItem(
      ACTIVE_PACK_KEY,
      JSON.stringify({ ns: meta.id || "course", defaultTheme: theme }),
    );
  } catch {
    // localStorage ممکن است در دسترس نباشد؛ ذخیرهٔ پک فعال اختیاری است
  }
}

function setActive(pack: Pack, id: string): Pack {
  activePack = pack;
  activePackId = id;
  persistActivePack(pack);
  engineEvents.emit("pack:activated", { id });
  return pack;
}

// منبع خام: با id مشخص، یا پک فعال
export function getRawPack(id?: string): Pack | null {
  return id ? getSourceById(id) : activePack || (activePackId ? getSourceById(activePackId) : null);
}

export function setActivePack(packOrId: string | Pack): Pack {
  const pack = typeof packOrId === "string" ? getSourceById(packOrId) : packOrId;
  if (!pack) throw new Error("[Runtime] Unknown pack: " + String(packOrId));
  const id = pack.id || (pack.meta && pack.meta.id) || activePackId;
  return setActive(pack, String(id));
}

export function replaceActivePack(pack: Pack): Pack | null {
  if (!pack) throw new Error("[Runtime] Cannot activate an empty pack");
  const id = pack.id || (pack.meta && pack.meta.id);
  if (!id) throw new Error("[Runtime] Pack must have an id");
  // جایگزینی نسخهٔ ثبت‌شده و سپس فعال‌سازی
  registerPack(pack, id);
  return activatePack(id);
}

export function activatePack(id: string): Pack | null {
  const p = getPackById(id);
  if (!p) return null;
  return setActive(p, id);
}

export function getActivePackId(): string | null {
  return activePackId;
}

export function getPack(id?: string): Pack | null {
  if (id) return getPackById(id);
  return activePack || (activePackId ? getPackById(activePackId) : null);
}

export function getCourse(id?: string): Course | Pack | null {
  const p = getPack(id);
  if (!p) return null;
  return (p.course as Course | undefined) || p;
}

export function getCategories(id?: string): Record<string, Category | unknown> {
  const p = getPack(id);
  return (p && (p.categories || p.cats)) || {};
}

export function getProblems(id?: string): unknown[] {
  const p = getPack(id);
  return (p && p.problems) || [];
}

export function getProblemSections(id?: string): unknown[] {
  const p = getPack(id);
  return (p && p.problemSections) || [];
}

export function getProblemNote(id?: string): string {
  const p = getPack(id);
  return (p && p.problemNote) || "";
}

export function getProblemHtml(id?: string): Record<string, unknown> {
  const p = getPack(id);
  return (p && p.problemHtml) || {};
}

export function getProblemRefs(id?: string): Record<string, unknown> {
  const p = getPack(id);
  return (p && p.problemRefs) || {};
}

export function getPackReviewCards(id?: string): unknown[] {
  const p = getPack(id);
  return (p && p.reviewCards) || [];
}

export function getPackAssessments(id?: string): unknown[] {
  const p = getPack(id);
  return (p && p.assessments) || [];
}

export function getPackGraphNodes(id?: string): unknown[] {
  const p = getPack(id);
  return (p && p.graphNodes) || [];
}

export function getWidgets(id?: string): Record<string, unknown> {
  const p = getPack(id);
  return (p && p.widgets) || {};
}
