import { NS, _dayKey, chip, escHtml, katexifyText, loadEvents, loadReviewState, lsGet, lsSet, recordEvent, saveReviewState, toFa, toast } from "../../core.js";
import { go, updateProg } from "../layout/router.js";
import { icon } from "../components/icons.js";
import { main } from "../../preferences/prefs.js";
(function initFlashcards(global) {
  "use strict";

  const DAY = 864e5,
    MIN = 6e4;
  const NEW_PER_DAY = 15;
  const GRADES = [
    { k: "again", n: 1, t: "دوباره", c: "rose" },
    { k: "hard", n: 2, t: "سخت", c: "amber" },
    { k: "good", n: 3, t: "خوب", c: "green" },
    { k: "easy", n: 4, t: "آسان", c: "blue" },
  ];

  function _state() {
    const s = loadReviewState() || {};
    if (!s.cards || typeof s.cards !== "object") s.cards = {};
    if (!s.daily || typeof s.daily !== "object") s.daily = { day: "", newN: 0 };
    return s;
  }
  function _todayKey() {
    return _dayKey(Date.now());
  }
  function _userKey() {
    return NS() + "UserCards";
  }
  function _loadUser() {
    try {
      const a = JSON.parse(lsGet(_userKey(), "[]"));
      return Array.isArray(a) ? a : [];
    } catch (_) {
      return [];
    }
  }
  function _saveUser(a) {
    lsSet(_userKey(), JSON.stringify(a.slice(-1000)));
  }

  function allCards() {
    const C = CourseRuntime.getCourse() || {};
    const out = [];
    (CourseRuntime.getPackReviewCards() || []).forEach((c, i) => {
      const front = c.front || c.t || c.title;
      if (!front) return;
      out.push({
        id: c.id || "rc-" + i,
        deck: "pack",
        front: String(front),
        back: String(c.back || c.def || c.d || ""),
        pts: [],
        kind: "text",
        disabled: false,
      });
    });
    (C.sessions || []).forEach((s) => {
      const deckDis = s.review === "off";
      const deck = "s:" + s.id;
      (s.concepts || []).forEach((c, i) => {
        if (!c || !c.t) return;
        if (c.review === false) return;
        out.push({
          id: "c:" + s.id + ":" + i,
          deck,
          sess: s.id,
          kind: "text",
          front: String(c.t),
          back: String(c.def || ""),
          pts: (c.pts || []).filter(Boolean),
          disabled: deckDis,
        });
      });
      (s.formulas || []).forEach((f, i) => {
        if (!f || !f.t) return;
        if (f.review === false) return;
        out.push({
          id: "f:" + s.id + ":" + i,
          deck,
          sess: s.id,
          kind: "formula",
          front: String(f.t),
          back: String(f.use || ""),
          tex: String(f.tex || ""),
          vars: Array.isArray(f.vars) ? f.vars : [],
          pts: [],
          disabled: deckDis,
        });
      });
    });
    _loadUser().forEach((u) =>
      out.push(
        Object.assign({ kind: "text", pts: [], back: "" }, u, { user: true, disabled: false }),
      ),
    );
    return out;
  }

  function deckTitle(deck) {
    if (deck === "pack") return "کارت‌های درس";
    if (deck === "user") return "کارت‌های من";
    if (deck && deck.indexOf("s:") === 0) {
      const sid = deck.slice(2);
      const ss = ((CourseRuntime.getCourse() || {}).sessions || []).find((x) => x.id === sid);
      return ss ? "جلسهٔ " + toFa(ss.num) + " — " + ss.title : sid;
    }
    return deck;
  }

  function _schedule(st, grade, now) {
    let ease = st.ease || 2.5,
      ivl = st.ivl || 0,
      reps = st.reps || 0,
      lapses = st.lapses || 0;
    let due;
    if (grade === 1) {
      lapses++;
      reps = 0;
      ivl = 0;
      ease = Math.max(1.3, ease - 0.2);
      due = now + 10 * MIN;
    } else if (grade === 2) {
      ease = Math.max(1.3, ease - 0.15);
      ivl = reps === 0 ? 1 : Math.max(1, Math.round(ivl * 1.2));
      reps++;
      due = now + ivl * DAY;
    } else if (grade === 3) {
      ivl = reps === 0 ? 1 : reps === 1 ? 3 : Math.max(2, Math.round(ivl * ease));
      reps++;
      due = now + ivl * DAY;
    } else {
      ease = Math.min(3.2, ease + 0.15);
      ivl = reps === 0 ? 4 : Math.max(3, Math.round(ivl * ease * 1.3));
      reps++;
      due = now + ivl * DAY;
    }
    return { ease, ivl, reps, lapses, due, last: now, seen: (st.seen || 0) + 1 };
  }

  function _fmtSpan(ms) {
    if (ms < 60 * MIN) return toFa(Math.max(1, Math.round(ms / MIN))) + " دقیقه";
    if (ms < DAY) return toFa(Math.round(ms / (60 * MIN))) + " ساعت";
    const d = Math.round(ms / DAY);
    if (d < 30) return toFa(d) + " روز";
    if (d < 365) return toFa(Math.round(d / 30)) + " ماه";
    return toFa(Math.round(d / 365)) + " سال";
  }

  function previews(st) {
    const now = Date.now();
    const base = st || {};
    const o = {};
    GRADES.forEach((g) => {
      o[g.k] = _fmtSpan(_schedule(base, g.n, now).due - now);
    });
    return o;
  }

  function _retention() {
    const evs = loadEvents()
      .filter((e) => e.t === "flash")
      .slice(-300);
    if (!evs.length) return null;
    const ok = evs.filter((e) => e.result === "good" || e.result === "easy").length;
    return Math.round((ok / evs.length) * 100);
  }
  function _todayReviewed() {
    const k = _todayKey();
    return loadEvents().filter((e) => e.t === "flash" && _dayKey(e.ts) === k).length;
  }
  function _isMastered(st) {
    return !!st && st.ivl >= 21 && st.reps >= 3;
  }

  function _deckStats(cards, state, now) {
    let due = 0,
      fresh = 0,
      mastered = 0,
      learning = 0;
    cards.forEach((c) => {
      const st = state.cards[c.id];
      if (!st) {
        fresh++;
        return;
      }
      if (st.due <= now) due++;
      if (_isMastered(st)) mastered++;
      else learning++;
    });
    return { total: cards.length, due, fresh, mastered, learning };
  }

  function _newAllowance(state) {
    const used = state.daily.day === _todayKey() ? state.daily.newN || 0 : 0;
    return Math.max(0, NEW_PER_DAY - used);
  }

  function _queueFor(deckId, cards, state) {
    const now = Date.now();
    const due = [],
      fresh = [];
    cards.forEach((c) => {
      if (c.disabled) return;
      if (deckId && deckId !== "all" && c.deck !== deckId) return;
      const st = state.cards[c.id];
      if (!st) fresh.push(c);
      else if (st.due <= now) due.push({ c, st });
    });
    due.sort((a, b) => a.st.due - b.st.due);
    return due.map((x) => x.c).concat(fresh.slice(0, _newAllowance(state)));
  }

  function _tex(src, display) {
    if (!src) return "";
    try {
      if (global.katex)
        return global.katex.renderToString(src, { displayMode: !!display, throwOnError: false });
    } catch (_) {}
    return escHtml(src);
  }

  function _backHTML(c) {
    if (c.kind === "formula") {
      const vars = (c.vars || [])
        .map((v) => {
          const sym = Array.isArray(v) ? v[0] : (v && v.s) || "";
          const desc = Array.isArray(v) ? v[1] : (v && v.d) || "";
          return `<li><span class="fc-sym">${_tex(sym, false)}</span><span>${escHtml(desc)}</span></li>`;
        })
        .join("");
      return `<div class="fc-formula">${_tex(c.tex, true)}</div>
        ${c.back ? `<p class="fc-body">${escHtml(c.back)}</p>` : ""}
        ${vars ? `<ul class="fc-vars">${vars}</ul>` : ""}`;
    }
    return `${c.back ? `<p class="fc-body">${escHtml(c.back)}</p>` : ""}
      ${c.pts && c.pts.length ? `<ul class="fc-pts">${c.pts.map((p) => `<li>${escHtml(p)}</li>`).join("")}</ul>` : ""}
      ${!c.back && !(c.pts && c.pts.length) ? `<p class="fc-body fc-empty">پاسخی برای این کارت ثبت نشده.</p>` : ""}`;
  }

  function _grade(card, gradeKey, study) {
    const g = GRADES.find((x) => x.k === gradeKey);
    if (!g) return;
    const state = _state();
    const now = Date.now();
    const today = _todayKey();
    if (state.daily.day !== today) state.daily = { day: today, newN: 0 };
    if (!state.cards[card.id]) state.daily.newN = (state.daily.newN || 0) + 1;
    state.cards[card.id] = _schedule(state.cards[card.id] || {}, g.n, now);
    saveReviewState(state);
    recordEvent("flash", { cardId: card.id, result: g.k, packId: CourseRuntime.getActivePackId() || "" });
    if (typeof updateProg === "function") updateProg();
  }

  let _study = null;

  function _studyHTML() {
    const s = _study;
    const c = s.queue[0];
    const done = s.total - s.queue.length;
    const pct = s.total ? Math.round((done / s.total) * 100) : 100;
    const deckName = s.deckId === "all" ? "همهٔ موعدها" : deckTitle(s.deckId);
    const pv = previews(_state().cards[c.id]);
    return `<div class="page fc-page fc-study">
      <header class="fc-study-head">
        <button type="button" class="btn ghost btn-sm" id="fcExit">${icon("chevRight")}<span>دسته‌ها</span></button>
        <div class="fc-study-title"><small>${escHtml(deckName)}</small><b>${c.kind === "formula" ? "فرمول" : "مفهوم"}</b></div>
        <span class="fc-count" dir="ltr">${toFa(done)} <i>/</i> ${toFa(s.total)}</span>
      </header>
      <div class="fc-bar" role="progressbar" aria-label="پیشرفت مرور" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${pct}"><i style="width:${pct}%"></i></div>
      <div class="fc-stage">
        <div class="fc-card${s.flipped ? " is-flipped" : ""}" id="fcCard" role="button" tabindex="0"
             aria-label="${s.flipped ? "پاسخ" : "نمایش پاسخ"}">
          <div class="fc-face fc-front">
            <span class="fc-tag">پرسش</span>
            <div class="fc-title">${c.kind === "formula" ? `<span class="fc-fname">${escHtml(c.front)}</span>` : escHtml(c.front)}</div>
            ${c.kind === "formula" ? `<div class="fc-formula-hint">فرمول را از حافظه بنویس، بعد برگردان</div>` : ""}
            <small class="fc-hint">برای دیدن پاسخ کلیک کنید یا Space را بزنید</small>
          </div>
          <div class="fc-face fc-back">
            <span class="fc-tag">پاسخ</span>
            <div class="fc-title fc-title--sm">${escHtml(c.front)}</div>
            <div class="fc-answer">${_backHTML(c)}</div>
            ${c.sess ? `<button type="button" class="fc-link" data-go-sess="${escHtml(c.sess)}">${icon("book")}<span>رفتن به جلسه</span></button>` : ""}
          </div>
        </div>
      </div>
      <div class="fc-grades${s.flipped ? " on" : ""}" ${s.flipped ? "" : 'aria-hidden="true"'}>
        ${GRADES.map(
          (
            g,
            i,
          ) => `<button type="button" class="fc-grade fc-grade--${g.c}" data-grade="${g.k}" ${s.flipped ? "" : 'tabindex="-1"'}>
          <span class="fc-grade-t">${g.t}</span>
          <span class="fc-grade-i">${escHtml(pv[g.k])}</span>
          <kbd>${toFa(i + 1)}</kbd>
        </button>`,
        ).join("")}
      </div>
      ${s.flipped ? "" : `<div class="fc-show"><button type="button" class="btn g" id="fcShow">نمایش پاسخ</button></div>`}
    </div>`;
  }

  function _renderStudy() {
    main.innerHTML = _studyHTML();
    katexifyText(main);
    _bindStudy();
  }

  function _flip() {
    if (!_study || _study.flipped) return;
    _study.flipped = true;
    const card = document.getElementById("fcCard");
    if (card) {
      card.classList.add("is-flipped");
      card.setAttribute("aria-label", "پاسخ");
    }
    const g = main.querySelector(".fc-grades");
    if (g) {
      g.classList.add("on");
      g.removeAttribute("aria-hidden");
      g.querySelectorAll(".fc-grade").forEach((b) => b.removeAttribute("tabindex"));
    }
    const sh = document.getElementById("fcShow");
    if (sh && sh.parentElement) sh.parentElement.remove();
  }

  function _answer(gradeKey) {
    if (!_study || !_study.flipped) return;
    const card = _study.queue[0];
    _grade(card, gradeKey, _study);
    _study.flipped = false;
    if (gradeKey === "again") {
      _study.queue.shift();
      _study.queue.splice(Math.min(3, _study.queue.length), 0, card);
      _study.againCount = (_study.againCount || 0) + 1;
    } else {
      _study.queue.shift();
    }
    if (!_study.queue.length) {
      _renderDone();
      return;
    }
    _renderStudy();
  }

  function _renderDone() {
    const st = _state();
    const cards = allCards();
    const stats = _deckStats(cards, st, Date.now());
    const s = _study;
    main.innerHTML = `<div class="page fc-page">
      <div class="fc-done">
        <div class="fc-done-ic">${icon("check")}</div>
        <h2>این دسته تمام شد</h2>
        <p>${toFa(s.total)} کارت مرور شد${s.againCount ? "؛ " + toFa(s.againCount) + " کارت دوباره آمد" : ""}. کارت‌های بعدی طبق زمان‌بندی در روزهای آینده برمی‌گردند.</p>
        <div class="fc-done-stats">
          <div><b>${toFa(stats.due)}</b><span>موعد امروز</span></div>
          <div><b>${toFa(stats.fresh)}</b><span>جدید</span></div>
          <div><b>${toFa(stats.mastered)}</b><span>تسلط‌یافته</span></div>
        </div>
        <div class="fc-done-actions">
          <button type="button" class="btn ghost" id="fcBackDecks">بازگشت به دسته‌ها</button>
          <button type="button" class="btn g" id="fcMore">مرور دسته‌ی بعدی</button>
        </div>
      </div>
    </div>`;
    _study = null;
    document.getElementById("fcBackDecks").onclick = () => pageReview();
    document.getElementById("fcMore").onclick = () => pageReview();
  }

  function _bindStudy() {
    const card = document.getElementById("fcCard");
    const exit = document.getElementById("fcExit");
    const show = document.getElementById("fcShow");
    if (card) {
      card.addEventListener("click", (e) => {
        if (e.target.closest("[data-go-sess]")) return;
        _flip();
      });
      card.addEventListener("keydown", (e) => {
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          _flip();
        }
      });
    }
    if (show) show.onclick = () => _flip();
    if (exit)
      exit.onclick = () => {
        _study = null;
        pageReview();
      };
    main.querySelectorAll("[data-grade]").forEach((b) => {
      b.onclick = (e) => {
        e.stopPropagation();
        _answer(b.dataset.grade);
      };
    });
    main.querySelectorAll("[data-go-sess]").forEach((b) => {
      b.onclick = (e) => {
        e.stopPropagation();
        _study = null;
        go("s/" + b.dataset.goSess);
      };
    });
  }

  if (!global._fcKeysBound) {
    global._fcKeysBound = true;
    document.addEventListener("keydown", (e) => {
      if (!_study) return;
      if (e.target && /INPUT|TEXTAREA|SELECT/.test(e.target.tagName)) return;
      if (e.key === "Escape") {
        _study = null;
        pageReview();
        return;
      }
      if (!_study.flipped && (e.key === " " || e.key === "Enter")) {
        e.preventDefault();
        _flip();
        return;
      }
      if (_study.flipped && ["1", "2", "3", "4"].indexOf(e.key) >= 0) {
        e.preventDefault();
        _answer(GRADES[+e.key - 1].k);
      }
    });
  }

  function _introHTML() {
    const s = _study;
    const deckName = s.deckId === "all" ? "همهٔ موعدها" : deckTitle(s.deckId);
    const concepts = s.queue.filter((x) => x.kind === "text").length;
    const formulas = s.queue.filter((x) => x.kind === "formula").length;
    const sessIds = [...new Set(s.queue.map((x) => x.sess).filter(Boolean))];
    const perCard = Number((CourseRuntime.getCourse() || {}).meta.reviewSecondsPerCard);
    const hasEstimate = Number.isFinite(perCard) && perCard > 0;
    const estMin = hasEstimate ? Math.max(1, Math.round((s.total * perCard) / 60)) : null;
    const sessLine = sessIds.length
      ? sessIds.length === 1
        ? (() => {
            const ss = ((CourseRuntime.getCourse() || {}).sessions || []).find(
              (x) => x.id === sessIds[0],
            );
            return ss ? "جلسهٔ " + toFa(ss.num) : "";
          })()
        : toFa(sessIds.length) + " جلسه"
      : "";
    return `<div class="page fc-page fc-intro-page">
      <div class="fc-intro">
        <div class="fc-intro-kicker">${icon("cards")} آماده‌سازی مرور</div>
        <h2 class="fc-intro-title">${escHtml(deckName)}</h2>
        <p class="fc-intro-desc">هر کارت یک پرسش است. ابتدا پاسخ را در ذهن خودت بساز، بعد برگردان و ارزیابی کن.</p>
        <div class="fc-intro-stats">
          <div><b>${toFa(s.total)}</b><span>کارت</span></div>
          <div><b>${toFa(concepts)}</b><span>مفهوم</span></div>
          <div><b>${toFa(formulas)}</b><span>فرمول</span></div>
          ${
            hasEstimate
              ? `<div><b>${toFa(estMin)}</b><span>دقیقهٔ تقریبی</span></div>`
              : sessLine
                ? `<div><b>${escHtml(sessLine)}</b><span>دامنه</span></div>`
                : ""
          }
        </div>
        <ol class="fc-intro-stages">
          <li><b>پرسش را بخوان</b><span>مفهوم یا عنوان فرمول روی کارت نمایش داده می‌شود</span></li>
          <li><b>پاسخ را بساز</b><span>قبل از برگردان، پاسخ را در ذهن خودت مرور کن</span></li>
          <li><b>ارزیابی کن</b><span>پس از برگردان، با یکی از چهار درجه ثبت کن</span></li>
        </ol>
        <div class="fc-intro-actions">
          <button type="button" class="btn ghost" id="fcIntroCancel">بازگشت</button>
          <button type="button" class="btn g" id="fcIntroStart">${icon("play")} شروع مرور</button>
        </div>
      </div>
    </div>`;
  }

  function _introHTML() {
    const s = _study;
    const deckName = s.deckId === "all" ? "همهٔ موعدها" : deckTitle(s.deckId);
    const concepts = s.queue.filter((x) => x.kind === "text").length;
    const formulas = s.queue.filter((x) => x.kind === "formula").length;
    const sessIds = [...new Set(s.queue.map((x) => x.sess).filter(Boolean))];
    const perCard = Number((CourseRuntime.getCourse() || {}).meta.reviewSecondsPerCard);
    const hasEstimate = Number.isFinite(perCard) && perCard > 0;
    const estMin = hasEstimate ? Math.max(1, Math.round((s.total * perCard) / 60)) : null;
    const sessLine = sessIds.length
      ? sessIds.length === 1
        ? (() => {
            const ss = ((CourseRuntime.getCourse() || {}).sessions || []).find(
              (x) => x.id === sessIds[0],
            );
            return ss ? "جلسهٔ " + toFa(ss.num) : "";
          })()
        : toFa(sessIds.length) + " جلسه"
      : "";
    return `<div class="page fc-page fc-intro-page">
      <div class="fc-intro">
        <div class="fc-intro-kicker">${icon("cards")} آماده‌سازی مرور</div>
        <h2 class="fc-intro-title">${escHtml(deckName)}</h2>
        <p class="fc-intro-desc">هر کارت یک پرسش است. ابتدا پاسخ را در ذهن خودت بساز، بعد برگردان و ارزیابی کن.</p>
        <div class="fc-intro-stats">
          <div><b>${toFa(s.total)}</b><span>کارت</span></div>
          <div><b>${toFa(concepts)}</b><span>مفهوم</span></div>
          <div><b>${toFa(formulas)}</b><span>فرمول</span></div>
          ${
            hasEstimate
              ? `<div><b>${toFa(estMin)}</b><span>دقیقهٔ تقریبی</span></div>`
              : sessLine
                ? `<div><b>${escHtml(sessLine)}</b><span>دامنه</span></div>`
                : ""
          }
        </div>
        <ol class="fc-intro-stages">
          <li><b>پرسش را بخوان</b><span>مفهوم یا عنوان فرمول روی کارت نمایش داده می‌شود</span></li>
          <li><b>پاسخ را بساز</b><span>قبل از برگردان، پاسخ را در ذهن خودت مرور کن</span></li>
          <li><b>ارزیابی کن</b><span>پس از برگردان، با یکی از چهار درجه ثبت کن</span></li>
        </ol>
        <div class="fc-intro-actions">
          <button type="button" class="btn ghost" id="fcIntroCancel">بازگشت</button>
          <button type="button" class="btn g" id="fcIntroStart">${icon("play")} شروع مرور</button>
        </div>
      </div>
    </div>`;
  }

  function _renderIntro() {
    main.innerHTML = _introHTML();
    const cancel = document.getElementById("fcIntroCancel");
    const start = document.getElementById("fcIntroStart");
    if (cancel)
      cancel.onclick = () => {
        _study = null;
        pageReview();
      };
    if (start)
      start.onclick = () => {
        if (!_study) return;
        _renderStudy();
      };
  }

  function startStudy(deckId) {
    const cards = allCards();
    if (deckId && deckId !== "all") {
      const same = cards.filter((c) => c.deck === deckId);
      if (same.length && same.every((c) => c.disabled)) {
        if (typeof toast === "function") toast("این جلسه از مرور خارج شده است");
        return;
      }
    }
    const queue = _queueFor(deckId, cards, _state());
    if (!queue.length) {
      if (typeof toast === "function") toast("در این دسته کارتی برای امروز نیست");
      return;
    }
    _study = { deckId, queue, total: queue.length, flipped: false, againCount: 0 };
    _renderIntro();
    window.scrollTo(0, 0);
  }
  let _filter = "all";
  let _formOpen = false;

  function _summaryHTML(cards, st) {
    const now = Date.now();
    const sum = _deckStats(
      cards.filter((c) => !c.disabled),
      st,
      now,
    );
    const ret = _retention();
    return `<div class="fc-summary">
      <div class="fc-sum fc-sum--due"><b>${toFa(sum.due)}</b><span>موعد امروز</span></div>
      <div class="fc-sum"><b>${toFa(Math.min(sum.fresh, _newAllowance(st)))}</b><span>کارت جدید امروز</span></div>
      <div class="fc-sum"><b>${toFa(_todayReviewed())}</b><span>مرورشده امروز</span></div>
      <div class="fc-sum"><b>${ret == null ? "—" : toFa(ret) + "٪"}</b><span>یادآوری درست</span></div>
      <button type="button" class="btn g fc-start-all" id="fcStartAll" ${sum.due + Math.min(sum.fresh, _newAllowance(st)) ? "" : "disabled"}>
        ${icon("cards")}<span>مرور همهٔ موعدها</span>
      </button>
    </div>`;
  }

  function _deckCardHTML(d, st, now) {
    const s = _deckStats(d.cards, st, now);
    const pct = s.total ? Math.round((s.mastered / s.total) * 100) : 0;
    const dis = !!d.disabled;
    const ready = dis ? 0 : s.due + Math.min(s.fresh, _newAllowance(st));
    return `<article class="fc-deck${ready ? "" : " is-idle"}${dis ? " is-disabled" : ""}">
      <header class="fc-deck-head">
        <b>${escHtml(d.title)}</b>
        <span class="fc-deck-n">${toFa(s.total)} کارت</span>
      </header>
      <div class="fc-deck-badges">
        ${dis ? `<span class="fc-badge fc-badge--off">غیر فعال</span>` : ""}
        ${!dis && s.due ? `<span class="fc-badge fc-badge--due">${toFa(s.due)} موعد</span>` : ""}
        ${!dis && s.fresh ? `<span class="fc-badge fc-badge--new">${toFa(s.fresh)} جدید</span>` : ""}
        ${!dis && !ready ? `<span class="fc-badge">همه مرور شده</span>` : ""}
      </div>
      <div class="fc-deck-prog" title="تسلط‌یافته"><i style="width:${pct}%"></i></div>
      <div class="fc-deck-foot">
        <span>${dis ? "این جلسه از مرور خارج شده است" : toFa(pct) + "٪ تسلط · " + toFa(s.learning) + " در حال یادگیری"}</span>
        <button type="button" class="btn ${ready ? "g" : "ghost"} btn-sm" data-deck="${escHtml(d.id)}" ${ready ? "" : "disabled"}>
          ${dis ? "غیر فعال" : ready ? "مرور" : "—"}
        </button>
      </div>
    </article>`;
  }

  function _userListHTML(cards) {
    const mine = _loadUser();
    if (!mine.length)
      return `<p class="fc-empty-note">هنوز کارتی نساخته‌اید. بالا را باز کنید و اولین کارت را بسازید.</p>`;
    return `<ul class="fc-ulist">${mine
      .map(
        (u) => `<li>
      <div><b>${escHtml(u.front)}</b><span>${escHtml(u.back)}</span></div>
      <button type="button" class="fc-del" data-del="${escHtml(u.id)}" aria-label="حذف کارت">${icon("x")}</button>
    </li>`,
      )
      .join("")}</ul>`;
  }

  function _formHTML(decks) {
    const opts = decks
      .filter((d) => d.id !== "pack")
      .map((d) => `<option value="${escHtml(d.id)}">${escHtml(d.title)}</option>`)
      .join("");
    return `<form class="fc-form" id="fcForm" novalidate>
      <label class="fc-field"><span>دسته</span>
        <select class="set-input" id="fcDeck"><option value="user">کارت‌های من</option>${opts}</select></label>
      <label class="fc-field"><span>پرسش (جلو)</span>
        <input class="set-input" id="fcFront" maxlength="200" placeholder="مثلاً: قانون اسنل" /></label>
      <label class="fc-field fc-field--wide"><span>پاسخ (پشت)</span>
        <textarea class="set-input" id="fcBack" rows="3" maxlength="800" placeholder="پاسخ را کوتاه و دقیق بنویس"></textarea></label>
      <div class="fc-form-actions"><small id="fcFormErr" hidden></small><button type="submit" class="btn g">افزودن کارت</button></div>
    </form>`;
  }

  function _bindPage(decks) {
    const all = document.getElementById("fcStartAll");
    if (all) all.onclick = () => startStudy("all");
    main.querySelectorAll("[data-filter]").forEach((b) => {
      b.onclick = () => {
        _filter = b.dataset.filter;
        _renderFcBody();
      };
    });
    main.querySelectorAll("[data-deck]").forEach((b) => {
      b.onclick = () => startStudy(b.dataset.deck);
    });
    const toggle = document.getElementById("fcToggleForm");
    if (toggle)
      toggle.onclick = () => {
        _formOpen = !_formOpen;
        _renderFcBody();
      };
    const form = document.getElementById("fcForm");
    if (form) {
      form.onsubmit = (e) => {
        e.preventDefault();
        const front = document.getElementById("fcFront").value.trim();
        const back = document.getElementById("fcBack").value.trim();
        const deck = document.getElementById("fcDeck").value;
        const err = document.getElementById("fcFormErr");
        if (!front) {
          err.hidden = false;
          err.textContent = "پرسش خالی است";
          return;
        }
        const mine = _loadUser();
        mine.push({
          id: "u:" + Date.now() + ":" + Math.floor(Math.random() * 999),
          front,
          back,
          deck,
        });
        _saveUser(mine);
        _formOpen = true;
        if (typeof toast === "function") toast("کارت ساخته شد", "ok");
        _renderFcBody();
      };
    }
    main.querySelectorAll("[data-del]").forEach((b) => {
      b.onclick = () => {
        _saveUser(_loadUser().filter((u) => u.id !== b.dataset.del));
        const st = _state();
        delete st.cards[b.dataset.del];
        saveReviewState(st);
        _renderFcBody();
      };
    });
  }

  function pageReview() {
    _study = null;
    const cards = allCards();
    if (!cards.length) {
      main.innerHTML = `<div class="page fc-page"><div class="fc-done"><h2>مرور</h2>
        <p>این درس هنوز کارتی برای مرور ندارد.</p></div></div>`;
      return;
    }
    const st = _state();
    const now = Date.now();
    const decks = [];
    const byId = new Map();
    cards.forEach((c) => {
      if (!byId.has(c.deck)) {
        const d = { id: c.deck, title: deckTitle(c.deck), cards: [] };
        byId.set(c.deck, d);
        decks.push(d);
      }
      byId.get(c.deck).cards.push(c);
    });
    decks.sort((a, b) => (a.id === "pack" ? 1 : 0) - (b.id === "pack" ? 1 : 0));

    const shown = decks.filter((d) => {
      const s = _deckStats(d.cards, st, now);
      if (_filter === "due") return s.due > 0;
      if (_filter === "new") return s.fresh > 0;
      if (_filter === "mastered") return s.mastered > 0 && s.mastered === s.total;
      return true;
    });
    const chip = (k, t) =>
      `<button type="button" class="fc-chip${_filter === k ? " on" : ""}" data-filter="${k}" aria-pressed="${_filter === k}">${t}</button>`;

    main.innerHTML = `<div class="page fc-page">
      <header class="fc-hero">
        <div>
          <span class="fc-kicker">${icon("cards")}مرور فلش‌کارت</span>
          <h1 class="fc-h1">مرور با زمان‌بندی</h1>
          <p>هر کارت بعد از هر پاسخ در زمان مناسب خودش برمی‌گردد. کارت‌های سخت زودتر و کارت‌های آسان دیرتر می‌آیند.</p>
        </div>
      </header>
      <div id="fc-body"></div>
    </div>`;
    _renderFcBody();
  }

  function _renderFcBody() {
    const body = document.getElementById("fc-body");
    if (!body) return;
    const cards = allCards();
    if (!cards.length) {
      body.innerHTML = `<p class="fc-empty-note">این درس هنوز کارتی برای مرور ندارد.</p>`;
      return;
    }
    const st = _state();
    const now = Date.now();
    const decks = [];
    const byId = new Map();
    cards.forEach((c) => {
      if (!byId.has(c.deck)) {
        const d = { id: c.deck, title: deckTitle(c.deck), cards: [], disabled: true };
        byId.set(c.deck, d);
        decks.push(d);
      }
      const d = byId.get(c.deck);
      d.cards.push(c);
      if (!c.disabled) d.disabled = false;
    });
    decks.sort((a, b) => (a.id === "pack" ? 1 : 0) - (b.id === "pack" ? 1 : 0));
    const shown = decks.filter((d) => {
      if (d.disabled) return _filter === "all";
      const s = _deckStats(d.cards, st, now);
      if (_filter === "due") return s.due > 0;
      if (_filter === "new") return s.fresh > 0;
      if (_filter === "mastered") return s.mastered > 0 && s.mastered === s.total;
      return true;
    });
    const chip = (k, t) =>
      `<button type="button" class="fc-chip${_filter === k ? " on" : ""}" data-filter="${k}" aria-pressed="${_filter === k}">${t}</button>`;
    body.innerHTML = `
      ${_summaryHTML(cards, st)}
      <div class="fc-toolbar">
        <div class="fc-chips" role="group" aria-label="فیلتر دسته‌ها">
          ${chip("all", "همه")}${chip("due", "موعد دارند")}${chip("new", "جدیدها")}${chip("mastered", "تسلط‌یافته")}
        </div>
        <button type="button" class="btn ghost btn-sm" id="fcToggleForm" aria-expanded="${_formOpen}">
          ${icon("plus")}<span>${_formOpen ? "بستن" : "کارت جدید"}</span>
        </button>
      </div>
      ${_formOpen ? `<section class="fc-create">${_formHTML(decks)}${_userListHTML(cards)}</section>` : ""}
      <div class="fc-decks">
        ${shown.length ? shown.map((d) => _deckCardHTML(d, st, now)).join("") : `<p class="fc-empty-note">دسته‌ای با این فیلتر نیست.</p>`}
      </div>`;
    katexifyText(body);
    _bindPage(decks);
  }

  global.pageReview = pageReview;
  global._renderFcBody = _renderFcBody;
  global.getReviewCards = function () {
    return allCards().filter((c) => !c.disabled);
  };
  global.fcStartStudy = startStudy;
})(typeof window !== "undefined" ? window : globalThis);
