// رجیستری ویجت‌ها (Phase 5.8): has، get، mount، cleanup، remount.
// createWidgetRegistry منبع ویجت‌ها را تزریق می‌گیرد تا بدون DOM و بدون global قابل تست باشد.
// نمونهٔ پیش‌فرض، ویجت‌های پک فعال را از CourseRuntime می‌خواند و در مرورگر global‌های قدیمی را نصب می‌کند.

// زمینهٔ mount: میزبان هر داده‌ای می‌تواند بفرستد (فیلدهای اضافه مجازند).
export type WidgetContext = Record<string, unknown>;

export interface Widget {
  title?: string;
  desc?: string;
  sess?: string[];
  mount?: (box: HTMLElement, context: WidgetContext) => void;
  unmount?: (box: HTMLElement, context: WidgetContext) => void;
  [key: string]: unknown;
}

/** کلید ویجت → تعریف ویجت (همان شکل ویجت‌های پک). */
export type WidgetMap = Record<string, Widget>;

export interface WidgetRegistryApi {
  has(key: string): boolean;
  get(key: string): Widget | null;
  mount(key: string, box: HTMLElement | null | undefined, context?: WidgetContext | null): boolean;
  cleanup(): void;
  remount(): void;
}

interface MountRecord {
  key: string;
  box: HTMLElement;
  context: WidgetContext;
  /** نمونه‌ای که روی box mount شده؛ unmount همیشه روی همان اجرا می‌شود، نه روی نسخهٔ فعلی منبع. */
  widget: Widget;
}

/** حداقل سطحی از window که این ماژول لازم دارد. */
export interface WidgetHost {
  WidgetRegistry?: WidgetRegistryApi;
  mountWidget?: WidgetRegistryApi["mount"];
  cleanupWidgets?: () => void;
  addEventListener?: (type: string, fn: () => void) => void;
}

export function createWidgetRegistry(source: () => WidgetMap): WidgetRegistryApi {
  const mounts: MountRecord[] = [];

  function get(key: string): Widget | null {
    const map = source() || {};
    return Object.prototype.hasOwnProperty.call(map, key) ? map[key] || null : null;
  }

  function has(key: string): boolean {
    return get(key) !== null;
  }

  function mount(
    key: string,
    box: HTMLElement | null | undefined,
    context?: WidgetContext | null,
  ): boolean {
    const widget = get(key);
    if (!widget || typeof widget.mount !== "function" || !box) return false;
    // هر box فقط یک ویجت دارد: قبلی را پاک می‌کنیم.
    for (let i = mounts.length - 1; i >= 0; i--) {
      if (mounts[i]!.box !== box) continue;
      const prev = mounts[i]!.widget;
      try {
        if (typeof prev.unmount === "function") prev.unmount(box, mounts[i]!.context);
      } catch {}
      mounts.splice(i, 1);
    }
    mounts.push({ key, box, context: context || {}, widget });
    try {
      widget.mount(box, context || {});
      return true;
    } catch {
      mounts.splice(mounts.length - 1, 1);
      try {
        box.innerHTML = "";
      } catch {}
      return false;
    }
  }

  function cleanup(): void {
    mounts.forEach((m) => {
      try {
        if (typeof m.widget.unmount === "function") m.widget.unmount(m.box, m.context);
      } catch {}
      try {
        if (m.box) m.box.innerHTML = "";
      } catch {}
    });
    mounts.length = 0;
  }

  function remount(): void {
    const current = mounts.slice();
    current.forEach((m) => {
      const next = get(m.key);
      if (!next || !m.box) return;
      try {
        if (typeof m.widget.unmount === "function") m.widget.unmount(m.box, m.context);
      } catch {}
      try {
        m.box.innerHTML = "";
      } catch {}
      m.widget = next;
      try {
        next.mount?.(m.box, m.context || {});
      } catch {}
    });
  }

  return Object.freeze({ has, get, mount, cleanup, remount });
}

/** ویجت‌های پک فعال (CourseRuntime). بدون CourseRuntime خالی است. */
export function courseWidgets(): WidgetMap {
  const runtime = (globalThis as { CourseRuntime?: { getWidgets?: () => unknown } }).CourseRuntime;
  return (runtime?.getWidgets?.() as WidgetMap | undefined) || {};
}

export const defaultWidgetRegistry: WidgetRegistryApi = createWidgetRegistry(courseWidgets);

/** نصب global‌های قدیمی و اتصال به تغییر تم. */
export function installWidgetRegistry(host: WidgetHost, api: WidgetRegistryApi): void {
  host.WidgetRegistry = api;
  host.mountWidget = (key, box, context) => api.mount(key, box, context);
  host.cleanupWidgets = () => api.cleanup();
  if (typeof host.addEventListener === "function") {
    host.addEventListener("lector:theme", () => api.remount());
  }
}

if (typeof window !== "undefined") {
  installWidgetRegistry(window as unknown as WidgetHost, defaultWidgetRegistry);
}
