(function () {
  "use strict";
  const K = window.PackWidgetKit;
  const wpal = K.wpal;
  let P = wpal();
  globalThis.addEventListener("lector:theme", () => {
    P = wpal();
  });
  const wl2rgb = window.PackWidgetKit.wl2rgb;
  const W = {
    title: "تداخل در لایه‌های نازک",
    desc: "ضخامت، ضرایب شکست و زاویهٔ تابش را تغییر دهید؛ شرط سازنده/ویرانگر، پرش فاز π در بازتاب، و رنگ بازتابی نور سفید را زنده ببینید.",
    sess: ["s18"],
    mount(box) {
      box.innerHTML = `<div class="film-widget">
  <div class="film-left">
    <div class="film-presets">
      <button data-p="soap" class="on">حباب صابون</button>
      <button data-p="ar">پوشش AR</button>
      <button data-p="oil">لکهٔ روغن</button>
    </div>
    <div class="wstage"><canvas width="700" height="360"></canvas></div>
  </div>
  <div class="film-controls">
    <div class="ctls"></div>
  </div>
  <div class="film-info"></div>
  <div class="film-props"></div>
</div>`;

      const cv = box.querySelector("canvas");
      const ctx = setupHD(cv, 700, 440);
      const ct = box.querySelector(".ctls");
      const info = box.querySelector(".film-info");

      let t_nm = 300;
      let n_f = 1.33;
      let n_0 = 1.0;
      let n_s = 1.0;
      let theta_deg = 30;

      const CW = 700,
        CH = 360;
      const TOP_Y = 180;
      const CX = 350;
      const L = 130;
      const REF_LAMBDA = 550;

      const ctlT = ctl(ct, "ضخامت لایه t", 20, 1000, 5, t_nm, "nm", (v) => {
        t_nm = v;
        draw();
      });
      const ctlNf = ctl(ct, "ضریب شکست لایه n_f", 1.0, 2.5, 0.01, n_f, "", (v) => {
        n_f = v;
        draw();
      });
      const ctlN0 = ctl(ct, "محیط بالای لایه n₀", 1.0, 2.0, 0.01, n_0, "", (v) => {
        n_0 = v;
        draw();
      });
      const ctlNs = ctl(ct, "محیط زیر لایه n_s", 1.0, 2.0, 0.01, n_s, "", (v) => {
        n_s = v;
        draw();
      });
      const ctlTheta = ctl(ct, "زاویهٔ تابش θ₁", 0, 85, 1, theta_deg, "°", (v) => {
        theta_deg = v;
        draw();
      });

      const presetWrap = box.querySelector(".film-presets");

      const PRESETS = {
        soap: { n_0: 1.0, n_f: 1.33, n_s: 1.0, t_nm: 300, theta_deg: 30 },
        ar: { n_0: 1.0, n_f: 1.23, n_s: 1.5, t_nm: 112, theta_deg: 0 },
        oil: { n_0: 1.0, n_f: 1.47, n_s: 1.33, t_nm: 400, theta_deg: 30 },
      };

      function applyPreset(key) {
        const p = PRESETS[key];
        if (!p) return;
        n_0 = p.n_0;
        n_f = p.n_f;
        n_s = p.n_s;
        t_nm = p.t_nm;
        theta_deg = p.theta_deg;
        [
          [ctlT, t_nm],
          [ctlNf, n_f],
          [ctlN0, n_0],
          [ctlNs, n_s],
          [ctlTheta, theta_deg],
        ].forEach(([inp, v]) => {
          inp.value = v;
          inp.dispatchEvent(new Event("input"));
        });
      }

      presetWrap.querySelectorAll("button").forEach((b) => {
        b.onclick = () => {
          presetWrap.querySelectorAll("button").forEach((x) => x.classList.toggle("on", x === b));
          applyPreset(b.dataset.p);
        };
      });

      function thetaT() {
        const th_i = (theta_deg * Math.PI) / 180;
        const s = (n_0 / n_f) * Math.sin(th_i);
        if (Math.abs(s) > 1) return null;
        return Math.asin(s);
      }

      function filmPx() {
        return 30 + (t_nm / 1000) * 140;
      }

      function reflectedIntensity(lambda_nm) {
        const theta_t = thetaT();
        if (theta_t === null) return 1;
        const cosT = Math.cos(theta_t);
        const r01 = (n_0 - n_f) / (n_0 + n_f);
        const r12 = (n_f - n_s) / (n_f + n_s);
        const t01 = (2 * n_0) / (n_0 + n_f);
        const t10 = (2 * n_f) / (n_0 + n_f);
        const phi = (4 * Math.PI * n_f * t_nm * cosT) / lambda_nm;
        const amp2 = t01 * t10 * r12;
        const I = r01 * r01 + amp2 * amp2 + 2 * r01 * amp2 * Math.cos(phi);
        return Math.max(0, Math.min(1, I));
      }

      function whiteLightColor() {
        let sr = 0,
          sg = 0,
          sb = 0;
        for (let wl = 390; wl <= 700; wl += 5) {
          const I = reflectedIntensity(wl);
          const [r, g, b] = wl2rgb(wl);
          sr += I * r;
          sg += I * g;
          sb += I * b;
        }
        const maxC = Math.max(sr, sg, sb, 1);
        const k = 235 / maxC;
        return {
          r: Math.round(Math.min(255, sr * k)),
          g: Math.round(Math.min(255, sg * k)),
          b: Math.round(Math.min(255, sb * k)),
        };
      }

      function drawArrow(x1, y1, x2, y2, color) {
        const angle = Math.atan2(y2 - y1, x2 - x1);
        const size = 9;
        ctx.fillStyle = color;
        ctx.beginPath();
        ctx.moveTo(x2, y2);
        ctx.lineTo(x2 - size * Math.cos(angle - 0.4), y2 - size * Math.sin(angle - 0.4));
        ctx.lineTo(x2 - size * Math.cos(angle + 0.4), y2 - size * Math.sin(angle + 0.4));
        ctx.fill();
      }

      function draw() {
        P = wpal();
        ctx.clearRect(0, 0, CW, CH);
        ctx.fillStyle = P.bg;
        ctx.fillRect(0, 0, CW, CH);

        const theta_t = thetaT();
        const th_i = (theta_deg * Math.PI) / 180;
        const sinI = Math.sin(th_i);
        const cosI = Math.cos(th_i);

        const t_px = filmPx();
        const BOT_Y = TOP_Y + t_px;

        const tanT = theta_t !== null ? Math.tan(theta_t) : 0;
        const dx_film = t_px * tanT;

        const r01 = (n_0 - n_f) / (n_0 + n_f);
        const r12 = (n_f - n_s) / (n_f + n_s);
        const alphaRay1 = Math.min(0.95, Math.abs(r01) * 8);
        const alphaRay2 = Math.min(0.95, Math.abs(r12) * 8);

        ctx.fillStyle = `rgba(140,160,255,${0.03 + n_0 * 0.03})`;
        ctx.fillRect(0, 0, CW, TOP_Y);
        ctx.fillStyle = `rgba(120,180,255,${0.06 + Math.min(1, (n_f - 1) * 0.4) * 0.12})`;
        ctx.fillRect(0, TOP_Y, CW, t_px);
        ctx.fillStyle = `rgba(100,120,180,${0.04 + n_s * 0.04})`;
        ctx.fillRect(0, BOT_Y, CW, CH - BOT_Y);

        ctx.strokeStyle = "#8fa3d9";
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(0, TOP_Y);
        ctx.lineTo(CW, TOP_Y);
        ctx.stroke();
        ctx.beginPath();
        ctx.moveTo(0, BOT_Y);
        ctx.lineTo(CW, BOT_Y);
        ctx.stroke();

        ctx.font = "11px Vazirmatn";
        ctx.textAlign = "left";
        ctx.fillStyle = P.dim;
        ctx.fillText(`n₀ = ${n_0.toFixed(2)}`, 8, 18);
        ctx.fillText(`n_f = ${n_f.toFixed(2)}  ·  t = ${t_nm} nm`, 8, TOP_Y + t_px / 2 + 4);
        ctx.fillText(`n_s = ${n_s.toFixed(2)}`, 8, BOT_Y + 18);

        ctx.strokeStyle = "rgba(140,160,255,.35)";
        ctx.lineWidth = 1;
        ctx.setLineDash([5, 5]);
        ctx.beginPath();
        ctx.moveTo(CX, TOP_Y - 110);
        ctx.lineTo(CX, BOT_Y + 30);
        ctx.stroke();
        ctx.setLineDash([]);

        const incStartX = CX - L * sinI;
        const incStartY = TOP_Y - L * cosI;
        ctx.strokeStyle = "#fcd34d";
        ctx.lineWidth = 2.5;
        ctx.beginPath();
        ctx.moveTo(incStartX, incStartY);
        ctx.lineTo(CX, TOP_Y);
        ctx.stroke();
        drawArrow(incStartX, incStartY, CX, TOP_Y, "#fcd34d");

        const ref1EndX = CX + L * sinI;
        const ref1EndY = TOP_Y - L * cosI;
        ctx.globalAlpha = alphaRay1;
        ctx.strokeStyle = "#fb7185";
        ctx.lineWidth = 2.5;
        ctx.beginPath();
        ctx.moveTo(CX, TOP_Y);
        ctx.lineTo(ref1EndX, ref1EndY);
        ctx.stroke();
        drawArrow(CX, TOP_Y, ref1EndX, ref1EndY, "#fb7185");
        ctx.globalAlpha = 1;

        const botHitX = CX + dx_film;
        const botHitY = BOT_Y;
        ctx.strokeStyle = "#38bdf8";
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(CX, TOP_Y);
        ctx.lineTo(botHitX, botHitY);
        ctx.stroke();

        const exitX = botHitX + dx_film;
        const exitY = TOP_Y;
        ctx.strokeStyle = "#38bdf8";
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(botHitX, botHitY);
        ctx.lineTo(exitX, exitY);
        ctx.stroke();

        const ref2EndX = exitX + L * sinI;
        const ref2EndY = TOP_Y - L * cosI;
        ctx.globalAlpha = alphaRay2;
        ctx.strokeStyle = "#34d399";
        ctx.lineWidth = 2.5;
        ctx.beginPath();
        ctx.moveTo(exitX, exitY);
        ctx.lineTo(ref2EndX, ref2EndY);
        ctx.stroke();
        drawArrow(exitX, exitY, ref2EndX, ref2EndY, "#34d399");
        ctx.globalAlpha = 1;

        ctx.fillStyle = "#fb7185";
        ctx.beginPath();
        ctx.arc(CX, TOP_Y, 5, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = "#38bdf8";
        ctx.beginPath();
        ctx.arc(botHitX, botHitY, 5, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = "#34d399";
        ctx.beginPath();
        ctx.arc(exitX, TOP_Y, 5, 0, Math.PI * 2);
        ctx.fill();

        const topShift = n_f > n_0;
        const botShift = n_s > n_f;
        const relativeShift = topShift !== botShift;

        ctx.font = "bold 12px Vazirmatn";
        ctx.textAlign = "center";
        ctx.fillStyle = topShift ? "#fb7185" : P.dim;
        ctx.fillText(topShift ? "Δφ₁ = π" : "Δφ₁ = 0", CX - 45, TOP_Y + 20);
        ctx.fillStyle = botShift ? "#38bdf8" : P.dim;
        ctx.fillText(botShift ? "Δφ₂ = π" : "Δφ₂ = 0", botHitX + 45, botHitY - 15);

        ctx.font = "11px Vazirmatn";
        ctx.fillStyle = "#fcd34d";
        ctx.textAlign = "right";
        ctx.fillText(`θ₁ = ${theta_deg}°`, CX - 8, TOP_Y - 42);
        if (theta_t !== null) {
          ctx.fillStyle = "#38bdf8";
          ctx.textAlign = "left";
          ctx.fillText(`θ₂ = ${((theta_t * 180) / Math.PI).toFixed(1)}°`, CX + 8, TOP_Y + 44);
        }

        ctx.font = "11px Vazirmatn";
        ctx.textAlign = "left";
        const legendX = CW - 230;
        const legendY = 20;
        ctx.fillStyle = "#fb7185";
        ctx.fillRect(legendX, legendY - 4, 14, 3);
        ctx.fillStyle = P.txt;
        ctx.fillText("پرتو ۱ — بازتاب از سطح بالا", legendX + 20, legendY + 2);
        ctx.fillStyle = "#34d399";
        ctx.fillRect(legendX, legendY + 16 - 4, 14, 3);
        ctx.fillStyle = P.txt;
        ctx.fillText("پرتو ۲ — بازتاب از سطح پایین", legendX + 20, legendY + 18);

        const cosT = theta_t !== null ? Math.cos(theta_t) : 1;
        const pathNm = 2 * n_f * t_nm * cosT;
        const phiRef =
          (4 * Math.PI * n_f * t_nm * cosT) / REF_LAMBDA + (relativeShift ? Math.PI : 0);
        const orderM = phiRef / (2 * Math.PI);
        const mFrac = orderM - Math.floor(orderM);
        const nearInt = mFrac < 0.12 || mFrac > 0.88;

        const wlColor = whiteLightColor();
        const colorStyle =
          `display:inline-block;width:44px;height:16px;border-radius:5px;` +
          `vertical-align:middle;border:1px solid var(--border-subtle);` +
          `background:rgb(${wlColor.r},${wlColor.g},${wlColor.b})`;

        const conditionText = relativeShift ? "2n_f t cosθ₂ = (m+½)λ" : "2n_f t cosθ₂ = mλ";

        info.innerHTML = `
  <div class="fi-cell">
  <span class="fi-k">راه نوری</span>
  <span class="fi-v">${toFa(pathNm.toFixed(0))} nm</span>
  </div>
  <div class="fi-cell">
  <span class="fi-k">پرش نسبی فاز</span>
  <span class="fi-v">${relativeShift ? "π" : "۰"}</span>
  </div>
  <div class="fi-cell">
  <span class="fi-k">مرتبه m در ۵۵۰nm</span>
  <span class="fi-v">${toFa(orderM.toFixed(2))}</span>
  </div>
  <div class="fi-cell">
  <span class="fi-k">رنگ بازتابی</span>
  <span class="fi-swatch" style="background:rgb(${wlColor.r},${wlColor.g},${wlColor.b})"></span>
  </div>`;

        const propsEl = box.querySelector(".film-props");
        if (propsEl) {
          propsEl.innerHTML =
            `<span class="badge ${relativeShift ? "b-ros" : "b-blu"}">` +
            `${relativeShift ? "پرش نسبی π" : "بدون پرش نسبی"}</span>` +
            `<span class="badge ${nearInt ? "b-grn" : "b-amb"}">` +
            `${nearInt ? "سازنده در ۵۵۰nm" : "بینابینی"}</span>`;
        }

        if (window.renderMathInElement) {
          renderMathInElement(info, {
            delimiters: [{ left: "$", right: "$", display: false }],
            throwOnError: false,
          });
        }
      }

      draw();
    },
  };
  CourseRuntime.registerPackSource("optics", { widgets: { film: W } });
})();
