import { escHtml } from "../../core.js";
import { icon } from "../../ui/components/icons.js";

interface ProblemStep {
  title?: string;
  body?: string;
  html?: string;
  text?: string;
}

interface StructuredProblem {
  id: string;
  section?: string;
  title?: string;
  statement?: string;
  statementEn?: string;
  data?: string;
  answer?: string;
  answerSpec?: unknown;
  steps?: ProblemStep[];
}

declare global {
  var hasStructuredProblems: () => boolean;
  var renderProblemObject: (p: StructuredProblem) => string;
  var problemsForSection: (secKey: string) => string;
}

(function initProblemRenderer(global: typeof globalThis) {
  "use strict";
  function hasStructuredProblems(): boolean {
    return CourseRuntime.getProblems().length > 0;
  }

  function renderProblemObject(p: StructuredProblem): string {
    const steps = (p.steps || [])
      .map((st) => {
        const t = st.title ? `<p><b>${escHtml(st.title)}</b></p>` : "";
        const body = st.body != null ? st.body : st.html != null ? st.html : escHtml(st.text || "");
        return t + (body ? `<div>${body}</div>` : "");
      })
      .join("");
    const sol = steps
      ? `<details class="sol"><summary>${icon("pencil")} مشاهدهٔ حل گام‌به‌گام</summary><div class="sol-body">${steps}</div></details>`
      : "";
    const hasSpec = !!p.answerSpec;
    const ans = !p.answer
      ? ""
      : hasSpec
        ? `<details class="sol pr-reveal"><summary>نمایش پاسخ</summary><div class="note" style="margin-top:8px"><b>پاسخ:</b> ${p.answer}</div></details>`
        : `<div class="note" style="margin-top:8px"><b>پاسخ:</b> ${p.answer}</div>`;
    const slot = hasSpec ? `<div class="practice-slot" data-pid="${escHtml(p.id)}"></div>` : "";
    const en = p.statementEn ? `<p class="en">${p.statementEn}</p>` : "";
    const data = p.data ? `<br><b>داده‌ها:</b> ${p.data}` : "";
    return `<article class="card" id="${escHtml(p.id)}"><h3>${escHtml(p.title)}</h3><div class="meta-box"><b>صورت مسئله:</b> ${p.statement || ""}${data}</div>${en}${slot}${sol}${ans}</article>`;
  }

  function problemsForSection(secKey: string): string {
    if (hasStructuredProblems()) {
      return (CourseRuntime.getProblems() as StructuredProblem[])
        .filter((p) => p.section === secKey)
        .map(renderProblemObject)
        .join("");
    }
    const legacy = CourseRuntime.getProblemHtml();
    if (!legacy || typeof legacy !== "object") return "";
    // legacy problemHtml values are HTML strings (pack contract)
    return (legacy[secKey] || legacy[String(secKey)] || "") as string;
  }

  global.hasStructuredProblems = hasStructuredProblems;
  global.renderProblemObject = renderProblemObject;
  global.problemsForSection = problemsForSection;
})(typeof window !== "undefined" ? window : globalThis);
