export function _checkKatexFonts() {
  if (!window.katex) return;
  if (!document.fonts || typeof document.fonts.check !== "function") return;
  if (!document.querySelector(".katex")) return;
  try {
    const ok = document.fonts.check("16px KaTeX_Main");
    if (!ok && window.console) {
      console.warn("[fonts] KaTeX_Main بارگذاری نشد. احتمالاً پوشهٔ src/vendor/fonts/ ناقص است.");
    }
  } catch (_) {}
}

export function initPWA() {
  const installBtn = document.getElementById("installBtn");
  let deferredPrompt = null;

  window.addEventListener("load", () => {
    if (typeof document.fonts !== "undefined" && document.fonts.ready) {
      document.fonts.ready.then(_checkKatexFonts).catch(() => _checkKatexFonts());
    } else {
      _checkKatexFonts();
    }
  });

  window.addEventListener("beforeinstallprompt", (e) => {
    e.preventDefault();
    deferredPrompt = e;
    if (installBtn) {
      installBtn.hidden = false;
      installBtn.classList.add("show");
    }
  });

  window.addEventListener("appinstalled", () => {
    deferredPrompt = null;
    if (installBtn) {
      installBtn.hidden = true;
      installBtn.classList.remove("show");
    }
  });

  if (installBtn) {
    installBtn.addEventListener("click", async () => {
      if (!deferredPrompt) return;
      deferredPrompt.prompt();
      const { outcome } = await deferredPrompt.userChoice;
      if (outcome === "accepted") {
        installBtn.hidden = true;
        installBtn.classList.remove("show");
      }
      deferredPrompt = null;
    });
  }
}
