import { toast } from "../core.js";
import type { Meta as PackMeta } from "../engine/contract/types.js";
import { CONTRACT_VERSION } from "../engine/contract/index.js";

// نمای مورد نیاز از دوره/پک برای خروجی Course Pack (فیلدهای ناشناخته نادیده گرفته می‌شوند)
interface SessionLike {
  id?: unknown;
  num?: unknown;
  title?: unknown;
  date?: unknown;
  time?: unknown;
  chapter?: unknown;
  ch?: unknown;
  prereq?: unknown[];
  topics?: unknown[];
  summary?: unknown;
  concepts?: unknown[];
  formulas?: unknown[];
  tips?: unknown[];
  widgets?: unknown[];
  detail?: unknown;
}

interface CourseLike {
  meta?: PackMeta;
  sessions?: SessionLike[];
  chapters?: unknown[];
  glossary?: unknown[];
  grading?: unknown[];
  books?: unknown[];
}

interface PackLike {
  categories?: Record<string, unknown>;
  problemNote?: string;
  problemSections?: unknown[];
  problems?: unknown[];
  widgets?: Record<string, unknown>;
}

function courseOf(): CourseLike {
  return (CourseRuntime.getCourse() as CourseLike | null) || {};
}

function packOf(): PackLike {
  return (CourseRuntime.getPack() as PackLike | null) || {};
}

export function buildCoursePackManifest(): Record<string, unknown> {
  const C = courseOf();
  const P = packOf();
  const M: PackMeta = C.meta || {};
  const sessions = C.sessions || [];
  return {
    kind: "lector-course-pack",
    // نسخهٔ قرارداد فعلی (در نسخهٔ قبلی روی global به همین مقدار بود؛ رفتار حفظ شده)
    contract: CONTRACT_VERSION,
    exportedAt: new Date().toISOString(),
    id: M.id || "course",
    title: M.title || M.appName || "",
    appName: M.appName || "",
    ver: M.ver || "",
    author: M.author || "",
    presentation: M.presentation || null,
    archetype: M.archetype || "stem",
    structure: M.structure || "linear",
    features: M.features || null,
    brand: M.brand || null,
    license: M.license || { mode: "open" },
    shell: M.shell || null,
    counts: {
      sessions: sessions.length,
      chapters: (C.chapters || []).length,
      glossary: (C.glossary || []).length,
      widgets: Object.keys(P.widgets || {}).length,
      problemsStructured: (P.problems || []).length,
      problemSections: (P.problemSections || []).length,
      formulas: sessions.reduce((a, s) => a + (s.formulas || []).length, 0),
      concepts: sessions.reduce((a, s) => a + (s.concepts || []).length, 0),
    },
  };
}

export function buildCoursePackData(): Record<string, unknown> {
  const C = courseOf();
  const P = packOf();
  return {
    manifest: buildCoursePackManifest(),
    meta: Object.assign({}, C.meta || {}),
    categories: Object.assign({}, P.categories || {}),
    problemNote: P.problemNote || "",
    problemSections: P.problemSections || [],
    problems: P.problems || [],
    widgets: P.widgets || {},
    chapters: C.chapters || [],
    sessions: (C.sessions || []).map((s) => ({
      id: s.id,
      num: s.num,
      title: s.title,
      date: s.date,
      time: s.time,
      chapter: s.chapter != null ? s.chapter : s.ch,
      prereq: s.prereq || [],
      topics: s.topics || [],
      summary: s.summary || "",
      concepts: s.concepts || [],
      formulas: s.formulas || [],
      tips: s.tips || [],
      widgets: s.widgets || [],
      detail: s.detail || null,
    })),
    glossary: C.glossary || [],
    grading: C.grading || [],
    books: C.books || [],
  };
}

export function downloadCoursePack(): void {
  const pack = buildCoursePackData();
  const manifest = pack.manifest as { id?: string };
  try {
    const blob = new Blob([JSON.stringify(pack, null, 2)], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download =
      (manifest.id || "course") + "-pack-" + new Date().toISOString().slice(0, 10) + ".json";
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(url);
    toast("Course Pack دانلود شد");
  } catch {
    toast("خروجی بسته ناموفق بود", "err");
  }
}

export function exportCoursePack(): void {
  downloadCoursePack();
}

declare global {
  var exportCoursePack: () => void;
  var downloadCoursePack: () => void;
  var buildCoursePackManifest: () => Record<string, unknown>;
  var buildCoursePackData: () => Record<string, unknown>;
}

globalThis.exportCoursePack = exportCoursePack;
globalThis.downloadCoursePack = downloadCoursePack;
globalThis.buildCoursePackManifest = buildCoursePackManifest;
globalThis.buildCoursePackData = buildCoursePackData;
