/*
 * Halo — تنها سیستم درخشش تعاملی اپ.
 *
 * لایه‌بندی (توکن‌ها در tokens.css):
 *  - #cursor-halo : هالهٔ محیطی نرم که دنبال موس است (z -1، زیر محتوا).
 *  - #halo-layer  : لایهٔ لبه‌ها، مستقیم زیر <body> با z = var(--z-halo).
 *                   عمداً بیرون از .app-sheet است تا isolation/overflow آن روی لبه‌ها اثر نگذارد.
 *
 * قانون نمایش (Occlusion test):
 *  لبه فقط وقتی روشن می‌شود که نزدیک‌ترین نقطهٔ کارت به موس، واقعاً بالاترین المان صفحه باشد
 *  (elementFromPoint). پس هاله پشت شیت تنظیمات، دیالوگ، هدر چسبان، ساید بار یا توست دیده نمی‌شود.
 *
 * اصول کارایی:
 *  - هیچ خواندن هندسه‌ای (getBoundingClientRect) در حین اسکرول انجام نمی‌شود؛ هاله تا پایان اسکرول مخفی است.
 *  - حلقهٔ rAF وقتی موس ساکن و هالهٔ محیطی همگرا باشد و محتوا آرام باشد متوقف می‌شود (CPU در idle = ۰).
 *  - اگر data-halo="off" یا data-fx-eff="lite" باشد، هیچ کاری انجام نمی‌شود.
 *  - روی دستگاه لمسی هاله فعال نمی‌شود.
 */
(function initHalo(global) {
  "use strict";

  const doc = document;
  const root = doc.documentElement;
  if (!doc.body || !global.matchMedia) return;
  if (matchMedia("(hover: none), (pointer: coarse)").matches) return;

  const REDUCED = matchMedia("(prefers-reduced-motion: reduce)").matches;

  // ── ۰. توکن‌ها: همهٔ اعداد از tokens.css خوانده می‌شوند ─────────
  const TK = (function readTokens() {
    const cs = getComputedStyle(root);
    const num = (name, fallback) => {
      const v = parseFloat(cs.getPropertyValue(name));
      return Number.isFinite(v) ? v : fallback;
    };
    return {
      range: num("--halo-range", 90),
      maxEdges: num("--halo-max-edges", 10),
      edgeMax: num("--halo-edge-strength", 0.42),
      ease: REDUCED ? 1 : num("--halo-ambient-ease", 0.2),
      quietMs: num("--halo-scroll-quiet", 140),
      settleMs: num("--halo-settle", 700),
    };
  })();

  // کاندیدها: سطوح محتوایی (بدون ساید بار، هدر، فوتر و دکمه‌ها)
  const TARGET_SEL = [
    ".card", ".concept", ".fcard", ".widget",
    ".pk-card", ".sess-card", ".hm-card", ".hm-hero", ".v2-hero", ".pack-hero", ".pack-sess",
    ".glos-card", ".viewer-toc", ".v2-toc", ".pss-card",
    ".lib-item", ".ccard", ".sess-accordion", ".rd-formula",
    ".rd-define", ".rd-callout", ".shead", ".diagram-card",
    ".ov-panel", ".pg-panel", ".lib-bento-card", ".learn-item",
    ".vw-bar", ".toc-head", ".sess-rail",
  ].join(",");

  // هرگز هاله نگیرند: شیت/دیالوگ/توست/تولتیپ و هر ناحیهٔ صریحاً خارج‌شده
  const BLOCK_SEL = [
    "[data-no-halo]", "[role='dialog']", "[aria-modal='true']",
    ".set-sheet-back", ".modal-back", "#toastUndo", ".toast-undo", ".gtip",
  ].join(",");

  // ── ۱. وضعیت فعال بودن (تنظیمات کاربر + حالت سبک) ────────────────
  function enabled() {
    const d = root.dataset;
    if (d.halo === "off" || d.fxEff === "lite") return false;
    if (doc.body.classList.contains("set-sheet-open")) return false;
    return !doc.querySelector(".modal-back:not([hidden])");
  }

  // ── ۲. هالهٔ محیطی (روی body، z -1، همان رفتار قبلی) ─────────────
  const ambient = doc.createElement("div");
  ambient.id = "cursor-halo";
  ambient.setAttribute("aria-hidden", "true");
  doc.body.appendChild(ambient);
  let ambientOn = false;

  // ── ۳. لایهٔ لبه‌ها ─────────────────────────────────────────────
  const layer = doc.createElement("div");
  layer.id = "halo-layer";
  layer.setAttribute("aria-hidden", "true");
  doc.body.appendChild(layer);

  // ── ۴. کاندیدها و visibility ────────────────────────────────────
  const visible = new Set();
  const observed = new Set();
  let candidates = [];
  const radiusCache = new WeakMap();

  const io = new IntersectionObserver(
    (entries) => {
      for (const e of entries) {
        if (e.isIntersecting) visible.add(e.target);
        else visible.delete(e.target);
      }
      schedule();
    },
    { rootMargin: "120px 0px" },
  );

  function scan() {
    const found = doc.querySelectorAll(TARGET_SEL);
    candidates = [];
    for (let i = 0; i < found.length; i++) {
      const el = found[i];
      if (el.closest(BLOCK_SEL)) continue;
      candidates.push(el);
      if (!observed.has(el)) {
        observed.add(el);
        io.observe(el);
      }
    }
    for (const el of observed) {
      if (!el.isConnected) {
        observed.delete(el);
        visible.delete(el);
        io.unobserve(el);
      }
    }
    schedule();
  }

  let scanTimer = 0;
  function scanSoon() {
    clearTimeout(scanTimer);
    scanTimer = setTimeout(scan, 150);
  }

  // ── ۵. overlayهای لبه ───────────────────────────────────────────
  const edges = [];
  let usedEdges = 0;

  function edgeAt(i) {
    if (!edges[i]) {
      const d = doc.createElement("div");
      d.className = "halo-edge";
      d.setAttribute("aria-hidden", "true");
      layer.appendChild(d);
      edges[i] = d;
    }
    return edges[i];
  }

  function hideAll() {
    for (let i = 0; i < usedEdges; i++) edges[i].style.opacity = "0";
    usedEdges = 0;
  }

  function radiusOf(el) {
    let r = radiusCache.get(el);
    if (r === undefined) {
      r = getComputedStyle(el).borderRadius;
      radiusCache.set(el, r);
    }
    return r;
  }

  // آیا نزدیک‌ترین نقطهٔ کارت به موس، واقعاً روی خود کارت است؟ (نه پشت شیت/هدر/دیالوگ)
  function isUncovered(el, r, x, y) {
    const px = Math.min(Math.max(x, r.left + 1), r.right - 1);
    const py = Math.min(Math.max(y, r.top + 1), r.bottom - 1);
    const top = doc.elementFromPoint(px, py);
    return !!top && (top === el || el.contains(top));
  }

  // ── ۶. حلقهٔ رندر ───────────────────────────────────────────────
  let mx = -9999, my = -9999; // موس واقعی
  let cx = -9999, cy = -9999; // هالهٔ نرم‌شده
  let pointerIn = false;
  let quiet = false; // در حین اسکرول
  let quietTimer = 0;
  let lastActivity = 0;
  let raf = 0;

  function markActive() {
    lastActivity = performance.now();
  }

  function schedule() {
    if (!raf) raf = requestAnimationFrame(frame);
  }

  function updateEdges() {
    if (!pointerIn || quiet || !enabled()) {
      hideAll();
      return;
    }

    const hits = [];
    for (let i = 0; i < candidates.length; i++) {
      const el = candidates[i];
      if (!visible.has(el)) continue;
      if (el.classList.contains("sess-rail") && !el.classList.contains("on")) continue;
      const r = el.getBoundingClientRect();
      if (r.width < 4 || r.height < 4) continue;
      const dx = Math.max(r.left - mx, 0, mx - r.right);
      const dy = Math.max(r.top - my, 0, my - r.bottom);
      const d = Math.sqrt(dx * dx + dy * dy);
      if (d < TK.range) hits.push({ el, r, d });
    }
    hits.sort((a, b) => a.d - b.d);

    let n = 0;
    for (let i = 0; i < hits.length && n < TK.maxEdges; i++) {
      const h = hits[i];
      if (!isUncovered(h.el, h.r, mx, my)) continue;

      const o = Math.min(1, Math.max(0, 1 - h.d / TK.range)) * TK.edgeMax;
      const node = edgeAt(n);
      const isRail = h.el.classList.contains("sess-rail");
      node.style.transform = "translate3d(" + h.r.left + "px," + h.r.top + "px,0)";
      node.style.width = h.r.width + "px";
      node.style.height = h.r.height + "px";
      if (isRail) {
        node.classList.add("halo-edge--rail");
        const clipVal = getComputedStyle(h.el).getPropertyValue("--sr-clip");
        if (clipVal) node.style.setProperty("--sr-clip", clipVal);
        node.style.borderRadius = "0";
      } else {
        node.classList.remove("halo-edge--rail");
        node.style.removeProperty("--sr-clip");
        node.style.borderRadius = radiusOf(h.el);
      }
      node.style.setProperty("--mx", mx - h.r.left + "px");
      node.style.setProperty("--my", my - h.r.top + "px");
      node.style.opacity = o.toFixed(3);
      n++;
    }
    for (let i = n; i < usedEdges; i++) edges[i].style.opacity = "0";
    usedEdges = n;
  }

  function frame() {
    raf = 0;
    const on = pointerIn && enabled();

    if (on !== ambientOn) {
      ambientOn = on;
      ambient.classList.toggle("is-active", on);
    }
    if (on) {
      cx += (mx - cx) * TK.ease;
      cy += (my - cy) * TK.ease;
      ambient.style.transform = "translate3d(" + cx.toFixed(1) + "px," + cy.toFixed(1) + "px,0)";
    }

    updateEdges();

    // ادامهٔ حلقه فقط تا وقتی لازم است: هالهٔ در حال همگرایی یا محتوای در حال تغییر
    const ambientMoving = on && (Math.abs(mx - cx) > 0.5 || Math.abs(my - cy) > 0.5);
    const contentBusy = performance.now() - lastActivity < TK.settleMs;
    if (pointerIn && (ambientMoving || contentBusy)) schedule();
  }

  // ── ۷. رویدادها ─────────────────────────────────────────────────
  function onLeave() {
    pointerIn = false;
    hideAll();
    ambientOn = false;
    ambient.classList.remove("is-active");
  }

  function onMove(e) {
    mx = e.clientX;
    my = e.clientY;
    if (!enabled()) {
      if (pointerIn) onLeave();
      return;
    }
    if (!pointerIn) {
      pointerIn = true;
      cx = mx;
      cy = my;
    }
    markActive();
    schedule();
  }

  function onScroll() {
    if (!pointerIn) return;
    // حین اسکرول هیچ هندسه‌ای نمی‌خوانیم؛ بعد از آرام شدن، یک‌بار بازمحاسبه می‌کنیم
    if (!quiet) {
      quiet = true;
      hideAll();
    }
    clearTimeout(quietTimer);
    quietTimer = setTimeout(() => {
      quiet = false;
      markActive();
      schedule();
    }, TK.quietMs);
  }

  doc.addEventListener("pointermove", onMove, { passive: true });
  doc.documentElement.addEventListener("pointerleave", onLeave);
  global.addEventListener("blur", onLeave);
  doc.addEventListener("scroll", onScroll, { passive: true, capture: true });
  global.addEventListener("resize", () => {
    markActive();
    scanSoon();
    schedule();
  }, { passive: true });
  global.addEventListener("hashchange", () => {
    hideAll();
    markActive();
    scanSoon();
  });
  // تغییر تنظیمات (هاله / کیفیت جلوه‌ها) از prefs.js منتشر می‌شود
  global.addEventListener("lector:fx", () => {
    if (!enabled()) onLeave();
    else {
      markActive();
      schedule();
    }
  });

  new MutationObserver(() => {
    markActive();
    scanSoon();
  }).observe(doc.body, { childList: true, subtree: true });

  scan();
  global.__haloRescan = scanSoon;
})(window);
