export function _prefRows(group) {
  return group.items
    .filter((item) => {
      if (item.key === "accent") return true;
      return typeof isPrefAllowed !== "function" || isPrefAllowed(item.key);
    })
    .map((item) => {
      const cur = getPref(item.key, Presentation.prefDefault(item.key, item.default));
      const mode = item.render || "text";
      const allowed = typeof isPrefAllowed !== "function" || isPrefAllowed(item.key);
      const lockAttr = allowed ? "" : ' disabled aria-disabled="true"';
      const lockClass = allowed ? "" : " is-locked";
      const lockNote = allowed ? "" : `<span class="set-lock-note">قفل</span>`;

      if (mode === "theme-cards" && typeof listThemes === "function") {
        const themes = listThemes();
        const selIdx = Math.max(0, themes.findIndex((t) => t.id === cur));
        const cards = themes
          .map((t) => {
            // اضافه کردن preserveAspectRatio برای پر کردن کامل کادر (مشابه object-fit: cover)
            const svgHtml = t.preview.replace('<svg ', '<svg preserveAspectRatio="xMidYMid slice" ');
            const isOn = cur === t.id;
            return `<div class="theme-card${isOn ? " on" : ""}" role="radio" aria-checked="${isOn ? "true" : "false"}" tabindex="${isOn ? "0" : "-1"}" data-val="${escHtml(t.id)}" aria-label="${escHtml(t.label)}">
            <span class="tc-head">
              <span class="tc-name">${escHtml(t.label)}</span>
              <span class="tc-check" aria-hidden="true">${icon("check")}</span>
            </span>
            <span class="tc-hint">${escHtml(t.hint || "")}</span>
            <span class="tc-preview" aria-hidden="true" style="--accent:${escHtml(t.accent[document.documentElement.getAttribute("data-theme") === "dark" ? "dark" : "light"])}">${svgHtml}</span>
          </div>`;
          })
          .join("");

        return `<div class="set-row set-row-theme">
          <div class="set-info set-info-center">
            <b>${item.label}</b>
            ${item.hint ? `<span>${item.hint}</span>` : ""}
          </div>
          <div class="tp-carousel-wrap" data-pref="${item.key}" data-active-idx="${selIdx}">
            <button type="button" class="tp-arrow prev" aria-label="قبلی">${icon("chevLeft")}</button>
            <div class="tp-carousel" role="radiogroup" aria-label="${escHtml(item.label)}">${cards}</div>
            <button type="button" class="tp-arrow next" aria-label="بعدی">${icon("chevRight")}</button>
          </div>
          <p class="tp-live" aria-live="polite"></p>
        </div>`;
      }

      const btns = item.options
        .map((opt) => {
          const on = cur === opt.val ? "on" : "";
          const tip = escHtml(opt.label || "");
          if (mode === "cards")
            return `<button type="button" data-val="${opt.val}" data-tip="${tip}" class="${on}"${lockAttr}><span class="seg-ic">${opt.icon || ""}</span><span class="sr-only">${opt.label}</span></button>`;
          if (mode === "swatches")
            return `<button type="button" data-val="${opt.val}" data-tip="${tip}" class="${on} sw-${opt.val}"${lockAttr}><span class="sr-only">${opt.label}</span></button>`;
          return `<button type="button" data-val="${opt.val}" class="${on}"${lockAttr}>${opt.label}</button>`;
        })
        .join("");
      return `<div class="set-row${lockClass}">
        <div class="set-info">
          <b>${item.label}${lockNote}</b>
          ${item.hint ? `<span>${item.hint}</span>` : ""}
        </div>
        <div class="seg set-seg${mode !== "text" ? " " + mode : ""}${lockClass}" data-pref="${item.key}">${btns}</div>
      </div>`;
    })
    .join("");
}

export function _section(id, title, hint, bodyHTML) {
  return `<section class="set-section" data-sec="${id}">
    ${title ? `<header class="set-sec-head"><h2>${title}</h2>${hint ? `<p>${hint}</p>` : ""}</header>` : ""}
    <div class="set-section-body">${bodyHTML}</div>
  </section>`;
}

export function renderPrefGroups() {
  if (typeof PREFERENCES === "undefined") return "";
  return PREFERENCES.map((g) => {
    const bodyHTML = _prefRows(g);
    if (!bodyHTML.trim()) return "";
    return _section(g.id, g.title, g.hint || "", bodyHTML);
  })
    .filter(Boolean)
    .join("");
}

export const CUSTOM_SECTIONS = [
  { id: "account", title: "حساب کاربری", icon: "user", build: _buildAccountBody },
  { id: "progress", title: "پیشرفت مطالعه", icon: "target", build: _buildProgressBody },
  { id: "advanced", title: "پیشرفته", icon: "sliders", build: _buildAdvancedBody },
  { id: "about", title: "دربارهٔ برنامه", icon: "info", build: _buildAboutBody },
];

// دسته‌بندی ناوبری: هر دسته با برچسب کوتاه شروع می‌شود (بار شناختی کمتر)
export const SECTION_GROUPS = [
  { label: "شخصی", ids: ["account", "progress"] },
  { label: "ظاهر و خواندن", ids: ["appearance", "reading", "effects", "print"] },
  { label: "رفتار", ids: ["interface", "notifications"] },
  { label: "سیستم", ids: ["advanced", "about"] },
];
export const SECTION_ORDER = SECTION_GROUPS.flatMap((g) => g.ids);

export function _allSections() {
  const byId = new Map();
  if (typeof PREFERENCES !== "undefined") {
    PREFERENCES.forEach((g) => byId.set(g.id, { kind: "pref", group: g }));
  }
  CUSTOM_SECTIONS.forEach((c) => byId.set(c.id, { kind: "custom", sec: c }));
  return SECTION_ORDER.map((id) => byId.get(id))
    .filter(Boolean)
    .filter((s) => s.kind !== "pref" || _prefRows(s.group).trim().length > 0);
}

