// بخش فعلی؛ برای بازسازی حالت وقتی اندازهٔ صفحه عوض می‌شود
export let _curSec = null;
export let _leavingDetail = false;
// جهت انیمیشن زیرصفحه‌های پیشرفته: "fwd" (ورود به زیرصفحه) یا "back" (بازگشت)
export let _subDir = null;
// سطح دوم «حساب کاربری» (داده‌ها و حذف اطلاعات محلی) و تعداد آیتم‌های آدرس قبلی
export let _accSub = null;
export let _bcCount = 0;
// پیش‌نویس عکس پروفایل تا قبل از «ذخیره»: undefined = بدون تغییر، null = حذف، string = تصویر جدید
export let _accDraftAvatar;
export const _ACC_SUB_TITLES = { data: "داده‌ها و حذف اطلاعات" };

export function renderSettingsNav(activeId) {
  if (typeof PREFERENCES === "undefined") return "";
  const byId = new Map(
    _allSections().map((s) => [s.kind === "pref" ? s.group.id : s.sec.id, s]),
  );
  return SECTION_GROUPS.map((g) => {
    const items = g.ids
      .map((id) => byId.get(id))
      .filter(Boolean)
      .map((s) => {
        const id = s.kind === "pref" ? s.group.id : s.sec.id;
        const title = s.kind === "pref" ? s.group.title : s.sec.title;
        const isOn = id === activeId ? " on" : "";
        return `<button class="set-nav-item${isOn}" data-sec="${id}" type="button">
        <span class="sn-ic">${icon(SET_SECTION_ICONS[id] || "gear")}</span>
        <span class="sn-txt">
          <span class="sn-lbl">${title}</span>
          <span class="sn-hint">${SET_SECTION_HINTS[id] || ""}</span>
        </span>
        <span class="sn-chev" aria-hidden="true">${icon("chevLeft")}</span>
      </button>`;
      })
      .join("");
    if (!items) return "";
    return `<section class="set-nav-group" aria-label="${g.label}">
      <div class="set-nav-cat" aria-hidden="true">${g.label}</div>
      <div class="set-nav-list">${items}</div>
    </section>`;
  }).join("");
}

export const _SUB_TITLES = { storage: "مدیریت حافظه", pwa: "نصب و به‌روزرسانی", changelog: "تاریخچه تغییرات" };

/**
 * نمایش یک بخش تنظیمات.
 * opts.detail: در موبایل اگر false باشد، منوی ریشه نشان داده می‌شود (هیچ بخشی باز نیست).
 * در دسکتاپ همیشه نمای جزئیات (سایدبار + پنل) است.
 */
export function _showSettingsSection(id, opts) {
  if (!id) return;
  const shell = _sr().querySelector(".set-shell");
  if (!shell) return;
  const mobile = _isMobileSheet();
  const detail = !mobile || !opts || opts.detail !== false;
  _curSec = id;

  if (id === "advanced") {
    const advBody = shell.querySelector('[data-sec="advanced"] .set-section-body');
    if (advBody) {
      advBody.innerHTML = _buildAdvancedBody();
      if (_subDir) {
        advBody.classList.remove("sub-fwd", "sub-back");
        void advBody.offsetWidth; // ریست انیمیشن
        advBody.classList.add(_subDir === "fwd" ? "sub-fwd" : "sub-back");
        _subDir = null;
      }
    }
    _bindAdvancedSection();
  }

  if (id === "account") {
    const accBody = shell.querySelector('[data-sec="account"] .set-section-body');
    const view = _accSub || "main";
    if (accBody && accBody.dataset.view !== view) {
      accBody.innerHTML = _buildAccountBody();
      accBody.dataset.view = view;
      _bindAccountSection();
      if (_subDir) {
        accBody.classList.remove("sub-fwd", "sub-back");
        void accBody.offsetWidth;
        accBody.classList.add(_subDir === "fwd" ? "sub-fwd" : "sub-back");
      }
    }
    _subDir = null;
  }

  shell.querySelectorAll(".set-section").forEach((sec) => {
    sec.classList.toggle("active", sec.dataset.sec === id);
  });
  shell.querySelectorAll(".set-nav-item").forEach((b) => {
    b.classList.toggle("on", detail && b.dataset.sec === id);
  });

  const secObj = _allSections().find((s) => (s.kind === "pref" ? s.group.id : s.sec.id) === id);
  const title = secObj ? (secObj.kind === "pref" ? secObj.group.title : secObj.sec.title) : "";

  // آدرس (نان‌رنجی): سطح‌های جدید از زیر و جلوی سطح‌های قبلی با انیمیشن ورود می‌آیند
  const crumbs = [];
  let showBack = false;
  if (!detail) {
    crumbs.push({ label: "تنظیمات", active: true });
  } else {
    crumbs.push({ label: "تنظیمات", sec: "root" });
    if (id === "advanced" && _advSub) {
      crumbs.push({ label: "پیشرفته", sec: "advanced" });
      crumbs.push({ label: _SUB_TITLES[_advSub] || "", active: true });
      showBack = true;
    } else if (id === "account" && _accSub) {
      crumbs.push({ label: "حساب کاربری", sec: "account" });
      crumbs.push({ label: _ACC_SUB_TITLES[_accSub] || "", active: true });
      showBack = true;
    } else {
      crumbs.push({ label: title, active: true });
      showBack = mobile;
    }
  }
  const bcTx = document.getElementById("setBreadcrumbTx");
  if (bcTx) {
    const prev = _bcCount;
    bcTx.innerHTML = crumbs
      .map((c, i) => {
        const isNew = i >= prev;
        const sep = i > 0 ? `<span class="sep${isNew ? " crumb-new" : ""}">/</span>` : "";
        const cls = (c.active ? " active" : "") + (isNew ? " crumb-new" : "");
        const data = c.sec ? ` data-sec="${c.sec}"` : "";
        return `${sep}<span class="crumb${cls}"${data}>${c.label}</span>`;
      })
      .join("");
  }
  _bcCount = crumbs.length;

  const accHead = shell.querySelector('[data-sec="account"] .set-sec-head h2');
  if (accHead) {
    if (!accHead.dataset.base) accHead.dataset.base = accHead.textContent;
    accHead.textContent = detail && id === "account" && _accSub ? _ACC_SUB_TITLES[_accSub] : accHead.dataset.base;
  }

  // عنوان سرِ بخش «پیشرفته» با زیرصفحه عوض می‌شود (مثلاً «مدیریت حافظه»)
  const advHead = shell.querySelector('[data-sec="advanced"] .set-sec-head h2');
  if (advHead) {
    if (!advHead.dataset.base) advHead.dataset.base = advHead.textContent;
    advHead.textContent = detail && id === "advanced" && _advSub ? _SUB_TITLES[_advSub] || advHead.dataset.base : advHead.dataset.base;
  }

  const backBtn = document.getElementById("setPanelBack");
  if (backBtn) {
    const wasBackShown = getComputedStyle(backBtn).display !== "none";
    backBtn.style.display = showBack ? "flex" : "none";
    // دکمهٔ بازگشت تازه ظاهر می‌شود: سربرگ یک‌بار انیمیشن ورود می‌گیرد
    const titleBox = document.querySelector(".set-sheet-title");
    if (showBack && !wasBackShown && titleBox) {
      titleBox.classList.remove("back-enter");
      void titleBox.offsetWidth;
      titleBox.classList.add("back-enter");
    }
  }

  shell.classList.toggle("is-mobile-detail", mobile && detail);
  if (!(mobile && detail)) shell.classList.remove("is-closing");

  requestAnimationFrame(() => requestAnimationFrame(() => _initSegPills()));
  try {
    sessionStorage.setItem("lector:settings:active", id);
  } catch (_) {}
  try {
    const newHash = detail ? "#/settings/" + id : "#/settings";
    if (location.hash !== newHash) history.replaceState(null, "", newHash);
  } catch (_) {}
}

// بازگشت از جزئیات به منوی ریشه (موبایل): انیمیشن خروج، سپس نمایش ریشه
export function _leaveSettingsDetail() {
  const shell = _sr().querySelector(".set-shell");
  if (!shell || !shell.classList.contains("is-mobile-detail") || _leavingDetail) return;
  _leavingDetail = true;
  shell.classList.add("is-closing");
  setTimeout(() => {
    _leavingDetail = false;
    _advSub = null;
    _accSub = null;
    _showSettingsSection(_curSec, { detail: false });
  }, 300);
}

