export function _storageUsageKB() {
  let total = 0;
  try {
    for (let i = 0; i < localStorage.length; i++) {
      const k = localStorage.key(i);
      if (!k) continue;
      const v = localStorage.getItem(k) || "";
      total += k.length + v.length;
    }
  } catch (_) {}
  return Math.round(total / 1024);
}

export function _getAggregatedStorage() {
  const ns = NS();

  const buckets = {
    photo: {
      label: "عکس پروفایل",
      desc: "تصویر شما در حساب کاربری",
      icon: "user",
      size: 0,
      keys: [],
    },
    learning: {
      label: "پیشرفت و مطالعه",
      desc: "تیک‌ها، حل تمرین‌ها، نشانک‌ها و یادداشت‌ها",
      icon: "book",
      size: 0,
      keys: [],
    },
    history: {
      label: "تاریخچه و آمار",
      desc: "سابقه فعالیت‌های روزانه و دفتر اشتباهات",
      icon: "clock",
      size: 0,
      keys: [],
    },
    settings: {
      label: "تنظیمات و سیستم",
      desc: "پوسته، تنظیمات دروس و وضعیت برنامه",
      icon: "sliders",
      size: 0,
      keys: [],
    },
  };

  let totalBytes = 0;

  for (let i = 0; i < localStorage.length; i++) {
    const k = localStorage.key(i);
    const v = localStorage.getItem(k) || "";
    const size = new Blob([k + v]).size;
    totalBytes += size;

    if (k === ns + "AccountAvatar") {
      buckets.photo.size += size;
      buckets.photo.keys.push(k);
    } else if (["Read", "Solved", "Bookmarks", "Notes", "Review"].some((x) => k === ns + x)) {
      buckets.learning.size += size;
      buckets.learning.keys.push(k);
    } else if (["Events", "Mistakes", "Tasks"].some((x) => k === ns + x)) {
      buckets.history.size += size;
      buckets.history.keys.push(k);
    } else if (k.startsWith(ns) || k.startsWith("lector")) {
      buckets.settings.size += size;
      buckets.settings.keys.push(k);
    }
  }

  return { buckets, totalBytes };
}

export function _renderStorageUI() {
  const { buckets, totalBytes } = _getAggregatedStorage();

  const fmtSize = (b) => {
    if (b === 0) return "۰ KB";
    if (b < 1024) return toFa(b) + " B";
    if (b < 1024 * 1024) return toFa((b / 1024).toFixed(1)) + " KB";
    return toFa((b / (1024 * 1024)).toFixed(2)) + " MB";
  };

  let barHTML = "";

  Object.entries(buckets).forEach(([key, b]) => {
    if (b.size > 0) {
      const pct = (b.size / Math.max(1, totalBytes)) * 100;
      barHTML += `<div class="stg-bar-segment stg-cat-${key}" style="width:${pct}%"></div>`;
    }
  });

  const sortedBuckets = Object.values(buckets)
    .filter((b) => b.size > 0)
    .sort((a, b) => b.size - a.size);

  let listHTML = sortedBuckets
    .map(
      (b) => `
    <div class="set-row">
      <div class="set-info set-info-row">
        <div class="set-tile">
          ${icon(b.icon)}
        </div>
        <div>
          <b>${escHtml(b.label)}</b>
          <span>${escHtml(b.desc)}</span>
        </div>
      </div>
      <div class="set-bucket-actions">
        <span class="set-bucket-size">${fmtSize(b.size)}</span>
        <button class="btn set-icon-btn" data-del-bucket="${b.keys.join(",")}" aria-label="پاک کردن">${icon("x")}</button>
      </div>
    </div>
  `,
    )
    .join("");

  if (!sortedBuckets.length) {
    listHTML = `<div class="set-row"><span class="set-empty">حافظه خالی است.</span></div>`;
  }

  const totalStr =
    totalBytes > 1024 * 1024
      ? toFa((totalBytes / (1024 * 1024)).toFixed(2))
      : toFa((totalBytes / 1024).toFixed(1));
  const unitStr = totalBytes > 1024 * 1024 ? "MB" : "KB";

  return `
    <div class="set-mem">
      <div class="set-mem-head">
        <span class="set-mem-label">حافظه استفاده‌شده</span>
        <div class="set-mem-total">
          ${totalStr} <small class="set-mem-unit">${unitStr}</small>
        </div>
      </div>
      
      <div class="set-mem-bar">
        ${barHTML || '<div class="set-mem-bar-empty"></div>'}
      </div>
      
      <div>${listHTML}</div>

      <div class="set-row set-row-danger">
        <div class="set-info">
          <b class="set-row-title">${icon("warn")} پاک‌سازی کامل داده‌ها</b>
          <span>بازگشت برنامه به حالت اولیه (غیرقابل بازگشت)</span>
        </div>
        <button class="btn set-btn-rose" id="advWipe" type="button">
          پاک‌سازی
        </button>
      </div>
    </div>
  `;
}

