export function _openAvatarPreview(src) {
  let back = document.getElementById("avatarPreviewBack");
  if (!back) {
    back = document.createElement("div");
    back.id = "avatarPreviewBack";
    back.className = "avatar-preview-back";
    document.body.appendChild(back);
  }
  back.innerHTML = `<img src="${src}" alt="عکس پروفایل" />`;

  const close = () => {
    back.classList.remove("open");
    setTimeout(() => {
      if (!back.classList.contains("open")) back.innerHTML = "";
    }, 260);
    document.removeEventListener("keydown", esc);
  };
  const esc = (e) => {
    if (e.key === "Escape") {
      e.preventDefault();
      close();
    }
  };
  document.addEventListener("keydown", esc);

  back.onclick = (e) => {
    if (e.target === back) close();
  };

  requestAnimationFrame(() => back.classList.add("open"));
}

export function _openCropModal(src, cb) {
  let back = document.getElementById("cropBack");
  if (!back) {
    back = document.createElement("div");
    back.id = "cropBack";
    back.className = "crop-back";
    document.body.appendChild(back);
  }

  back.innerHTML = `
    <div class="crop-modal" role="dialog" aria-modal="true" aria-label="برش عکس پروفایل">
      <header class="crop-head">
        <b>برش عکس پروفایل</b>
        <button type="button" class="crop-x" aria-label="بستن">${icon("x")}</button>
      </header>
      <div class="crop-stage" id="cropStage">
        <img id="cropImg" alt="" draggable="false" />
        <div class="crop-frame" aria-hidden="true"></div>
      </div>
      <div class="crop-controls">
        <button type="button" class="crop-tool" data-zoom="out" aria-label="کوچک‌تر" title="کوچک‌تر">${icon("minus")}</button>
        <button type="button" class="crop-tool" data-zoom="in" aria-label="بزرگ‌تر" title="بزرگ‌تر">${icon("plus")}</button>
        <span class="crop-controls-sep" aria-hidden="true"></span>
        <button type="button" class="crop-tool" data-rotate="90" aria-label="چرخش ۹۰ درجه ساعت‌گرد" title="چرخش ۹۰°">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2"
               stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
            <path d="M21 12a9 9 0 1 1-3-6.7"/>
            <polyline points="21 4 21 9 16 9"/>
          </svg>
        </button>
      </div>
      <footer class="crop-foot">
        <button type="button" class="btn ghost" id="cropCancel">انصراف</button>
        <button type="button" class="btn g" id="cropOk">${icon("check")} برش و ذخیره</button>
      </footer>
    </div>`;

  const stage = back.querySelector("#cropStage");
  const img = back.querySelector("#cropImg");

  const STAGE = Math.min(320, window.innerWidth - 64);
  const FRAME = Math.round(STAGE * 0.75);
  const FRAME_L = (STAGE - FRAME) / 2;
  const FRAME_T = (STAGE - FRAME) / 2;
  const FRAME_R = FRAME_L + FRAME;
  const FRAME_B = FRAME_T + FRAME;
  stage.style.width = STAGE + "px";
  stage.style.height = STAGE + "px";
  stage.style.setProperty("--crop-frame", FRAME + "px");

  let iw = 0,
    ih = 0;
  let baseScale = 1,
    userScale = 1;
  let tx = 0,
    ty = 0;
  let dragging = false,
    startX = 0,
    startY = 0,
    startTx = 0,
    startTy = 0;
  let rotating = false;

  const clamp = () => {
    const eff = baseScale * userScale;
    const rw = iw * eff,
      rh = ih * eff;
    if (tx > FRAME_L) tx = FRAME_L;
    if (tx + rw < FRAME_R) tx = FRAME_R - rw;
    if (ty > FRAME_T) ty = FRAME_T;
    if (ty + rh < FRAME_B) ty = FRAME_B - rh;
  };
  const apply = () => {
    const eff = baseScale * userScale;
    img.style.width = iw * eff + "px";
    img.style.height = ih * eff + "px";
    img.style.left = tx + "px";
    img.style.top = ty + "px";
  };
  const center = () => {
    const eff = baseScale * userScale;
    const rw = iw * eff,
      rh = ih * eff;
    tx = FRAME_L + (FRAME - rw) / 2;
    ty = FRAME_T + (FRAME - rh) / 2;
    clamp();
    apply();
  };

  img.style.visibility = "hidden";
  img.onload = () => {
    rotating = false;
    iw = img.naturalWidth;
    ih = img.naturalHeight;
    baseScale = Math.max(FRAME / iw, FRAME / ih);
    userScale = 1;
    center();
    img.style.visibility = "visible";
  };
  img.onerror = () => {
    if (typeof toast === "function") toast("بارگذاری تصویر ناموفق بود", "err");
    close(null);
  };
  img.src = src;

  let zoomAnim = 0;

  function _applyZoomTo(targetScale) {
    targetScale = Math.max(1, Math.min(3, targetScale));
    if (Math.abs(targetScale - userScale) < 0.001) return;

    if (zoomAnim) {
      cancelAnimationFrame(zoomAnim);
      zoomAnim = 0;
    }

    const startScale = userScale;
    const startTx = tx;
    const startTy = ty;

    const cx = FRAME_L + FRAME / 2;
    const cy = FRAME_T + FRAME / 2;
    const srcX = (cx - startTx) / (baseScale * startScale);
    const srcY = (cy - startTy) / (baseScale * startScale);
    const endTx = cx - srcX * baseScale * targetScale;
    const endTy = cy - srcY * baseScale * targetScale;

    const reduce =
      window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (reduce) {
      userScale = targetScale;
      tx = endTx;
      ty = endTy;
      clamp();
      apply();
      return;
    }

    const dur = 220;
    const t0 = performance.now();
    const ease = (t) => 1 - Math.pow(1 - t, 2.6);

    const step = (now) => {
      const t = Math.min(1, (now - t0) / dur);
      const e = ease(t);
      userScale = startScale + (targetScale - startScale) * e;
      tx = startTx + (endTx - startTx) * e;
      ty = startTy + (endTy - startTy) * e;
      clamp();
      apply();
      if (t < 1) {
        zoomAnim = requestAnimationFrame(step);
      } else {
        userScale = targetScale;
        tx = endTx;
        ty = endTy;
        clamp();
        apply();
        zoomAnim = 0;
      }
    };
    zoomAnim = requestAnimationFrame(step);
  }

  back.querySelectorAll("[data-zoom]").forEach((b) => {
    b.onclick = () => {
      const delta = b.dataset.zoom === "in" ? 0.15 : -0.15;
      _applyZoomTo(userScale + delta);
    };
  });

  function rotate90(delta) {
    if (rotating) return;
    rotating = true;
    const rad = (delta * Math.PI) / 180;
    const nw = Math.abs(delta) % 180 === 90 ? ih : iw;
    const nh = Math.abs(delta) % 180 === 90 ? iw : ih;
    const c = document.createElement("canvas");
    c.width = nw;
    c.height = nh;
    const cx = c.getContext("2d");
    cx.imageSmoothingEnabled = true;
    cx.imageSmoothingQuality = "high";
    cx.translate(nw / 2, nh / 2);
    cx.rotate(rad);
    cx.drawImage(img, -iw / 2, -ih / 2);
    img.src = c.toDataURL("image/jpeg", 0.95);
  }

  back.querySelectorAll("[data-rotate]").forEach((b) => {
    b.onclick = () => rotate90(+b.dataset.rotate);
  });

  stage.addEventListener("pointerdown", (e) => {
    if (img.style.visibility === "hidden") return;
    if (zoomAnim) {
      cancelAnimationFrame(zoomAnim);
      zoomAnim = 0;
    }
    dragging = true;
    startX = e.clientX;
    startY = e.clientY;
    startTx = tx;
    startTy = ty;
    try {
      stage.setPointerCapture(e.pointerId);
    } catch (_) {}
    stage.style.cursor = "grabbing";
  });
  stage.addEventListener("pointermove", (e) => {
    if (!dragging) return;
    tx = startTx + (e.clientX - startX);
    ty = startTy + (e.clientY - startY);
    clamp();
    apply();
  });
  const endDrag = (e) => {
    if (!dragging) return;
    dragging = false;
    try {
      stage.releasePointerCapture(e.pointerId);
    } catch (_) {}
    stage.style.cursor = "grab";
  };
  stage.addEventListener("pointerup", endDrag);
  stage.addEventListener("pointercancel", endDrag);

  const close = (result) => {
    back.classList.remove("open");
    setTimeout(() => {
      if (!back.classList.contains("open")) back.innerHTML = "";
    }, 260);
    document.removeEventListener("keydown", esc);
    if (cb) cb(result);
  };
  const esc = (e) => {
    if (e.key === "Escape") {
      e.preventDefault();
      close(null);
    }
  };
  document.addEventListener("keydown", esc);

  back.onclick = (e) => {
    if (e.target === back) close(null);
  };
  back.querySelector(".crop-x").onclick = () => close(null);
  back.querySelector("#cropCancel").onclick = () => close(null);

  back.querySelector("#cropOk").onclick = () => {
    const eff = baseScale * userScale;
    const srcSize = FRAME / eff;

    const OUT = Math.min(2048, Math.max(512, Math.round(srcSize)));

    const srcX = (FRAME_L - tx) / eff;
    const srcY = (FRAME_T - ty) / eff;
    const cv = document.createElement("canvas");
    cv.width = OUT;
    cv.height = OUT;
    const cx = cv.getContext("2d");
    cx.imageSmoothingEnabled = true;
    cx.imageSmoothingQuality = "high";
    try {
      cx.drawImage(img, srcX, srcY, srcSize, srcSize, 0, 0, OUT, OUT);
      close(cv.toDataURL("image/jpeg", 0.92));
    } catch (_) {
      if (typeof toast === "function") toast("برش عکس ناموفق بود", "err");
      close(null);
    }
  };

  requestAnimationFrame(() => back.classList.add("open"));
}

