export function bindPrefSegments() {
  _sr()
    .querySelectorAll("[data-pref]")
    .forEach((seg) => {
      const key = seg.dataset.pref;
      seg.querySelectorAll("button").forEach((b) => {
        b.onclick = () => {
          setPref(key, b.dataset.val);
          seg.querySelectorAll("button").forEach((x) => {
            const isOn = x === b;
            x.classList.toggle("on", isOn);
            if (x.hasAttribute("aria-pressed")) {
              x.setAttribute("aria-pressed", isOn ? "true" : "false");
            }
          });
          _updateSegPill(seg, true);
          if (key === "theme") {
            const bt = document.getElementById("themeToggle");
            if (bt) {
              bt.innerHTML = icon(
                document.documentElement.getAttribute("data-theme") === "light" ? "sun" : "moon",
              );
            }
            if (typeof reRenderMmd === "function") reRenderMmd();
          }
        };
      });
    });
  _initSegPills();
}

export function _initSegPills() {
  const root = _sr();
  const activeSection = root.querySelector(".set-section.active");
  const scope = activeSection || root;
  scope.querySelectorAll(".set-seg").forEach((seg) => {
    if (seg.classList.contains("swatches")) return;
    if (seg.classList.contains("is-locked")) return;
    let pill = seg.querySelector(".seg-pill");
    if (!pill) {
      pill = document.createElement("span");
      pill.className = "seg-pill";
      seg.insertBefore(pill, seg.firstChild);
    }
    _updateSegPill(seg, false);
  });
}

export function _updateSegPill(seg, animate) {
  const pill = seg.querySelector(".seg-pill");
  if (!pill) return;
  const active = seg.querySelector("button.on");
  if (!active) {
    pill.style.opacity = "0";
    return;
  }
  const x = active.offsetLeft;
  const y = active.offsetTop;
  const w = active.offsetWidth;
  const h = active.offsetHeight;

  const fromTf = pill.style.transform || `translate(0px, 0px)`;
  const fromW = pill.style.width || "0px";
  const fromH = pill.style.height || "0px";
  const toTf = `translate(${x}px, ${y}px)`;
  const toW = w + "px";
  const toH = h + "px";

  pill.style.opacity = "1";

  if (!animate || !pill.animate) {
    pill.style.transform = toTf;
    pill.style.width = toW;
    pill.style.height = toH;
    return;
  }

  // اندازه فوراً ست می‌شود تا layout thrash حذف شود
  pill.style.width = toW;
  pill.style.height = toH;

  if (!animate || !pill.animate) {
    pill.style.transform = toTf;
    pill._x = x;
    return;
  }

  // فقط transform انیمیت می‌شود (compositor-only، بدون reflow)
  try {
    pill.animate(
      [
        { transform: `translate(${fromTf.match(/-?\d+(\.\d+)?px/)?.[0] || "0px"}, ${y}px)` },
        { transform: toTf },
      ],
      { duration: 220, easing: "cubic-bezier(.22, 1, .36, 1)", fill: "none" },
    );
  } catch (_) {}

  pill.style.transform = toTf;
  pill._x = x;
}

export let _segResizeRaf = 0;
export function _handleSegResize() {
  if (_segResizeRaf) return;
  _segResizeRaf = requestAnimationFrame(() => {
    _segResizeRaf = 0;
    if (!document.getElementById("setSheetBack")) return;
    _initSegPills();
  });
}

