export function _bindAdvancedSection() {
  const root = _sr();
  
  if (!_advSub) {
    root.querySelectorAll(".adv-menu-btn").forEach(btn => {
      btn.onclick = (e) => {
        e.preventDefault();
        _advSub = btn.dataset.adv;
        _subDir = "fwd";
        _showSettingsSection("advanced");
      };
    });
    return;
  }

  const $wipe = root.querySelector("#advWipe");
  const $container = root.querySelector("#stgContainer");

  if ($wipe)
    $wipe.onclick = async () => {
      const ok = await uiConfirm({
        title: "پاک‌سازی کامل",
        danger: true,
        message: "همهٔ داده‌های این برنامه — مطالعه، حل، نشانک، یادداشت، دفتر اشتباهات، مرور، تسک‌ها، حساب محلی و تنظیمات — پاک شود؟<br><b>این عمل قابل بازگشت نیست.</b>",
        okText: "پاک کن",
        iconSvg: icon("warn"),
      });
      if (!ok) return;
      try {
        const ns = NS();
        const keys = [];
        for (let i = 0; i < localStorage.length; i++) {
          const k = localStorage.key(i);
          if (k && k.startsWith(ns)) keys.push(k);
        }
        keys.forEach((k) => lsDel(k));
      } catch (_) {}
      if (typeof toast === "function") toast("همهٔ داده‌ها پاک شد", "ok");
      setTimeout(() => location.reload(), 700);
    };

  if ($container) {
    $container.onclick = async (e) => {
      const btn = e.target.closest("[data-del-key]");
      if (!btn) return;
      const key = btn.dataset.delKey;
      const ok = await uiConfirm({
        title: "حذف داده",
        message: "آیا از حذف این بخش از حافظه مطمئن هستید؟",
        okText: "حذف",
        danger: true,
      });
      if (!ok) return;
      lsDel(key);
      if (typeof toast === "function") toast("داده حذف شد", "ok");
      $container.innerHTML = _renderStorageUI();
      const newWipe = $container.querySelector("#advWipe");
      if (newWipe && $wipe) newWipe.onclick = $wipe.onclick;
    };
  }
}

