export function _settingsActiveId(initialSec) {
  // گرفتن لیست همه تب‌ها بر اساس ترتیبی که در منو می‌بینی
  const sections = _allSections();
  const allIds = sections.map((s) => (s.kind === "pref" ? s.group.id : s.sec.id));
  
  // اگر لینک مستقیمی در آدرس بود (مثلاً از داخل دکمه‌ای در برنامه)
  if (initialSec && allIds.includes(initialSec)) {
    return initialSec;
  }
  
  // در غیر این صورت، همیشه به اولین تب در منو (که «حساب کاربری» است) برگرد
  return allIds[0] || "account";
}

