/* core.js declares readSet as a null-initialised let and assigns the Set later in ensureStore(). */
function readSetNow(): Set<string> {
  return readSet as unknown as Set<string>;
}

export function prefStorageKey(key: string): string {
  return K.pref(key);
}

export function getPref(key: string, def: string): string {
  return lsGet(prefStorageKey(key), "") || def;
}

export function setPref(key: string, value: string): void {
  lsSet(prefStorageKey(key), value);

  const html = document.documentElement;
  const allowSmooth =
    key !== "theme" &&
    key !== "motion" &&
    html.getAttribute("data-motion") !== "off" &&
    !(
      typeof window.matchMedia === "function" &&
      matchMedia("(prefers-reduced-motion: reduce)").matches
    );
  if (allowSmooth) {
    html.classList.add("pref-changing");
    clearTimeout(window._prefChangingTimer);
    window._prefChangingTimer = setTimeout(() => {
      html.classList.remove("pref-changing");
    }, 480);
  }

  applyPrefs();
  if (key === "preset" && location.hash.indexOf("#/settings") === 0) {
    if (typeof pageSettings === "function") {
      let sub: string | null = null;
      try {
        sub = sessionStorage.getItem("lector:settings:active");
      } catch {}
      pageSettings(sub);
    }
  }
}

export function resolveTheme(val: string): string {
  if (val === "system") {
    return typeof window.matchMedia === "function" &&
      matchMedia("(prefers-color-scheme: dark)").matches
      ? "dark"
      : "light";
  }
  return val;
}

export let _lastResolvedTheme: string | null = null;
export function applyPrefs(): void {
  if (typeof PREFERENCES === "undefined") return;
  const html = document.documentElement;
  const newTheme = resolveTheme(getPref("theme", "system"));
  const currentTheme = html.getAttribute("data-theme");
  const changed = currentTheme !== newTheme;
  if (changed && typeof Motion !== "undefined" && Motion.withInstant) {
    Motion.withInstant(() => {});
  } else if (changed) {
    html.classList.add("theme-instant");
    void html.offsetWidth;
  }

  html.removeAttribute("data-palette");

  PREFERENCES.forEach((group) => {
    group.items.forEach((item) => {
      const val = getPref(item.key, Presentation.prefDefault(item.key, item.default));
      if (item.key === "theme") {
        html.setAttribute("data-theme", resolveTheme(val));
        return;
      }
      html.setAttribute("data-" + item.key, val);
    });
  });

  _lastResolvedTheme = newTheme;

  // data-fx-eff: سطح واقعی جلوه‌ها (خودکار/کامل/سبک) — Fx رویداد lector:fx را هم می‌فرستد
  if (typeof Fx !== "undefined") Fx.apply(getPref("fx", "auto"));
  else window.dispatchEvent(new Event("lector:fx"));

  if (typeof applyThemePreset === "function") applyThemePreset();

  Presentation.apply(html);

  const bt = document.getElementById("themeToggle");
  if (bt && typeof icon === "function") {
    bt.innerHTML = icon(newTheme === "light" ? "sun" : "moon");
    bt.setAttribute("aria-label", newTheme === "light" ? "پوستهٔ تاریک" : "پوستهٔ روشن");
  }

  if (typeof syncFavicon === "function") syncFavicon();

  if (changed) {
    if (typeof Motion === "undefined" || !Motion.withInstant) {
      requestAnimationFrame(() =>
        requestAnimationFrame(() => {
          html.classList.remove("theme-instant");
        }),
      );
    }
    window.dispatchEvent(new Event("lector:theme"));
  }
}

export function watchSystemTheme(): void {
  if (!window.matchMedia) return;
  const mq = matchMedia("(prefers-color-scheme: dark)");
  const handler = () => {
    if (getPref("theme", "system") !== "system") return;
    applyPrefs();
    const bt = document.getElementById("themeToggle");
    if (bt)
      bt.innerHTML = icon(
        document.documentElement.getAttribute("data-theme") === "light" ? "sun" : "moon",
      );
    if (typeof reRenderMmd === "function") reRenderMmd();
  };
  if (typeof mq.addEventListener === "function") mq.addEventListener("change", handler);
  else if (typeof mq.addListener === "function") mq.addListener(handler);
}

export function migrateOldPrefs() {
  const old = lsGet(K.theme(), "");
  if (!old) return;
  if (!lsGet(prefStorageKey("theme"), "")) lsSet(prefStorageKey("theme"), old);
  lsDel(K.theme());
}

export function roadmapMermaid(ch: RoadmapChapter[]): string {
  const lab = (c: RoadmapChapter, i: number): string =>
    `F${i}["فصل ${toFa(c.n)} · ${String(c.short || c.t)
      .replace(/["#<>\[\]{}()]/g, " ")
      .trim()}"]`;
  return "flowchart LR\n " + ch.map((c, i) => (i ? `F${i - 1} --> ` : "") + lab(c, i)).join("\n ");
}

