(function () {
  "use strict";
  const K = window.PackWidgetKit;
  const wpal = K.wpal;
  let P = wpal();
  globalThis.addEventListener("lector:theme", () => {
    P = wpal();
  });
  const W = {
    title: "تابش جسم سیاه — قانون وین",
    desc: "با تغییر دما، جابه‌جایی پیک طیف را ببینید؛ منحنی چشم نیز قابل مقایسه است.",
    sess: ["s02", "s04"],
    mount(box) {
      box.innerHTML = `<div class="wgrid" style="--wctl:240px"><div class="wstage"><canvas width="640" height="330"></canvas></div><div><div class="ctls"></div><div class="winfo"></div><label style="display:flex;gap:8px;align-items:center;font-size:13px;color:var(--text-secondary);margin-top:8px;cursor:pointer"><input type="checkbox" id="bbEye" checked> نمایش منحنی حساسیت چشم</label></div></div>`;
      const cv = box.querySelector("canvas"),
        ct = box.querySelector(".ctls"),
        info = box.querySelector(".winfo"),
        eye = box.querySelector("#bbEye");
      const x = setupHD(cv, 640, 330);
      let T = 5500;
      ctl(ct, "دمای جسم سیاه", 1000, 12000, 50, 5500, "K", (v) => {
        T = v;
        draw();
      });
      eye.onchange = draw;
      function planck(l, T) {
        const c2 = 0.014388;
        return Math.pow(l, -5) / (Math.exp(c2 / (l * T)) - 1);
      }
      function kelvin(k) {
        k /= 100;
        let r, g, b;
        r = k <= 66 ? 255 : 329.7 * Math.pow(k - 60, -0.1332);
        g = k <= 66 ? 99.47 * Math.log(k) - 161.12 : 288.12 * Math.pow(k - 60, -0.0755);
        b = k >= 66 ? 255 : k <= 19 ? 0 : 138.52 * Math.log(k - 10) - 305.04;
        const c = (v) => Math.max(0, Math.min(255, Math.round(v)));
        return [c(r), c(g), c(b)];
      }
      function draw() {
        P = wpal();
        x.clearRect(0, 0, 640, 330);
        x.fillStyle = P.bg;
        x.fillRect(0, 0, 640, 330);
        const padL = 50,
          padR = 20,
          padT = 24,
          padB = 40,
          W = 640 - padL - padR,
          H = 330 - padT - padB;
        const lmin = 100e-9,
          lmax = 3000e-9;
        const lam = 2.898e-3 / T,
          Bm = planck(lam, T);
        x.strokeStyle = P.axis;
        x.lineWidth = 1;
        x.beginPath();
        x.moveTo(padL, padT);
        x.lineTo(padL, padT + H);
        x.lineTo(padL + W, padT + H);
        x.stroke();
        x.fillStyle = P.dim;
        x.font = "10.5px Vazirmatn";
        x.textAlign = "center";
        for (let l = 500; l <= 3000; l += 500) {
          const px = padL + ((l * 1e-9 - lmin) / (lmax - lmin)) * W;
          x.fillText(toFa(l) + " nm", px, 330 - 18);
          x.strokeStyle = "rgba(103,115,155,.18)";
          x.beginPath();
          x.moveTo(px, padT);
          x.lineTo(px, padT + H);
          x.stroke();
        }
        const px2 = (py) => padL + ((py - 200e-9) / 2800e-9) * W,
          py2 = (v) => padT + H - (v / Bm) * H * 0.82;
        if (eye.checked) {
          x.strokeStyle = "rgba(251,191,36,.65)";
          x.setLineDash([5, 5]);
          x.beginPath();
          for (let l = 380; l <= 700; l += 4) {
            const v = Math.exp(-Math.pow(l - 555, 2) / (2 * 42 * 42));
            const X = px2(l * 1e-9),
              Y = padT + H - v * H * 0.75;
            l === 380 ? x.moveTo(X, Y) : x.lineTo(X, Y);
          }
          x.stroke();
          x.setLineDash([]);
        }
        const grd = x.createLinearGradient(padL, 0, padL + W, 0);
        grd.addColorStop(0, "#7c3aed");
        grd.addColorStop(0.25, "#3b82f6");
        grd.addColorStop(0.5, "#22d3ee");
        grd.addColorStop(0.7, "#34d399");
        grd.addColorStop(1, "#f59e0b");
        x.strokeStyle = grd;
        x.lineWidth = 2.6;
        x.beginPath();
        let started = false;
        for (let i = 0; i <= 300; i++) {
          const l = lmin + ((lmax - lmin) * i) / 300;
          const v = planck(l, T);
          if (v > Bm * 1.02) continue;
          const X = px2(l),
            Y = Math.max(padT, padT + H - (v / Bm) * H * 0.82);
          if (!started) {
            x.moveTo(X, Y);
            started = true;
          } else x.lineTo(X, Y);
        }
        x.stroke();
        const wx = px2(lam);
        if (wx > padL && wx < padL + W) {
          x.strokeStyle = "rgba(244,114,182,.7)";
          x.setLineDash([4, 4]);
          x.beginPath();
          x.moveTo(wx, padT);
          x.lineTo(wx, padT + H);
          x.stroke();
          x.setLineDash([]);
          x.fillStyle = "#f472b6";
          x.beginPath();
          x.arc(wx, py2(Bm), 4.5, 0, 7);
          x.fill();
          x.fillStyle = "#f472b6";
          x.font = "11px Vazirmatn";
          x.fillText("λ_max", wx, padT + 14);
        }
        const [cr, cg, cb] = kelvin(T);
        info.innerHTML = `<div class="row"><span>دمای جسم</span><b>${toFa(T)} کلوین</b></div>
  <div class="row"><span>طول‌موج بیشینه — وین</span><b>${toFa((lam * 1e9).toFixed(0))} نانومتر</b></div>
  <div class="row"><span>توان نسبی — $T^4$</span><b>${toFa(Math.pow(T / 5778, 4).toFixed(2))}× خورشید</b></div>
  <div class="row"><span>رنگ تقریبی</span><b><span style="display:inline-block;width:40px;height:15px;border-radius:5px;background:rgb(${cr},${cg},${cb});vertical-align:middle"></span></b></div>
  <div class="props"><span class="badge b-amb">مربع زیر منحنی ∝ $\\sigma T^4$</span></div>`;
        if (window.renderMathInElement)
          renderMathInElement(info, {
            delimiters: [{ left: "$", right: "$", display: false }],
            throwOnError: false,
          });
      }
      draw();
    },
  };
  CourseRuntime.registerPackSource("optics", { widgets: { blackbody: W } });
})();
