(function () {
  "use strict";
  const K = window.PackWidgetKit;
  const wpal = K.wpal;
  let P = wpal();
  globalThis.addEventListener("lector:theme", () => {
    P = wpal();
  });
  const wl2rgb = window.PackWidgetKit.wl2rgb;
  const W = {
    title: "دوشکاف یانگ و فریزهای تداخلی",
    desc: "فاصلهٔ نوارها $\\Delta y=\\lambda L/d$ — طول‌موج، فاصلهٔ شکاف‌ها و فاصلهٔ پرده را تغییر دهید.",
    sess: ["s02", "s06", "s15"],
    mount(box) {
      box.innerHTML = `<div class="wgrid" style="--wctl:280px">
  <div class="wstage" style="aspect-ratio: 680 / 380;"><canvas width="680" height="380"></canvas></div>
  <div>
  <div class="ctls"></div>
  <div class="winfo">
  <div class="row"><span>رنگ نور</span><b data-f="color">—</b></div>
  <div class="row"><span>فاصلهٔ نوارها Δy</span><b data-f="dy">—</b></div>
  <div class="row"><span>شرط نوار روشن</span><b data-f="bright"></b></div>
  <div class="row"><span>شرط نوار تاریک</span><b data-f="dark"></b></div>
  <div class="props">
  <span class="badge b-cyn">تداخل سازنده ← روشن</span>
  <span class="badge b-vio">تداخل ویرانگر ← تاریک</span>
  </div>
  </div>
  </div>
  </div>`;

      const cv = box.querySelector("canvas");
      const ctx = setupHD(cv, 680, 380);
      const ct = box.querySelector(".ctls");
      const colorEl = box.querySelector('[data-f="color"]');
      const dyEl = box.querySelector('[data-f="dy"]');
      const brightEl = box.querySelector('[data-f="bright"]');
      const darkEl = box.querySelector('[data-f="dark"]');

      if (window.katex) {
        try {
          katex.render("\\Delta = m\\lambda", brightEl, { throwOnError: false });
          katex.render("\\Delta = (m+\\tfrac12)\\lambda", darkEl, { throwOnError: false });
        } catch (_) {
          brightEl.textContent = "Δ = mλ";
          darkEl.textContent = "Δ = (m+½)λ";
        }
      } else {
        brightEl.textContent = "Δ = mλ";
        darkEl.textContent = "Δ = (m+½)λ";
      }

      let wl = 550,
        d = 0.2,
        L = 1.5;

      const CW = 680,
        CH = 380;
      const PAD_TOP = 30,
        PAD_BOT = 30;
      const STRIP_X = 20,
        STRIP_W = 130;
      const PLOT_X = 200,
        PLOT_W = 450;
      const PLOT_Y_TOP = PAD_TOP;
      const PLOT_Y_BOT = CH - PAD_BOT;
      const PLOT_H = PLOT_Y_BOT - PLOT_Y_TOP;
      const FIXED_VIEW_RANGE_MM = 15.0;

      let rafId = 0;
      function scheduleDraw() {
        if (rafId) return;
        rafId = requestAnimationFrame(() => {
          rafId = 0;
          if (!cv.isConnected) return;
          draw();
        });
      }

      function draw() {
        P = wpal();
        const dy_mm = ((wl * L) / d) * 1e-3;
        const [r, g, b] = wl2rgb(wl);
        const col = `rgb(${r},${g},${b})`;

        ctx.clearRect(0, 0, CW, CH);
        ctx.fillStyle = P.bg;
        ctx.fillRect(0, 0, CW, CH);

        for (let py = 0; py < PLOT_H; py++) {
          const y_mm = (py / PLOT_H - 0.5) * 2 * FIXED_VIEW_RANGE_MM;
          const phase = (Math.PI * y_mm) / dy_mm;
          const I = Math.pow(Math.cos(phase), 2);
          const intensity = 0.05 + 0.95 * Math.pow(I, 0.6);
          ctx.fillStyle = `rgba(${r},${g},${b},${intensity})`;
          ctx.fillRect(STRIP_X, PLOT_Y_TOP + py, STRIP_W, 1);
        }
        ctx.strokeStyle = P.axis;
        ctx.lineWidth = 1;
        ctx.strokeRect(STRIP_X + 0.5, PLOT_Y_TOP + 0.5, STRIP_W - 1, PLOT_H - 1);

        ctx.fillStyle = P.dim;
        ctx.font = "11px Vazirmatn";
        ctx.textAlign = "center";
        ctx.fillText("الگوی فریز", STRIP_X + STRIP_W / 2, PAD_TOP - 10);

        ctx.strokeStyle = P.axis;
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(PLOT_X + 0.5, PLOT_Y_TOP);
        ctx.lineTo(PLOT_X + 0.5, PLOT_Y_BOT);
        ctx.lineTo(PLOT_X + PLOT_W, PLOT_Y_BOT + 0.5);
        ctx.stroke();

        ctx.strokeStyle = P.grid;
        ctx.setLineDash([4, 4]);
        ctx.beginPath();
        ctx.moveTo(PLOT_X + PLOT_W / 2, PLOT_Y_TOP);
        ctx.lineTo(PLOT_X + PLOT_W / 2, PLOT_Y_BOT);
        ctx.stroke();
        ctx.setLineDash([]);

        ctx.fillStyle = P.dim;
        ctx.font = "10.5px Vazirmatn";
        ctx.textAlign = "left";
        ctx.fillText("مکان روی پرده", PLOT_X + 6, PAD_TOP - 10);

        ctx.textAlign = "center";
        ctx.font = "11px Vazirmatn";
        ctx.fillText("شدت I/I₀ (مقیاس ثابت)", PLOT_X + PLOT_W / 2, PLOT_Y_BOT + 22);

        ctx.strokeStyle = col;
        ctx.lineWidth = 2.5;
        ctx.beginPath();
        for (let py = 0; py <= PLOT_H; py++) {
          const y_mm = (py / PLOT_H - 0.5) * 2 * FIXED_VIEW_RANGE_MM;
          const phase = (Math.PI * y_mm) / dy_mm;
          const I = Math.pow(Math.cos(phase), 2);
          const X = PLOT_X + I * PLOT_W;
          const Y = PLOT_Y_TOP + py;
          if (py === 0) ctx.moveTo(X, Y);
          else ctx.lineTo(X, Y);
        }
        ctx.stroke();

        colorEl.textContent = `${toFa(wl)} نانومتر`;
        colorEl.style.color = col;
        dyEl.textContent = `${toFa(dy_mm.toFixed(2))} میلی‌متر`;
      }

      ctl(ct, "طول‌موج نور", 400, 700, 1, wl, "nm", (v) => {
        wl = v;
        scheduleDraw();
      });
      ctl(ct, "فاصلهٔ شکاف‌ها d", 0.05, 0.6, 0.01, d, "mm", (v) => {
        d = v;
        scheduleDraw();
      });
      ctl(ct, "فاصلهٔ پرده L", 0.5, 3, 0.1, L, "m", (v) => {
        L = v;
        scheduleDraw();
      });

      draw();
    },
  };
  CourseRuntime.registerPackSource("optics", { widgets: { young: W } });
})();
