export function exportBackup() {
  const prefs = {};
  if (typeof PREFERENCES !== "undefined") {
    PREFERENCES.forEach((group) =>
      group.items.forEach((item) => {
        prefs[item.key] = getPref(item.key, Presentation.prefDefault(item.key, item.default));
      }),
    );
  }
  const _loadObj = (fn, fallback) => {
    try {
      return typeof fn === "function" ? fn() || fallback : fallback;
    } catch (_) {
      return fallback;
    }
  };
  const _loadArr = () => {
    try {
      return JSON.parse(lsGet(K.recent(), "[]")) || [];
    } catch (_) {
      return [];
    }
  };
  const data = {
    ver: 4,
    id: NS(),
    date: new Date().toISOString(),
    title: (CourseRuntime.getCourse() || {}).meta.appName,
    read: [...readSet],
    solved: [...solvedSet],
    prefs,
    bookmarks: _loadObj(typeof loadBookmarks === "function" ? loadBookmarks : null, {}),
    notes: _loadObj(typeof loadNotes === "function" ? loadNotes : null, {}),
    mistakes: _loadObj(typeof loadMistakes === "function" ? loadMistakes : null, {}),
    review: _loadObj(typeof loadReviewState === "function" ? loadReviewState : null, {}),
    recent: _loadArr(),
  };
  try {
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `${NS()}-backup-${new Date().toISOString().slice(0, 10)}.json`;
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(url);
    if (typeof toast === "function") toast("فایل پشتیبان دانلود شد");
  } catch (e) {
    if (typeof toast === "function") toast("پشتیبان‌گیری ناموفق ✕");
  }
}

// پشتیبان ناامن است: فقط آبجکت ساده، کلیدهای مجاز، و حد اندازه؛ مقدارهای نامعتبر دور ریخته می‌شوند
export const _BK_MAX_KEYS = 5000;
export const _BK_MAX_TEXT = 20000;
export function _bkPlain(v) {
  return v && typeof v === "object" && !Array.isArray(v);
}
export function _bkClean(obj, { textOnly } = {}) {
  if (!_bkPlain(obj)) return {};
  const out = {};
  let n = 0;
  for (const k of Object.keys(obj)) {
    if (k === "__proto__" || k === "constructor" || k === "prototype") continue;
    if (++n > _BK_MAX_KEYS) break;
    const v = obj[k];
    if (textOnly) {
      if (typeof v === "string") out[k] = v.slice(0, _BK_MAX_TEXT);
    } else if (_bkPlain(v) || typeof v === "string" || typeof v === "number" || typeof v === "boolean") {
      out[k] = v;
    }
  }
  return out;
}
export function importBackup(file) {
  if (!file) return;
  if (file.size > 5 * 1024 * 1024) {
    if (typeof toast === "function") toast("فایل پشتیبان بیش از حد بزرگ است", "err");
    return;
  }
  const r = new FileReader();
  r.onload = (e) => {
    try {
      const d = JSON.parse(e.target.result);
      if (!d || !Array.isArray(d.read) || !Array.isArray(d.solved)) throw new Error("bad");
      if (d.id && d.id !== NS()) {
        if (typeof toast === "function") toast(`این پشتیبان مربوط به «${d.title || d.id}» است ✕`);
        return;
      }
      readSet.clear();
      d.read.forEach((x) => typeof x === "string" && readSet.add(x));
      solvedSet.clear();
      d.solved.forEach((x) => typeof x === "string" && solvedSet.add(x));
      saveRead();
      saveSolved();

      if (d.ver >= 4) {
        if (_bkPlain(d.bookmarks) && typeof saveBookmarks === "function") {
          saveBookmarks(_bkClean(d.bookmarks));
        }
        if (_bkPlain(d.notes) && typeof saveNotes === "function") {
          saveNotes(_bkClean(d.notes, { textOnly: true }));
        }
        if (_bkPlain(d.mistakes) && typeof saveMistakes === "function") {
          saveMistakes(_bkClean(d.mistakes));
        }
        if (_bkPlain(d.review) && typeof saveReviewState === "function") {
          saveReviewState(_bkClean(d.review));
        }
        if (Array.isArray(d.recent)) {
          try {
            lsSet(K.recent(), JSON.stringify(d.recent.slice(0, 5)));
          } catch (_) {}
        }
      }

      if (d.prefs && typeof d.prefs === "object") {
        Object.entries(d.prefs).forEach(([k, v]) => {
          if (typeof v === "string") setPref(k, v);
        });
      } else if (typeof d.theme === "string" && (d.theme === "light" || d.theme === "dark")) {
        setPref("theme", d.theme);
      }
      const bt = document.getElementById("themeToggle");
      if (bt) bt.innerHTML = icon(getPref("theme", "dark") === "light" ? "sun" : "moon");

      refreshShellSidebar();
      updateProg();
      route();
      if (typeof toast === "function")
        toast(`بازیابی انجام شد — ${toFa(d.read.length)} جلسه و ${toFa(d.solved.length)} مسئله`);
    } catch (err) {
      if (typeof toast === "function") toast("فایل پشتیبان نامعتبر است ✕");
    }
  };
  r.readAsText(file);
}

