export function setActive(p) {
  if (p !== "settings") window._lastActiveKey = p;
  document.querySelectorAll(".navit").forEach((b) => b.classList.toggle("on", b.dataset.p === p));
}

// پیشرفت = نسبت مفاهیم «مسلط» (Phase 5). خواندن جلسه دیگر معیار نیست.
// محاسبهٔ مدل async است (IndexedDB)؛ آخرین گزارش در کش می‌ماند و بعد از هر تغییر دوباره محاسبه می‌شود.
export let _masteryCache = null;
export let _masteryBusy = false;
export let _masteryDirty = false;

export function updateProg() {
  renderProg();
  refreshMastery();
}

export function refreshMastery() {
  if (!window.LearningState || typeof LearningState.masteryReport !== "function") return;
  if (_masteryBusy) {
    _masteryDirty = true;
    return;
  }
  _masteryBusy = true;
  LearningState.masteryReport()
    .then((r) => {
      _masteryCache = r;
    })
    .catch(() => {})
    .finally(() => {
      _masteryBusy = false;
      renderProg();
      if (_masteryDirty) {
        _masteryDirty = false;
        refreshMastery();
      }
    });
}

export function masterySnapshot() {
  return _masteryCache;
}

export function renderProg() {
  const rep = _masteryCache && _masteryCache.report;
  const total = rep ? rep.total : 0;
  const mastered = rep ? rep.counts.mastered : 0;
  const target = total ? Math.round((mastered / total) * 100) : 0;

  const meter = document.getElementById("sbMeter");
  if (meter) meter.style.width = target + "%";
  const bar = document.querySelector(".sb-prog-bar");
  if (bar) bar.setAttribute("aria-valuenow", String(target));

  const meterTx = document.getElementById("sbMeterTx");
  if (meterTx) {
    meterTx.textContent = !rep
      ? "در حال محاسبه…"
      : total
        ? `${toFa(mastered)} از ${toFa(total)} مفهوم مسلط`
        : "بدون مفهوم قابل سنجش";
  }

  const arc = document.getElementById("sbProgArc");
  const pct = document.getElementById("sbProgPct");
  if (arc) {
    const R = 15;
    const Circ = 2 * Math.PI * R;
    arc.style.strokeDasharray = Circ;
    arc.style.strokeDashoffset = Circ * (1 - target / 100);
  }
  if (pct) pct.textContent = toFa(target) + "٪";
}

