export function _parseHash(hash) {
  const h = (hash || "").replace(/^#\/?/, "");
  if (!h) return { view: "home" };
  const parts = h.split("/");

  if (parts[0] === "p" && parts[1]) {
    const packId = decodeURIComponent(parts[1]);
    if (parts[2] === "s" && parts[3]) {
      const raw = decodeURIComponent(parts[3]);
      const at = raw.indexOf("@");
      const sid = at >= 0 ? raw.slice(0, at) : raw;
      const anchor = at >= 0 ? raw.slice(at + 1) : null;
      return { view: "session", packId, sid, anchor };
    }
    if (parts[2] === "progress") return { view: "pack-progress", packId };
    if (parts[2]) return { view: "pack-unknown", packId, sub: parts[2] };
    return { view: "pack", packId };
  }

  if (parts[0] === "s" && parts[1]) {
    const raw = decodeURIComponent(parts[1]);
    const at = raw.indexOf("@");
    const sid = at >= 0 ? raw.slice(0, at) : raw;
    const anchor = at >= 0 ? raw.slice(at + 1) : null;
    return { view: "session", sid, anchor, legacy: true };
  }

  return { view: parts[0], sub: parts[1] || null };
}

export function _renderRoute(h) {
  const r = _parseHash(h);
  if (r.view !== "settings" && typeof closeSettingsSheet === "function") closeSettingsSheet();

  if (r.packId && r.packId !== CourseRuntime.getActivePackId()) {
    const switched = CourseRuntime.activatePack(r.packId);
    if (switched) {
      if (typeof applyPrefs === "function") applyPrefs();
      if (typeof applyBrand === "function") applyBrand();
      refreshShellSidebar();
    }
  }
  const guards = {
    lab: "labs",
    problems: "problems",
    review: "review",
    exam: "exam",
    graph: "graph",
    glossary: "glossary",
    refs: "refs",
  };

  if (r.view === "home") {
    pageHome();
    setActive("home");
  } else if (r.view === "library") {
    if (typeof pageLibrary === "function") pageLibrary();
    else pageHome();
    setActive("library");
  } else if (r.view === "shop") {
    if (!flagOn("shop")) {
      location.hash = "#/home";
      return;
    }
    if (typeof pageShop === "function") pageShop();
    else pageHome();
    setActive("shop");
  } else if (r.view === "pack") {
    if (typeof pagePackOverview === "function") pagePackOverview(r.packId);
    else pageHome();
    setActive("home");
  } else if (r.view === "pack-progress") {
    if (typeof pagePackOverview === "function") pagePackOverview(r.packId);
    setActive("home");
  } else if (r.view === "pack-unknown") {
    pageDisabled(r.sub, "این مسیر");
    setActive("home");
  } else if (r.view === "session") {
    pageSession(r.sid, r.anchor);
    setActive("s/" + r.sid);
  } else if (r.view === "progress") {
    if (typeof pageProgress === "function") pageProgress();
    else pageDisabled("progress", "پیشرفت");
    setActive("progress");
  } else if (r.view === "plan") {
    if (typeof pagePlan === "function") pagePlan();
    else pageDisabled("plan", "برنامه‌ریز");
    setActive("plan");
  } else if (r.view === "settings") {
    if (!window._lastRouteHash && typeof pageHome === "function") pageHome();
    openSettingsSheet(r.sub);
    setActive("settings");
  } else if (r.view === "guide" || r.view === "D_E_V" || r.view === "exportDEV") {
    const tab = r.view === "exportDEV" ? "g-export" : r.sub || null;
    if (typeof pageDEV === "function") pageDEV(tab);
    else pageDisabled(r.view, "این مسیر");
  } else if (guards[r.view]) {
    const feat = guards[r.view];
    if (!featureEnabled(feat)) {
      pageDisabled(feat);
      setActive(r.view);
    } else if (r.view === "lab") {
      pageLab();
      setActive("lab");
    } else if (r.view === "problems") {
      pageProblems();
      setActive("problems");
    } else if (r.view === "refs") {
      pageRefs();
      setActive("refs");
    } else if (r.view === "glossary") {
      pageGlossary();
      setActive("glossary");
    } else if (r.view === "review" && typeof pageReview === "function") {
      pageReview();
      setActive("review");
    } else if (r.view === "exam" && typeof pageExam === "function") {
      pageExam();
      setActive("exam");
    } else if (r.view === "graph" && typeof pageGraph === "function") {
      pageGraph();
      setActive("graph");
    } else {
      pageDisabled(feat);
      setActive(r.view);
    }
  } else {
    pageDisabled(r.view, "این مسیر");
    setActive("home");
  }
}

export function goSession(packId, sid, anchor) {
  const id = packId || CourseRuntime.getActivePackId();
  const base = id
    ? "p/" + encodeURIComponent(id) + "/s/" + encodeURIComponent(sid)
    : "s/" + encodeURIComponent(sid);
  go(anchor ? base + "@" + anchor : base);
}
window.goSession = goSession;

// ناحیهٔ اسکرول‌پذیر (فرمول بلند، جدول، کد) باید با صفحه‌کلید هم در دسترس باشد (WCAG 2.1.1).
// بعد از رندر و بعد از KaTeX تأخیری بررسی می‌شود؛ فقط ناحیه‌هایی که واقعاً سرریز دارند.
// خواندن‌ها اول و نوشتن‌ها بعد: نوشتن وسط خواندن‌ها هر بار layout اجباری می‌سازد (در صفحهٔ مسئله‌ها ~۴۰٪ زمان).
export function markScrollRegions() {
  const nodes = document.querySelectorAll(".katex-display, pre, .tbl-wrap");
  const pending = [];
  nodes.forEach((el) => {
    if (!el.hasAttribute("tabindex") && el.scrollWidth > el.clientWidth + 1) pending.push(el);
  });
  pending.forEach((el) => el.setAttribute("tabindex", "0"));
}

export function route() {
  const _idle = (fn) => (window.requestIdleCallback ? requestIdleCallback(fn, { timeout: 1500 }) : setTimeout(fn, 300));
  setTimeout(() => _idle(markScrollRegions), 300);
  try { _ovReconcile(); } catch (_) {}
  try {
    if (typeof window.paletteClose === "function") window.paletteClose();
  } catch (_) {}
  if (typeof window._sessCleanup === "function") {
    try {
      window._sessCleanup();
    } catch (_) {}
    window._sessCleanup = null;
  }
  if (typeof cleanupWidgets === "function") cleanupWidgets();

  const h = location.hash.replace(/^#\//, "");
  const inSess = h.startsWith("s/");
  document.body.classList.toggle("in-session", inSess);
  if (window.SessionRail) window.SessionRail.sync(h);

  if (!h.startsWith("settings")) window._lastRouteHash = location.hash || "#/home";
  _renderRoute(h);
  if (typeof checkTaskReminders === "function") {
    try {
      checkTaskReminders();
    } catch (_) {}
  }

  if (typeof stagger === "function") {
    const mainEl = document.getElementById("main");
    if (mainEl) stagger(mainEl);
  }

  const key = location.hash || "#/home";
  const mem = _scrollMem[key];
  requestAnimationFrame(() => {
    if (!_explicitNav && typeof mem === "number" && mem > 0) {
      // بازگشت به محل قبلی: اول از ابتدای صفحه شروع می‌کنیم و نرم به محل قبلی می‌رویم
      window.scrollTo({ top: 0, behavior: "instant" });
      setTimeout(() => window.scrollTo({ top: mem, behavior: "smooth" }), 140);
    } else {
      window.scrollTo(0, 0);
    }
    _explicitNav = false;
  });
}
export function go(p, anchor) {
  _saveScrollNow();
  _explicitNav = true;
  location.hash = "#/" + (anchor ? p + "@" + anchor : p);
}
window.addEventListener("hashchange", route);

document.addEventListener("click", (e) => {
  const btn = e.target.closest(".btn");
  if (!btn) return;
  if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
  const r = btn.getBoundingClientRect();
  const d = Math.max(r.width, r.height);
  const span = document.createElement("span");
  span.className = "rip";
  span.style.width = span.style.height = d + "px";
  span.style.left = e.clientX - r.left - d / 2 + "px";
  span.style.top = e.clientY - r.top - d / 2 + "px";
  btn.appendChild(span);
  setTimeout(() => span.remove(), 620);
});

(function initGlobalProgress() {
  if (window._globalProgressReady) return;
  window._globalProgressReady = true;
  const bar =
    document.getElementById("readGlow") ||
    (() => {
      const b = document.createElement("div");
      b.id = "readGlow";
      b.className = "read-glow";
      b.innerHTML = "<i></i>";
      document.body.appendChild(b);
      return b;
    })();
  const fill = bar.querySelector("i");
  let raf = 0;
  function update() {
    raf = 0;
    const doc = document.documentElement;
    const total = Math.max(1, doc.scrollHeight - window.innerHeight);
    const p = Math.min(1, Math.max(0, window.scrollY / total));
    fill.style.transform = "scaleX(" + p.toFixed(4) + ")";
    bar.classList.toggle("show", total > 80);
  }
  const onScroll = () => {
    if (!raf) raf = requestAnimationFrame(update);
  };
  window.addEventListener("scroll", onScroll, { passive: true });
  window.addEventListener("resize", onScroll, { passive: true });
  new MutationObserver(onScroll).observe(document.getElementById("main"), { childList: true });
  update();
})();

export let _ovPushed = false;
export let _ovSelfBack = false;
export const _ovStack = [];

export function _ovLockScroll() {
  document.documentElement.classList.add("has-overlay");
  document.body.classList.add("has-overlay");
}
export function _ovUnlockScroll() {
  document.documentElement.classList.remove("has-overlay");
  document.body.classList.remove("has-overlay");
  try {
    document.documentElement.style.overflow = "";
    document.body.style.overflow = "";
  } catch (_) {}
}

/** آزادسازی قفل اسکرول وقتی هیچ overlay واقعی باز نیست (رفع گیر موبایل) */
export function _ovReconcile() {
  const sb = document.getElementById("sidebar");
  const sbOpen = !!(sb && sb.classList.contains("open"));
  const setOpen = document.body.classList.contains("set-sheet-open");
  const drawerOpen = document.body.classList.contains("drawer-open");
  const modalOpen = !!document.querySelector(
    ".hm-modal-back.open, .set-sheet-back.open, #dtpBack.open, #hmModalBack.open",
  );
  const scrimOn = !!document.querySelector("#shellScrim.on, .scrim.on");
  const pal = document.getElementById("palette");
  const palOpen = !!(pal && (pal.classList.contains("on") || pal.classList.contains("closing")));

  if (sbOpen || setOpen || drawerOpen || modalOpen || scrimOn || palOpen) return;

  if (_ovStack.length) _ovStack.length = 0;
  _ovPushed = false;
  _ovUnlockScroll();
  document.documentElement.classList.remove("pal-lock");
}

window._ovReconcile = _ovReconcile;

export function _ovOpen(closeFn) {
  _ovStack.push({ close: closeFn });
  if (_ovStack.length === 1) _ovLockScroll();
  if (!_ovPushed) {
    _ovPushed = true;
    try {
      history.pushState({ opticsOverlay: 1 }, "");
    } catch (_) {}
  }
}
export function _ovClose(silent, keepState) {
  const top = _ovStack.pop();
  if (top && top.close) top.close();
  if (_ovStack.length === 0) _ovUnlockScroll();
  
  if (_ovStack.length === 0 && _ovPushed) {
    _ovPushed = false; // همیشه ریست شود تا باگ پرتاپ شدن رخ ندهد
    if (!keepState) {
      if (silent) {
        try { history.replaceState(null, ""); } catch (_) {}
      } else {
        _ovSelfBack = true;
        try { history.back(); } catch (_) {}
      }
    } else {
      try { history.replaceState(null, ""); } catch (_) {}
    }
  }
}

export function _openSb() {
  const sb = $("#sidebar");
  if (!sb || sb.classList.contains("open")) return;
  sb.classList.add("open");
  _ovOpen(() => sb.classList.remove("open"));
}
export function _closeSb() {
  const sb = $("#sidebar");
  if (!sb || !sb.classList.contains("open")) return;
  _ovClose(false);
}
export function _closeSbSilent(keepState) {
  const sb = $("#sidebar");
  if (!sb) return;
  const wasOpen = sb.classList.contains("open");
  sb.classList.remove("open");
  const sc = $("#shellScrim");
  if (sc) sc.classList.remove("on");
  /* اگر از مسیر shell باز شده، استک _ov خالی است — فقط کلاس‌ها را بردار */
  if (wasOpen && _ovStack.length) {
    try {
      _ovClose(true, keepState === undefined ? true : keepState);
    } catch (_) {
      _ovUnlockScroll();
    }
  } else {
    _ovUnlockScroll();
  }
  try { _ovReconcile(); } catch (_) {}
}

window._ovOpen = _ovOpen;
window._ovClose = _ovClose;
window._closeSidebarSilent = _closeSbSilent;

window.__printDoc = function () {
  var opened = [];
  document.querySelectorAll("details:not([open])").forEach(function (d) {
    d.open = true;
    opened.push(d);
  });
  var remount = function () {
    if (typeof WidgetRegistry !== "undefined") WidgetRegistry.remount();
  };
  window.__APP_PRINTING = true;
  remount();
  var done = false;
  var finish = function () {
    if (done) return;
    done = true;
    window.__APP_PRINTING = false;
    remount();
    opened.forEach(function (d) {
      d.open = false;
    });
    opened = [];
  };
  window.addEventListener("afterprint", finish, { once: true });
  requestAnimationFrame(function () {
    requestAnimationFrame(function () {
      window.print();
    });
  });
};
