document.addEventListener("click", async (e) => {
  const sum = e.target.closest("summary");
  if (!sum) return;

  const d = sum.closest(
    "details.sol, details.sess-notes, details.sess-accordion, " +
      "details.fn, details[data-smooth]",
  );
  if (!d) return;

  const body = sum.nextElementSibling;
  if (!body || body.nodeType !== 1) return;

  if (d.dataset.anim === "1") return;
  e.preventDefault();
  d.dataset.anim = "1";

  const DUR = 240;
  const EASE = "cubic-bezier(.32, .72, 0, 1)";
  const M = typeof Motion !== "undefined" ? Motion : null;

  async function runAnim(frames) {
    if (M && typeof M.play === "function") {
      const a = M.play(body, frames, {
        duration: DUR,
        easing: EASE,
        fill: "forwards",
      });
      if (a && a.finished) {
        try {
          await a.finished;
        } catch (_) {}
      }
      return a;
    }
    await new Promise((r) => setTimeout(r, DUR));
    return null;
  }

  const cs = getComputedStyle(body);
  const PT = parseFloat(cs.paddingTop) || 0;
  const PB = parseFloat(cs.paddingBottom) || 0;

  try {
    if (d.open) {
      d.classList.add("closing");
      const h = Math.ceil(body.getBoundingClientRect().height);

      body.style.overflow = "hidden";
      body.style.height = h + "px";
      body.style.paddingTop = PT + "px";
      body.style.paddingBottom = PB + "px";
      body.style.opacity = "1";
      void body.offsetHeight;

      const a = await runAnim([
        {
          height: h + "px",
          paddingTop: PT + "px",
          paddingBottom: PB + "px",
          opacity: 1,
        },
        {
          height: "0px",
          paddingTop: "0px",
          paddingBottom: "0px",
          opacity: 0,
        },
      ]);

      d.open = false;
      if (a && typeof a.cancel === "function") a.cancel();
      body.style.cssText = "";
      d.classList.remove("closing");
    } else {
      d.open = true;

      body.style.overflow = "hidden";
      body.style.paddingTop = "0px";
      body.style.paddingBottom = "0px";
      body.style.height = "0px";
      body.style.opacity = "0";
      void body.offsetHeight;

      const natural = Math.ceil(body.scrollHeight);

      const a = await runAnim([
        {
          height: "0px",
          paddingTop: "0px",
          paddingBottom: "0px",
          opacity: 0,
        },
        {
          height: natural + PT + PB + "px",
          paddingTop: PT + "px",
          paddingBottom: PB + "px",
          opacity: 1,
        },
      ]);

      if (a && typeof a.cancel === "function") a.cancel();
      body.style.cssText = "";
    }
  } finally {
    d.dataset.anim = "0";
  }
});

export function getSessionWeight(session) {
  const concepts = (session.concepts || []).length;
  const formulas = (session.formulas || []).length;
  let problems = 0;
  if (Object.keys(CourseRuntime.getProblemRefs() || {}).length) {
    Object.values(CourseRuntime.getProblemRefs() || {}).forEach((refs) => {
      if (refs.some((r) => r[0] === session.id)) problems++;
    });
  }

  return Math.max(1, concepts * 2 + formulas * 3 + problems * 4);
}

