// API یکپارچهٔ وضعیت یادگیری (Learning state) — facade روی AttemptLog + Mastery + SRS.
//
// این فایل خالص است: بدون DOM، بدون import از core.js. همهٔ ورودی‌ها (لاگ، مجموعهٔ حل‌شده‌ها،
// رویدادهای فلش‌کارت، داده‌های پک) از بیرون و از طریق LearningStateDeps می‌آیند،
// پس createLearningState در Node با داده‌های ساختگی قابل تست است.
//
// وضعیت‌های موجود:
//   - خوانده‌شدن جلسه، حل‌شدن مسئله، اشتباه، نشانک، یادداشت: هنوز در core.js ذخیره می‌شوند
//     (کلیدها و قالب داده تغییر نکرده‌اند تا پیشرفت کاربران حفظ شود).
//   - تاریخچهٔ پاسخ‌ها: در IndexedDB (AttemptLog).
//
// installLearningStateGlobal (انتهای فایل) همان نام global «LearningState» را برای UI فعلی می‌سازد.
// این تنها جایی است که به globalهای قدیمی (CourseRuntime، getSolvedSet، …) وابسته است، و آن هم تنبل.

import {
  createDefaultLog,
  type Attempt,
  type AttemptInput,
  type AttemptLog,
  type AttemptSummary,
} from "./attempt-log.js";
import {
  buildReport,
  collect,
  nextSteps,
  type FlashEventInput,
  type MasteryReport,
  type NextStep,
  type PackInput,
  type ProblemInput,
  type ProblemState,
  type SectionInput,
  type SessionInput,
} from "./index.js";

// وضعیت یک مسئله: «حل‌شده» (علامت دستی)، «تلاش‌شده» (پاسخ ثبت شده)، یا «جدید».
export type ProblemStatus = "solved" | "attempted" | "new";

// خلاصهٔ تلاش‌ها برای یک مسئله (همان شکل AttemptSummary).
export type Summary = AttemptSummary;

// یک جلسه از پک، همراه با کارت‌های مرورپذیر.
export interface RuntimeSession extends SessionInput {
  title?: string;
  concepts?: { t?: string }[];
  formulas?: { t?: string; review?: boolean }[];
}

// نمای خام یک پک، همان چیزی که runtime می‌دهد.
export interface RuntimePackSnapshot {
  id: string;
  sessions: RuntimeSession[];
  knowledge: unknown;
  sections: SectionInput[];
  problems: ProblemInput[];
}

// وابستگی‌های تزریقی. همه تنبل‌اند: هر بار که لازم شوند خوانده می‌شوند.
export interface LearningStateDeps {
  openLog: () => AttemptLog;
  solvedIds: () => Set<string>;
  readIds: () => Set<string>;
  flashEvents: () => FlashEventInput[];
  packs: () => { packs: RuntimePackSnapshot[]; activePackId: string };
  now: () => number;
}

// نتیجهٔ masteryReport: گزارش تسلط، مسائل، و سه گام بعدی پیشنهادی.
export interface MasteryView {
  report: MasteryReport;
  problems: ProblemState[];
  next: NextStep[];
}

export interface LearningState {
  masteryReport(): Promise<MasteryView>;
  isSolved(pid: string): boolean;
  isRead(sid: string): boolean;
  problemStatus(pid: string): Promise<ProblemStatus>;
  recordAttempt(attempt: AttemptInput): Promise<Attempt>;
  attemptsFor(pid: string): Promise<Attempt[]>;
  summaryFor(pid: string): Promise<Summary>;
  storageBackend(): string;
  storageFellBack(): boolean;
}

// همان قاعدهٔ ساخت کارت در flashcards.js: متن یا فرمول بازبینی‌شونده.
export function hasFlashcards(s: RuntimeSession): boolean {
  const concepts = (s.concepts || []).some((c) => c && c.t);
  const formulas = (s.formulas || []).some((f) => f && f.t && f.review !== false);
  return concepts || formulas;
}

// تبدیل نمای runtime به ورودی MasteryModel.collect. فقط خواندن.
export function toPackInput(snap: RuntimePackSnapshot): PackInput {
  return {
    id: snap.id,
    sessions: snap.sessions.map((s) => ({
      id: s.id,
      title: s.title || s.id,
      hasCards: hasFlashcards(s),
    })),
    knowledge: Array.isArray(snap.knowledge) ? (snap.knowledge as PackInput["knowledge"]) : [],
    sections: snap.sections,
    problems: snap.problems.map((q) => ({
      id: q.id,
      title: q.title || q.id,
      section: q.section,
      concepts: Array.isArray(q.concepts) ? q.concepts : [],
    })),
  };
}

export function createLearningState(deps: LearningStateDeps): LearningState {
  let _log: AttemptLog | null = null;
  function log(): AttemptLog {
    if (!_log) _log = deps.openLog();
    return _log;
  }

  // وضعیت یک مسئله بر اساس داده‌های موجود.
  async function problemStatus(pid: string): Promise<ProblemStatus> {
    if (deps.solvedIds().has(pid)) return "solved";
    const s = await log().summary(pid);
    return s.attempts > 0 ? "attempted" : "new";
  }

  // ثبت یک پاسخ. فقط تاریخچه را می‌نویسد؛ علامت «حل‌شده» را تغییر نمی‌دهد.
  function recordAttempt(attempt: AttemptInput): Promise<Attempt> {
    return log().record(attempt);
  }

  // گزارش تسلط: universe مفاهیم، وضعیت هر مفهوم و تلاش‌های اخیر. فقط خواندن.
  async function masteryReport(): Promise<MasteryView> {
    const now = deps.now();
    const attempts = await log().all();
    const flashEvents = deps.flashEvents().filter((e) => e && e.t === "flash");
    const { packs, activePackId } = deps.packs();
    const data = collect({
      packs: packs.map(toPackInput),
      activePackId,
      attempts,
      flashEvents,
      solvedIds: deps.solvedIds(),
    });
    const report = buildReport({ units: data.units, evidence: data.evidence, now });
    return {
      report,
      problems: data.problems,
      next: nextSteps(report, { problems: data.problems, limit: 3 }),
    };
  }

  return Object.freeze({
    masteryReport,
    isSolved: (pid: string): boolean => deps.solvedIds().has(pid),
    isRead: (sid: string): boolean => deps.readIds().has(sid),
    problemStatus,
    recordAttempt,
    attemptsFor: (pid: string): Promise<Attempt[]> => log().forProblem(pid),
    summaryFor: (pid: string): Promise<Summary> => log().summary(pid),
    storageBackend: (): string => log().backend.name,
    storageFellBack: (): boolean => log().fellBack,
  });
}

// ── اتصال به globalهای قدیمی (فقط برای UI فعلی) ─────────────────────────
interface CourseIn {
  sessions?: RuntimeSession[];
  knowledge?: unknown;
}
interface CourseRuntimeLike {
  listRegisteredPacks(): { id: string }[] | null | undefined;
  getCourse(id: string): CourseIn | null | undefined;
  getProblemSections(id: string): SectionInput[] | null | undefined;
  getProblems(id: string): ProblemInput[] | null | undefined;
  getActivePackId(): string | null | undefined;
}
interface LegacyGlobals {
  CourseRuntime?: CourseRuntimeLike;
  getSolvedSet?: () => Set<string>;
  getReadSet?: () => Set<string>;
  loadEvents?: () => FlashEventInput[];
}

function snapshotRuntime(RT: CourseRuntimeLike | undefined): {
  packs: RuntimePackSnapshot[];
  activePackId: string;
} {
  if (!RT) return { packs: [], activePackId: "" };
  const packs: RuntimePackSnapshot[] = (RT.listRegisteredPacks() || []).map((p) => {
    const course: CourseIn = RT.getCourse(p.id) || {};
    return {
      id: p.id,
      sessions: course.sessions || [],
      knowledge: course.knowledge,
      sections: RT.getProblemSections(p.id) || [],
      problems: RT.getProblems(p.id) || [],
    };
  });
  return { packs, activePackId: RT.getActivePackId() || "" };
}

function legacyDeps(): LearningStateDeps {
  const g = globalThis as LegacyGlobals;
  return {
    openLog: () => createDefaultLog(),
    solvedIds: () => (typeof g.getSolvedSet === "function" ? g.getSolvedSet() : new Set()),
    readIds: () => (typeof g.getReadSet === "function" ? g.getReadSet() : new Set()),
    flashEvents: () => (typeof g.loadEvents === "function" ? g.loadEvents() : []),
    packs: () => snapshotRuntime(g.CourseRuntime),
    now: () => Date.now(),
  };
}

Object.assign(globalThis, { LearningState: createLearningState(legacyDeps()) });
