// پرچم‌های قابلیت (Feature flags) سراسری.
// هر پرچم یک تصمیم محصولی است؛ تغییر آن‌ها نباید نیاز به تغییر کد در جاهای دیگر داشته باشد.
//  shop                : فروشگاه در ناوبری و پالت فرمان نمایش داده نمی‌شود (کد آن حذف نشده است).
//  licenseEnforcement  : اگر false باشد، بنر «نیاز به لایسنس» هرگز نمایش داده نمی‌شود.
//  guard               : محافظت محتوا (غیرفعال‌سازی راست‌کلیک و میانبرها) — در حال حاضر فعال.

export interface FeatureFlags {
  shop: boolean;
  licenseEnforcement: boolean;
  guard: boolean;
}

export const FLAGS: Readonly<FeatureFlags> = Object.freeze({
  shop: false,
  licenseEnforcement: false,
  guard: true,
});

// وضعیت یک پرچم؛ نام ناشناخته (مثلاً از کد JS) همیشه false است
export function flagOn(name: keyof FeatureFlags): boolean {
  return Object.prototype.hasOwnProperty.call(FLAGS, name) && FLAGS[name] === true;
}

declare global {
  var LECTOR_FLAGS: Readonly<FeatureFlags>;
  var flagOn: (name: keyof FeatureFlags) => boolean;
}

globalThis.LECTOR_FLAGS = FLAGS;
globalThis.flagOn = flagOn;
