// گراف دانش (Knowledge graph): مفاهیم، پیش‌نیازهای ارجاعی و پیوند به جلسه/مسئله.
// خالص (بدون DOM و بدون storage) تا در Node قابل تست باشد.
//
// ورودی: آرایه‌ای از آیتم‌ها به شکل
//   { id, title, sessions: [sid], prereq: [id], problems: [pid] }
// خروجی: { nodes: Map, order: [id] | null, cycle: [id] | null, missing: [{id, ref}], errors: [{kind, id, msg}] }
// order: ترتیب مطالعه (پیش‌نیاز قبل از وابسته). اگر چرخه باشد null است.

// یک گرهٔ گراف پس از اعتبارسنجی.
export interface GraphNode {
  id: string;
  title: string;
  sessions: string[];
  prereq: string[];
  problems: string[];
}

// ارجاع پیش‌نیاز ناموجود.
export interface GraphMissing {
  id: string;
  ref: string;
}

// خطای ساخت گراف.
export interface GraphError {
  kind: "shape" | "id" | "duplicate";
  id?: string;
  msg: string;
}

export interface KnowledgeGraph {
  nodes: Map<string, GraphNode>;
  order: string[] | null;
  cycle: string[] | null;
  missing: GraphMissing[];
  errors: GraphError[];
}

// وضعیت دسترسی یک مفهوم.
export interface Availability {
  state: "ready" | "blocked" | "unknown";
  blockers: string[];
}

// شکل خام یک آیتم ورودی (پیش از اعتبارسنجی).
interface RawGraphItem {
  id?: unknown;
  title?: unknown;
  t?: unknown;
  sessions?: unknown;
  prereq?: unknown;
  problems?: unknown;
}

function strList(x: unknown): string[] {
  if (!Array.isArray(x)) return [];
  const out: string[] = [];
  (x as unknown[]).forEach((v) => {
    if (typeof v === "string" && v.trim()) out.push(v.trim());
  });
  return out;
}

export function buildKnowledgeGraph(items: unknown): KnowledgeGraph {
  const nodes = new Map<string, GraphNode>();
  const errors: GraphError[] = [];
  const list: unknown[] = Array.isArray(items) ? items : [];

  list.forEach((raw, i) => {
    if (!raw || typeof raw !== "object") {
      errors.push({ kind: "shape", msg: "آیتم #" + (i + 1) + " باید شیء باشد" });
      return;
    }
    const r = raw as RawGraphItem;
    const id = typeof r.id === "string" ? r.id.trim() : "";
    if (!id) {
      errors.push({ kind: "id", msg: "آیتم #" + (i + 1) + " شناسهٔ (id) ندارد" });
      return;
    }
    if (nodes.has(id)) {
      errors.push({ kind: "duplicate", id, msg: "شناسهٔ تکراری «" + id + "»" });
      return;
    }
    nodes.set(id, {
      id,
      title: String(r.title || r.t || id),
      sessions: strList(r.sessions),
      prereq: strList(r.prereq),
      problems: strList(r.problems),
    });
  });

  const missing: GraphMissing[] = [];
  nodes.forEach((n) => {
    n.prereq.forEach((ref) => {
      if (!nodes.has(ref)) missing.push({ id: n.id, ref });
    });
  });

  const cycle = findCycle(nodes);
  const order = cycle ? null : topoOrder(nodes);
  return { nodes, order, cycle, missing, errors };
}

// DFS با سه رنگ. اگر چرخه باشد، مسیر چرخه را برمی‌گرداند.
export function findCycle(nodes: Map<string, GraphNode>): string[] | null {
  const WHITE = 0;
  const GRAY = 1;
  const BLACK = 2;
  const color = new Map<string, number>();
  const stack: string[] = [];
  let found: string[] | null = null;

  function visit(id: string): boolean {
    color.set(id, GRAY);
    stack.push(id);
    const n = nodes.get(id);
    if (!n) return false;
    for (const ref of n.prereq) {
      if (!nodes.has(ref)) continue;
      const c = color.get(ref) || WHITE;
      if (c === GRAY) {
        const at = stack.indexOf(ref);
        found = stack.slice(at).concat(ref);
        return true;
      }
      if (c === WHITE && visit(ref)) return true;
    }
    stack.pop();
    color.set(id, BLACK);
    return false;
  }

  for (const id of nodes.keys()) {
    if ((color.get(id) || WHITE) === WHITE && visit(id)) return found;
  }
  return null;
}

// Kahn: پیش‌نیاز اول. ترتیب پایدار: با ترتیب ورود آیتم‌ها در ties.
export function topoOrder(nodes: Map<string, GraphNode>): string[] {
  const indeg = new Map<string, number>();
  const dependents = new Map<string, string[]>();
  nodes.forEach((_n, id) => {
    indeg.set(id, 0);
    dependents.set(id, []);
  });
  nodes.forEach((n, id) => {
    n.prereq.forEach((ref) => {
      if (!nodes.has(ref)) return;
      indeg.set(id, (indeg.get(id) ?? 0) + 1);
      dependents.get(ref)?.push(id);
    });
  });
  const queue: string[] = [];
  indeg.forEach((d, id) => {
    if (d === 0) queue.push(id);
  });
  const out: string[] = [];
  while (queue.length) {
    const id = queue.shift() as string;
    out.push(id);
    (dependents.get(id) ?? []).forEach((dep) => {
      indeg.set(dep, (indeg.get(dep) ?? 0) - 1);
      if (indeg.get(dep) === 0) queue.push(dep);
    });
  }
  return out;
}

// همهٔ پیش‌نیازهای غیرمستقیم یک مفهوم (بدون خود آن). ارجاع‌های ناموجود نادیده گرفته می‌شوند.
export function prerequisitesOf(graph: KnowledgeGraph, id: string): string[] {
  const out = new Set<string>();
  const walk = (cur: string): void => {
    const n = graph.nodes.get(cur);
    if (!n) return;
    n.prereq.forEach((ref) => {
      if (out.has(ref) || !graph.nodes.has(ref)) return;
      out.add(ref);
      walk(ref);
    });
  };
  walk(id);
  return [...out];
}

// وضعیت دسترسی یک مفهوم بر اساس مجموعهٔ مفاهیم تسلط‌یافته.
//  ready   : همهٔ پیش‌نیازهای مستقیم تسلط یافته‌اند
//  blocked : برخی پیش‌نیازها تسلط ندارند (blockers را برمی‌گرداند)
//  unknown : مفهوم در گراف نیست
export function availability(
  graph: KnowledgeGraph,
  id: string,
  masteredSet?: Set<string> | readonly string[] | null,
): Availability {
  const n = graph.nodes.get(id);
  if (!n) return { state: "unknown", blockers: [] };
  const mastered = masteredSet instanceof Set ? masteredSet : new Set(masteredSet || []);
  const blockers = n.prereq.filter((ref) => graph.nodes.has(ref) && !mastered.has(ref));
  return blockers.length ? { state: "blocked", blockers } : { state: "ready", blockers: [] };
}

// شکل کامل API (برای سازگاری با validate.ts که نوع آن را وارد می‌کند).
export interface KnowledgeGraphApi {
  buildKnowledgeGraph: typeof buildKnowledgeGraph;
  findCycle: typeof findCycle;
  topoOrder: typeof topoOrder;
  prerequisitesOf: typeof prerequisitesOf;
  availability: typeof availability;
}

// ── سازگاری با کد JS موجود: نام global «KnowledgeGraph» ───────────────
const legacyApi: KnowledgeGraphApi = Object.freeze({
  buildKnowledgeGraph,
  findCycle,
  topoOrder,
  prerequisitesOf,
  availability,
});
Object.assign(globalThis, { KnowledgeGraph: legacyApi });

