// رندررهای ریاضی (Phase 5.3): math و formula.
// خروجی فقط نشانه‌گذاری است. KaTeX در همان مسیر hydrate می‌شود که session.js برای
// .rd-math-body و data-tex دارد (deferKatexTex → katexRenderAsync). کارگر KaTeX در Phase 15 می‌آید.
import { escHtml } from "../escape.js";
import type { BlockMap, Renderer } from "../types.js";

export const renderMath: Renderer<BlockMap["math"]> = (b) => {
  const label = b.label ? `<span class="rd-math-lbl">${escHtml(b.label)}</span>` : "";
  return `<div class="rd-math" data-tex="${escHtml(b.tex || "")}">${label}<div class="rd-math-body" dir="ltr"></div></div>`;
};

export const renderFormula: Renderer<BlockMap["formula"]> = (b) =>
  `<div class="rd-formula" data-ref="${escHtml(b.ref || "")}"></div>`;
