(function () {
  "use strict";
  const K = window.PackWidgetKit;
  const wpal = K.wpal;
  let P = wpal();
  globalThis.addEventListener("lector:theme", () => {
    P = wpal();
  });
  const W = {
    title: "فازورها و برهم‌نهی دو موج",
    desc: "اختلاف فاز را تغییر دهید و ببینید چگونه فرمول برآیند رفتار می‌کند.",
    sess: ["s14"],
    mount(box) {
      box.innerHTML = `<div class="wgrid phasor-widget" style="--wctl:260px">
  <div class="wstage"><canvas width="460" height="360"></canvas></div>
  <div class="phasor-controls">
    <div class="ctls"></div>
    <div class="winfo"></div>
  </div>
</div>`;

      const cv = box.querySelector("canvas"),
        x = setupHD(cv, 460, 360),
        ct = box.querySelector(".ctls"),
        info = box.querySelector(".winfo");
      let d = 60,
        r = 1;

      ctl(ct, "اختلاف فاز δ", 0, 360, 2, 60, "°", (v) => {
        d = v;
        draw();
      });
      ctl(ct, "نسبت دامنهٔ موج ۲ به ۱", 0, 1.5, 0.05, 1, "", (v) => {
        r = v;
        draw();
      });

      function arrow(x1, y1, x2, y2, col, w = 3) {
        x.strokeStyle = col;
        x.lineWidth = w;
        x.beginPath();
        x.moveTo(x1, y1);
        x.lineTo(x2, y2);
        x.stroke();
        const a = Math.atan2(y2 - y1, x2 - x1);
        x.fillStyle = col;
        x.beginPath();
        x.moveTo(x2, y2);
        x.lineTo(x2 - 11 * Math.cos(a - 0.4), y2 - 11 * Math.sin(a - 0.4));
        x.lineTo(x2 - 11 * Math.cos(a + 0.4), y2 - 11 * Math.sin(a + 0.4));
        x.fill();
      }

      function draw() {
        P = wpal();
        x.fillStyle = P.bg;
        x.fillRect(0, 0, 460, 360);
        const cx = 230,
          cy = 180,
          L = 100;

        x.strokeStyle = P.grid;
        x.lineWidth = 1;
        x.beginPath();
        x.arc(cx, cy, L + 40, 0, 7);
        x.stroke();
        x.beginPath();
        x.moveTo(cx - L - 50, cy);
        x.lineTo(cx + L + 50, cy);
        x.moveTo(cx, cy - L - 50);
        x.lineTo(cx, cy + L + 50);
        x.stroke();

        const rad = (d * Math.PI) / 180;

        const e1x = cx + L,
          e1y = cy;
        arrow(cx, cy, e1x, e1y, "#fbbf24");

        const e2x = cx + L * r * Math.cos(rad);
        const e2y = cy - L * r * Math.sin(rad);
        arrow(cx, cy, e2x, e2y, "#a78bfa");

        const resX = cx + L + L * r * Math.cos(rad);
        const resY = cy - L * r * Math.sin(rad);
        arrow(cx, cy, resX, resY, "#22d3ee", 3.5);

        x.strokeStyle = "rgba(255,255,255,.15)";
        x.lineWidth = 1;
        x.setLineDash([4, 4]);
        x.beginPath();
        x.moveTo(e1x, e1y);
        x.lineTo(resX, resY);
        x.stroke();
        x.beginPath();
        x.moveTo(e2x, e2y);
        x.lineTo(resX, resY);
        x.stroke();
        x.setLineDash([]);

        x.strokeStyle = "rgba(34,211,238,.6)";
        x.lineWidth = 2;
        x.beginPath();
        x.arc(cx, cy, 40, 0, -rad, true);
        x.stroke();

        x.font = "bold 13px Vazirmatn";
        x.textAlign = "center";
        x.fillStyle = "#fbbf24";
        x.fillText("E₁", e1x + 15, e1y + 5);
        x.fillStyle = "#a78bfa";
        x.fillText("E₂", e2x + 15, e2y - 5);
        x.fillStyle = "#22d3ee";
        x.fillText("برآیند", resX + 20, resY);
        x.fillStyle = "#22d3ee";
        x.fillText("δ", cx + 50 * Math.cos(-rad / 2), cy + 50 * Math.sin(-rad / 2));

        const e0_sq = 1 + r * r + 2 * r * Math.cos(rad);
        const e0 = Math.sqrt(e0_sq);
        const i_coh = e0_sq;
        const i_incoh = 1 + r * r;

        info.innerHTML = `
  <div class="row"><span>دامنهٔ برآیند E₀/E₁</span><b>${toFa(e0.toFixed(2))}</b></div>
  <div class="row"><span>شدت همدوس — E₀²</span><b>${toFa(i_coh.toFixed(2))} × I₁</b></div>
  <div class="row"><span>شدت ناهمدوس — جمع</span><b>${toFa(i_incoh.toFixed(2))} × I₁</b></div>
  <div class="props">
  ${
    d === 0
      ? '<span class="badge b-grn">تداخل سازندهٔ کامل</span>'
      : d === 180 && Math.abs(r - 1) < 0.03
        ? '<span class="badge b-ros">تداخل ویرانگر کامل — خاموشی</span>'
        : '<span class="badge b-cyn">حالت بینابینی</span>'
  }
  </div>`;
      }
      draw();
    },
  };
  CourseRuntime.registerPackSource("optics", { widgets: { phasor: W } });
})();
