  function _syncTopbarHeight() {
    const h = document.querySelector("header.top");
    if (!h) return;
    const height = Math.round(h.getBoundingClientRect().height);
    if (height <= 0) return;
    const next = height + "px";
    if (document.documentElement.style.getPropertyValue("--topbar-h") === next) return;
    document.documentElement.style.setProperty("--topbar-h", next);
  }
  global._syncTopbarHeight = _syncTopbarHeight;

