  // ── اعلان‌ها ───────────────────────────────────────────────────
  // toast(msg, kind, opts)
  //   kind : ok | err | warn | info   (پیش‌فرض info)
  //   opts : { title, icon, action: { label, run }, sticky, duration }
  // قواعد: حداکثر TOAST_MAX پیام روی صفحه؛ پیام تکراری شمارش می‌شود نه کپی؛
  // تایمر و نوار پیشرفت با hover/focus مکث می‌شوند؛ خطا و هشدار بیشتر می‌مانند؛
  // sticky تا بسته‌شدن دستی یا اجرای اقدام می‌ماند.
  const TOAST_MAX = 3;
  const TOAST_ICON = { ok: "check", err: "close", warn: "warn", info: "sparkles" };
  const TOAST_DUR = { short: 2200, normal: 3700, long: 6500 };

  function mkEl(tag, cls, text) {
    const n = document.createElement(tag);
    if (cls) n.className = cls;
    if (text != null) n.textContent = text;
    return n;
  }

  function toast(msg, kind, opts) {
    kind = TOAST_ICON[kind] ? kind : "info";
    opts = opts || {};
    const host = $("#toasts");
    if (!host) return null;
    const text = String(msg == null ? "" : msg);
    const live = () => Array.from(host.children).filter((el) => !el._killed);

    const twin = live().find((el) => el.dataset.msg === text && el.dataset.kind === kind);
    if (twin) {
      twin._bump();
      return { dismiss: twin._kill };
    }

    const pref = typeof global.getPref === "function" ? global.getPref("notifyToast", "normal") : "normal";
    const base = TOAST_DUR[pref] || TOAST_DUR.normal;
    const urgent = kind === "err" || kind === "warn";
    const dur = opts.duration || (urgent ? Math.max(base, 5200) : base);

    while (live().length >= TOAST_MAX) {
      const pool = live();
      const victim = pool.find((el) => !el._sticky) || pool[0];
      victim._kill();
    }

    const t = mkEl("div", "toast " + kind);
    t.dataset.msg = text;
    t.dataset.kind = kind;
    t.dataset.n = "1";
    t.setAttribute("role", urgent ? "alert" : "status");
    t._sticky = !!opts.sticky;

    const ico = mkEl("span", "toast-ico");
    ico.setAttribute("aria-hidden", "true");
    ico.innerHTML = icon(opts.icon || TOAST_ICON[kind]);

    const body = mkEl("div", "toast-body");
    if (opts.title) body.appendChild(mkEl("div", "toast-title", String(opts.title)));
    body.appendChild(mkEl("div", "toast-tx", text));

    let act = null;
    if (opts.action) {
      act = mkEl("button", "toast-act", String(opts.action.label || "باشه"));
      act.type = "button";
      act.onclick = () => {
        try {
          if (opts.action.run) opts.action.run();
        } finally {
          t._kill();
        }
      };
    }

    const count = mkEl("span", "toast-count", "×۲");
    count.hidden = true;
    const close = mkEl("button", "toast-x");
    close.type = "button";
    close.setAttribute("aria-label", "بستن");
    close.innerHTML = icon("close");
    close.onclick = () => t._kill();

    const bar = mkEl("span", "toast-bar");
    bar.hidden = t._sticky;
    if (act) t.append(ico, body, act, count, close, bar);
    else t.append(ico, body, count, close, bar);
    t.style.setProperty("--toast-dur", dur + "ms");

    let timer = null;
    let left = dur;
    let startedAt = 0;
    let hot = false;
    let killed = false;

    const arm = () => {
      if (killed || t._sticky || hot) return;
      clearTimeout(timer);
      startedAt = Date.now();
      timer = setTimeout(() => t._kill(), left);
      bar.style.animationPlayState = "running";
    };
    const pause = () => {
      if (!timer) return;
      clearTimeout(timer);
      timer = null;
      left = Math.max(0, left - (Date.now() - startedAt));
      bar.style.animationPlayState = "paused";
    };

    t._bump = () => {
      const n = Number(t.dataset.n || 1) + 1;
      t.dataset.n = String(n);
      count.textContent = "×" + n.toLocaleString("fa-IR");
      count.hidden = false;
      left = dur;
      clearTimeout(timer);
      timer = null;
      bar.style.animation = "none";
      void bar.offsetWidth;
      bar.style.animation = "";
      if (hot) bar.style.animationPlayState = "paused";
      else arm();
    };

    // کشتن: flag همگام، سپس انیمیشن خروج و حذف
    t._kill = async () => {
      if (killed) return;
      killed = true;
      t._killed = true;
      clearTimeout(timer);
      try {
        const anim = global.Motion && global.Motion.toastExit ? global.Motion.toastExit(t) : null;
        if (anim && anim.finished) await anim.finished;
      } catch (_) {}
      t.remove();
    };

    t.addEventListener("pointerenter", () => {
      hot = true;
      pause();
    });
    t.addEventListener("pointerleave", () => {
      hot = false;
      if (!t.contains(document.activeElement)) arm();
    });
    t.addEventListener("focusin", () => {
      hot = true;
      pause();
    });
    t.addEventListener("focusout", (e) => {
      if (!t.contains(e.relatedTarget)) {
        hot = false;
        arm();
      }
    });

    host.appendChild(t);
    if (global.Motion && global.Motion.toastEnter) global.Motion.toastEnter(t);
    arm();
    return { dismiss: t._kill };
  }

  const palette = {
    items: [],
    sel: 0,
    filtered: [],
  };

  const PAL_HIST_KEY = "lector:palette:history";
  const PAL_HIST_MAX = 12;

  function _palNorm(s) {
    return String(s || "")
      .replace(/[۰-۹]/g, (d) => "۰۱۲۳۴۵۶۷۸۹".indexOf(d))
      .replace(/[٠-٩]/g, (d) => "٠١٢٣٤٥٦٧٨٩".indexOf(d))
      .toLowerCase()
      .replace(/\s+/g, " ")
      .trim();
  }

  function _palLoadHist() {
    try {
      const raw = localStorage.getItem(PAL_HIST_KEY);
      const arr = raw ? JSON.parse(raw) : [];
      return Array.isArray(arr) ? arr : [];
    } catch (_) {
      return [];
    }
  }

  function _palSaveHist(arr) {
    try {
      localStorage.setItem(PAL_HIST_KEY, JSON.stringify(arr.slice(0, PAL_HIST_MAX)));
    } catch (_) {}
  }

  function _palPushHist(it) {
    if (!it || it._ephemeral) return;
    const id = it.id || it.label;
    if (!id) return;
    const prev = _palLoadHist().filter((h) => h.id !== id);
    prev.unshift({
      id,
      label: it.label,
      icon: it.icon || "sparkles",
      section: it.section || "",
      hint: it.hint || "",
    });
    _palSaveHist(prev);
  }

  function _palParseTimer(q) {
    let s = _palNorm(q);
    s = s.replace(/^(تایمر|timer|t)\s*/i, "").replace(/\s+/g, "");
    if (!s) return null;
    const m = s.match(/^(\d{1,3})(?:\/(\d{1,3}))?(?:[x×*](\d{1,2}))?$/i);
    if (!m) return null;
    const focus = Math.min(120, Math.max(1, parseInt(m[1], 10) || 0));
    if (!focus) return null;
    const brk = m[2] != null ? Math.min(60, Math.max(1, parseInt(m[2], 10) || 5)) : null;
    const cycles = m[3] != null ? Math.min(12, Math.max(1, parseInt(m[3], 10) || 1)) : null;
    return { focus, brk, cycles, complete: true };
  }

  function _palTimerDraft(q) {
    const raw = _palNorm(q);
    if (!raw) return null;
    const hasPrefix = /^(تایمر|timer|t)(\s|$)/i.test(raw) || /^(تایمر|timer|t)/i.test(raw);
    const s = raw.replace(/^(تایمر|timer|t)\s*/i, "").replace(/\s+/g, "");
    if (!s && hasPrefix) return { kind: "help" };
    if (!s) return null;
    if (!/^[\d\/x×*]+$/i.test(s)) return null;
    const mFocus = s.match(/^(\d{1,3})(.*)$/);
    if (!mFocus) return hasPrefix ? { kind: "help" } : null;
    const focus = Math.min(120, Math.max(1, parseInt(mFocus[1], 10) || 0));
    if (!focus) return { kind: "help" };
    let rest = mFocus[2] || "";
    if (!rest) return { kind: "focus", focus };
    if (rest === "/") return { kind: "needBreak", focus };
    const mBrk = rest.match(/^\/(\d{0,3})(.*)$/);
    if (!mBrk) return { kind: "focus", focus };
    if (!mBrk[1]) return { kind: "needBreak", focus };
    const brk = Math.min(60, Math.max(1, parseInt(mBrk[1], 10) || 0));
    rest = mBrk[2] || "";
    if (!rest) return { kind: "focusBreak", focus, brk };
    if (/^[x×*]$/i.test(rest)) return { kind: "needCycles", focus, brk };
    const mCy = rest.match(/^[x×*](\d{0,2})$/i);
    if (mCy && !mCy[1]) return { kind: "needCycles", focus, brk };
    if (mCy && mCy[1]) {
      const cycles = Math.min(12, Math.max(1, parseInt(mCy[1], 10) || 1));
      return { kind: "full", focus, brk, cycles };
    }
    return { kind: "focusBreak", focus, brk };
  }

  function _palApplyTimer(cfg, andStart) {
    const nsFn =
      typeof global.NS === "function"
        ? global.NS
        : typeof window.NS === "function"
          ? window.NS
          : null;
    const ns = nsFn ? nsFn() : "course";
    const focus = Math.min(120, Math.max(1, Number(cfg.focus) || 25));
    const brkRaw =
      cfg.brk != null ? Number(cfg.brk) : Number(localStorage.getItem(ns + "PomoBreakMin") || 5);
    const cyRaw =
      cfg.cycles != null
        ? Number(cfg.cycles)
        : Number(localStorage.getItem(ns + "PomoCycles") || 4);
    const brk = Math.min(60, Math.max(1, brkRaw || 5));
    const cycles = Math.min(12, Math.max(1, cyRaw || 4));

    try {
      localStorage.setItem(ns + "PomoFocusMin", String(focus));
      localStorage.setItem(ns + "PomoBreakMin", String(brk));
      localStorage.setItem(ns + "PomoCycles", String(cycles));
    } catch (_) {}

    const st = {
      phase: "focus",
      cycle: 1,
      left: focus * 60,
      running: !!andStart,
      endTs: andStart ? Date.now() + focus * 60 * 1000 : 0,
    };
    try {
      sessionStorage.setItem(ns + "TimerState", JSON.stringify(st));
    } catch (_) {}

    if (typeof window._homeTimerSync === "function") {
      try {
        window._homeTimerSync();
      } catch (_) {}
    }
    try {
      window.dispatchEvent(new Event("lector:timer"));
    } catch (_) {}

    const fa = typeof toFa === "function" ? toFa : String;
    const lb = "تایمر " + fa(focus) + "/" + fa(brk) + " ×" + fa(cycles);
    if (typeof toast === "function") {
      toast(andStart ? lb + " — شروع شد" : lb + " ذخیره شد", "ok");
    }
  }

  function _palTimerItems(q) {
    const fa = typeof toFa === "function" ? toFa : String;
    const cfg = _palParseTimer(q);
    if (cfg) {
      const brk = cfg.brk != null ? cfg.brk : null;
      const cy = cfg.cycles != null ? cfg.cycles : null;
      const summary =
        fa(cfg.focus) +
        " دقیقه تمرکز" +
        (brk != null ? " · " + fa(brk) + " استراحت" : "") +
        (cy != null ? " · " + fa(cy) + " چرخه" : "");
      return [
        {
          id: "timer:set:" + cfg.focus + "/" + cfg.brk + "x" + cfg.cycles,
          icon: "bolt",
          label: "تنظیم تایمر — " + summary,
          hint: "فقط ذخیره",
          section: "تایمر",
          _ephemeral: true,
          run: () => _palApplyTimer(cfg, false),
        },
        {
          id: "timer:start:" + cfg.focus + "/" + cfg.brk + "x" + cfg.cycles,
          icon: "play",
          label: "شروع تایمر — " + summary,
          hint: "ذخیره و شروع",
          section: "تایمر",
          _ephemeral: true,
          run: () => _palApplyTimer(cfg, true),
        },
      ];
    }

    const d = _palTimerDraft(q);
    if (!d) return [];

    const tips = {
      help: "مثال: ۲۵   یا   ۲۵/۵   یا   ۲۵/۵×۴",
      focus: "ادامه بده: /۵ برای استراحت  ·  یا Enter همین الان",
      needBreak: "مدت استراحت را بنویس — مثلاً ۲۵/۵",
      focusBreak: "ادامه: ×۴ برای تعداد چرخه  ·  یا Enter همین الان",
      needCycles: "تعداد چرخه را بنویس — مثلاً ۲۵/۵×۴",
      full: "",
    };

    const items = [];
    items.push({
      id: "timer:guide",
      icon: "bolt",
      label: tips[d.kind] || tips.help,
      hint: "راهنما",
      section: "تایمر",
      _ephemeral: true,
      run: () => {
        if (typeof toast === "function") toast("الگو: تمرکز/استراحت×چرخه  —  مثال ۲۵/۵×۴", "ok");
      },
    });

    if (d.focus) {
      const partial = {
        focus: d.focus,
        brk: d.brk != null ? d.brk : null,
        cycles: d.cycles != null ? d.cycles : null,
      };
      const sum =
        fa(d.focus) +
        " دقیقه" +
        (d.brk != null ? " / " + fa(d.brk) : "") +
        (d.cycles != null ? " ×" + fa(d.cycles) : "");
      items.push({
        id: "timer:partial-set",
        icon: "bolt",
        label: "اعمال تا اینجا — " + sum,
        hint: "ذخیره",
        section: "تایمر",
        _ephemeral: true,
        run: () => _palApplyTimer(partial, false),
      });
      items.push({
        id: "timer:partial-start",
        icon: "play",
        label: "شروع با " + sum,
        hint: "شروع",
        section: "تایمر",
        _ephemeral: true,
        run: () => _palApplyTimer(partial, true),
      });
    }
    return items;
  }

  // قفل اسکرول پشت منوی فرمان: چرخ و لمس بیرون از فهرست گزینه‌ها بی‌اثر می‌شوند
  function _palScrollGuard(e) {
    const host = $("#palette");
    if (!host || !host.classList.contains("on") || host.classList.contains("closing")) return;
    if (!document.documentElement.classList.contains("pal-lock")) return;
    if (e.target && e.target.closest && e.target.closest(".pal-body")) return;
    e.preventDefault();
  }
  function _palLockScroll(on) {
    document.documentElement.classList.toggle("pal-lock", !!on);
  }

  function paletteBuild() {
    const host = $("#palette");
    if (!host) return;
    if (!palette.scrollGuardBound) {
      palette.scrollGuardBound = true;
      ["wheel", "touchmove"].forEach((t) =>
        document.addEventListener(t, _palScrollGuard, { passive: false, capture: true }),
      );
    }
    host.innerHTML = `
      <div class="pal-box pal-box--spot" id="palBox">
        <div class="pal-head pal-head--spot">
          ${icon("search")}
          <input class="pal-input" id="palInput"
                 placeholder="فرمان، جلسه، تایمر ۲۵/۵×۴…"
                 autocomplete="off" spellcheck="false" />
          <kbd class="pal-esc">Esc</kbd>
        </div>
        <div class="pal-body pal-body--spot" id="palBody"></div>
        <div class="pal-foot">
          <span><kbd>↑↓</kbd> حرکت</span>
          <span><kbd>↵</kbd> اجرا</span>
          <span><kbd>Esc</kbd> بستن</span>
          <span style="margin-inline-start:auto;opacity:.7"><kbd>~</kbd></span>
        </div>
      </div>
    `;

    const input = $("#palInput", host);
    input.addEventListener("input", () => palettePaint(input.value));
    host.addEventListener("click", (e) => {
      if (e.target === host) paletteClose();
    });
  }

