  function setActive(route) {
    const items = $$(".sb-item");
    if (!items.length) return;
    const first = (route || "").split("/")[0] || "home";

    let match = null;
    items.forEach((it) => {
      const r = it.dataset.route;
      const on = r === route || r === first || (first === "s" && r === "library");
      it.classList.toggle("active", on);
      if (on && !match) match = it;
    });

    const pill = $("#sbPill");
    if (!pill) return;
    if (!match) {
      pill.style.opacity = "0";
      return;
    }
    pill.style.top = match.offsetTop + "px";
    pill.style.height = match.offsetHeight + "px";
    pill.style.opacity = "1";
  }

