import { deferKatexTex, escHtml, formulaCard, katexifyText, toFa } from "../../core.js";
import { main } from "../../preferences/prefs.js";
import { icon } from "../components/icons.js";
export let _refsCols = 0;
export let _refsCat = "all";
// _refsMathIO حذف شد — deferKatex در core.js مدیریت می‌کند

export function pageRefs() {
  const categories = CourseRuntime.getCategories();
  const cats = [...Object.keys(categories), "__other"];
  const totalFormulas = ((CourseRuntime.getCourse() || {}).sessions || []).reduce(
    (a, s) => a + (s.formulas || []).length,
    0,
  );

  const catChips = ["all", ...cats]
    .map((c) => {
      const label = c === "all" ? "همه" : getCat(c).l;
      const on = _refsCat === c ? " on" : "";
      return `<button type="button" class="refs-chip${on}" data-refs-cat="${escHtml(c)}">${escHtml(label)}</button>`;
    })
    .join("");

  const colsChips = [
    { v: "0", t: "خودکار" },
    { v: "1", t: "۱ ستون" },
    { v: "2", t: "۲ ستون" },
    { v: "3", t: "۳ ستون" },
  ]
    .map((c) => {
      const on = String(_refsCols) === c.v ? " on" : "";
      return `<button type="button" class="refs-chip${on}" data-refs-cols="${c.v}">
      <span>${c.t}</span>
    </button>`;
    })
    .join("");

  const _formulasByCat = new Map();
  cats.forEach((cat) => _formulasByCat.set(cat, []));
  ((CourseRuntime.getCourse() || {}).sessions || []).forEach((s) => {
    (s.formulas || []).forEach((f, i) => {
      const cat = categories[f.cat] ? f.cat : "__other";
      _formulasByCat.get(cat).push({ f, s, i });
    });
  });

  main.innerHTML = `<div class="page refs-page">
    <header class="refs-hero">
      <span class="refs-kicker">${icon("sigma")}مرجع فرمول</span>
      <h1 class="refs-h1">مرجع سریع فرمول‌ها</h1>
      <p class="refs-sub">تمام روابط ${toFa(((CourseRuntime.getCourse() || {}).sessions || []).length)} جلسه به تفکیک موضوع</p>
    </header>

    <div class="refs-toolbar" role="toolbar" aria-label="کنترل‌های نمایش">
      <div class="refs-group" role="group" aria-label="فیلتر دسته">
        <span class="refs-lbl">دسته‌بندی</span>
        <div class="refs-chips">${catChips}</div>
      </div>
      <div class="refs-group refs-group--cols" role="group" aria-label="تعداد ستون">
        <span class="refs-lbl">چیدمان</span>
        <div class="refs-chips">${colsChips}</div>
      </div>
    </div>

    <div id="refsContainer"></div>
  </div>`;

  const _applyCols = () => {
    const cont = document.getElementById("refsContainer");
    if (!cont) return;
    if (_refsCols > 0) {
      cont.style.setProperty("--refs-cols-tpl", "repeat(" + _refsCols + ", minmax(0, 1fr))");
    } else {
      cont.style.removeProperty("--refs-cols-tpl");
    }
  };

  const _render = () => {
    const cont = document.getElementById("refsContainer");
    if (!cont) return;
    _applyCols();

    const visibleCats = _refsCat === "all" ? cats : [_refsCat];
    const allFormulasInOrder = [];
    let html = "";
    let total = 0;

    visibleCats.forEach((cat) => {
      const items = _formulasByCat.get(cat) || [];
      if (!items.length) return;
      total += items.length;
      html += `<div class="refs-sec" data-refs-sec="${escHtml(cat)}">
        <h2 class="refs-sec-h">${getCat(cat).l}<span class="refs-sec-n">${toFa(items.length)} رابطه</span></h2>
        <div class="fgrid">`;
      items.forEach((it) => {
        html += formulaCard(it.f, it.s, it.i);
        allFormulasInOrder.push(it.f);
      });
      html += `</div></div>`;
    });

    if (!html) {
      html = `<div class="card" style="padding:24px;text-align:center;color:var(--text-secondary)">فرمولی در این دسته‌بندی ثبت نشده است.</div>`;
    }
    cont.innerHTML = html;

    const _cards = Array.from(cont.querySelectorAll(".fcard"));
    const _vh = (window.innerHeight || 800) + 400;
    _cards.forEach((card, i) => {
      const f = allFormulasInOrder[i];
      if (!f) return;
      const texEl = card.querySelector(".ftex");
      const varsEl = card.querySelector(".fvars");
      // عنوان، توضیح کاربرد و متغیرها — هر سه ممکن است $…$ داشته باشند
      const renderVars = () => {
        if (!window.katexifyText) return;
        card.querySelectorAll(".fhead, .fuse, .fvars").forEach((el) => katexifyText(el));
      };
      const r = card.getBoundingClientRect();
      if (r.top < _vh) {
        if (texEl && f.tex && window.katex) {
          try {
            katex.render(f.tex, texEl, { displayMode: true, throwOnError: false });
          } catch (_) {
            texEl.textContent = f.tex;
          }
        }
        renderVars();
      } else {
        deferKatexTex(texEl, f.tex, true);
      }
      // متن کوتاه (عنوان، کاربرد، متغیرها) همیشه همزمان رندر می‌شود؛ هزینهٔ آن ناچیز است
      // و زمان‌بندی idle برای این بخش در عمل بعضی کارت‌ها را جا می‌انداخت.
      renderVars();
    });
  };

  main.querySelectorAll("[data-refs-cat]").forEach((b) => {
    b.onclick = () => {
      _refsCat = b.dataset.refsCat;
      main.querySelectorAll("[data-refs-cat]").forEach((x) => {
        x.classList.toggle("on", x === b);
      });
      _render();
    };
  });
  main.querySelectorAll("[data-refs-cols]").forEach((b) => {
    b.onclick = () => {
      _refsCols = +b.dataset.refsCols;
      main.querySelectorAll("[data-refs-cols]").forEach((x) => {
        x.classList.toggle("on", x === b);
      });
      _applyCols();
    };
  });

  _render();
}
