(function () {
  "use strict";
  const W = {
    title: "نمودار PV و محاسبهٔ کار",
    desc: "چهار فرآیند شبه‌ایستای مختلف (هم‌دما، هم‌فشار، هم‌حجم، آدیاباتیک) را از حالت اول به حالت دوم ببینید و کار محاسبه‌شده را مقایسه کنید. قرارداد علامت زیمانسکی: کار روی سامانه مثبت.",
    sess: ["s03"],
    mount(box) {
      box.innerHTML = `<div class="wgrid" style="--wctl:270px">
  <div class="wstage"><canvas width="680" height="420"></canvas></div>
  <div>
  <div class="ctls"></div>
  <div class="winfo"></div>
  </div>
  </div>`;

      const cv = box.querySelector("canvas");
      const ctx = setupHD(cv, 680, 420);
      const ct = box.querySelector(".ctls");
      const info = box.querySelector(".winfo");

      let Pi_atm = 4.0;
      let Pf_atm = 1.0;
      let Vi_L = 5.0;
      let Vf_L = 20.0;
      let n_mol = 1.0;
      let T_K = 300.0;
      let gamma = 1.4;
      let process = "isothermal";

      const CW = 680,
        CH = 420;
      const PADL = 60,
        PADB = 50,
        PADT = 30,
        PADR = 30;
      const PLOTW = CW - PADL - PADR;
      const PLOTH = CH - PADT - PADB;
      const VMAX = 25.0;
      const PMAX = 6.0;

      function wpalLocal() {
        if (window.__APP_PRINTING)
          return {
            bg: "rgba(0,0,0,0)",
            axis: "#4b5563",
            grid: "rgba(55,65,81,.14)",
            txt: "#1f2430",
            dim: "#5b6472",
          };
        const light = document.documentElement.getAttribute("data-theme") === "light";
        return light
          ? {
              bg: "#f7f5ef",
              axis: "#9a9488",
              grid: "rgba(70,64,55,.18)",
              txt: "#4a463d",
              dim: "#8a8578",
            }
          : {
              bg: "#05070f",
              axis: "#3b4770",
              grid: "rgba(103,115,155,.18)",
              txt: "#eaeefb",
              dim: "#67739b",
            };
      }

      function v2x(v) {
        return PADL + (v / VMAX) * PLOTW;
      }
      function p2y(p) {
        return PADT + PLOTH - (p / PMAX) * PLOTH;
      }

      function computePath() {
        const pts = [];
        const R = 0.082057;

        if (process === "isothermal") {
          const T = (Pi_atm * Vi_L) / (n_mol * R);
          T_K = T;
          for (let i = 0; i <= 60; i++) {
            const v = Vi_L + (Vf_L - Vi_L) * (i / 60);
            const p = (n_mol * R * T) / v;
            pts.push({ V: v, P: p });
          }
        } else if (process === "isobaric") {
          Pf_atm = Pi_atm;
          for (let i = 0; i <= 30; i++) {
            const v = Vi_L + (Vf_L - Vi_L) * (i / 30);
            pts.push({ V: v, P: Pi_atm });
          }
        } else if (process === "isochoric") {
          Vf_L = Vi_L;
          for (let i = 0; i <= 30; i++) {
            const p = Pi_atm + (Pf_atm - Pi_atm) * (i / 30);
            pts.push({ V: Vi_L, P: p });
          }
        } else if (process === "adiabatic") {
          const K = Pi_atm * Math.pow(Vi_L, gamma);
          for (let i = 0; i <= 60; i++) {
            const v = Vi_L + (Vf_L - Vi_L) * (i / 60);
            const p = K / Math.pow(v, gamma);
            pts.push({ V: v, P: p });
          }
          Pf_atm = pts[pts.length - 1].P;
          T_K = (Pf_atm * Vf_L) / (n_mol * R);
        }
        return pts;
      }

      function computeWork(pts) {
        let W = 0;
        for (let i = 1; i < pts.length; i++) {
          const dV = pts[i].V - pts[i - 1].V;
          const Pmid = (pts[i].P + pts[i - 1].P) / 2;
          W += -Pmid * dV;
        }
        return W * 101.325;
      }

      function draw() {
        const P = wpalLocal();
        ctx.clearRect(0, 0, CW, CH);
        ctx.fillStyle = P.bg;
        ctx.fillRect(0, 0, CW, CH);

        ctx.strokeStyle = P.axis;
        ctx.lineWidth = 1.5;
        ctx.beginPath();
        ctx.moveTo(PADL, PADT);
        ctx.lineTo(PADL, PADT + PLOTH);
        ctx.lineTo(PADL + PLOTW, PADT + PLOTH);
        ctx.stroke();

        ctx.strokeStyle = P.grid;
        ctx.lineWidth = 1;
        for (let v = 0; v <= VMAX; v += 5) {
          ctx.beginPath();
          ctx.moveTo(v2x(v), PADT);
          ctx.lineTo(v2x(v), PADT + PLOTH);
          ctx.stroke();
          ctx.fillStyle = P.dim;
          ctx.font = "10px Vazirmatn";
          ctx.textAlign = "center";
          ctx.fillText(toFa(v), v2x(v), PADT + PLOTH + 16);
        }
        for (let p = 0; p <= PMAX; p += 1) {
          ctx.beginPath();
          ctx.moveTo(PADL, p2y(p));
          ctx.lineTo(PADL + PLOTW, p2y(p));
          ctx.stroke();
          ctx.fillStyle = P.dim;
          ctx.font = "10px Vazirmatn";
          ctx.textAlign = "right";
          ctx.fillText(toFa(p), PADL - 6, p2y(p) + 3);
        }

        ctx.fillStyle = P.dim;
        ctx.font = "11px Vazirmatn";
        ctx.textAlign = "center";
        ctx.fillText("حجم V (لیتر)", PADL + PLOTW / 2, PADT + PLOTH + 34);
        ctx.save();
        ctx.translate(20, PADT + PLOTH / 2);
        ctx.rotate(-Math.PI / 2);
        ctx.fillText("فشار P (اتمسفر)", 0, 0);
        ctx.restore();

        const pts = computePath();
        ctx.strokeStyle = "#22d3ee";
        ctx.lineWidth = 3;
        ctx.beginPath();
        pts.forEach((pt, i) => {
          const x = v2x(pt.V),
            y = p2y(pt.P);
          if (i === 0) ctx.moveTo(x, y);
          else ctx.lineTo(x, y);
        });
        ctx.stroke();

        ctx.fillStyle = "rgba(34,211,238,.15)";
        ctx.beginPath();
        ctx.moveTo(v2x(pts[0].V), p2y(0));
        pts.forEach((pt) => ctx.lineTo(v2x(pt.V), p2y(pt.P)));
        ctx.lineTo(v2x(pts[pts.length - 1].V), p2y(0));
        ctx.closePath();
        ctx.fill();

        const i = pts[0],
          f = pts[pts.length - 1];
        ctx.fillStyle = "#34d399";
        ctx.beginPath();
        ctx.arc(v2x(i.V), p2y(i.P), 6, 0, 2 * Math.PI);
        ctx.fill();
        ctx.fillStyle = "#f472b6";
        ctx.beginPath();
        ctx.arc(v2x(f.V), p2y(f.P), 6, 0, 2 * Math.PI);
        ctx.fill();

        ctx.fillStyle = "#34d399";
        ctx.font = "bold 12px Vazirmatn";
        ctx.textAlign = "left";
        ctx.fillText("i", v2x(i.V) + 10, p2y(i.P) - 8);
        ctx.fillStyle = "#f472b6";
        ctx.fillText("f", v2x(f.V) + 10, p2y(f.P) - 8);

        const W = computeWork(pts);
        const pathName =
          {
            isothermal: "هم‌دما",
            isobaric: "هم‌فشار",
            isochoric: "هم‌حجم",
            adiabatic: "آدیاباتیک",
          }[process] || "—";

        info.innerHTML = `
  <div class="row"><span>فرآیند</span><b>${pathName}</b></div>
  <div class="row"><span>حالت i</span><b>P=${toFa(Pi_atm.toFixed(2))} atm · V=${toFa(Vi_L.toFixed(1))} L</b></div>
  <div class="row"><span>حالت f</span><b>P=${toFa(Pf_atm.toFixed(2))} atm · V=${toFa(Vf_L.toFixed(1))} L</b></div>
  <div class="row"><span>دما T</span><b>${toFa(T_K.toFixed(1))} K</b></div>
  <div class="row"><span>کار W</span><b>${W > 0 ? "+" : ""}${toFa(W.toFixed(1))} J</b></div>
  <div class="props">
    <span class="badge ${W > 0 ? "b-grn" : W < 0 ? "b-ros" : ""}">${W > 0 ? "کار روی سامانه" : W < 0 ? "کار توسط سامانه" : "بدون کار"}</span>
    <span class="badge b-cyn">مساحت زیر منحنی = −W</span>
  </div>`;
      }

      const processRow = document.createElement("div");
      processRow.className = "seg";
      processRow.style.marginTop = "6px";
      processRow.innerHTML = `
  <button data-pr="isothermal" class="on">هم‌دما</button>
  <button data-pr="isobaric">هم‌فشار</button>
  <button data-pr="isochoric">هم‌حجم</button>
  <button data-pr="adiabatic">آدیاباتیک</button>`;
      box.querySelector(".wgrid > div:last-child").insertBefore(processRow, info);
      processRow.querySelectorAll("button").forEach((b) => {
        b.onclick = () => {
          process = b.dataset.pr;
          processRow.querySelectorAll("button").forEach((x) => x.classList.toggle("on", x === b));
          draw();
        };
      });

      ctl(ct, "P اولیه (atm)", 0.5, 5.5, 0.1, Pi_atm, "atm", (v) => {
        Pi_atm = v;
        draw();
      });
      ctl(ct, "V اولیه (L)", 1, 15, 0.5, Vi_L, "L", (v) => {
        Vi_L = v;
        draw();
      });
      ctl(ct, "V نهایی (L)", 2, 24, 0.5, Vf_L, "L", (v) => {
        Vf_L = v;
        draw();
      });
      ctl(ct, "P نهایی (atm) — فقط هم‌حجم", 0.5, 5.5, 0.1, Pf_atm, "atm", (v) => {
        Pf_atm = v;
        draw();
      });

      draw();
    },
  };
  CourseRuntime.registerPackSource("thermo", { widgets: { pvd: W } });
})();
