(function () {
  "use strict";
  const K = window.PackWidgetKit;
  const wpal = K.wpal;
  let P = wpal();
  globalThis.addEventListener("lector:theme", () => {
    P = wpal();
  });
  const W = {
    title: "آینهٔ کروی — تصویرسازی با پرتوهای اصلی",
    desc: "با جابه‌جایی جسم و تغییر فاصلهٔ کانونی، محل و ویژگی‌های تصویر را ببینید. $\\frac{1}{s}+\\frac{1}{s'}=\\frac{1}{f}$",
    sess: ["s09"],
    mount(box) {
      box.innerHTML = `<div class="wgrid"><div class="wstage"><svg viewBox="0 0 680 400"></svg></div><div><div class="ctls"></div><div class="seg" style="margin-top:6px"></div><div class="winfo"></div></div></div>`;
      const sg = box.querySelector("svg"),
        ct = box.querySelector(".ctls"),
        seg = box.querySelector(".seg"),
        info = box.querySelector(".winfo");
      let type = "concave",
        fp = 130,
        s = 320;
      const VX = 560,
        Y = 205,
        HO = 75;
      ctl(ct, "فاصلهٔ جسم تا آینه", 70, 480, 5, s, "واحد", (v) => {
        s = v;
        draw();
      });
      ctl(ct, "اندازهٔ فاصلهٔ کانونی", 60, 220, 5, fp, "واحد", (v) => {
        fp = v;
        draw();
      });
      seg.innerHTML = `<button data-t="concave" class="on">مقعر — کاوا</button><button data-t="convex">محدب — کوژ</button>`;
      seg.querySelectorAll("button").forEach(
        (b) =>
          (b.onclick = () => {
            type = b.dataset.t;
            seg.querySelectorAll("button").forEach((x) => x.classList.toggle("on", x === b));
            draw();
          }),
      );
      function line(x1, y1, x2, y2, st, w = 2, dash) {
        const l = svgEl("line", { x1, y1, x2, y2, stroke: st, "stroke-width": w }, sg);
        if (dash) l.setAttribute("stroke-dasharray", dash);
        return l;
      }
      function txt(x, y, t, fill = wpal().txt, sz = 12, anc = "middle") {
        const e = svgEl(
          "text",
          {
            x,
            y,
            fill,
            "font-size": sz,
            "text-anchor": anc,
            "font-family": "Vazirmatn",
          },
          sg,
        );
        e.textContent = t;
        return e;
      }
      function draw() {
        P = wpal();
        sg.innerHTML = "";
        const f = type === "concave" ? fp : -fp,
          xo = VX - s,
          tipY = Y - HO;
        line(20, Y, 660, Y, P.axis, 1.5);
        const arc =
          type === "concave"
            ? `M ${VX + 20} ${Y - 150} Q ${VX - 32} ${Y} ${VX + 20} ${Y + 150}`
            : `M ${VX - 8} ${Y - 150} Q ${VX + 38} ${Y} ${VX - 8} ${Y + 150}`;
        svgEl(
          "path",
          {
            d: arc,
            stroke: "#8fa3d9",
            fill: "rgba(143,163,217,.12)",
            "stroke-width": 3,
          },
          sg,
        );
        const nearInf = Math.abs(s - f) < 7;
        let si = null,
          m = null,
          xi = null,
          yim = null;
        if (!nearInf) {
          si = (s * f) / (s - f);
          m = -si / s;
          xi = VX - si;
          yim = Y - m * HO;
        }
        const real = si > 0;
        const Fx = VX - f,
          Cx = VX - 2 * f;
        [
          [Fx, "F", "#fbbf24"],
          [Cx, "C", "#60a5fa"],
          [VX, "V", "#94a3b8"],
        ].forEach((p) => {
          svgEl("circle", { cx: p[0], cy: Y, r: 4, fill: p[2] }, sg);
          txt(p[0], Y + 22, p[1], p[2], 13);
        });
        function ext(x1, y1, x2, y2, xto) {
          const k = (xto - x1) / (x2 - x1);
          return [xto, y1 + k * (y2 - y1)];
        }
        if (!nearInf) {
          line(xo, tipY, VX, tipY, "#fcd34d");
          if (real) {
            const e = ext(VX, tipY, xi, yim, 30);
            line(VX, tipY, e[0], e[1], "#38bdf8");
          } else {
            const dx = VX - xi,
              dy = tipY - yim,
              L = Math.hypot(dx, dy),
              e = [VX + (dx / L) * 560, tipY + (dy / L) * 560];
            line(VX, tipY, e[0], e[1], "#38bdf8");
            line(VX, tipY, xi, yim, "#38bdf8", 1.6, "6 6");
          }
          const t2 = (VX - xo) / (Fx - xo),
            y2 = tipY + t2 * (Y - tipY);
          line(xo, tipY, VX, y2, "#fcd34d");
          if (f > 0 && s < f) line(xo, tipY, Fx, Y, "#fcd34d", 1.4, "5 6");
          if (real) line(VX, y2, 30, y2, "#38bdf8");
          else {
            line(VX, y2, 30, y2, "#38bdf8");
            line(VX, y2, xi, yim, "#38bdf8", 1.6, "6 6");
          }
          const t3 = (VX - xo) / (Cx - xo),
            y3 = tipY + t3 * (Y - tipY);
          line(xo, tipY, VX, y3, "#fcd34d");
          if (f > 0 && s < 2 * f) line(xo, tipY, Cx, Y, "#fcd34d", 1.4, "5 6");
          const e3 = ext(VX, y3, xo, tipY, 30);
          line(VX, y3, e3[0], e3[1], "#38bdf8");
        } else {
          line(xo, tipY, VX, tipY, "#fcd34d");
          line(VX, tipY, 30, tipY, "#38bdf8");
          txt(
            300,
            60,
            "جسم روی کانون است؛ پرتوها موازی خارج می‌شوند — تصویر در بی‌نهایت",
            "#fbbf24",
            14,
          );
        }
        line(xo, Y, xo, tipY, "#34d399", 3.5);
        svgEl("path", { d: `M ${xo} ${tipY} l -6 12 l 12 0 z`, fill: "#34d399" }, sg);
        txt(xo, Y + 24, "جسم", "#34d399", 12);
        if (!nearInf) {
          const col = real ? "#f472b6" : "#c084fc";
          line(xi, Y, xi, yim, col, 3.5, real ? null : "7 7");
          const dir = yim < Y ? -1 : 1;
          svgEl("path", { d: `M ${xi} ${yim} l ${-6} ${-dir * 12} l 12 0 z`, fill: col }, sg);
          txt(xi, Y + 24, "تصویر", col, 12);
        }
        const cm = (v) => (v / 4).toFixed(1);
        let props = "";
        if (nearInf) {
          props = `<span class="badge b-amb">تصویر در بی‌نهایت</span><span class="badge b-blu">پرتوهای خروجی موازی</span>`;
        } else {
          props =
            (real
              ? `<span class="badge b-grn">حقیقی</span>`
              : `<span class="badge b-vio">مجازی</span>`) +
            (m < 0
              ? `<span class="badge b-ros">وارونه</span>`
              : `<span class="badge b-cyn">مستقیم</span>`) +
            (Math.abs(m) > 1.02
              ? `<span class="badge b-amb">بزرگ‌تر ×${Math.abs(m).toFixed(2)}</span>`
              : Math.abs(m) < 0.98
                ? `<span class="badge b-blu">کوچک‌تر ×${Math.abs(m).toFixed(2)}</span>`
                : `<span class="badge b-blu">هم‌اندازه</span>`);
        }
        info.innerHTML = `
  <div class="row"><span>فاصلهٔ جسم $s$</span><b>${toFa(cm(s))} سانتی‌متر</b></div>
  <div class="row"><span>فاصلهٔ کانونی $f$</span><b>${toFa(cm(Math.abs(f)))} سانتی‌متر ${f > 0 ? "(مقعر)" : "(محدب)"}</b></div>
  <div class="row"><span>فاصلهٔ تصویر $s'$</span><b>${nearInf ? "بی‌نهایت" : toFa(cm(Math.abs(si))) + " سانتی‌متر — " + (real ? "جلوی آینه" : "پشت آینه")}</b></div>
  <div class="row"><span>بزرگ‌نمایی $m=-\\frac{s\'}{s}$</span><b>${nearInf ? "—" : toFa(m.toFixed(2))}</b></div>
  <div class="props">${props}</div>`;
        if (window.renderMathInElement)
          renderMathInElement(info, {
            delimiters: [{ left: "$", right: "$", display: false }],
            throwOnError: false,
          });
      }
      draw();
    },
  };
  CourseRuntime.registerPackSource("optics", { widgets: { mirror: W } });
})();
