import { dailyStats, escHtml, lifetimeStats, loadEvents, loadMistakes, loadReviewState, problemIds, readCount, solvedCount, solvedSet, stagger, toFa } from "../../core.js";
import { _packReadCount } from "./_shared.js";
import { masterySnapshot } from "../layout/router.js";
import { icon } from "../components/icons.js";
import { main } from "../../preferences/prefs.js";
export function _heatmapHTML(rows, weeks) {
  const w = weeks || 26;
  const cells = rows.slice(-w * 7);
  const maxTotal = cells.reduce((m, c) => Math.max(m, c.total + (c.study || 0) / 10), 1);
  const dayNames = ["ش", "ی", "د", "س", "چ", "پ", "ج"];
  let html = '<div class="hm-wrap"><div class="hm-days">';
  dayNames.forEach((d) => {
    html += `<span>${d}</span>`;
  });
  html += '</div><div class="hm-grid">';
  cells.forEach((c) => {
    const v = c.total + (c.study || 0) / 10;
    const lvl =
      v === 0 ? 0 : v / maxTotal > 0.75 ? 4 : v / maxTotal > 0.5 ? 3 : v / maxTotal > 0.25 ? 2 : 1;
    const iso = new Date(c.ts).toISOString().slice(0, 10);
    let dateLb = iso;
    try {
      dateLb = new Intl.DateTimeFormat("fa-IR", { day: "numeric", month: "long" }).format(
        new Date(iso + "T00:00:00"),
      );
    } catch (_) {}
    let tip;
    if (c.total === 0 && !c.study) {
      tip = dateLb + " — بدون فعالیت";
    } else {
      const parts = [];
      if (c.read) parts.push(toFa(c.read) + " جلسه");
      if (c.solve) parts.push(toFa(c.solve) + " مسئله");
      if (c.note) parts.push(toFa(c.note) + " یادداشت");
      if (c.flash) parts.push(toFa(c.flash) + " فلش");
      if (c.study) parts.push(toFa(c.study) + " دقیقه");
      tip = dateLb + " — " + parts.join(" · ");
    }
    html += `<span class="hm-c" data-l="${lvl}" data-tip="${escHtml(tip)}" data-hm="${iso}"></span>`;
  });
  html += "</div></div>";
  return html;
}

export function pageProgress() {
  const C = CourseRuntime.getCourse() || {};
  const sessions = C.sessions || [];
  const totalSess = sessions.length;
  const readN = readCount();
  const readPct = totalSess ? Math.round((readN / totalSess) * 100) : 0;

  const totalP = problemIds().size;
  const solvedN = solvedCount();
  const solvedPct = totalP ? Math.round((solvedN / totalP) * 100) : 0;

  const life = lifetimeStats();
  const evs = loadEvents();

  const rs = (typeof loadReviewState === "function" ? loadReviewState() : {}) || {};
  const cardsState = rs.cards || {};
  const allC = typeof getReviewCards === "function" ? getReviewCards() : [];
  const masteredN = allC.filter((c) => {
    const st = cardsState[c.id];
    return st && st.ivl >= 21 && st.reps >= 3;
  }).length;
  const seenCards = allC.filter((c) => cardsState[c.id]).length;
  const flashEv = evs.filter((e) => e.t === "flash").slice(-300);
  const okN = flashEv.filter((e) => e.result === "good" || e.result === "easy").length;
  const retention = flashEv.length ? Math.round((okN / flashEv.length) * 100) : null;

  const packs = CourseRuntime.listRegisteredPacks();
  const activeId = CourseRuntime.getActivePackId();
  const packRows = packs.map((p) => {
    const ss = (p.course && p.course.sessions) || [];
    const n = typeof _packReadCount === "function" ? _packReadCount(p.id, ss) : 0;
    const pct = ss.length ? Math.round((n / ss.length) * 100) : 0;
    return {
      id: p.id,
      name: p.appName || p.title || p.id,
      n,
      total: ss.length,
      pct,
      active: p.id === activeId,
    };
  });

  const probs = CourseRuntime.getProblems() || [];
  const weakSecs = (CourseRuntime.getProblemSections() || [])
    .map((sec) => {
      const list = probs.filter((p) => String(p.section) === String(sec.k));
      const done = list.filter((p) => solvedSet.has(p.id)).length;
      return {
        t: sec.t,
        done,
        total: list.length,
        pct: list.length ? Math.round((done / list.length) * 100) : 0,
      };
    })
    .filter((x) => x.total > 0)
    .sort((a, b) => a.pct - b.pct)
    .slice(0, 4);

  const leeches = allC
    .map((c) => ({ c, st: cardsState[c.id] }))
    .filter((x) => x.st && (x.st.lapses || 0) >= 2)
    .sort((a, b) => (b.st.lapses || 0) - (a.st.lapses || 0))
    .slice(0, 4);

  const mistakesN = Object.keys(loadMistakes()).length;

  const days = typeof dailyStats === "function" ? dailyStats(14) : [];
  const maxDay = Math.max(1, ...days.map((d) => d.total));
  const dayBars = days
    .map((d) => {
      const v = d.total;
      const h = v ? Math.max(8, Math.round((v / maxDay) * 100)) : 0;
      const dt = new Date(d.ts);
      const lbl = toFa(dt.getDate());
      return `<div class="pg-day${v ? "" : " is-zero"}" title="${escHtml(d.key)}: ${toFa(v)} فعالیت">
      <div class="pg-day-col"><i style="height:${h}%"></i></div>
      <span>${lbl}</span></div>`;
    })
    .join("");

  const snap = typeof masterySnapshot === "function" ? masterySnapshot() : null;
  const mRep = snap && snap.report;
  const mTotal = mRep ? mRep.total : 0;
  const mMastered = mRep ? mRep.counts.mastered : 0;
  const mPct = mTotal ? Math.round((mMastered / mTotal) * 100) : 0;
  const mUncertain = mRep ? mRep.units.filter((u) => u.uncertain && u.status !== "unseen").length : 0;
  const STATUS_FA = { unseen: "ندیده", learning: "در یادگیری", practicing: "در تمرین", mastered: "مسلط", decaying: "در فراموشی" };
  const unitHref = (id) => {
    const m = /^(.+?)\/sess:(.+)$/.exec(id);
    return m ? "#/p/" + encodeURIComponent(m[1]) + "/s/" + encodeURIComponent(m[2]) : "#/problems";
  };
  const nextHTML = !snap
    ? `<li class="pg-empty">در حال محاسبه…</li>`
    : snap.next.length
      ? snap.next
          .map((s) => {
            const href = s.problem ? "#" + escHtml(s.problem.id) : s.action === "review" ? "#/review" : unitHref(s.unitId);
            const act = s.action === "review" ? "مرور" : s.action === "practice" ? "تمرین" : "شروع";
            return `<li><span>${escHtml(s.label)}</span><b>${escHtml(s.reason)}</b>
      <a class="pg-link" href="${href}">${icon(s.action === "review" ? "cards" : s.action === "practice" ? "pencil" : "book")}<span>${act}${s.problem ? ": " + escHtml(s.problem.title) : ""}</span></a></li>`;
          })
          .join("")
      : `<li class="pg-empty">فعلاً پیشنهادی نیست؛ یا همه‌چیز مسلط است یا شواهد هنوز کافی نیست.</li>`;
  const countsHTML = mRep
    ? Object.keys(STATUS_FA)
        .map((k) => `<span class="pg-st st-${k}"><b>${toFa(mRep.counts[k] || 0)}</b>${STATUS_FA[k]}</span>`)
        .join("")
    : "";
  const unitsHTML = mRep
    ? mRep.units
        .filter((u) => u.status !== "unseen")
        .sort((a, b) => ["decaying", "practicing", "learning", "mastered"].indexOf(a.status) - ["decaying", "practicing", "learning", "mastered"].indexOf(b.status) || a.score - b.score)
        .slice(0, 12)
        .map(
          (u) => `<li><span>${escHtml(u.label)}</span><b class="pg-st-inline st-${u.status}">${STATUS_FA[u.status]}${u.uncertain ? " · نامشخص" : ""} · ${toFa(Math.round(u.score * 100))}٪</b></li>`,
        )
        .join("") || `<li class="pg-empty">هنوز شاهدی ثبت نشده. با مرور کارت یا حل تمرین شروع کن.</li>`
    : `<li class="pg-empty">در حال محاسبه…</li>`;

  const ring = (pct, cls) => {
    const R = 30,
      Ci = 2 * Math.PI * R;
    return `<svg class="pg-ring ${cls}" viewBox="0 0 76 76" aria-hidden="true">
      <circle class="pg-ring-bg" cx="38" cy="38" r="${R}"/>
      <circle class="pg-ring-fg" cx="38" cy="38" r="${R}" stroke-dasharray="${Ci.toFixed(1)}"
              stroke-dashoffset="${(Ci * (1 - pct / 100)).toFixed(1)}"/></svg>`;
  };

  const kpi = (pct, cls, value, label, sub, ic) => `
    <article class="pg-kpi ${cls}">
      <div class="pg-kpi-ring">${ring(pct, cls)}<span class="pg-kpi-ic">${icon(ic)}</span></div>
      <div class="pg-kpi-body">
        <b dir="ltr">${value}</b>
        <span>${label}</span>
        <small>${sub}</small>
      </div>
    </article>`;

  const packHTML = packRows.length
    ? packRows
        .map(
          (x) => `
    <div class="pg-pack${x.active ? " is-active" : ""}">
      <div class="pg-pack-h">
        <b>${escHtml(x.name)}</b>
        ${x.active ? `<span class="pg-tag">فعال</span>` : ""}
        <span class="pg-pack-n">${x.total ? `${toFa(x.n)} از ${toFa(x.total)} جلسه` : "برای دیدن آمار فعالش کنید"}</span>
      </div>
      <div class="pg-bar"><i style="width:${x.pct}%"></i></div>
    </div>`,
        )
        .join("")
    : `<p class="pg-empty">هنوز پکی ثبت نشده است.</p>`;

  const weakHTML = weakSecs.length
    ? weakSecs
        .map(
          (w) => `
    <li><span>${escHtml(w.t)}</span><b>${toFa(w.done)} از ${toFa(w.total)}</b>
      <div class="pg-bar pg-bar--sm"><i style="width:${w.pct}%"></i></div></li>`,
        )
        .join("")
    : `<li class="pg-empty">مسئله‌ای برای بررسی نیست.</li>`;

  const leechHTML = leeches.length
    ? leeches
        .map(
          (x) => `
    <li><span>${escHtml(x.c.front)}</span><b class="pg-rose">${toFa(x.st.lapses)} بار فراموش</b></li>`,
        )
        .join("")
    : `<li class="pg-empty">کارت پرخطایی نداری؛ عالی است.</li>`;

  main.innerHTML = `<div class="page pg-page">
    <header class="pg-hero">
      <div>
        <span class="pg-kicker">${icon("target")}پیشرفت مطالعه</span>
        <h1 class="pg-h1">وضعیت یادگیری تو</h1>
        <p>این عددها فقط از فعالیت شما در همین مرورگر ساخته می‌شوند.</p>
      </div>
      <div class="pg-streak">
        <b>${toFa(life.streak)}</b><span>روز پیوسته</span>
      </div>
    </header>

    <section class="pg-kpis">
      ${kpi(readPct, "is-cyan", `${toFa(readN)}<small> / ${toFa(totalSess)}</small>`, "جلسه خوانده شد", `${toFa(readPct)}٪ از کل درس`, "book")}
      ${kpi(solvedPct, "is-green", `${toFa(solvedN)}<small> / ${toFa(totalP)}</small>`, "مسئله حل شد", `${toFa(solvedPct)}٪ از تمرین‌ها`, "pencil")}
      ${kpi(
        mPct,
        "is-blue",
        `${toFa(mMastered)}<small> / ${toFa(mTotal)}</small>`,
        "مفهوم مسلط",
        snap ? `${toFa(mUncertain)} مفهوم هنوز نامشخص · ${toFa(seenCards)} کارت دیده` : "در حال محاسبه",
        "target",
      )}
      ${kpi(retention == null ? 0 : retention, "is-amber", retention == null ? "—" : `${toFa(retention)}٪`, "یادآوری درست", retention == null ? "هنوز مروری ثبت نشده" : `از ${toFa(flashEv.length)} مرور اخیر`, "sparkles")}
    </section>

    <div class="pg-grid">
      <section class="pg-panel pg-panel--wide">
        <div class="pg-panel-h"><h3>فعالیت ۱۴ روز اخیر</h3>
          <span class="pg-meta">${toFa(days.reduce((a, d) => a + d.total, 0))} فعالیت</span></div>
        <div class="pg-days">${dayBars}</div>
      </section>

      <section class="pg-panel">
        <div class="pg-panel-h"><h3>پیشرفت هر پک</h3><span class="pg-meta">${toFa(packs.length)} پک</span></div>
        <div class="pg-packs">${packHTML}</div>
      </section>

      <section class="pg-panel pg-panel--wide">
        <div class="pg-panel-h"><h3>گام بعدی</h3><span class="pg-meta">بر اساس شواهد، نه درصد خواندن</span></div>
        <ul class="pg-list">${nextHTML}</ul>
      </section>

      <section class="pg-panel pg-panel--wide">
        <div class="pg-panel-h"><h3>مفاهیم بر اساس وضعیت</h3><span class="pg-meta">${toFa(mTotal)} مفهوم</span></div>
        <div class="pg-st-row">${countsHTML}</div>
        <ul class="pg-list">${unitsHTML}</ul>
        <p class="pg-note">خواندن جلسه شاهد تسلط نیست. فقط پاسخ‌های تمرین و مرور کارت‌ها حساب می‌شوند؛ مفهومی با کمتر از ${toFa(3)} شاهد «نامشخص» است.</p>
      </section>

      <section class="pg-panel">
        <div class="pg-panel-h"><h3>نقاط ضعف تمرین</h3><span class="pg-meta">کم‌حل‌ترین بخش‌ها</span></div>
        <ul class="pg-list">${weakHTML}</ul>
        <a class="pg-link" href="#/problems">${icon("pencil")}<span>رفتن به حل تمرین</span></a>
      </section>

      <section class="pg-panel">
        <div class="pg-panel-h"><h3>کارت‌های پرخطا</h3><span class="pg-meta">فراموش‌شده‌های تکراری</span></div>
        <ul class="pg-list">${leechHTML}</ul>
        <a class="pg-link" href="#/review">${icon("cards")}<span>مرور این کارت‌ها</span></a>
      </section>

      <section class="pg-panel">
        <div class="pg-panel-h"><h3>دفتر اشتباهات</h3><span class="pg-meta">${toFa(mistakesN)} مورد</span></div>
        <p class="pg-note">${mistakesN ? "سوال‌های علامت‌خورده را از دفتر اشتباهات مرور کن." : "هنوز سوالی به دفتر اشتباهات اضافه نشده است."}</p>
        <a class="pg-link" href="#/problems">${icon("warn")}<span>باز کردن دفتر اشتباهات</span></a>
      </section>
    </div>
  </div>`;
  stagger(main);
}
if (typeof window !== "undefined") window.pageProgress = pageProgress;
