// رجیستری پک‌ها و واحدها: ذخیرهٔ منابع خام، پک‌های ثبت‌شده و واحدهای هر پک.
// هیچ پک فعالی اینجا نگه داشته نمی‌شود (آن کار active.ts است).

import type { Pack, Meta, Course, Widget } from "../contract/types.js";

// هر واحد (session / widget / problem ...) حداقل باید id داشته باشد
export interface UnitBase {
  id: string;
  order?: number;
  num?: number;
  [key: string]: unknown;
}

export interface UnitError {
  packId: string;
  kind?: string;
  id?: string;
  msg: string;
}

export type PackSource = Partial<Pack> & { course?: Course };

const sources = new Map<string, Pack>();
const registered = new Map<string, Pack>();
const unitStore = new Map<string, Record<string, Map<string, UnitBase>>>();
const unitErrors: UnitError[] = [];

function mergePackSource(id: string | undefined, source: PackSource | undefined): Pack {
  if (!id) throw new Error("[Runtime] Pack id is required");
  const prev: Pack = sources.get(id) || { id };
  const next: Pack = Object.assign({}, prev, source || {}, { id });
  if (source && source.widgets) {
    const widgets: Record<string, unknown> = Object.assign({}, prev.widgets || {});
    for (const key of Object.keys(source.widgets)) {
      if (widgets[key]) {
        unitErrors.push({ packId: id, kind: "widgets", id: key, msg: "ویجت تکراری" });
        console.error('[Runtime] duplicate widget "' + key + '" in pack "' + id + '"');
      }
      widgets[key] = (source.widgets as Record<string, Widget>)[key];
    }
    next.widgets = widgets;
  }
  sources.set(id, next);
  return next;
}

// منبع خام پک (پیش از normalize) را ثبت یا با منبع قبلی ادغام می‌کند
export function registerPackSource(
  idOrSource: string | PackSource,
  maybeSource?: PackSource,
): Pack {
  const source: PackSource | undefined = typeof idOrSource === "string" ? maybeSource : idOrSource;
  const id: string | undefined =
    typeof idOrSource === "string"
      ? idOrSource
      : source && (source.id || (source.course && source.course.meta && source.course.meta.id));
  return mergePackSource(id, source);
}

export function getRawPack(id: string): Pack | null {
  return sources.get(id) || null;
}

export function listSources(): { id: string; title: string }[] {
  return Array.from(sources.values()).map((p) => ({
    id: p.id,
    title: String(
      (p.course && p.course.meta && (p.course.meta.title || p.course.meta.appName)) ||
        (p.meta && (p.meta.title || p.meta.appName)) ||
        p.id,
    ),
  }));
}

// پک normalize‌شده را در رجیستری می‌گذارد (جایگزین نسخهٔ قبلی با همان id)
export function registerPack(pack: Pack, idOverride?: string): Pack {
  const id = idOverride || (pack && pack.id);
  if (!pack || !id) throw new Error("[Runtime] Pack must have an id");
  registered.set(id, pack);
  return pack;
}

export function getPackById(id: string): Pack | null {
  return registered.get(id) || null;
}

export interface RegisteredPackInfo {
  id: string;
  title: string;
  appName: string;
  subtitle: string;
  uni: string;
  ver: string;
  archetype: string;
  layout: string;
  meta: Meta;
}

export function listRegisteredPacks(): RegisteredPackInfo[] {
  return Array.from(registered.values()).map((p) => {
    const m: Meta = (p.course && p.course.meta) || p.meta || ({} as Meta);
    return {
      id: p.id,
      title: String(m.title || m.appName || p.id),
      appName: String(m.appName || ""),
      subtitle: String(m.subtitle || ""),
      uni: String(m.uni || ""),
      ver: String(m.ver || ""),
      archetype: String(m.archetype || "stem"),
      layout: String(m.layout || "classic"),
      meta: m,
    };
  });
}

// واحدهای یک پک به‌تفکیک نوع (session، problem، …)، مرتب‌شده بر اساس order یا num
export function registerUnit<T extends UnitBase>(packId: string, kind: string, unit: T): T | null {
  if (!packId || !kind) throw new Error("[Runtime] registerUnit needs packId and kind");
  if (!unit || !unit.id) {
    unitErrors.push({ packId, kind, msg: "واحد بدون id" });
    console.error("[Runtime] unit without id in " + packId + "/" + kind);
    return null;
  }
  let byPack = unitStore.get(packId);
  if (!byPack) {
    byPack = {};
    unitStore.set(packId, byPack);
  }
  const byKind: Map<string, UnitBase> = byPack[kind] || (byPack[kind] = new Map());
  if (byKind.has(unit.id)) {
    unitErrors.push({ packId, kind, id: unit.id, msg: "id تکراری" });
    console.error("[Runtime] duplicate " + kind + ' id "' + unit.id + '" in pack "' + packId + '"');
    return null;
  }
  byKind.set(unit.id, unit);
  return unit;
}

export function getUnits(packId: string, kind: string): UnitBase[] {
  const byPack = unitStore.get(packId);
  const byKind = byPack && byPack[kind];
  if (!byKind) return [];
  const key = (u: UnitBase): number => (u.order != null ? u.order : u.num != null ? u.num : 0);
  return Array.from(byKind.values()).sort((a, b) => key(a) - key(b));
}

export function getUnitErrors(): UnitError[] {
  return unitErrors.slice();
}
