// API عمومی هستهٔ اجرای دوره (CourseRuntime).
// ماژول‌ها: registry (منابع و واحدها)، active (پک فعال و خواننده‌ها).
// پک‌ها بدون اعتبارسنجی کامل دریافت می‌شوند؛ قرارداد ساختار در contract اعمال می‌شود.

import * as registry from "./registry.js";
import * as active from "./active.js";

export type { Pack, Course, Meta, Category } from "../contract/types.js";
export type { UnitBase, UnitError, RegisteredPackInfo, PackSource } from "./registry.js";
export { engineEvents, Emitter } from "../events.js";
export type { EngineEvents } from "../events.js";

const api = Object.freeze({
  registerPackSource: registry.registerPackSource,
  getRawPack: active.getRawPack,
  setActivePack: active.setActivePack,
  replaceActivePack: active.replaceActivePack,
  listPacks: registry.listSources,
  getPack: active.getPack,
  getCourse: active.getCourse,
  getCategories: active.getCategories,
  getProblems: active.getProblems,
  getProblemSections: active.getProblemSections,
  getProblemNote: active.getProblemNote,
  getProblemHtml: active.getProblemHtml,
  getProblemRefs: active.getProblemRefs,
  getPackReviewCards: active.getPackReviewCards,
  getPackAssessments: active.getPackAssessments,
  getPackGraphNodes: active.getPackGraphNodes,
  getWidgets: active.getWidgets,
  registerUnit: registry.registerUnit,
  getUnits: registry.getUnits,
  getUnitErrors: registry.getUnitErrors,
  registerPack: registry.registerPack,
  getPackById: registry.getPackById,
  listRegisteredPacks: registry.listRegisteredPacks,
  activatePack: active.activatePack,
  getActivePackId: active.getActivePackId,
});

export type CourseRuntimeApi = typeof api;

declare global {
  var CourseRuntime: CourseRuntimeApi;
}

globalThis.CourseRuntime = api;
