// رجیستری آرکی‌تایپ‌ها: هر «قالب» دوره (stem، narrative ...) حالت نمایش جلسه را تعیین می‌کند.

export interface ArchetypeSession {
  detail?: { sections?: unknown[] } | null;
  [key: string]: unknown;
}

export interface Archetype {
  id: string;
  version?: number;
  extends?: string;
  resolveMode(mode: string | undefined, session: ArchetypeSession | undefined): string;
  decorateSession?(session: ArchetypeSession, mode: string | undefined): unknown;
}

export interface ArchetypeRegistryApi {
  register(archetype: Archetype): void;
  get(id: string): Archetype | null;
  list(): string[];
  getActive(): Archetype | null;
  applySession(session: ArchetypeSession, mode?: string): unknown;
}

const registry = new Map<string, Archetype>();

function register(archetype: Archetype): void {
  if (!archetype || !archetype.id) throw new Error("[Archetype] id is required");
  registry.set(archetype.id, Object.freeze(archetype));
}

function get(id: string): Archetype | null {
  return registry.get(id) || registry.get("stem") || null;
}

function list(): string[] {
  return Array.from(registry.keys());
}

function getActive(): Archetype | null {
  const id = Presentation.current().archetype || "stem";
  return get(id) || get("stem") || get("base") || null;
}

function applySession(session: ArchetypeSession, mode?: string): unknown {
  const a = getActive();
  return a && typeof a.decorateSession === "function"
    ? a.decorateSession(session, mode)
    : undefined;
}

export const ArchetypeRegistry: ArchetypeRegistryApi = Object.freeze({
  register,
  get,
  list,
  getActive,
  applySession,
});

declare global {
  var ArchetypeRegistry: ArchetypeRegistryApi;
}

globalThis.ArchetypeRegistry = ArchetypeRegistry;
