import { K, lsDel, lsGet, lsSet, toFa } from "../../../core.js";
import { go } from "../../layout/router.js";
import { icon } from "../icons.js";
export const SEARCH_CONF = {
  limit: 10,
  fuzzy: 2,
  w: { title: 3, sub: 1.2, text: 0.5 },
  boost: { جلسه: 1.25, مفهوم: 1.1, فرمول: 1, واژه: 0.95 },
};
export let INDEX = [],
  CUR_HITS = [],
  CUR_ACT = -1,
  SEARCH_TYPE_FILTER = "all";
export const esc = (s) => (s || "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
export const norm = (s) =>
  (s || "")
    .toLowerCase()
    .replace(/ي/g, "ی")
    .replace(/ك/g, "ک")
    .replace(/[۰-۹]/g, (d) => String("۰۱۲۳۴۵۶۷۸۹".indexOf(d)))
    .replace(/[٠-٩]/g, (d) => String("٠١٢٣٤٥٦٧٨٩".indexOf(d)))
    .replace(/[\u200c\u200e\u200f\u064b-\u0652\u0654\u0670]/g, "")
    .replace(/\s+/g, " ")
    .trim();
export const toks = (s) =>
  norm(s)
    .split(" ")
    .filter((t) => t.length > 1);
export function lev(a, b) {
  if (Math.abs(a.length - b.length) > SEARCH_CONF.fuzzy) return 9;
  let p = Array.from({ length: b.length + 1 }, (_, j) => j);
  for (let i = 1; i <= a.length; i++) {
    const c = [i];
    for (let j = 1; j <= b.length; j++)
      c[j] = Math.min(p[j] + 1, c[j - 1] + 1, p[j - 1] + (a[i - 1] !== b[j - 1] ? 1 : 0));
    p = c;
  }
  return p[b.length];
}
export function buildIndex() {
  INDEX = [];
  const push = (o) => {
    o._t = norm(o.title);
    o._s = norm(o.sub);
    o._tt = toks(o.title);
    o._xt = toks(o.title + " " + (o.text || ""));
    INDEX.push(o);
  };
  ((CourseRuntime.getCourse() || {}).sessions || []).forEach((s) => {
    push({
      type: "جلسه",
      cls: "b-vio",
      title: "جلسهٔ " + toFa(s.num) + " — " + s.title,
      sub: s.topics.slice(0, 3).join(" · "),
      page: "s/" + s.id,
      text: s.topics.join(" ") + " " + s.summary,
    });
    s.concepts.forEach((c, i) =>
      push({
        type: "مفهوم",
        cls: "b-cyn",
        title: c.t,
        sub: (c.def || "").slice(0, 90),
        page: "s/" + s.id,
        anchor: "c-" + s.id + "-" + i,
        text: (c.pts || []).join(" "),
      }),
    );
    s.formulas.forEach((f, i) =>
      push({
        type: "فرمول",
        cls: "b-amb",
        title: f.t,
        sub: (f.use || "").slice(0, 90),
        page: "s/" + s.id,
        anchor: "f-" + s.id + "-" + i,
        text: f.use,
      }),
    );
  });
  ((CourseRuntime.getCourse() || {}).glossary || []).forEach((g) =>
    push({
      type: "واژه",
      cls: "b-grn",
      title: g.t,
      sub: (g.d || "").slice(0, 90),
      page: "glossary",
      text: g.d,
    }),
  );
}
export function tokenScore(t, words, fuzz) {
  let b = 0;
  for (const w of words) {
    if (w === t) {
      b = 1;
      break;
    }
    if (w.startsWith(t) || (t.length > 3 && w.includes(t))) {
      b = Math.max(b, 0.8);
      continue;
    }
    if (fuzz && t.length >= 4 && lev(w, t) <= SEARCH_CONF.fuzzy) b = Math.max(b, 0.55);
  }
  return b;
}
export function scoreIt(it, q, tokens) {
  let sc = it._t.includes(q) ? 2.5 : 0;
  for (const t of tokens) {
    const bt = tokenScore(t, it._tt, true);
    sc += bt * SEARCH_CONF.w.title;
    if (bt < 1) {
      const bs = it._s.includes(t) ? 0.9 : tokenScore(t, it._xt, true) * 0.8;
      sc += bs * (SEARCH_CONF.w.sub + SEARCH_CONF.w.text);
    }
  }
  return sc * (SEARCH_CONF.boost[it.type] || 1);
}
export function hlRe(q) {
  const ign = "[\\u200c\\u200e\\u200f\\u064b-\\u0652\\u0654\\u0670 ]*";
  const pat = [...q.trim()]
    .map((ch) => {
      if (ch === " ") return ign;
      if (ch === "ی") return "[یي]";
      if (ch === "ک") return "[کك]";
      if (/[0-9]/.test(ch)) return "[" + ch + "۰-۹]";
      if (/[.*+?^${}()|[\]\\]/.test(ch)) return "\\" + ch;
      return ch;
    })
    .join(ign);
  try {
    return new RegExp(pat, "gi");
  } catch (e) {
    return /$^/;
  }
}
export function runQuery(raw) {
  if (!INDEX.length && typeof buildIndex === "function") buildIndex();
  const q = norm(raw);
  if (q.length < 2) return [];
  const tokens = toks(raw);
  let hits = INDEX.map((it) => ({ it, sc: scoreIt(it, q, tokens) }))
    .filter((h) => h.sc > 1)
    .sort((a, b) => b.sc - a.sc)
    .map((h) => h.it);
  if (SEARCH_TYPE_FILTER && SEARCH_TYPE_FILTER !== "all")
    hits = hits.filter((h) => h.type === SEARCH_TYPE_FILTER);
  return hits.slice(0, SEARCH_CONF.limit);
}
export function hitsHTML(list, q) {
  const re = hlRe(q);
  return list
    .map(
      (h, i) =>
        '<div class="si" data-i="' +
        i +
        '"><span class="badge ' +
        h.cls +
        '">' +
        h.type +
        "</span><div><b>" +
        esc(h.title).replace(re, (m) => "<mark>" + m + "</mark>") +
        "</b><span>" +
        esc(h.sub).replace(re, (m) => "<mark>" + m + "</mark>") +
        "</span></div></div>",
    )
    .join("");
}
export function recentGet() {
  try {
    const r = JSON.parse(lsGet(K.recent(), "[]"));
    return Array.isArray(r) ? r : [];
  } catch (e) {
    return [];
  }
}
export function saveRecent(q) {
  q = (q || "").trim();
  if (q.length < 2) return;
  const r = recentGet().filter((x) => x !== q);
  r.unshift(q);
  lsSet(K.recent(), JSON.stringify(r.slice(0, 5)));
}
export let dIn = null,
  dRes = null;
export function closeDesktop() {
  if (dRes) dRes.classList.remove("show");
}
export function desktopShow(list, q) {
  CUR_HITS = list;
  CUR_ACT = -1;
  const types = ["all", "جلسه", "مفهوم", "فرمول", "واژه"];
  const filters =
    '<div class="sfilter">' +
    types
      .map(
        (t) =>
          '<button type="button" class="sfilter-btn' +
          (SEARCH_TYPE_FILTER === t ? " on" : "") +
          '" data-t="' +
          t +
          '">' +
          (t === "all" ? "همه" : t) +
          "</button>",
      )
      .join("") +
    "</div>";
  if (!list.length) {
    dRes.innerHTML =
      filters +
      '<div class="si"><span style="color:var(--text-tertiary)">موردی یافت نشد…</span></div>';
    dRes.classList.add("show");
    bindSFilters(q);
    return;
  }
  dRes.innerHTML = filters + hitsHTML(list, q);
  dRes.classList.add("show");
  dRes.querySelectorAll(".si").forEach((el) => (el.onclick = () => openHit(+el.dataset.i)));
  bindSFilters(q);
}
export function bindSFilters(q) {
  dRes.querySelectorAll(".sfilter-btn").forEach(
    (b) =>
      (b.onclick = (e) => {
        e.stopPropagation();
        SEARCH_TYPE_FILTER = b.dataset.t;
        desktopShow(runQuery(dIn.value || q || ""), dIn.value || q || "");
      }),
  );
}
export function showRecent() {
  const r = recentGet();
  if (!r.length) {
    dRes.classList.remove("show");
    return;
  }
  dRes.innerHTML =
    '<div class="si" style="cursor:default;flex-wrap:wrap;align-items:center"><span class="badge b-blu">اخیر</span><div style="flex:1">' +
    r.map((x) => '<span class="rchip">' + esc(x) + "</span>").join("") +
    '</div><span class="rchip rclear" title="پاک کردن تاریخچهٔ جست‌وجو">پاک کردن ✕</span></div>';
  dRes.classList.add("show");
  dRes.querySelectorAll(".rchip:not(.rclear)").forEach(
    (el) =>
      (el.onclick = () => {
        dIn.value = el.textContent;
        desktopShow(runQuery(el.textContent), el.textContent);
        dIn.focus();
      }),
  );
  dRes.querySelector(".rclear").onclick = (e) => {
    e.stopPropagation();
    lsDel(K.recent());
    dRes.classList.remove("show");
  };
}
export function openHit(i) {
  const h = CUR_HITS[i];
  if (!h) return;
  saveRecent((dIn.value || "").trim());
  if (typeof closeMobileSilent === "function") closeMobileSilent();
  
  try {
    go(h.page, h.anchor);
  } finally {
    closeDesktop();
    dIn.value = "";
    dIn.blur();
  }
}
export function _searchBind() {
  dIn = document.getElementById("searchIn");
  dRes = document.getElementById("searchRes");
  if (!dIn || !dRes) return;
  dIn.addEventListener("input", () => desktopShow(runQuery(dIn.value), dIn.value));
  dIn.addEventListener("focus", () => {
    const v = dIn.value.trim();
    if (!v) showRecent();
    else desktopShow(runQuery(v), v);
  });
  dIn.addEventListener("keydown", (e) => {
    if (e.key === "Escape") {
      closeDesktop();
      closeMobile();
      dIn.value = "";
      CUR_HITS = [];
      CUR_ACT = -1;
      if (dRes) dRes.classList.remove("show");
      dIn.blur();
    } else if (e.key === "ArrowDown" || e.key === "ArrowUp") {
      e.preventDefault();
      if (!CUR_HITS.length) return;
      CUR_ACT = (CUR_ACT + (e.key === "ArrowDown" ? 1 : -1) + CUR_HITS.length) % CUR_HITS.length;
      const els = dRes.querySelectorAll(".si");
      els.forEach((el, i) => el.classList.toggle("active", i === CUR_ACT));
      if (els[CUR_ACT]) els[CUR_ACT].scrollIntoView({ block: "nearest" });
    } else if (e.key === "Enter") {
      openHit(CUR_ACT >= 0 ? CUR_ACT : 0);
    }
  });
}
document.addEventListener("keydown", (e) => {
  if (e.key !== "/" || e.ctrlKey || e.metaKey || e.altKey) return;
  const ae = document.activeElement || {};
  const tag = ae.tagName || "";
  if (tag === "INPUT" || tag === "TEXTAREA" || ae.isContentEditable) return;
  e.preventDefault();
  const el = document.getElementById("searchIn");
  if (!el) return;
  const wrap = document.querySelector(".searchwrap");
  const isMobile = window.matchMedia("(max-width: 1024px)").matches;
  if (wrap && isMobile && !wrap.classList.contains("open")) {
    const btn = document.getElementById("searchBtn");
    if (btn) {
      btn.click();
      return;
    }
  }
  el.focus();
  el.select();
});
// [NOTE] عناصر موبایل دیرهنگام ساخته می‌شوند (بعد از Shell.mount)، پس همیشه در لحظهٔ استفاده خوانده می‌شوند
export const getMPanel = () => document.querySelector(".searchwrap");
export const getMOpenBtn = () =>
  document.getElementById("mobileSearchBtn") || document.getElementById("searchBtn");
export function _closeMobileDOM() {
  const mPanel = getMPanel(),
    mOpenBtn = getMOpenBtn();
  if (!mPanel) return;
  mPanel.classList.remove("open");
  if (mOpenBtn) {
    mOpenBtn.innerHTML = icon("search");
    mOpenBtn.setAttribute("aria-label", "جستجو");
  }
  dIn.value = "";
  dIn.blur();
}
export function openMobile() {
  const mPanel = getMPanel(),
    mOpenBtn = getMOpenBtn();
  if (!mPanel) return;
  if (typeof window._closeSidebarSilent === "function") window._closeSidebarSilent(true);
  mPanel.classList.add("open");
  if (mOpenBtn) {
    mOpenBtn.innerHTML = icon("close");
    mOpenBtn.setAttribute("aria-label", "بستن جستجو");
  }
  if (typeof window._ovOpen === "function") window._ovOpen(_closeMobileDOM);
  setTimeout(() => dIn.focus(), 260);
}
export function closeMobile() {
  const mPanel = getMPanel();
  if (!mPanel || !mPanel.classList.contains("open")) return;
  if (typeof window._ovClose === "function") window._ovClose(false);
  else _closeMobileDOM();
}
export function closeMobileSilent() {
  const mPanel = getMPanel();
  if (!mPanel || !mPanel.classList.contains("open")) return;
  if (typeof window._ovClose === "function") window._ovClose(true, true);
  else _closeMobileDOM();
}
window.closeMobileSilent = closeMobileSilent;
// [NOTE] از composedPath استفاده می‌شود: openMobile آیکن دکمه را عوض می‌کند و e.target ممکن است جدا شده باشد
export const inMBtn = (e) =>
  (e.composedPath ? e.composedPath() : []).some((n) => n && n.id === "mobileSearchBtn");
// [NOTE] کلیک دکمهٔ جستجوی موبایل با delegation گرفته می‌شود تا به ترتیب ساخت DOM وابسته نباشد
document.addEventListener("click", (e) => {
  if (!inMBtn(e)) return;
  const p = getMPanel();
  if (p && p.classList.contains("open")) closeMobile();
  else openMobile();
});
document.addEventListener("click", (e) => {
  if (!inMBtn(e) && !e.target.closest(".searchwrap") && !e.target.closest("#searchBtn")) {
    closeMobile();
    closeDesktop();
  }
});
addEventListener("resize", () => {
  if (innerWidth > 1060) {
    if (typeof closeMobileSilent === "function") closeMobileSilent();
    if (typeof window._closeSidebarSilent === "function") window._closeSidebarSilent(false);
  }
});
buildIndex();
if (window._shellMounted) _searchBind();
else window.addEventListener("lector:shell-mounted", _searchBind, { once: true });
