import { ArchetypeRegistry } from "./registry.js";
import type { Archetype, ArchetypeSession } from "./registry.js";

ArchetypeRegistry.register({
  id: "narrative",
  version: 1,
  extends: "base",
  resolveMode(mode: string | undefined, session: ArchetypeSession | undefined): string {
    return (ArchetypeRegistry.get("base") as Archetype).resolveMode(mode, session);
  },
  decorateSession(s: ArchetypeSession, mode: string | undefined): unknown {
    const stem = ArchetypeRegistry.get("stem");
    return stem && typeof stem.decorateSession === "function"
      ? stem.decorateSession(s, mode)
      : undefined;
  },
});
