import { PREFERENCES } from "./preferences/preferences.js";
import { $, escHtml } from "./core.js";
import type { Meta as PackMeta } from "./engine/contract/types.js";

export const DEFAULT_STOPS = ["#a78bfa", "#60a5fa", "#22d3ee", "#34d399", "#fbbf24"];
export const DEFAULT_LOGO_INNER =
  '<path d="M5 6h10a3 3 0 0 1 3 3v17a2 2 0 0 0-2-2H5z"/><path d="M27 6H17a3 3 0 0 0-3 3v17a2 2 0 0 1 2-2h11z"/>';

interface BrandConfig {
  themeColor?: string;
  primary?: string;
  logoSvg?: string;
  productName?: string;
  name?: string;
  hideAuthor?: boolean;
  supportUrl?: string;
}

interface LicenseConfig {
  mode?: string;
  required?: boolean;
  key?: string;
}

export type LicenseResult = { ok: false; reason: string } | { ok: true; mode: string };

// meta دوره (بدون خطا وقتی دوره یا meta هنوز نیست)
function courseMeta(): PackMeta {
  return CourseRuntime.getCourse()?.meta ?? {};
}

function isHex(s: unknown): boolean {
  return /^#[0-9a-f]{6}$/i.test(String(s || "").trim());
}
export const _isHex = isHex;

// پنج رنگ گرادیان درس (در صورت معتبر بودن)
function isStops(v: unknown): v is string[] {
  return Array.isArray(v) && v.length === 5 && v.every(isHex);
}

export function _shade(hex: string, k: number): string {
  const n = parseInt(hex.slice(1), 16);
  const c = (v: number): number => Math.max(0, Math.min(255, Math.round(v * (1 + k))));
  const r = c(n >> 16),
    g = c((n >> 8) & 255),
    b = c(n & 255);
  return "#" + ((1 << 24) | (r << 16) | (g << 8) | b).toString(16).slice(1);
}
export const _grad = (st: string[]): string => "linear-gradient(90deg," + st.join(",") + ")";

export function courseStops(): string[] | null {
  const st = courseMeta().look?.stops;
  return isStops(st) ? st : null;
}

export function applyCourseLook(): void {
  const look = courseMeta().look || {};
  const stops = courseStops();
  if (stops && !document.getElementById("course-accent")) {
    const [c0 = "", , c2 = ""] = stops;
    const darkAccent = c0;
    const lightAccent = _shade(c0, -0.28);
    const css =
      ':root[data-accent="course"]{--ac:' +
      darkAccent +
      ";--ac-2:" +
      stops[2] +
      "}" +
      ':root[data-theme="dark"][data-accent="course"]{--ac:' +
      darkAccent +
      ";--ac-2:" +
      c2 +
      ";--ac-ink:#0b0f1e;--accent:" +
      darkAccent +
      "}" +
      ':root[data-theme="light"][data-accent="course"]{--ac:' +
      lightAccent +
      ";--ac-2:" +
      _shade(c2, -0.28) +
      ";--ac-ink:#ffffff;--accent:" +
      lightAccent +
      "}" +
      ".set-seg.swatches button.sw-course{background:linear-gradient(90deg," +
      c0 +
      " 50%," +
      c2 +
      " 50%)}";
    const st = document.createElement("style");
    st.id = "course-accent";
    st.textContent = css;
    document.head.appendChild(st);
  }
  PREFERENCES.forEach((g) =>
    g.items.forEach((it) => {
      if (it.key === "accent") {
        if (stops && !it.options.some((o) => o.val === "course"))
          it.options.unshift({ val: "course", label: "رنگ درس" });
        const want: string | null =
          typeof look.accent === "string" && look.accent ? look.accent : stops ? "course" : null;
        if (want && it.options.some((o) => o.val === want)) it.default = want;
      }
      if (it.key === "theme" && ["dark", "light", "system"].includes(String(look.theme)))
        it.default = String(look.theme);
    }),
  );
}

function sanitizedLogoInner(): string {
  return String(courseMeta().logoSvg || DEFAULT_LOGO_INNER)
    .replace(/<script[\s\S]*?<\/script>/gi, "")
    .replace(/\son\w+\s*=\s*("[^"]*"|'[^']*')/gi, "");
}

export function _logoSvgMarkup(): string {
  return (
    '<svg viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round">' +
    sanitizedLogoInner() +
    "</svg>"
  );
}

export function _faviconDataUri(theme: string): string {
  const stroke = theme === "light" ? "#1e293b" : "#e8ebf5";
  const svg =
    '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 32">' +
    '<g fill="none" stroke="' +
    stroke +
    '" stroke-width="2.6" ' +
    'stroke-linecap="round" stroke-linejoin="round">' +
    sanitizedLogoInner() +
    "</g></svg>";
  return "data:image/svg+xml," + encodeURIComponent(svg);
}

// فاوآیکن: اگر دوره لوگوی سفارشی دارد همان، وگرنه مکعب لکتور (public/favicon.svg) که خودش تم‌آگاه است
export function syncFavicon(): void {
  const link = document.querySelector<HTMLLinkElement>('link[rel="icon"]');
  if (!link) return;
  const custom = courseMeta().logoSvg;
  link.type = "image/svg+xml";
  if (custom) {
    const isDark =
      typeof window.matchMedia === "function"
        ? matchMedia("(prefers-color-scheme: dark)").matches
        : true;
    link.href = _faviconDataUri(isDark ? "dark" : "light");
  } else {
    link.href = "./public/favicon.svg";
  }
}
if (typeof window.matchMedia === "function") {
  try {
    matchMedia("(prefers-color-scheme: dark)").addEventListener("change", syncFavicon);
  } catch {
    // مرورگرهای قدیمی‌تر از addEventListener روی MediaQueryList پشتیبانی نمی‌کنند
  }
}

export function applyBrand(): void {
  const m = courseMeta();
  document.title =
    m.appName + (m.subtitle ? " | " + m.subtitle : "") + (m.uni ? " — " + m.uni : "");
  const an = $(".app-name") || $(".sb-brand-tx b");
  if (an) an.textContent = String(m.appName);
  const sl = $(".sub-long");
  if (sl)
    sl.textContent =
      (m.title ? "دستیار تخصصی درس " + m.title + " · " : "") + (m.uni ? m.uni + " · " : "");
  const vt = $(".ver-tag");
  if (vt) vt.textContent = String(m.ver);
  const lg = $(".brand .logo");
  if (lg) lg.innerHTML = _logoSvgMarkup();
  updateFooter();
  syncThemeColor();
  applyBrandWhiteLabel();
}

export const ENGINE_INFO = { tag: "LECTOR ENGINE", version: "v1.0.1" };

export function updateFooter(): void {
  const el = document.getElementById("app-footer");
  if (!el) return;
  el.innerHTML =
    `<span class="af-tag">${escHtml(ENGINE_INFO.tag)}</span>` +
    `<span class="af-sep" aria-hidden="true">·</span>` +
    `<span class="af-ver">${escHtml(ENGINE_INFO.version)}</span>` +
    `<span class="af-sep" aria-hidden="true">·</span>` +
    `<button type="button" class="af-link" id="afAbout">درباره‌ی برنامه</button>`;
  const btn = document.getElementById("afAbout");
  if (btn)
    btn.onclick = () => {
      location.hash = "#/settings/about";
    };
}

export function syncThemeColor(): void {
  const bg = getComputedStyle(document.documentElement).getPropertyValue("--surface-canvas").trim();
  if (!bg) return;
  const metas = document.querySelectorAll('meta[name="theme-color"]');
  if (metas.length) {
    metas.forEach((m) => m.setAttribute("content", bg));
    return;
  }
  const mt = document.createElement("meta");
  mt.name = "theme-color";
  mt.content = bg;
  document.head.appendChild(mt);
}

export function applyBrandWhiteLabel(): void {
  const meta = courseMeta();
  const brand = (meta.brand ?? {}) as BrandConfig;
  const root = document.documentElement;
  if (brand.themeColor) {
    document.querySelectorAll('meta[name="theme-color"]').forEach((m) => {
      m.setAttribute("content", brand.themeColor ?? "");
    });
  }
  if (brand.primary && /^#[0-9a-fA-F]{6}$/.test(brand.primary)) {
    root.style.setProperty("--brand-primary", brand.primary);
  }
  if (brand.logoSvg && !meta.logoSvg) {
    meta.logoSvg = brand.logoSvg;
  }
  if (brand.productName || brand.name) {
    const title = brand.productName || brand.name || "";
    const el = document.querySelector(".app-name");
    if (el) el.textContent = title;
    try {
      document.title = title;
    } catch {
      // عنوان سند ممکن است در بعضی محیط‌ها قابل تغییر نباشد
    }
  }
  if (brand.hideAuthor) {
    document.querySelectorAll<HTMLElement>("[data-brand-author]").forEach((n) => {
      n.hidden = true;
    });
  }
  if (brand.supportUrl) {
    root.setAttribute("data-support-url", brand.supportUrl);
  }
}

export function checkLicense(): LicenseResult {
  const lic = (courseMeta().license ?? {}) as LicenseConfig;
  if (lic.mode === "key" && lic.required && !lic.key) {
    return { ok: false, reason: "license-key-missing" };
  }
  return { ok: true, mode: lic.mode || "open" };
}

export function assertLicenseOrBanner(): void {
  if (!flagOn("licenseEnforcement")) return;
  const r = checkLicense();
  if (r.ok) return;
  if (document.getElementById("licBanner")) return;
  const bar = document.createElement("div");
  bar.id = "licBanner";
  bar.setAttribute("role", "status");
  bar.style.cssText =
    "position:fixed;bottom:0;left:0;right:0;z-index:100;padding:10px 16px;background:var(--surface-raised);border-top:1px solid var(--border-subtle);text-align:center;font-size:calc(13px * var(--fs-scale, 1));color:var(--text-secondary)";
  bar.textContent = "این بسته به کلید لایسنس نیاز دارد (مسیر آیندهٔ API).";
  document.body.appendChild(bar);
}
