// رندررهای رسانه (Phase 5.5): figure و mermaid.
import { escHtml } from "../escape.js";
import type { BlockMap, Renderer } from "../types.js";

export const renderFigure: Renderer<BlockMap["figure"]> = (b) => {
  const cap = b.caption ? `<figcaption>${escHtml(b.caption)}</figcaption>` : "";
  return `<figure class="rd-figure"><img src="${escHtml(b.src || "")}" alt="${escHtml(b.alt || b.caption || "")}" loading="lazy"/>${cap}</figure>`;
};

// کد Mermaid به‌صورت متن escape‌شده داخل .mmd می‌رود؛ رندر واقعی Mermaid در ویوور انجام می‌شود.
export const renderMermaid: Renderer<BlockMap["mermaid"]> = (b) => {
  const cap = b.caption ? `<figcaption>${escHtml(b.caption)}</figcaption>` : "";
  return `<figure class="rd-figure rd-mmd"><div class="mmd">${escHtml(b.code || "")}</div>${cap}</figure>`;
};
