import { main } from "../../preferences/prefs.js";
import { after, escHtml, toFa } from "../../core.js";
import { icon } from "../components/icons.js";
export function pageLab() {
  const widgetEntries = Object.entries(CourseRuntime.getWidgets() || {});
  if (!widgetEntries.length) {
    main.innerHTML = `<div class="page"><div class="card" style="padding:24px;text-align:center">ویجتی در این درس تعریف نشده است.</div></div>`;
    return;
  }

  const cards = widgetEntries
    .map(([k, w]) => {
      const sessArr = Array.isArray(w.sess) ? w.sess : [];
      const sessLinks = sessArr
        .map((id) => {
          const ss = ((CourseRuntime.getCourse() || {}).sessions || []).find((x) => x.id === id);
          return ss
            ? `<a onclick="go('s/${id}')" style="cursor:pointer">جلسهٔ ${toFa(ss.num)}</a>`
            : "";
        })
        .filter(Boolean)
        .join("، ");
      const relatedHTML = sessLinks
        ? ` <span style="color:var(--text-tertiary)">· مرتبط با ${sessLinks}</span>`
        : "";
      return `<div class="widget" id="lab-${escHtml(k)}" data-lab-anchor="${escHtml(k)}">
    <div class="wt"><span class="wt-ic">${icon("flask")}</span><h3>${escHtml(w.title)}</h3></div>
    <div class="wd">${w.desc}${relatedHTML}</div>
    <div data-widget="${escHtml(k)}"></div>
  </div>`;
    })
    .join("");

  const side = widgetEntries
    .map(
      ([k, w], i) => `
  <a class="pss-item" href="#lab-${escHtml(k)}" data-anchor="lab-${escHtml(k)}">
    <span class="pss-num">${toFa(i + 1)}</span>
    <span class="pss-body">
      <b>${escHtml(w.title || k)}</b>
      <span class="pss-meta">${Array.isArray(w.sess) && w.sess.length ? "مرتبط با " + toFa(w.sess.length) + " جلسه" : "بدون ارتباط"}</span>
    </span>
  </a>`,
    )
    .join("");

  main.innerHTML = `<div class="page lab-page">
  <header class="lab-hero">
    <span class="lab-kicker">${icon("flask")}آزمایشگاه</span>
    <h1 class="lab-h1">${escHtml((CourseRuntime.getCourse() || {}).meta.labTitle || "آزمایشگاه تعاملی")}</h1>
    <p class="lab-sub">${escHtml((CourseRuntime.getCourse() || {}).meta.labSubtitle || "شبیه‌سازی‌های تعاملی درس را خودتان کاوش کنید")}</p>
  </header>
  <div class="lab-grid">
    <div class="lab-main">
      <div class="lab-list">${cards}</div>
    </div>
    <aside class="lab-side" aria-label="فهرست ویجت‌ها">
      <div class="pss-card pss-card--toc">
        <div class="pss-head">${icon("flask")}<b>ویجت‌ها</b><span class="pss-count">${toFa(widgetEntries.length)}</span></div>
        <nav class="pss-nav">${side}</nav>
      </div>
    </aside>
  </div>
</div>`;

  after(main);

  (function initLabScrollSpy() {
    const sidebar = main.querySelector(".lab-side");
    if (!sidebar) return;
    const links = Array.from(sidebar.querySelectorAll(".pss-item[data-anchor]"));
    if (!links.length) return;
    const targets = links.map((a) => document.getElementById(a.dataset.anchor)).filter(Boolean);
    if (!targets.length) return;

    let raf = 0;
    const tick = () => {
      raf = 0;
      const ref = (window.scrollY || document.documentElement.scrollTop) + 140;
      let active = -1;
      for (let i = 0; i < targets.length; i++) {
        if (targets[i].offsetTop <= ref) active = i;
        else break;
      }
      links.forEach((a, i) => a.classList.toggle("on", i === active));
    };
    const onScroll = () => {
      if (!raf) raf = requestAnimationFrame(tick);
    };
    window.addEventListener("scroll", onScroll, { passive: true });
    tick();

    links.forEach((a) =>
      a.addEventListener("click", (e) => {
        const el = document.getElementById(a.dataset.anchor);
        if (!el) return;
        e.preventDefault();
        const y = el.getBoundingClientRect().top + window.scrollY - 96;
        window.scrollTo({ top: y, behavior: "smooth" });
      }),
    );

    const prev = window._sessCleanup;
    window._sessCleanup = () => {
      if (prev)
        try {
          prev();
        } catch (_) {}
      window.removeEventListener("scroll", onScroll);
      if (raf) cancelAnimationFrame(raf);
    };
  })();
}
