// رندررهای اولیه (Phase 5.2): p، h، list، hr، quote.
import { escHtml } from "../escape.js";
import type { BlockMap, Renderer } from "../types.js";
import { textHTML } from "./shared.js";

export const renderParagraph: Renderer<BlockMap["p"]> = (b) => `<p class="rd-p">${textHTML(b)}</p>`;

// سطح فقط ۳ یا ۴ است؛ هر مقدار دیگر به ۳ برمی‌گردد (همان قاعدهٔ نسخهٔ قبلی).
export const renderHeading: Renderer<BlockMap["h"]> = (b) => {
  const level = b.level === 4 ? 4 : 3;
  const tag = level === 4 ? "h4" : "h3";
  return `<${tag} class="rd-h${level}">${textHTML(b)}</${tag}>`;
};

export const renderList: Renderer<BlockMap["list"]> = (b) => {
  const tag = b.ordered ? "ol" : "ul";
  const items = (b.items || [])
    .map((it) => {
      if (typeof it === "string") return `<li>${it}</li>`;
      // آیتم تهی (null/undefined) به‌جای خطا، `li` خالی می‌شود.
      if (it == null) return "<li></li>";
      return `<li>${it.html || escHtml(it.text || "")}</li>`;
    })
    .join("");
  return `<${tag} class="rd-list">${items}</${tag}>`;
};

export const renderRule: Renderer<BlockMap["hr"]> = () => `<hr class="rd-hr"/>`;

export const renderQuote: Renderer<BlockMap["quote"]> = (b) => {
  const by = b.by ? `<cite>— ${escHtml(b.by)}</cite>` : "";
  return `<blockquote class="rd-quote">${textHTML(b)}${by}</blockquote>`;
};
