// نرمال‌سازی پک خام به شکل قرارداد v3: مقدارهای پیش‌فرض، آلیاس‌های نسخهٔ قدیمی و جایگزینی placeholderها.
// نرمال‌سازی داده را تغییر می‌دهد؛ درستیِ آن را validate بررسی می‌کند.

import { normalizePresentationMeta } from "./presentation.js";
import { CONTRACT_VERSION } from "./constants.js";
import { deriveProblemRefs } from "./derive.js";
import type { Concept, Course, Formula, Meta, Pack, Problem, Session } from "./types.js";

type Dict = Record<string, unknown>;

export function isObj(v: unknown): v is Dict {
  return !!v && typeof v === "object";
}

// ورودی کوتاه و ناقص را به Course کامل تبدیل می‌کند (در جا)
export function normalizeCourse(input: unknown): Course {
  const C = (isObj(input) ? input : {}) as Dict;
  const m = (C.meta = isObj(C.meta) ? C.meta : {}) as Dict;
  m.title = m.title || "";
  m.appName = m.appName || m.title || "درسنامه";
  m.subtitle = m.subtitle || "درسنامه تعاملی";
  m.uni = m.uni || "";
  m.term = m.term || "";
  m.ver = m.ver || "v0.1";
  m.author = m.author || "";
  m.id = m.id || "course";
  m.contract = Number.isFinite(+(m.contract as number))
    ? +(m.contract as number)
    : CONTRACT_VERSION;
  m.look = isObj(m.look) ? m.look : {};
  m.archetype = m.archetype || "stem";
  m.structure = m.structure || "linear";
  normalizePresentationMeta(m as Meta);
  m.cover = isObj(m.cover) ? m.cover : null;
  m.category = m.category || "";
  m.level = m.level || "";
  m.rating = Number.isFinite(+(m.rating as number)) ? +(m.rating as number) : null;
  m.students = Number.isFinite(+(m.students as number)) ? +(m.students as number) : null;
  m.price = Number.isFinite(+(m.price as number)) ? +(m.price as number) : 0;
  m.oldPrice = Number.isFinite(+(m.oldPrice as number)) ? +(m.oldPrice as number) : 0;
  if (!Array.isArray(m.tags)) m.tags = [];
  m.brand = isObj(m.brand) ? m.brand : {};
  m.license = isObj(m.license) ? m.license : { mode: "key" };
  m.shell = isObj(m.shell) ? m.shell : {};
  m.labels = isObj(m.labels) ? m.labels : {};
  m.features = isObj(m.features) ? m.features : {};
  ["grading", "books", "chapters", "sessions", "glossary", "knowledge"].forEach((k) => {
    if (!Array.isArray(C[k])) C[k] = [];
  });

  const sessions = C.sessions as Session[];
  sessions.forEach((s0, i) => {
    const s = (isObj(s0) ? s0 : {}) as Session;
    sessions[i] = s;
    normalizeSession(s, i);
  });

  const phMap: Record<string, number> = {
    sessions: sessions.length,
    chapters: ((C.chapters as unknown[]) || []).length,
    glossary: ((C.glossary as unknown[]) || []).length,
    formulas: sessions.reduce((a, s) => a + (s.formulas || []).length, 0),
    concepts: sessions.reduce((a, s) => a + (s.concepts || []).length, 0),
  };
  ["description", "gradingNote"].forEach((k) => {
    const v = m[k];
    if (typeof v === "string" && v.indexOf("{") !== -1) {
      m[k] = v.replace(/\{(\w+)\}/g, (_: string, key: string) =>
        phMap[key] != null ? String(phMap[key]) : "",
      );
    }
  });

  return C as Course;
}

// یک جلسه در جا نرمال می‌شود؛ i اندیس آن در فهرست است (برای id و num پیش‌فرض)
function normalizeSession(s: Session, i: number): void {
  s.id = s.id || "s" + String(i + 1).padStart(2, "0");
  s.num = Number.isFinite(+s.num) ? +s.num : i + 1;
  s.date = s.date || "—";
  s.time = s.time || "—";
  s.title = s.title || "جلسهٔ " + s.num;
  if (s.experience === undefined) s.experience = "editorial";
  ["prereq", "topics", "concepts", "formulas", "tips", "diagrams", "widgets", "footnotes"].forEach(
    (k) => {
      const key = k as keyof Session;
      if (!Array.isArray(s[key])) (s as Dict)[k] = [];
    },
  );
  s.summary = s.summary || "";
  s.concepts.forEach((c0, ci) => {
    const c = (isObj(c0) ? c0 : {}) as Concept;
    s.concepts[ci] = c;
    if (!Array.isArray(c.pts)) c.pts = [];
  });
  s.formulas.forEach((f0, fi) => {
    const f = (isObj(f0) ? f0 : {}) as Formula;
    s.formulas[fi] = f;
    if (!Array.isArray(f.vars)) f.vars = [];
    f.use = f.use || "";
    f.tex = f.tex || "";
    if (f.review !== false) f.review = true;
  });

  s.review = s.review === "off" ? "off" : "auto";
  s.concepts.forEach((c) => {
    if (c && c.review !== false) c.review = true;
  });

  if (s.detail && typeof s.detail === "object") {
    const d = s.detail;
    d.intro = d.intro || "";
    d.outro = d.outro || "";
    if (!Array.isArray(d.sections)) d.sections = [];
    d.sections = d.sections.filter(
      (sec) => sec && typeof sec === "object" && Array.isArray(sec.blocks),
    );
    d.sections.forEach((sec, si) => {
      sec.id = sec.id || s.id + "-sec-" + (si + 1);
      sec.title = sec.title || "";
      sec.blocks = sec.blocks.filter((b) => b && typeof b === "object" && b.type);
    });
  } else {
    s.detail = null;
  }
}

// مسائل را در جا نرمال می‌کند؛ id تکراری با پسوند شمارهٔ ردیف یکتا می‌شود
export function normalizeProblems(input: unknown): Problem[] {
  const list = (Array.isArray(input) ? input : []) as Problem[];
  const seen = new Set<unknown>();
  list.forEach((p0, i) => {
    if (!p0 || typeof p0 !== "object") return;
    const p = p0;
    p.id = p.id || "p-auto-" + (i + 1);
    if (seen.has(p.id)) p.id = p.id + "-" + (i + 1);
    seen.add(p.id);
    p.section = p.section != null ? p.section : 0;
    p.title = p.title || "مسئله " + p.id;
    p.statement = p.statement != null ? p.statement : "";
    // آلیاس‌های نسخهٔ قدیمی‌تر داده (بدون تغییر در فایل داده):
    //   sess → session ، hint (رشته) → hints ([رشته])
    if (p.session == null && p.sess != null) p.session = p.sess;
    if (!Array.isArray(p.hints)) {
      p.hints = typeof p.hint === "string" && p.hint ? [p.hint] : [];
    }
    if (!Array.isArray(p.steps)) p.steps = [];
    if (!Array.isArray(p.refs)) p.refs = [];
    if (!Array.isArray(p.tags)) p.tags = [];
    if (!Array.isArray(p.concepts)) p.concepts = [];
    if (p.answerSpec === undefined) p.answerSpec = null;
  });
  return list;
}

// خروجی خام هر شکل پک (raw.course یا خود raw) را به Pack قرارداد v3 تبدیل می‌کند
export function normalizePack(source: unknown): Pack {
  const raw = (isObj(source) ? source : {}) as Dict & Partial<Pack>;
  const course = normalizeCourse(raw.course || raw);
  const problems = normalizeProblems(raw.problems);
  return {
    kind: "lector-pack-data",
    contract: CONTRACT_VERSION,
    id: String(raw.id || course.meta.id || "course"),
    course,
    categories: raw.categories || raw.cats || {},
    problemNote: raw.problemNote || "",
    problemSections: Array.isArray(raw.problemSections) ? raw.problemSections : [],
    problemHtml: isObj(raw.problemHtml) ? raw.problemHtml : {},
    problemRefs: deriveProblemRefs(problems),
    problems,
    knowledge: Array.isArray(course.knowledge) ? course.knowledge : [],
    widgets: isObj(raw.widgets) ? raw.widgets : {},
    reviewCards: Array.isArray(raw.reviewCards) ? raw.reviewCards : [],
    assessments: Array.isArray(raw.assessments) ? raw.assessments : [],
    graphNodes: Array.isArray(raw.graphNodes) ? raw.graphNodes : [],
  };
}
