// اعتبارسنجی پک، جلسه و فرمول (قرارداد v3). خروجی: فهرست مسائل با سطح error/warn/info.
// ترتیب و متن پیام‌ها عمداً ثابت است تا نتیجهٔ اعتبارسنجی بین نسخه‌ها قابل مقایسه بماند.

import { BLOCK_TYPES, CALLOUT_TONES, HEADING_LEVELS } from "../blocks/block-types.js";
import type { KnowledgeGraph, KnowledgeGraphApi } from "../mastery/knowledge-graph.js";
import { getPack } from "../runtime/active.js";
import { resolvePresentation } from "./presentation.js";
import { ACCEPTED_CONTRACTS, CONTRACT_VERSION, EXPERIENCE_KINDS } from "./constants.js";
import type {
  Block,
  Course,
  Formula,
  Meta,
  Pack,
  Problem,
  Session,
  ValidationIssue,
  Widget,
} from "./types.js";

// سرویس‌های همسایه که روی global ثبت می‌شوند (وابستگی حلقه‌ای نداشته باشیم)
export interface AnswerCheckApi {
  validateSpec(spec: unknown): string[];
}

declare global {
  var AnswerCheck: AnswerCheckApi;
  var KnowledgeGraph: KnowledgeGraphApi;
}

type Dict = Record<string, unknown>;
type Add = (lvl: string, where: string, msg: string) => void;

const blockTypes: readonly string[] = BLOCK_TYPES;
const calloutTones: readonly string[] = CALLOUT_TONES;
const headingLevels: readonly unknown[] = HEADING_LEVELS;

export interface FormulaEnv {
  cats: Dict;
  titles: Set<unknown>;
  add: Add;
}

export interface SessionEnv {
  widgets: Dict;
  cats: Dict;
  add: Add;
}

// فرمول یک جلسه: عنوان یکتا در جلسه، tex معتبر، دسته‌بندی و vars
export function validateFormula(f: Formula, where: string, env: FormulaEnv): void {
  const { cats, titles, add } = env;
  if (!f.t) add("error", where, "عنوان (t) ندارد");
  else if (titles.has(f.t))
    add("error", where, "عنوان فرمول در جلسه یکتا نیست («" + String(f.t) + "»)");
  titles.add(f.t);
  if (!f.tex) add("error", where, "tex خالی است");
  if (/\$|`|\$\{/.test(String(f.tex))) add("error", where, "tex نباید $ یا backtick داشته باشد");
  if (f.cat && !cats[String(f.cat)])
    add("warn", where, "cat=«" + String(f.cat) + "» در categories نیست (به «سایر» می‌رود)");
  if (!f.cat) add("warn", where, "cat ندارد");
  (f.vars || []).forEach((v) => {
    if (!Array.isArray(v) || v.length !== 2)
      add("error", where, "vars باید آرایهٔ جفت‌های دوعضوی باشد");
  });
  if (f.review !== undefined && typeof f.review !== "boolean") {
    add("error", where + " · review", "باید boolean باشد");
  }
}

// بلوک یک بخش detail: نوع، ارجاع‌ها و فیلدهای الزامی هر نوع
function validateBlock(b: Block, bw: string, s: Session, widgets: Dict, add: Add): void {
  if (!blockTypes.includes(String(b.type))) {
    add("warn", bw, "type ناشناخته «" + String(b.type) + "»");
    return;
  }
  if (b.type === "formula") {
    if (!b.ref) add("error", bw, "formula بدون ref");
    else if (!s.formulas.some((f) => f.t === b.ref))
      add("error", bw, "formula.ref=«" + String(b.ref) + "» در فرمول‌های " + s.id + " نیست");
  }
  if (b.type === "widget") {
    if (!b.ref) add("error", bw, "widget بدون ref");
    else if (!widgets[String(b.ref)])
      add("error", bw, "widget.ref=«" + String(b.ref) + "» در Pack نیست");
  }
  if (b.type === "math" && !b.tex) add("error", bw, "math بدون tex");
  if (b.type === "list" && !Array.isArray(b.items)) add("error", bw, "list بدون items");
  if (b.type === "table" && (!Array.isArray(b.head) || !Array.isArray(b.rows)))
    add("error", bw, "table نیازمند head و rows آرایه‌ای");
  if (b.type === "quiz" && (!Array.isArray(b.options) || !Number.isInteger(b.answer)))
    add("error", bw, "quiz نیازمند options آرایه‌ای و answer عدد صحیح");
  if (b.type === "flash" && !Array.isArray(b.cards))
    add("error", bw, "flash نیازمند cards آرایه‌ای");
  if (b.type === "compare" && !Array.isArray(b.columns))
    add("error", bw, "compare نیازمند columns آرایه‌ای");
  if (b.type === "steps" && !Array.isArray(b.items))
    add("error", bw, "steps نیازمند items آرایه‌ای");
  if (b.type === "keys" && !Array.isArray(b.items)) add("error", bw, "keys نیازمند items آرایه‌ای");
  if (b.type === "figure") {
    if (!b.src) add("error", bw, "figure بدون src");
    else if (!b.alt) add("warn", bw, "figure بدون alt");
    if (!b.caption) add("warn", bw, "figure بدون caption");
  }
  if (b.type === "mermaid" && !b.code) add("error", bw, "mermaid بدون code");
  if (b.type === "callout" && b.tone && !calloutTones.includes(String(b.tone)))
    add("warn", bw, "callout.tone ناشناخته «" + String(b.tone) + "»");
  if (b.type === "h" && b.level !== undefined && !headingLevels.includes(b.level))
    add("warn", bw, "h.level فقط 3 یا 4 مجاز است");
  if (b.type === "hr")
    add(
      "warn",
      bw,
      "hr داخل blocks فقط برای سازگاری نگه داشته شده؛ توصیه می‌شود بین sectionها باشد",
    );
}

// یک جلسه (بدون بررسی یکتایی id/num که در سطح پک انجام می‌شود)
export function validateSession(s: Session, env: SessionEnv): void {
  const { widgets, cats, add } = env;
  const w = "جلسهٔ " + String(s.num) + " (" + String(s.id) + ")";
  if (!/^s\d{2,}$/.test(s.id)) add("warn", w, "الگوی id باید sNN باشد");
  if (!s.concepts.length) add("warn", w, "بدون مفهوم");
  s.concepts.forEach((c, i) => {
    if (!c.t) add("error", w + " · مفهوم " + (i + 1), "عنوان (t) ندارد");
  });
  if (s.review !== "auto" && s.review !== "off") {
    add("error", w + " · review", 'مقدار باید "auto" یا "off" باشد');
  }
  s.concepts.forEach((c, i) => {
    if (c.review !== undefined && typeof c.review !== "boolean") {
      add("error", w + " · مفهوم " + (i + 1) + " · review", "باید boolean باشد");
    }
  });
  const titles = new Set<unknown>();
  s.formulas.forEach((f, i) =>
    validateFormula(f, w + " · فرمول " + (i + 1), { cats, titles, add }),
  );
  s.widgets.forEach((k) => {
    if (!widgets[String(k)]) add("error", w, "ویجت «" + String(k) + "» در Pack ثبت نشده");
  });

  if (s.detail) {
    if (!s.detail.sections.length) add("warn", w + " · detail", "detail بدون بخش معتبر");
    s.detail.sections.forEach((sec, si) => {
      const sw = w + " · detail §" + (si + 1) + (sec.title ? " («" + sec.title + "»)" : "");
      sec.blocks.forEach((b, bi) => validateBlock(b, sw + " بلوک " + (bi + 1), s, widgets, add));
    });
  }
}

export function validatePack(pack: Pack | null | undefined): ValidationIssue[] {
  const p = (pack || {}) as Partial<Pack>;
  const C = (p.course || {}) as Partial<Course>;
  const m = (C.meta || {}) as Meta;
  const cats = (p.categories || {}) as Dict;
  const widgets = (p.widgets || {}) as Record<string, Widget | unknown>;
  const problems = (Array.isArray(p.problems) ? p.problems : []) as Problem[];
  const sections = (Array.isArray(p.problemSections) ? p.problemSections : []) as Dict[];
  const refs = (p.problemRefs || {}) as Record<string, unknown>;
  const sessions = (C.sessions || []) as Session[];
  const issues: ValidationIssue[] = [];
  const add: Add = (lvl, where, msg) => {
    issues.push({ lvl, where, msg });
  };

  if (!m.title) add("warn", "meta.title", "عنوان درس خالی است");
  if (!m.id || m.id === "course")
    add("warn", "meta.id", "شناسهٔ ذخیره‌سازی (meta.id) تعریف نشده یا عمومی است");
  if (m.contract && (m.contract as number) > CONTRACT_VERSION)
    add(
      "warn",
      "meta.contract",
      "data.js با قرارداد نسخهٔ " +
        String(m.contract) +
        " ساخته شده ولی اپ فقط تا " +
        CONTRACT_VERSION +
        " را می‌شناسد",
    );
  if (
    m.contract &&
    !ACCEPTED_CONTRACTS.includes(m.contract as number) &&
    (m.contract as number) <= CONTRACT_VERSION
  )
    add("warn", "meta.contract", "نسخهٔ قرارداد " + String(m.contract) + " پشتیبانی نمی‌شود");
  const look = (m.look || {}) as Dict;
  if (look.stops && (!Array.isArray(look.stops) || look.stops.length !== 5))
    add("error", "meta.look.stops", "stops باید آرایهٔ ۵ رنگ hex باشد");
  if (!Object.keys(cats).length) add("warn", "categories", "هیچ دسته‌بندی فرمولی تعریف نشده");

  const ids = new Set<unknown>();
  const nums = new Set<unknown>();
  sessions.forEach((s) => {
    const w = "جلسهٔ " + String(s.num) + " (" + String(s.id) + ")";
    if (ids.has(s.id)) add("error", w, "id تکراری");
    if (nums.has(s.num)) add("error", w, "num تکراری");
    ids.add(s.id);
    nums.add(s.num);
    validateSession(s, { widgets: widgets as Dict, cats, add });
  });

  Object.entries(widgets).forEach(([wk, w0]) => {
    if (!w0 || typeof w0 !== "object") {
      add("error", "ویجت " + wk, "تعریف ویجت ناقص است");
      return;
    }
    const w = w0 as { sess?: unknown };
    if (w.sess != null && !Array.isArray(w.sess)) {
      add("warn", "ویجت " + wk, "sess باید آرایه باشد");
      return;
    }
    ((w.sess as unknown[]) || []).forEach((sid) => {
      if (!ids.has(sid))
        add("warn", "ویجت " + wk, "sess به جلسهٔ ناموجود " + String(sid) + " اشاره می‌کند");
    });
  });

  const chapterNums = new Set<unknown>();
  ((C.chapters || []) as Dict[]).forEach((c) => {
    if (chapterNums.has(c.n)) add("error", "فصل " + String(c.n), "شمارهٔ فصل تکراری");
    chapterNums.add(c.n);
  });
  ((C.glossary || []) as Dict[]).forEach((g, i) => {
    if (!g.t || !g.d) add("warn", "واژه‌نامه #" + (i + 1), "t یا d خالی است");
  });
  sections.forEach((s) =>
    ((s.links || []) as unknown[]).forEach((id) => {
      if (!ids.has(id))
        add("warn", "مسائل · " + String(s.t), "لینک به جلسهٔ ناموجود " + String(id));
    }),
  );
  Object.entries(refs).forEach(([pid, rs]) =>
    ((rs || []) as [string, string][]).forEach(([sid, t]) => {
      const s = sessions.find((x) => x.id === sid);
      if (!s) add("warn", "مسئله " + pid, "ارجاع به جلسهٔ ناموجود " + sid);
      else if (!s.formulas.some((f) => f.t === t))
        add("warn", "مسئله " + pid, "فرمول «" + t + "» در " + sid + " پیدا نشد");
    }),
  );

  // ── قرارداد v3 ──────────────────────────────────────────────
  sessions.forEach((s) => {
    if (!EXPERIENCE_KINDS.includes(String(s.experience))) {
      add(
        "error",
        "جلسهٔ " + s.num + " (" + s.id + ") · experience",
        "«" + String(s.experience) + "» معتبر نیست؛ یکی از: " + EXPERIENCE_KINDS.join("، "),
      );
    }
  });

  const problemIdSet = new Set<unknown>(problems.map((p) => p.id));
  const knowledgeIds = new Set<string>(
    ((C.knowledge || []) as Dict[]).map((k) => (k && typeof k.id === "string" ? k.id.trim() : "")),
  );
  problems.forEach((p) => {
    const pw = "مسئلهٔ " + p.id;
    if (p.session != null && !ids.has(p.session))
      add("warn", pw, "session=«" + String(p.session) + "» به جلسهٔ ناموجود اشاره می‌کند");
    if (p.answerSpec != null && typeof AnswerCheck !== "undefined") {
      AnswerCheck.validateSpec(p.answerSpec).forEach((msg) =>
        add("error", pw + " · answerSpec", msg),
      );
    }
    ((p.concepts || []) as unknown[]).forEach((kid) => {
      if (!knowledgeIds.has(String(kid)))
        add("warn", pw, "concept «" + String(kid) + "» در course.knowledge نیست");
    });
  });

  if (((C.knowledge || []) as unknown[]).length && typeof KnowledgeGraph !== "undefined") {
    const g: KnowledgeGraph = KnowledgeGraph.buildKnowledgeGraph(C.knowledge);
    g.errors.forEach((e) => add("error", "knowledge", e.msg));
    g.missing.forEach((mm) =>
      add("error", "knowledge · " + mm.id, "پیش‌نیاز «" + mm.ref + "» تعریف نشده است"),
    );
    if (g.cycle) add("error", "knowledge", "چرخه در پیش‌نیازها: " + g.cycle.join(" → "));
    g.nodes.forEach((n) => {
      n.sessions.forEach((sid) => {
        if (!ids.has(sid)) add("warn", "knowledge · " + n.id, "جلسهٔ ناموجود «" + sid + "»");
      });
      n.problems.forEach((pid) => {
        if (!problemIdSet.has(pid))
          add("warn", "knowledge · " + n.id, "مسئلهٔ ناموجود «" + pid + "»");
      });
    });
  }

  resolvePresentation(m as Dict as Meta).issues.forEach((i) =>
    add(i.level, "meta · " + i.path, i.msg),
  );
  return issues;
}

// اعتبارسنجی و نوشتن نتیجه روی خود پک (pack.validation)
export function runPackValidation(pack?: Pack | null): ValidationIssue[] {
  const target = pack || getPack();
  const issues = validatePack(target);
  if (target && typeof target === "object") target.validation = issues;
  return issues;
}
