// پوستهٔ سازگاری: global «BlockRenderers» برای کدهای قدیمی (مثلاً session.js) که هنوز آن را صدا می‌زنند.
// منطق رندر در renderers/ و registry.ts است. این فایل فقط global را نصب می‌کند،
// ویجت و آیکون را از میزبان به زمینه تزریق می‌کند، و تفویض کلیک خودآزمایی را روی document می‌بندد.
import { icon } from "../../ui/components/icons.js";
import type { BlockContext, LooseRenderer } from "./types.js";
import { defaultBlockRegistry } from "./registry.js";
import { bindSelfCheckDelegation } from "./renderers/interactive.js";
import { defaultWidgetRegistry } from "../widgets/registry.js";

interface BlockRenderersApi {
  register(type: string, fn: LooseRenderer): void;
  render(block: unknown, context?: BlockContext | null): string;
  has(type: string): boolean;
  types(): string[];
}

declare global {
  var BlockRenderers: BlockRenderersApi;
  var __checkBound: boolean | undefined;
}

(function initBlockRenderers(global: typeof globalThis) {
  "use strict";

  // ویجت و آیکون از میزبان می‌آیند؛ زمینهٔ صریح مهاجم از آن‌ها بالاتر است.
  const hostContext = (context?: BlockContext | null): BlockContext => ({
    widget: (key: string) => defaultWidgetRegistry.get(key),
    icon,
    ...(context || {}),
  });

  const api: BlockRenderersApi = Object.freeze({
    register: (type: string, fn: LooseRenderer) => defaultBlockRegistry.registerAny(type, fn),
    render: (block: unknown, context?: BlockContext | null) =>
      defaultBlockRegistry.render(block, hostContext(context)),
    has: (type: string) => defaultBlockRegistry.has(type),
    types: () => defaultBlockRegistry.types(),
  });
  global.BlockRenderers = api;

  if (typeof document !== "undefined" && !global.__checkBound) {
    global.__checkBound = true;
    bindSelfCheckDelegation(document);
  }
})(typeof window !== "undefined" ? window : globalThis);
